// Gerado por scripts/juntar.mjs a partir de dados/. Não editar à mão.
window.BANCO = [{"id":"amostra-001","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Enviaste o formulário com este campo preenchido, mas no servidor $_POST['email'] não existe. Porquê?","codigo":"<label for=\"email\">Email</label>\n<input type=\"email\" id=\"email\" required>","linguagem":"html","alternativas":["Falta o atributo name: sem ele, o campo não é enviado.","Falta o atributo value com o email escrito.","O type=\"email\" só é enviado em formulários com method=\"get\".","O id e o for têm de ter valores diferentes."],"correta":0,"explicacao":"O valor chega ao servidor com a chave do atributo name ($_POST['email']). O id só serve para o <label for>, o CSS e o JavaScript.","manual":"4.2"},{"id":"html-001","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Para que serve a linha <!DOCTYPE html> no início de uma página?","codigo":"","linguagem":"","alternativas":["Diz ao browser que a página é HTML5.","Liga a folha de estilos à página.","Indica a língua em que a página está escrita.","Faz os acentos aparecerem corretamente."],"correta":0,"explicacao":"O <!DOCTYPE html> só declara que o documento é HTML5. A língua é o lang do <html>, os acentos são o meta charset e o CSS liga-se com <link>.","manual":"4.1"},{"id":"html-002","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que linha do <head> garante que os acentos aparecem corretamente?","codigo":"","linguagem":"","alternativas":["<html lang=\"pt\">","<!DOCTYPE html>","<meta name=\"viewport\" content=\"width=device-width\">","<meta charset=\"UTF-8\">"],"correta":3,"explicacao":"O meta charset diz ao browser a codificação do texto; com UTF-8, \"ç\", \"ã\" e \"é\" aparecem bem. O lang indica a língua, mas não resolve a codificação.","manual":"4.1"},{"id":"html-003","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Para que serve o atributo lang=\"pt\" em <html lang=\"pt\">?","codigo":"","linguagem":"","alternativas":["Faz o browser traduzir a página para português automaticamente.","Garante que os acentos aparecem bem em qualquer browser.","Indica a língua da página, o que ajuda os leitores de ecrã e os tradutores.","Obriga o browser a mostrar os erros dos formulários em português."],"correta":2,"explicacao":"O lang só declara a língua do conteúdo. Os acentos dependem do meta charset, e as mensagens de erro em português vêm do nosso validacao.js.","manual":"4.1"},{"id":"html-004","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Abres a tua aplicação no telemóvel e a página aparece minúscula, como se fosse um ecrã de computador encolhido. Que linha falta no <head>?","codigo":"","linguagem":"","alternativas":["<html lang=\"pt\">","<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">","<link rel=\"stylesheet\" href=\"css/estilo.css\">","<meta charset=\"UTF-8\">"],"correta":1,"explicacao":"O meta viewport faz a página adaptar-se à largura do ecrã do telemóvel. Sem ele, o telemóvel simula um ecrã largo e encolhe tudo.","manual":"4.1"},{"id":"html-005","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Onde aparece o texto que está dentro de <title>?","codigo":"","linguagem":"","alternativas":["Só no código-fonte, nunca é visível.","No separador do browser.","No rodapé de todas as páginas.","No topo da página, como título principal."],"correta":1,"explicacao":"O <title> fica no <head> e dá o texto do separador do browser. O título que aparece na própria página é o <h1>.","manual":"4.1"},{"id":"html-006","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Qual é a forma correta de ligar uma folha de estilos externa a uma página?","codigo":"","linguagem":"","alternativas":["<style src=\"css/estilo.css\"></style>","<script href=\"css/estilo.css\"></script>","<link rel=\"stylesheet\" href=\"css/estilo.css\">","<link src=\"css/estilo.css\" type=\"text/stylesheet\">"],"correta":2,"explicacao":"O CSS externo liga-se com <link rel=\"stylesheet\" href=\"...\">. O <style> não tem src, e o <script> serve para JavaScript.","manual":"4.1, 5.1, Anexo B"},{"id":"html-007","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Em que parte da página deve ficar o <link rel=\"stylesheet\">?","codigo":"","linguagem":"","alternativas":["No fim do <body>, depois do conteúdo.","Dentro do <footer>.","Antes da linha <!DOCTYPE html>.","Dentro do <head>."],"correta":3,"explicacao":"O <link> do CSS vai no <head>, junto ao <title> e aos <meta>, para o browser já ter os estilos quando desenha o conteúdo.","manual":"4.1, 5.1"},{"id":"html-008","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Qual é a diferença entre o <head> e o <body> de uma página?","codigo":"","linguagem":"","alternativas":["O <head> tem dados sobre a página; o <body> tem o que se vê.","O <head> tem o menu visível no topo; o <body> tem o resto do conteúdo.","O <head> é processado pelo servidor; o <body> pelo browser.","O <head> só pode ter CSS; o <body> só pode ter HTML."],"correta":0,"explicacao":"No <head> ficam o charset, o viewport, o <title> e o <link> do CSS, que não aparecem como conteúdo. O menu visível no topo é o <header>, que fica dentro do <body>.","manual":"4.1, 9.2"},{"id":"html-009","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Este é um excerto do includes/cabecalho.php da Biblioteca. Onde fica o menu com os links Livros, Autores e Sair?","codigo":"<body>\n<header class=\"topo\">\n    <a href=\"index.php\">📚 Biblioteca</a>\n    <nav>\n        <?php if (isset($_SESSION['id_utilizador'])): ?>\n            <a href=\"livros.php\">Livros</a>\n            <a href=\"autores.php\">Autores</a>\n            <a href=\"conta.php\">A minha conta</a>\n            <span class=\"ola\">Olá, <?= htmlspecialchars($_SESSION['nome']) ?></span>\n            <a href=\"logout.php\">Sair</a>\n        <?php else: ?>\n            <a href=\"login.php\">Entrar</a>\n            <a href=\"registo.php\">Criar conta</a>\n        <?php endif; ?>\n    </nav>\n</header>\n<main>","linguagem":"php","alternativas":["Num <nav>, dentro do <head>.","No <footer>, antes do </body>.","Num <nav>, dentro do <header>, no <body>.","Dentro do <head>, logo a seguir ao <title> e ao <meta>."],"correta":2,"explicacao":"O <header> é o cabeçalho visível da página e fica no <body>; o <nav> agrupa os links de navegação. Não confundas <header> com <head>, que não mostra conteúdo.","manual":"9.2"},{"id":"html-010","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O validacao.js tem de estar em todas as páginas. Vendo o includes/rodape.php da Biblioteca (em baixo), como é que isso é feito?","codigo":"</main>\n<footer class=\"rodape\">\n    Biblioteca · Projeto UC00615 ·\n    <a href=\"privacidade.php\">Política de privacidade</a>\n</footer>\n<script src=\"js/validacao.js\"></script>\n</body>\n</html>","linguagem":"html","alternativas":["Com <script href=\"js/validacao.js\"></script> no cabeçalho, antes do <title>.","Com <script src=\"js/validacao.js\"></script> no rodapé, incluído por todas as páginas.","Com <link rel=\"script\" href=\"js/validacao.js\"> em cada formulário.","Com <script src=\"js/validacao.js\"></script> no db.php, que é o primeiro a ser incluído."],"correta":1,"explicacao":"O rodape.php carrega o script com src, no fim do <body>, e é incluído por todas as páginas. O <script> usa src (não href), e o db.php não gera HTML.","manual":"9.2, 6.3"},{"id":"html-011","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Qual é a forma correta de carregar um ficheiro de JavaScript externo?","codigo":"","linguagem":"","alternativas":["<script src=\"js/validacao.js\"></script>","<link rel=\"stylesheet\" href=\"js/validacao.js\">","<js src=\"js/validacao.js\"></js>","<script href=\"js/validacao.js\"></script>"],"correta":0,"explicacao":"O ficheiro de JavaScript carrega-se com o atributo src do <script>. O href é do <a> e do <link>; trocar os dois é um erro frequente.","manual":"9.2, 6.3"},{"id":"html-012","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Qual é o problema desta página?","codigo":"<!DOCTYPE html>\n<html lang=\"pt\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title>Livros</title>\n</head>\n<body>\n    <link rel=\"stylesheet\" href=\"css/estilo.css\">\n    <h1>Os Maias</h1>\n</body>\n</html>","linguagem":"html","alternativas":["Falta fechar o <link> com a tag </link> correspondente.","O <title> devia estar dentro do <body>.","O <h1> só pode aparecer dentro de um <header>.","A ligação ao CSS devia estar dentro do <head>."],"correta":3,"explicacao":"O <link rel=\"stylesheet\"> pertence ao <head>. O <link> não tem tag de fecho, e o <title> fica mesmo no <head>.","manual":"4.1, 5.1"},{"id":"html-013","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O cabeçalho da Biblioteca abre <html>, <body> e <main>; o rodapé é o ficheiro em baixo. Uma página inclui o cabeçalho mas esquece-se de incluir o rodapé. O que fica a faltar no HTML enviado?","codigo":"</main>\n<footer class=\"rodape\">\n    Biblioteca · Projeto UC00615 ·\n    <a href=\"privacidade.php\">Política de privacidade</a>\n</footer>\n<script src=\"js/validacao.js\"></script>\n</body>\n</html>","linguagem":"html","alternativas":["Nada, porque o cabeçalho já fecha a página toda.","Só o </html>; tudo o resto já vem do cabeçalho.","O link da política, o validacao.js e o fecho do main, body e html.","O <head>, com o <title> e a ligação ao CSS."],"correta":2,"explicacao":"O rodapé fecha o que o cabeçalho abriu (</main>, </body>, </html>), mostra o <footer> com o link da política e carrega o validacao.js. O <head> está no cabeçalho, por isso não falta.","manual":"9.2"},{"id":"html-014","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Cada página da Biblioteca define a variável $titulo antes de incluir o cabeçalho. Vendo este excerto do includes/cabecalho.php, para que serve?","codigo":"<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <title><?= htmlspecialchars($titulo) ?> · Biblioteca</title>\n    <link rel=\"stylesheet\" href=\"css/estilo.css\">\n</head>","linguagem":"php","alternativas":["Para o cabeçalho escolher qual ficheiro CSS deve ligar.","Para o texto do <title>, no separador do browser, mudar em cada página.","Para o <h1> de cada página ser criado automaticamente.","Para o browser saber em que língua está a página."],"correta":1,"explicacao":"O cabeçalho escreve <title><?= htmlspecialchars($titulo) ?> · Biblioteca</title>, por isso cada página tem o seu texto no separador. O <h1> é escrito por cada página.","manual":"9.2"},{"id":"html-015","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que método deve usar o formulário de registo, que cria uma conta?","codigo":"","linguagem":"","alternativas":["method=\"send\"","method=\"submit\"","method=\"get\"","method=\"post\""],"correta":3,"explicacao":"Tudo o que cria ou altera dados usa method=\"post\": os dados vão no corpo do pedido e não no endereço.","manual":"4.2, 1.2"},{"id":"html-016","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Para que serve o atributo action de um <form>?","codigo":"","linguagem":"","alternativas":["Indica o endereço para onde os dados são enviados.","Dá ao formulário um nome para o servidor o reconhecer.","Indica se os dados vão por GET ou por POST.","Define a função de JavaScript que valida o formulário."],"correta":0,"explicacao":"O action diz para onde vão os dados (por exemplo, o próprio registo.php). O GET ou POST é escolhido pelo method.","manual":"4.2"},{"id":"html-017","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Num formulário com method=\"post\", onde vão os dados dos campos?","codigo":"","linguagem":"","alternativas":["No corpo do pedido, sem aparecerem no endereço.","No endereço, depois do ?.","Num cookie que o browser cria para o formulário.","Na sessão do utilizador, guardada no browser."],"correta":0,"explicacao":"Com POST, os campos vão no corpo do pedido. Com GET é que aparecem no endereço depois do ?.","manual":"1.2, 4.2"},{"id":"html-018","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Porque é que o formulário de pesquisa da Biblioteca usa method=\"get\"?","codigo":"<form method=\"get\" action=\"livros.php\" class=\"pesquisa\">\n    <input type=\"search\" name=\"q\" placeholder=\"Pesquisar por título\">\n    <button type=\"submit\">Pesquisar</button>\n</form>","linguagem":"html","alternativas":["Porque um campo type=\"search\" só funciona com method=\"get\".","O texto vai no endereço, por isso a pesquisa pode ser guardada ou partilhada.","Porque o POST não consegue enviar mais do que um campo.","Porque o GET é mais seguro do que o POST para enviar texto."],"correta":1,"explicacao":"Pesquisar só lê dados, por isso é um GET: o texto fica no URL (?q=mar), que pode ir para os favoritos. Não é uma questão de segurança.","manual":"12.2, 1.2"},{"id":"html-020","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Este formulário de login não tem o atributo method. O que acontece quando é enviado?","codigo":"<form action=\"login.php\">\n    <label for=\"email\">Email</label>\n    <input type=\"email\" id=\"email\" name=\"email\">\n    <label for=\"password\">Password</label>\n    <input type=\"password\" id=\"password\" name=\"password\">\n    <button type=\"submit\">Entrar</button>\n</form>","linguagem":"html","alternativas":["É enviado com POST, que é o método por omissão.","Não é enviado: o method é obrigatório.","É enviado com GET, e a password aparece no endereço.","O browser pergunta ao utilizador que método quer usar no envio."],"correta":2,"explicacao":"Sem method, o browser usa GET, por isso os campos vão para o URL (login.php?email=...&password=...). Um formulário com password tem de ter method=\"post\".","manual":"4.2, 1.2"},{"id":"html-021","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O formulário de edição tem action=\"livro_editar.php?id=7\" e method=\"post\". Como é que o id chega ao servidor?","codigo":"<form method=\"post\" action=\"livro_editar.php?id=7\">\n    <label for=\"titulo\">Título</label>\n    <input type=\"text\" id=\"titulo\" name=\"titulo\" value=\"Os Maias\">\n    <button type=\"submit\">Guardar</button>\n</form>","linguagem":"html","alternativas":["Chega em $_POST['id'], junto com os campos do formulário.","Não chega: num POST, o que está depois do ? é ignorado.","Só chega se houver também um campo hidden com name=\"id\".","Vem no endereço do action, por isso lê-se em $_GET['id'], mesmo num POST."],"correta":3,"explicacao":"O que está no action depois do ? vai no endereço e lê-se em $_GET; os campos do formulário vão no corpo e lêem-se em $_POST. Por isso o id chega também no POST.","manual":"12.5, 7.5"},{"id":"html-022","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Que método deve usar o formulário de login, e porquê?","codigo":"","linguagem":"","alternativas":["POST, porque é mais rápido do que o GET.","POST, porque envia a password, que não deve aparecer no endereço.","GET, porque o login só lê dados e não grava nada.","GET, porque assim o login pode ir para os favoritos."],"correta":1,"explicacao":"O login usa POST: os dados vão no corpo do pedido. Com GET, a password ficava no URL, no histórico e nos favoritos.","manual":"1.2, 4.2"},{"id":"html-023","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que elemento se usa para o botão que envia um formulário?","codigo":"","linguagem":"","alternativas":["<button type=\"submit\">","<input type=\"send\" value=\"Enviar\">","<button type=\"send\">","<a href=\"#\">Enviar</a>"],"correta":0,"explicacao":"O botão que envia o formulário é <button type=\"submit\">. Um link <a> não envia os campos do formulário.","manual":"4.2, Anexo B"},{"id":"html-024","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Qual é o problema de usar method=\"get\" num formulário que cria um livro?","codigo":"<form method=\"get\" action=\"livro_novo.php\">\n    <label for=\"titulo\">Título</label>\n    <input type=\"text\" id=\"titulo\" name=\"titulo\">\n    <button type=\"submit\">Guardar</button>\n</form>","linguagem":"html","alternativas":["Com GET, a sinopse não pode ter acentos nem espaços.","Com GET, o botão type=\"submit\" deixa de funcionar.","Um GET não deve alterar dados: o endereço pode ser repetido, guardado ou partilhado.","Não há problema, desde que o servidor valide os dados."],"correta":2,"explicacao":"Um GET deve poder repetir-se sem efeitos. Se criar um livro, basta abrir o endereço outra vez (ou um robô segui-lo) para criar outro. Para criar dados usa-se POST.","manual":"1.2, 4.4"},{"id":"html-025","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que atributo de um campo define a chave com que o valor chega ao servidor?","codigo":"","linguagem":"","alternativas":["id","name","for","value"],"correta":1,"explicacao":"O name é a chave: name=\"email\" chega como $_POST['email']. Sem name, o campo não é enviado. O id serve para o <label for>, o CSS e o JavaScript.","manual":"4.2"},{"id":"html-026","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Com que chave lês no servidor o valor escrito neste campo?","codigo":"<label for=\"titulo\">Título do livro</label>\n<input type=\"text\" id=\"titulo\" name=\"nome_livro\">","linguagem":"html","alternativas":["$_POST['nome_livro']","$_POST['Título do livro']","$_POST['titulo']","$_POST['text']"],"correta":0,"explicacao":"A chave é sempre o name do campo. O id (titulo) só liga o campo à etiqueta; o texto da etiqueta e o type não são enviados.","manual":"4.2"},{"id":"html-027","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Qual é a diferença entre os atributos id e name de um campo?","codigo":"","linguagem":"","alternativas":["O name só serve para o CSS e o JavaScript; o id só serve para o servidor.","São sinónimos: o browser envia o que existir.","O id é a chave do valor enviado; o name identifica o elemento.","O name é a chave do valor enviado; o id identifica o elemento."],"correta":3,"explicacao":"O servidor recebe o valor com a chave do name. O id é usado pelo <label for>, pelo CSS (#id) e pelo getElementById() no JavaScript.","manual":"4.2, 6.2"},{"id":"html-028","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Num projeto, ao gravar um registo, aparece \"Warning: Undefined array key \"isbn\"\". O campo do formulário é este. Qual é a causa?","codigo":"<label for=\"isbn\">ISBN (opcional)</label>\n<input type=\"text\" id=\"isbn\" maxlength=\"13\">","linguagem":"html","alternativas":["O id devia ser diferente do for do <label>.","O campo não tem required, por isso chega vazio.","O campo não tem name, por isso não é enviado.","O maxlength cortou o valor antes de ser enviado."],"correta":2,"explicacao":"Sem name, o browser não envia o campo e $_POST['isbn'] não existe. Um campo vazio chegava na mesma, como texto vazio.","manual":"17.1, 4.2"},{"id":"html-029","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Como se liga uma etiqueta <label> a um campo?","codigo":"","linguagem":"","alternativas":["O <label> e o campo têm o mesmo name.","O <label> é escrito logo a seguir ao campo.","O for do <label> tem o mesmo valor que o name do campo.","O for do <label> tem o mesmo valor que o id do campo."],"correta":3,"explicacao":"<label for=\"email\"> liga-se ao campo com id=\"email\". O name não entra nesta ligação: serve para enviar o valor.","manual":"4.2, Anexo B"},{"id":"html-030","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"O que se ganha em ligar um <label> ao seu campo?","codigo":"","linguagem":"","alternativas":["Clicar no texto põe o cursor no campo, e os leitores de ecrã sabem o que pede.","O browser passa a validar o campo automaticamente.","O texto da etiqueta é enviado ao servidor junto com o valor.","O texto da etiqueta aparece dentro do campo como sugestão."],"correta":0,"explicacao":"A ligação dá conforto (o clique no texto vai para o campo) e acessibilidade. A etiqueta não é enviada nem valida nada.","manual":"4.2"},{"id":"html-031","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O que acontece quando clicas no texto \"Email\"?","codigo":"<label for=\"email\">Email</label>\n<input type=\"email\" id=\"mail\" name=\"email\">","linguagem":"html","alternativas":["O cursor vai para o campo, porque o for corresponde ao name.","O formulário é enviado, porque o campo é do tipo email.","Nada: o for não corresponde a nenhum id, por isso o cursor não vai para o campo.","O browser mostra um erro e a página não aparece."],"correta":2,"explicacao":"O for liga-se ao id, e aqui o id é \"mail\". O name (email) não conta para a etiqueta. O browser não dá erro: a etiqueta só fica sem efeito.","manual":"4.2"},{"id":"html-032","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"No registo, a caixa do consentimento está dentro do próprio <label>. Que efeito tem isso?","codigo":"<label class=\"check\" for=\"consentimento\">\n    <input type=\"checkbox\" id=\"consentimento\" name=\"consentimento\" required>\n    <span>Li e aceito a política de privacidade.</span>\n</label>","linguagem":"html","alternativas":["O texto da etiqueta passa a ser enviado como valor da caixa.","Clicar no texto ativa ou desativa a caixa, como clicar na própria caixa.","A caixa deixa de ser enviada ao servidor, por estar dentro de outro elemento.","A caixa fica assinalada logo quando a página abre."],"correta":1,"explicacao":"A etiqueta continua ligada à caixa, por isso clicar no texto muda o estado da caixa. Isso é conforto para o utilizador; o valor enviado não muda.","manual":"4.2"},{"id":"html-033","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Que valor deve ter o atributo for da etiqueta deste campo?","codigo":"<label for=\"______\">Ano de edição</label>\n<input type=\"number\" id=\"ano_edicao\" name=\"ano\">","linguagem":"html","alternativas":["Ano de edição","ano","ano_edicao","number"],"correta":2,"explicacao":"O for tem de ser igual ao id do campo (ano_edicao). O name (ano) é só a chave com que o valor chega ao servidor.","manual":"4.2"},{"id":"html-034","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Este campo não tem id e a etiqueta não tem for. A etiqueta fica ligada ao campo?","codigo":"<label>\n    Email\n    <input type=\"email\" name=\"email\">\n</label>","linguagem":"html","alternativas":["Sim, porque o name tem o mesmo texto que a etiqueta.","Sim, porque o campo está dentro do <label>.","Não, porque sem for e id não há ligação.","Não, e o campo também deixa de ser enviado."],"correta":1,"explicacao":"Há duas formas de ligar: for igual ao id, ou o campo dentro do <label>. O campo continua a ser enviado, porque tem name.","manual":"4.2"},{"id":"html-035","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Para que serve o atributo value de um <input>?","codigo":"","linguagem":"","alternativas":["Dá o valor inicial do campo.","Liga o campo à etiqueta com o mesmo texto.","Limita o número de caracteres que se podem escrever.","Dá a chave com que o valor chega ao servidor."],"correta":0,"explicacao":"O value é o valor com que o campo aparece preenchido. A chave é o name, o limite é o maxlength e a etiqueta liga-se pelo id.","manual":"4.2"},{"id":"html-036","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"No registo, o campo do nome tem value=\"<?= htmlspecialchars($nome) ?>\". Para que serve este value?","codigo":"","linguagem":"","alternativas":["Para o browser validar o nome antes de enviar o formulário.","Para o nome ser guardado no cookie da sessão.","Para o nome ir no endereço depois do envio.","Para, depois de um erro, o campo voltar com o que o utilizador escreveu."],"correta":3,"explicacao":"Quando a validação falha, a página volta a mostrar o formulário; com o value, os campos não aparecem vazios e o utilizador não tem de escrever tudo outra vez.","manual":"4.2, 9.5"},{"id":"html-037","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Pesquisaste \"mar\" e a página livros.php?q=mar foi mostrada. O que aparece dentro da caixa de pesquisa?","codigo":"<input type=\"search\" name=\"q\"\n       placeholder=\"Pesquisar por título\"\n       value=\"<?= htmlspecialchars($q) ?>\">","linguagem":"html","alternativas":["Nada, porque o value só funciona com method=\"post\".","mar","q","Pesquisar por título"],"correta":1,"explicacao":"O $q tem o texto pesquisado e é posto no value, por isso a caixa mostra \"mar\". O placeholder só aparece quando a caixa está vazia.","manual":"12.2"},{"id":"html-038","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Porque é que a Biblioteca usa htmlspecialchars() dentro de value=\"...\"?","codigo":"<input type=\"text\" id=\"titulo\" name=\"titulo\"\n       value=\"<?= htmlspecialchars($livro['titulo']) ?>\">","linguagem":"html","alternativas":["Para que aspas ou < no texto não partam o HTML nem sejam executados.","Para que o browser cifre o valor antes de o enviar.","Para que o maxlength conte bem os caracteres com acento.","Para que o valor seja gravado em UTF-8 na base de dados."],"correta":0,"explicacao":"Um título com \" fecharia o atributo value e o resto seria lido como HTML. O htmlspecialchars() troca \", <, > e & por entidades, que aparecem como texto.","manual":"14.1, 4.2"},{"id":"html-039","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"No formulário de edição de um livro, os campos já aparecem preenchidos. Como?","codigo":"","linguagem":"","alternativas":["Os dados vêm num campo hidden enviado pela página de detalhe.","O selected preenche todos os campos com os valores atuais.","O browser lembra-se do que foi escrito da última vez que o livro foi criado.","No GET, o livro é lido da base de dados e posto no value de cada campo."],"correta":3,"explicacao":"O livro_editar.php faz um SELECT no GET e o formulário escreve esses valores no value dos campos (e no meio da textarea). O selected só serve para as opções de um <select>.","manual":"12.5, 4.2"},{"id":"html-040","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"O que indica o atributo required num campo?","codigo":"<label for=\"nome\">Nome</label>\n<input type=\"text\" id=\"nome\" name=\"nome\" required>","linguagem":"html","alternativas":["Que o servidor recusa sempre o pedido inteiro se esse campo chegar vazio.","Que o campo é enviado mesmo que não tenha name.","Que o campo é obrigatório e o formulário não deve ir com ele vazio.","Que o valor do campo é cifrado antes de ser enviado."],"correta":2,"explicacao":"O required é uma regra para o browser (e, na Biblioteca, um sinal para o validacao.js). O servidor só recusa porque tem a sua própria validação.","manual":"4.2"},{"id":"html-041","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Um formulário tem required em todos os campos. O servidor ainda precisa de verificar se vêm vazios?","codigo":"","linguagem":"","alternativas":["Não, desde que o formulário tenha também o atributo novalidate.","Só nos campos de password, porque os outros são verificados pelo browser.","Não: o browser nunca envia um formulário com um campo required vazio.","Sim: o required pode ser contornado, por isso a validação no servidor é obrigatória."],"correta":3,"explicacao":"Basta desligar o JavaScript, alterar o HTML com F12 ou enviar o pedido sem o formulário. A validação no browser é conforto; a segurança está no servidor.","manual":"6.1, 6.4, 14"},{"id":"html-042","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"O que faz o atributo maxlength=\"13\" no campo do ISBN?","codigo":"<label for=\"isbn\">ISBN (opcional)</label>\n<input type=\"text\" id=\"isbn\" name=\"isbn\" maxlength=\"13\">","linguagem":"html","alternativas":["Faz o servidor recusar ISBN com mais de 13 algarismos.","Mostra o campo com 13 caracteres de largura.","Não deixa escrever mais de 13 caracteres no campo.","Obriga a escrever exatamente 13 caracteres."],"correta":2,"explicacao":"O maxlength limita o que se pode escrever no browser. Não obriga a um tamanho mínimo, e o servidor tem a sua própria regra.","manual":"4.2"},{"id":"html-043","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Alguém tira o maxlength=\"200\" do campo do título com F12 e envia um título com 300 caracteres. Vendo a validação no servidor (em baixo), o que acontece?","codigo":"function validar_livro($pdo, $livro)\n{\n    $erros = [];\n\n    if ($livro['titulo'] === '' || mb_strlen($livro['titulo']) > 200) {\n        $erros[] = 'O título é obrigatório e não pode ter mais de 200 caracteres.';\n    }\n    // ...\n}","linguagem":"php","alternativas":["O servidor recusa e mostra o erro, porque valida o tamanho outra vez.","O livro é gravado com os 300 caracteres.","O browser corta automaticamente o título para 200 caracteres antes de o enviar.","A página dá um erro 500 e não mostra nada."],"correta":0,"explicacao":"O validar_livro() verifica que o título não tem mais de 200 caracteres. As regras do browser podem ser contornadas, por isso o servidor repete-as.","manual":"12.4, 14"},{"id":"html-044","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O que faz o atributo novalidate no <form> do registo?","codigo":"<form method=\"post\" action=\"registo.php\"\n      id=\"form-principal\" class=\"formulario\" novalidate>","linguagem":"html","alternativas":["Desliga a validação no servidor para esse formulário.","Desliga as mensagens automáticas do browser, para o nosso JavaScript mostrar os erros.","Desliga o validacao.js nesse formulário.","Impede o envio enquanto houver campos required vazios."],"correta":1,"explicacao":"Com novalidate, o browser não mostra os seus avisos; é o validacao.js que mostra todos os erros juntos e em português. O servidor valida sempre.","manual":"4.2"},{"id":"html-045","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O <form> do registo tem novalidate. Com o JavaScript desligado, envias o registo em branco. O que acontece?","codigo":"","linguagem":"","alternativas":["Nada acontece: o botão fica desativado sem JavaScript.","A conta é criada com os campos vazios.","O pedido chega ao servidor, que encontra e mostra os erros.","O browser mostra os seus avisos automáticos e não envia nada."],"correta":2,"explicacao":"O novalidate desliga os avisos do browser e o JavaScript está desligado, por isso o formulário é enviado. É a validação no servidor que encontra os erros.","manual":"6.3, 4.2, 16"},{"id":"html-046","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"No registo, o campo da password tem data-minimo=\"8\". Para que serve este atributo?","codigo":"<label for=\"password\">Password (mínimo 8 caracteres)</label>\n<input type=\"password\" id=\"password\" name=\"password\"\n       required data-minimo=\"8\">","linguagem":"html","alternativas":["Define a largura do campo, em caracteres.","É lido pelo validacao.js, que só verifica os 8 caracteres onde ele existe.","Faz o servidor exigir uma password com pelo menos 8 caracteres.","É uma regra do HTML: o browser recusa passwords com menos de 8."],"correta":1,"explicacao":"Os atributos data-* são nossos: o browser ignora-os e o JavaScript lê-os (password.dataset.minimo). A regra dos 8 só atua onde ele existe, ou seja, no registo.","manual":"6.3, 4.2"},{"id":"html-047","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"No login, o campo da password é <input type=\"password\" id=\"password\" name=\"password\" required>, sem data-minimo. Escreves uma password com 5 caracteres e envias. Vendo esta parte do validacao.js, o que acontece?","codigo":"// 3. Password com pelo menos 8 caracteres (só no registo)\nconst password = document.getElementById('password');\nif (password && password.dataset.minimo && password.value !== '' && password.value.length < 8) {\n    erros.push('A password tem de ter pelo menos 8 caracteres.');\n}","linguagem":"javascript","alternativas":["Deixa enviar: a regra dos 8 caracteres só atua se houver data-minimo.","Impede o envio, porque o required exige 8 caracteres.","Mostra \"A password tem de ter pelo menos 8 caracteres.\"","Apaga a password do campo e pede para escrever outra vez."],"correta":0,"explicacao":"O validacao.js só verifica o tamanho quando o campo tem data-minimo; no login não tem. O required só exige que não esteja vazio.","manual":"6.3"},{"id":"html-048","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Como se cria um campo de password num formulário?","codigo":"","linguagem":"","alternativas":["<input type=\"text\" secret>","<input type=\"hidden\">","<password>","<input type=\"password\">"],"correta":3,"explicacao":"O campo de password é <input type=\"password\">: o texto aparece como pontos. O hidden não aparece de todo.","manual":"4.2, Anexo B"},{"id":"html-049","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O que faz, de facto, um campo <input type=\"password\">?","codigo":"","linguagem":"","alternativas":["Impede que a password seja enviada num formulário com method=\"get\".","Mostra pontos no ecrã; o valor é enviado tal como foi escrito.","Guarda o hash da password no browser.","Cifra a password no browser antes de a enviar."],"correta":1,"explicacao":"O type=\"password\" só esconde o texto de quem olha para o ecrã. Não cifra nada: é preciso POST, HTTPS e password_hash() no servidor.","manual":"4.2, 14.3"},{"id":"html-050","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que vantagem tem usar <input type=\"email\"> num telemóvel?","codigo":"","linguagem":"","alternativas":["O email é enviado cifrado.","Não deixa registar emails repetidos.","Aparece o teclado com o @.","O browser confirma que o email existe."],"correta":2,"explicacao":"No telemóvel, o type=\"email\" mostra o teclado com @. Verificar o formato a sério e impedir repetidos é trabalho do servidor (e do UNIQUE).","manual":"4.2"},{"id":"html-051","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que tipo de campo usa a Biblioteca para o ano de edição de um livro?","codigo":"","linguagem":"","alternativas":["<input type=\"number\">","<input type=\"search\">","<input type=\"date\">","<input type=\"year\" min=\"1450\">"],"correta":0,"explicacao":"O ano é um número, por isso usa type=\"number\". O type=\"year\" não existe, e o date pede um dia completo.","manual":"4.2"},{"id":"html-052","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que tipo de campo usa a Biblioteca para a caixa de pesquisa?","codigo":"","linguagem":"","alternativas":["<input type=\"searchbox\">","<input type=\"filter\">","<input type=\"find\">","<input type=\"search\">"],"correta":3,"explicacao":"A caixa de pesquisa é <input type=\"search\">, num formulário com method=\"get\". Os outros tipos não existem.","manual":"4.2, 12.2"},{"id":"html-053","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que elemento se usa para um texto com várias linhas, como a sinopse de um livro?","codigo":"","linguagem":"","alternativas":["<text>","<textarea>","<input type=\"multiline\">","<input type=\"text\" rows=\"4\">"],"correta":1,"explicacao":"O texto em várias linhas escreve-se numa <textarea>. O <input type=\"text\"> só tem uma linha.","manual":"4.2"},{"id":"html-054","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Ao editar, a sinopse não aparece no campo. Qual é o erro?","codigo":"<label for=\"sinopse\">Sinopse</label>\n<textarea id=\"sinopse\" name=\"sinopse\" rows=\"4\"\n          value=\"<?= htmlspecialchars($livro['sinopse']) ?>\"></textarea>","linguagem":"html","alternativas":["Falta o atributo type=\"text\" na textarea.","O value só funciona em formulários com method=\"get\".","Uma textarea não pode ter o atributo name.","Numa textarea, o valor vai entre <textarea> e </textarea>, não em value."],"correta":3,"explicacao":"A <textarea> não tem atributo value: o texto inicial escreve-se entre a tag de abertura e a de fecho, como na Biblioteca.","manual":"12.4, 4.2"},{"id":"html-055","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Uma caixa <input type=\"checkbox\" name=\"consentimento\"> não foi assinalada. O que chega ao servidor?","codigo":"<input type=\"checkbox\" id=\"consentimento\"\n       name=\"consentimento\" required>","linguagem":"html","alternativas":["$_POST['consentimento'] com o valor \"off\".","$_POST['consentimento'] com o valor \"false\".","Nada: a caixa não é enviada, por isso não existe em $_POST.","$_POST['consentimento'] com um texto vazio."],"correta":2,"explicacao":"Uma checkbox só é enviada se estiver assinalada. Por isso o servidor usa isset($_POST['consentimento']) para saber se o utilizador aceitou.","manual":"7.5, 10.2"},{"id":"html-056","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Porque é que a caixa do consentimento tem de vir desmarcada quando a página abre?","codigo":"","linguagem":"","alternativas":["Porque o utilizador tem de a assinalar ele próprio; já assinalada não é consentimento.","Porque o browser não envia caixas que já vêm assinaladas.","Porque o servidor só aceita caixas que mudaram de estado.","Porque o required não funciona numa caixa já assinalada."],"correta":0,"explicacao":"O consentimento tem de ser um ato do utilizador. Uma caixa já assinalada não prova que ele aceitou a política.","manual":"15.2"},{"id":"html-057","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Para que serve um <input type=\"hidden\">?","codigo":"","linguagem":"","alternativas":["Para esconder a password enquanto o utilizador a escreve.","Para guardar um valor no servidor entre pedidos.","Para enviar um valor sem ele aparecer na página.","Para enviar um valor cifrado ao servidor."],"correta":2,"explicacao":"Na Biblioteca, o hidden leva o id do livro a apagar, sem aparecer. Esconder a password é o type=\"password\"; guardar entre pedidos é a sessão.","manual":"4.2, 4.4"},{"id":"html-058","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O botão Apagar tem <input type=\"hidden\" name=\"id_livro\" value=\"3\">. Alguém muda o valor para 5 com F12 e envia. O que recebe o servidor?","codigo":"","linguagem":"","alternativas":["Não recebe nada: o browser não envia um hidden alterado.","Recebe 5: um hidden não aparece, mas pode ser alterado como outro campo.","Recebe 3, porque os campos hidden não podem ser alterados.","Recebe 3 e 5, e usa o primeiro valor."],"correta":1,"explicacao":"Tudo o que vem do browser pode ser alterado, incluindo os hidden. Por isso o servidor nunca confia nesses valores sem os verificar (e controla o acesso).","manual":"4.2, 12.4, 14"},{"id":"html-059","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Envias este formulário sem assinalar a caixa. Que chaves existem em $_POST?","codigo":"<form method=\"post\" action=\"guardar.php\">\n    <input type=\"hidden\" name=\"id_autor\" value=\"4\">\n    <input type=\"text\" name=\"nome\" value=\"Sophia\">\n    <input type=\"checkbox\" name=\"ativo\">\n    <input type=\"text\" id=\"pais\" value=\"Portugal\">\n    <button type=\"submit\">Guardar</button>\n</form>","linguagem":"html","alternativas":["id_autor e nome","nome e pais","id_autor, nome e ativo","nome, ativo e pais"],"correta":0,"explicacao":"O hidden é enviado (só não aparece). A checkbox não assinalada não é enviada, e o campo do país não tem name, por isso também não vai.","manual":"4.2, 7.5"},{"id":"html-060","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Qual é o problema deste campo num formulário de login?","codigo":"<label for=\"password\">Password</label>\n<input type=\"text\" id=\"password\" name=\"password\">","linguagem":"html","alternativas":["O for e o id não podem ter o mesmo valor.","A password não é enviada, porque o type=\"text\" não tem value.","O name não pode ser \"password\", porque é uma palavra reservada do HTML.","A password aparece em claro no ecrã; devia ser type=\"password\"."],"correta":3,"explicacao":"Com type=\"text\", quem estiver ao lado vê a password. O campo é enviado na mesma, porque tem name; o for igual ao id está certo.","manual":"4.2"},{"id":"html-061","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O botão \"Criar conta\" deste formulário é um link. O que acontece ao clicar nele?","codigo":"<form method=\"post\" action=\"registo.php\">\n    <label for=\"nome\">Nome</label>\n    <input type=\"text\" id=\"nome\" name=\"nome\">\n    <a href=\"registo.php\" class=\"btn\">Criar conta</a>\n</form>","linguagem":"html","alternativas":["O formulário é enviado com POST, porque o link está dentro dele.","O browser abre registo.php com GET, sem enviar os campos.","Nada, porque um link não funciona dentro de um <form>.","O formulário é enviado com GET, com o nome no endereço."],"correta":1,"explicacao":"Um link faz sempre um pedido GET ao seu href e ignora o formulário. Para enviar os campos é preciso um <button type=\"submit\">.","manual":"4.4, 4.2"},{"id":"html-062","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que elementos se usam para mostrar uma lista de opções para escolher uma?","codigo":"","linguagem":"","alternativas":["<ul> com um <li> por opção, dentro do <form>","<input type=\"list\"> com um <li> por opção","<choice> com um <item> por opção","<select> com um <option> por opção"],"correta":3,"explicacao":"Uma caixa de seleção é um <select> com vários <option>. Uma lista <ul> só mostra itens, não envia nada.","manual":"4.3"},{"id":"html-063","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O utilizador escolhe \"Sophia de Mello Breyner\" e envia. O que chega ao servidor?","codigo":"<select id=\"id_autor\" name=\"id_autor\">\n    <option value=\"\">— escolhe —</option>\n    <option value=\"1\">José Saramago</option>\n    <option value=\"2\">Sophia de Mello Breyner</option>\n</select>","linguagem":"html","alternativas":["$_POST['id_autor'] com o valor '2'","$_POST['option'] com o valor '2'","$_POST['Sophia de Mello Breyner'] com o valor '2'","$_POST['id_autor'] com \"Sophia de Mello Breyner\""],"correta":0,"explicacao":"A chave é o name do <select> e o valor é o value da opção escolhida. O texto visível é só para o utilizador.","manual":"4.3"},{"id":"html-064","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Na caixa de seleção do autor, porque é que o value de cada <option> é o id e não o nome?","codigo":"","linguagem":"","alternativas":["Porque um <select> só aceita valores numéricos.","Porque o browser não consegue enviar textos com acentos.","Porque o que se guarda na chave estrangeira do livro é o id do autor.","Porque assim o nome não aparece duas vezes na lista."],"correta":2,"explicacao":"O livro guarda id_autor (a chave estrangeira). O utilizador vê o nome, mas é enviado o id.","manual":"4.3, 3.3"},{"id":"html-065","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Para que serve o atributo selected num <option>?","codigo":"<select id=\"id_autor\" name=\"id_autor\">\n    <option value=\"\">— escolhe —</option>\n    <option value=\"1\">José Saramago</option>\n    <option value=\"3\" selected>Eça de Queirós</option>\n</select>","linguagem":"html","alternativas":["Impede o utilizador de escolher qualquer outra opção da lista.","Deixa essa opção já escolhida quando a página abre.","Destaca a opção a outra cor, sem a escolher.","Torna obrigatório escolher essa opção."],"correta":1,"explicacao":"O selected indica a opção escolhida à partida. Ao editar um livro, é assim que aparece o autor atual.","manual":"4.3"},{"id":"html-066","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"Ao editar um livro, o formulário não põe selected em nenhuma opção. O que vê o utilizador na caixa do autor?","codigo":"","linguagem":"","alternativas":["A primeira opção, \"— escolhe —\", em vez do autor atual.","O autor atual, porque o browser lembra-se do valor gravado.","A caixa vazia, sem nenhuma opção na lista.","A última opção da lista, por ser a mais recente."],"correta":0,"explicacao":"Sem selected, o browser mostra a primeira opção. Se o utilizador gravar sem reparar, envia o value vazio e o servidor recusa (\"Escolhe um autor da lista.\").","manual":"4.3, 12.4"},{"id":"html-067","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O <select> do autor é required e a primeira opção é <option value=\"\">— escolhe —</option>. O que acontece se o utilizador não escolher nenhum autor?","codigo":"","linguagem":"","alternativas":["É enviado o id do primeiro autor que aparece na lista.","O campo id_autor não é enviado de todo.","É enviado o texto \"— escolhe —\".","O campo vai vazio e é tratado como não preenchido."],"correta":3,"explicacao":"O valor enviado é o value da opção, que aqui é vazio. O validacao.js acusa o campo obrigatório e, no servidor, o id fica 0 e o autor é recusado.","manual":"4.3, 6.3, 12.4"},{"id":"html-068","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O utilizador só pode escolher autores da lista. Porque é que o servidor confirma na base de dados que o id_autor existe?","codigo":"","linguagem":"","alternativas":["Porque o required do <select> só funciona no servidor.","Porque o browser não envia o value das opções com acentos.","Porque o formulário pode ser alterado e enviar um id que não está na lista.","Porque o <select> às vezes envia o nome em vez do id."],"correta":2,"explicacao":"Alguém pode alterar o HTML ou o pedido e enviar id_autor=999. Por isso validar_livro() verifica na base de dados que o autor existe.","manual":"12.4"},{"id":"html-069","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que tipo de pedido faz um link <a href=\"...\">?","codigo":"","linguagem":"","alternativas":["GET ou POST, conforme o que o servidor pedir.","Um pedido POST, se o link estiver dentro de um <form>.","Um pedido POST, se o link tiver target=\"_blank\".","Sempre um pedido GET."],"correta":3,"explicacao":"Um link é sempre um pedido GET. Por isso serve para navegar, nunca para alterar dados.","manual":"4.4, 1.2"},{"id":"html-070","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Porque é que a Biblioteca não apaga livros com um link como <a href=\"livro_apagar.php?id=3\">?","codigo":"<!-- Errado: um link para apagar -->\n<a href=\"livro_apagar.php?id=3\" class=\"btn perigo\">Apagar</a>","linguagem":"html","alternativas":["Um link não consegue levar o id do livro até ao servidor.","Um GET é mais lento do que um POST para apagar dados.","Um link é um GET: um robô ou uma pré-visualização podia segui-lo e apagar o livro.","Um link não pode apontar para um ficheiro PHP."],"correta":2,"explicacao":"Um GET nunca deve alterar dados, porque qualquer coisa que siga o link o executa. Apagar faz-se com um formulário POST.","manual":"1.2, 4.4"},{"id":"html-072","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Qual é a forma correta de fazer o botão Apagar de um livro?","codigo":"","linguagem":"","alternativas":["Um <a href=\"livro_apagar.php?id=3\" class=\"btn perigo\">Apagar</a>.","Um <form method=\"post\"> com um hidden para o id e um botão submit.","Um <form method=\"get\"> com um hidden para o id e um botão submit.","Um <button> com onclick que muda o endereço para livro_apagar.php?id=3."],"correta":1,"explicacao":"Apagar altera dados, por isso é um formulário POST, mesmo que só tenha um botão. Os outros fazem um GET, que nunca deve apagar.","manual":"4.4"},{"id":"html-074","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Qual destas ações deve ser feita com um link ou um formulário GET?","codigo":"","linguagem":"","alternativas":["Criar uma conta.","Apagar um autor.","Pesquisar livros por título.","Gravar as alterações de um livro."],"correta":2,"explicacao":"Pesquisar só lê dados, por isso é GET. Criar, gravar e apagar alteram dados e usam POST.","manual":"1.2, 12.1"},{"id":"html-075","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O botão Apagar foi feito com <form method=\"get\" action=\"livro_apagar.php\">, com um hidden id_livro=3. O livro_apagar.php é este. O que acontece quando o formulário é enviado?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/auth.php';\n\nif ($_SERVER['REQUEST_METHOD'] !== 'POST') {\n    header('Location: livros.php');\n    exit;\n}\n\n$stmt = $pdo->prepare('DELETE FROM livros WHERE id_livro = ?');\n$stmt->execute([(int) ($_POST['id_livro'] ?? 0)]);","linguagem":"php","alternativas":["Nada é apagado: o livro_apagar.php só aceita POST e volta para a lista.","O livro 3 é apagado, mas o id aparece no endereço.","O livro 3 é apagado, porque o id vai no hidden.","O browser recusa enviar um hidden com method=\"get\"."],"correta":0,"explicacao":"Com GET, o pedido é livro_apagar.php?id_livro=3, e o livro_apagar.php começa por recusar tudo o que não seja POST. Um formulário GET é tão GET como um link.","manual":"12.6, 4.4"},{"id":"html-076","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"No apagar de um livro, o id vai num campo hidden; no editar, vai no action (livro_editar.php?id=7). Onde lê o servidor cada um?","codigo":"","linguagem":"","alternativas":["Os dois em $_POST, porque os dois formulários são POST.","Apagar: $_GET['id_livro']; editar: $_POST['id'].","Os dois em $_GET, porque os ids vão sempre no endereço.","Apagar: $_POST['id_livro']; editar: $_GET['id']."],"correta":3,"explicacao":"O hidden é um campo do formulário e vai no corpo do POST ($_POST). O que está no action depois do ? vai no endereço ($_GET).","manual":"12.5, 12.6, 7.5"},{"id":"html-077","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Um formulário tem method=\"get\" e um campo com name=\"q\". Onde lês o valor no servidor?","codigo":"","linguagem":"","alternativas":["$_GET['q']","$_SESSION['q']","$_GET['search']","$_POST['q']"],"correta":0,"explicacao":"Com GET, os campos vão no endereço e lêem-se em $_GET, com a chave do name.","manual":"7.5, 12.2"},{"id":"html-078","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Este link mostra o detalhe de um livro. Como chega o id ao servidor?","codigo":"<a href=\"livro_ver.php?id=7\">Ver detalhe →</a>","linguagem":"html","alternativas":["No corpo de um pedido POST, escondido; lê-se em $_POST['id'].","No endereço, num pedido GET; lê-se em $_GET['id'].","Não chega: os links não enviam valores.","Num cookie; lê-se em $_SESSION['id']."],"correta":1,"explicacao":"O que está depois do ? num link vai no endereço de um pedido GET e lê-se em $_GET.","manual":"1.2, 7.5, 12.3"},{"id":"html-079","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Na página de detalhe, o formulário do botão Apagar tem action=\"livro_apagar.php\". Para onde vão os dados quando é enviado?","codigo":"<form method=\"post\" action=\"livro_apagar.php\">\n    <input type=\"hidden\" name=\"id_livro\" value=\"3\">\n    <button type=\"submit\">Apagar</button>\n</form>","linguagem":"html","alternativas":["Para a página inicial.","Para a própria página de detalhe.","Para o livro_apagar.php.","Para o ficheiro onde o <form> foi escrito."],"correta":2,"explicacao":"Os dados vão sempre para o endereço do action, que pode ser outro ficheiro. O livro_apagar.php apaga e depois redireciona para a lista.","manual":"4.2, 4.4"},{"id":"html-080","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Com method=\"post\", a password fica protegida enquanto viaja até ao servidor?","codigo":"","linguagem":"","alternativas":["Não, porque o POST põe os dados no endereço.","Sim: só o servidor consegue ler o corpo de um pedido POST.","Sim: o POST cifra os dados do formulário.","Não: não aparece no endereço, mas vai em claro no corpo do pedido sem HTTPS."],"correta":3,"explicacao":"O POST tira os dados do endereço, mas não os cifra. Para não viajarem em claro, uma aplicação real precisa de HTTPS.","manual":"1.2, 14.3"},{"id":"html-081","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"O que faz o atributo target=\"_blank\" num link?","codigo":"","linguagem":"","alternativas":["Abre o link noutro separador.","Descarrega a página em vez de a mostrar.","Só abre o link se o formulário estiver preenchido.","Abre o link na mesma página, por cima do formulário."],"correta":0,"explicacao":"target=\"_blank\" abre o destino num separador novo, deixando a página atual como estava.","manual":"4.2, 15.2"},{"id":"html-082","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"No registo, porque é que o link para a política de privacidade tem target=\"_blank\"?","codigo":"<span>Li e aceito a\n    <a href=\"privacidade.php\" target=\"_blank\">política de privacidade</a>.\n</span>","linguagem":"html","alternativas":["Para a política não contar como uma página da aplicação.","Para o utilizador a ler noutro separador antes de aceitar, sem sair do formulário.","Porque a política tem de estar alojada noutro servidor.","Para a caixa do consentimento ficar assinalada ao abrir a política."],"correta":1,"explicacao":"O utilizador pode ler a política antes de aceitar, sem perder o que já escreveu no registo. A caixa tem de ser assinalada por ele.","manual":"15.2, 4.2"},{"id":"html-083","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que elemento se usa para o rodapé da página?","codigo":"","linguagem":"","alternativas":["<footnote>","<tfoot>","<foot>","<footer>"],"correta":3,"explicacao":"O rodapé é o <footer>; na Biblioteca tem o link para a política de privacidade. O <tfoot> é só para tabelas.","manual":"9.2"},{"id":"html-084","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que elemento agrupa os links de navegação do menu?","codigo":"","linguagem":"","alternativas":["<navigation>","<head>","<nav>","<links>"],"correta":2,"explicacao":"O menu está num <nav>, dentro do <header>. O <head> não mostra conteúdo.","manual":"9.2"},{"id":"html-085","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O cabeçalho da Biblioteca abre <main> e o rodapé fecha-o. O que fica dentro do <main>?","codigo":"","linguagem":"","alternativas":["O menu de navegação com os links.","O link para a política de privacidade.","A ligação ao CSS e ao JavaScript.","O conteúdo próprio de cada página, incluindo as mensagens."],"correta":3,"explicacao":"O <main> tem o conteúdo principal: as mensagens e tudo o que cada página escreve. O menu está no <header> e a política no <footer>.","manual":"9.2"},{"id":"html-086","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Na página de detalhe, os dados do livro estão numa lista <dl>. Qual é o papel de <dt> e <dd>?","codigo":"<dl>\n    <dt>Autor</dt>\n    <dd>José Saramago</dd>\n    <dt>Ano de edição</dt>\n    <dd>1982</dd>\n</dl>","linguagem":"html","alternativas":["<dt> é o nome do dado e <dd> é o seu valor.","<dt> e <dd> são itens de uma lista numerada.","<dt> é o valor e <dd> é o nome do dado.","<dt> é uma linha e <dd> é uma coluna de uma tabela."],"correta":0,"explicacao":"A <dl> é uma lista de pares termo/descrição: <dt> tem o termo (Autor) e <dd> a descrição (o nome do autor).","manual":"12.3"},{"id":"html-087","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Na lista de livros, cada livro aparece num <article class=\"cartao\">. Porque é um <article>?","codigo":"<article class=\"cartao\">\n    <h2>Memorial do Convento</h2>\n    <p class=\"meta\">José Saramago · 1982</p>\n    <a href=\"livro_ver.php?id=1\">Ver detalhe →</a>\n</article>","linguagem":"html","alternativas":["Porque o <article> é o único elemento que aceita display: flex no CSS.","Porque o <article> põe o título do livro a negrito.","Porque cada cartão é um bloco de conteúdo independente: um livro.","Porque o <article> é obrigatório dentro de um <main>."],"correta":2,"explicacao":"O <article> delimita um bloco que faz sentido sozinho, como o cartão de um livro. O aspeto (flexbox, negrito) vem do CSS, não do elemento.","manual":"12.2"},{"id":"html-088","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"Na lista de livros, o título da página está num <h1> e o título de cada livro num <h2>. Porquê?","codigo":"<h1>Livros</h1>\n<article class=\"cartao\">\n    <h2>Os Maias</h2>\n</article>\n<article class=\"cartao\">\n    <h2>Mensagem</h2>\n</article>","linguagem":"html","alternativas":["Só pode haver um <h2> por página, e os livros repetem-se.","O <h1> é o título principal da página; o <h2> é o título de cada parte.","O <h2> é maior do que o <h1>, por isso destaca os livros.","O <h1> só pode estar dentro do <header>."],"correta":1,"explicacao":"Os títulos têm níveis: <h1> para o título da página, <h2> para as secções dentro dela. O tamanho vem do CSS.","manual":"12.2"},{"id":"html-089","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"A Biblioteca mostra os erros de validação numa lista <ul> com um <li> por erro. Que tipo de lista é a <ul>?","codigo":"<ul>\n    <li>O email não é válido.</li>\n    <li>A password tem de ter pelo menos 8 caracteres.</li>\n</ul>","linguagem":"html","alternativas":["Uma lista de termos e descrições.","Uma tabela simples, com uma linha por item.","Uma lista numerada: 1, 2, 3...","Uma lista com pontos, sem números."],"correta":3,"explicacao":"A <ul> é uma lista com pontos, sem números; cada item é um <li>. A lista de termos e descrições é a <dl>.","manual":"9.4"},{"id":"html-090","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Qual é a forma correta de escrever um link para outra página?","codigo":"","linguagem":"","alternativas":["<a link=\"livros.php\">Livros</a>","<a href=\"livros.php\">Livros</a>","<a src=\"livros.php\">Livros</a>","<link href=\"livros.php\">Livros</link>"],"correta":1,"explicacao":"Um link é <a href=\"...\">texto</a>. O <link> só serve no <head>, para ligar o CSS.","manual":"4.4, Anexo B"},{"id":"html-091","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"A página de detalhe agrupa o título, os dados e os botões num <section class=\"detalhe\">. Para que serve o <section>?","codigo":"","linguagem":"","alternativas":["Agrupa uma parte da página com um tema comum.","Cria um formulário com os dados do livro.","Liga a página a outra secção do site.","Esconde o conteúdo até o utilizador clicar no título da secção."],"correta":0,"explicacao":"O <section> agrupa uma parte da página com um tema (aqui, o detalhe do livro). A classe \"detalhe\" serve para o CSS lhe dar aspeto.","manual":"12.3"},{"id":"html-092","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O formulário de pesquisa não tem id=\"form-principal\". Vendo o início do validacao.js, este atua sobre a pesquisa?","codigo":"document.addEventListener('DOMContentLoaded', function () {\n    const form = document.getElementById('form-principal');\n    if (!form) {\n        return; // esta página não tem formulário para validar\n    }\n    form.addEventListener('submit', function (event) {\n        // ... validações ...\n    });\n});","linguagem":"javascript","alternativas":["Não, porque o validacao.js só atua em formulários que têm o atributo novalidate.","Sim: o validacao.js atua em todos os formulários da página.","Não: o validacao.js só atua no formulário com id=\"form-principal\".","Sim, desde que o formulário tenha method=\"get\"."],"correta":2,"explicacao":"O validacao.js começa por getElementById('form-principal'); se não houver, não faz nada. Por isso a pesquisa não é validada.","manual":"6.3"},{"id":"html-093","bloco":"web","tema":"HTML e formulários","dificuldade":"media","pergunta":"O registo.php mostra o formulário e também recebe os dados (action=\"registo.php\"). Como distingue o PHP as duas situações?","codigo":"","linguagem":"","alternativas":["Vê se o $_GET tem a chave action.","Vê se $_SERVER['REQUEST_METHOD'] é 'POST'.","Vê se o id do formulário é form-principal.","Vê se o formulário tem o atributo novalidate."],"correta":1,"explicacao":"Abrir a página é um GET; enviar o formulário é um POST. O PHP vê o método em $_SERVER['REQUEST_METHOD'].","manual":"7.5, 10.2"},{"id":"html-094","bloco":"web","tema":"HTML e formulários","dificuldade":"facil","pergunta":"Que dois valores do atributo method se usam nos formulários desta UC?","codigo":"","linguagem":"","alternativas":["send e receive","get e put","post e delete","get e post"],"correta":3,"explicacao":"Nesta UC só se usam GET (ler dados, com os campos no endereço) e POST (alterar dados, com os campos no corpo do pedido).","manual":"1.2, 4.2"},{"id":"html-095","bloco":"web","tema":"HTML e formulários","dificuldade":"dificil","pergunta":"O registo foi enviado com a password curta e o servidor mostrou o formulário outra vez, com os erros. Que campos aparecem preenchidos?","codigo":"<input type=\"text\" id=\"nome\" name=\"nome\" required\n       value=\"<?= htmlspecialchars($nome) ?>\">\n<input type=\"email\" id=\"email\" name=\"email\" required\n       value=\"<?= htmlspecialchars($email) ?>\">\n<input type=\"password\" id=\"password\" name=\"password\" required>","linguagem":"html","alternativas":["Todos, porque o browser guarda o que foi escrito.","Nenhum, porque a página foi carregada de novo.","O nome e o email; a password aparece vazia.","Só o email, porque o type=\"email\" guarda o valor."],"correta":2,"explicacao":"Só os campos com value voltam preenchidos. O campo da password não tem value, por isso aparece vazio e o utilizador tem de a escrever outra vez.","manual":"4.2, 9.5"},{"id":"amostra-002","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Sabendo que estas três regras estão no mesmo ficheiro, por esta ordem, de que cor fica o texto de <p class=\"aviso\">Atenção</p>?","codigo":".aviso { color: blue; }\np      { color: red; }\n.aviso { color: orange; }","linguagem":"css","alternativas":["Vermelho, porque a regra p é a do meio.","Azul, porque é a primeira regra de classe.","Laranja.","Preto, porque as regras contraditórias anulam-se."],"correta":2,"explicacao":"A classe ganha ao elemento, por isso o vermelho perde. Entre as duas regras .aviso, igualmente específicas, ganha a que aparece mais abaixo no ficheiro: laranja.","manual":"5.3"},{"id":"css-001","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Que linha liga uma folha de estilos externa à página?","codigo":"","linguagem":"","alternativas":["<link rel=\"stylesheet\" href=\"css/estilo.css\">","<style src=\"css/estilo.css\"></style>","<script href=\"css/estilo.css\"></script>","<css rel=\"stylesheet\" src=\"css/estilo.css\">"],"correta":0,"explicacao":"Uma folha externa liga-se com <link rel=\"stylesheet\" href=\"...\">. O <style> não tem atributo src e o <script> serve para JavaScript.","manual":"5.1"},{"id":"css-002","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Em que parte da página se põe o <link> da folha de estilos?","codigo":"","linguagem":"","alternativas":["No fim do <body>, junto ao <script>.","Dentro do <footer>, no rodapé.","Dentro do <head>, antes do <body>.","Depois de </html>, no fim do ficheiro."],"correta":2,"explicacao":"O <link> vai no <head>: na Biblioteca está no cabecalho.php, a seguir ao <title>. Quem fica no fim do <body> é o <script> do JavaScript.","manual":"4.1, 5.1"},{"id":"css-003","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Queres mudar a cor de todos os botões da Biblioteca, em todas as páginas. O que tens de alterar?","codigo":"","linguagem":"","alternativas":["O atributo style de cada botão, página a página.","O cabecalho.php e o rodape.php, onde estão os botões.","Um bloco <style> no topo de cada ficheiro .php.","Só a regra dos botões no css/estilo.css."],"correta":3,"explicacao":"Todas as páginas ligam o mesmo ficheiro externo, por isso o aspeto do site inteiro muda num só sítio. É uma das duas vantagens de ter o CSS fora das páginas.","manual":"5.1"},{"id":"css-004","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Porque é que, com o CSS num ficheiro externo, as páginas seguintes carregam mais depressa?","codigo":"","linguagem":"","alternativas":["O browser guarda o ficheiro em cache e reutiliza-o.","O servidor envia o CSS já misturado no HTML.","O PHP aplica os estilos antes de enviar a página.","O ficheiro externo só é lido quando se carrega em F5."],"correta":0,"explicacao":"O browser descarrega o estilo.css uma vez e guarda-o em cache; nas páginas seguintes já o tem. O CSS é sempre aplicado no browser, nunca pelo PHP.","manual":"5.1"},{"id":"css-005","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Para que serve o atributo rel=\"stylesheet\" no <link>?","codigo":"","linguagem":"","alternativas":["Indica o caminho do ficheiro .css a carregar.","Diz ao browser que o ficheiro ligado é uma folha de estilos.","Faz com que os estilos só se apliquem a esta página.","Dá às regras do ficheiro prioridade sobre as outras."],"correta":1,"explicacao":"O rel diz que tipo de relação tem o ficheiro com a página (aqui, folha de estilos). O caminho vai no href.","manual":"5.1"},{"id":"css-006","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"O ficheiro está em css/estilo.css e a página livros.php está na pasta principal do projeto. O cabeçalho tem esta linha e a página aparece sem estilos. Qual é o problema?","codigo":"<link rel=\"stylesheet\" href=\"estilo.css\">","linguagem":"html","alternativas":["O href devia ser css/estilo.css.","Falta o atributo type=\"text/css\" no <link>.","O <link> só funciona se estiver dentro do <body>.","O rel devia ser \"style\" e não \"stylesheet\"."],"correta":0,"explicacao":"O href é um caminho para o ficheiro: sem css/ o browser procura estilo.css ao lado da página e não o encontra. Na Biblioteca é href=\"css/estilo.css\".","manual":"5.1, 2.5"},{"id":"css-007","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Onde corre o CSS de uma aplicação como a Biblioteca?","codigo":"","linguagem":"","alternativas":["No servidor Apache, antes de enviar a página.","No MySQL, junto com os dados.","No browser do utilizador.","No PHP, dentro do cabecalho.php."],"correta":2,"explicacao":"HTML, CSS e JavaScript correm no browser. O PHP corre no servidor e só envia o texto do HTML, onde está o <link> para o CSS.","manual":"1.4"},{"id":"css-008","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Qual é o erro neste <head>?","codigo":"<head>\n    <meta charset=\"UTF-8\">\n    <title>Livros</title>\n    <style src=\"css/estilo.css\"></style>\n</head>","linguagem":"html","alternativas":["O <style> tem de ficar dentro do <body> para ser aplicado.","Para ligar um ficheiro usa-se <link>, não <style src>.","Falta o atributo rel=\"stylesheet\" dentro do <style>.","O caminho do ficheiro tem de começar por http://localhost."],"correta":1,"explicacao":"Não existe <style src>. Uma folha externa liga-se sempre com <link rel=\"stylesheet\" href=\"css/estilo.css\">.","manual":"5.1"},{"id":"css-009","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Um colega copiou o mesmo CSS para um bloco <style> em cada página. Que desvantagem tem isto em relação ao estilo.css?","codigo":"","linguagem":"","alternativas":["As regras dentro de <style> só se aplicam ao primeiro elemento.","O <style> só funciona quando o JavaScript está ligado.","O PHP deixa de conseguir incluir o cabeçalho.","Cada mudança de aspeto obriga a alterar todas as páginas."],"correta":3,"explicacao":"Com os estilos espalhados pelas páginas perde-se a grande vantagem do ficheiro externo: mudar o aspeto num só sítio (e o browser guardá-lo em cache).","manual":"5.1"},{"id":"css-010","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Que linha do <head> faz a página adaptar-se à largura do telemóvel?","codigo":"","linguagem":"","alternativas":["<meta charset=\"UTF-8\">","<meta name=\"viewport\" ...>","<link rel=\"stylesheet\" media=\"mobile\">","<html lang=\"pt\">"],"correta":1,"explicacao":"A meta viewport faz a página usar a largura real do ecrã do telemóvel. O charset trata dos acentos e o lang indica a língua.","manual":"4.1, 5.5"},{"id":"css-011","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Numa regra de CSS, o que é o seletor?","codigo":".cartao {\n    padding: 18px;\n}","linguagem":"css","alternativas":["O nome que aparece antes dos dois pontos, dentro das chavetas.","A parte antes das chavetas, que diz a que elementos a regra se aplica.","O valor que aparece depois dos dois pontos.","O bloco entre as chavetas, com as propriedades."],"correta":1,"explicacao":"Cada regra tem um seletor (aqui .cartao) e um bloco de propriedades entre chavetas, cada uma com propriedade: valor;.","manual":"5.2"},{"id":"css-012","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Qual destas regras está escrita corretamente?","codigo":"","linguagem":"","alternativas":[".btn ( color = #ffffff; )",".btn { color = #ffffff, }",".btn { color: #ffffff; }",".btn [ color: #ffffff ]"],"correta":2,"explicacao":"O bloco vai entre chavetas e cada declaração é propriedade: valor; (dois pontos e ponto e vírgula).","manual":"5.2"},{"id":"css-013","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Como se escreve um comentário numa folha de estilos?","codigo":"","linguagem":"","alternativas":["// Botões","<!-- Botões -->","/* Botões */","# Botões"],"correta":2,"explicacao":"Em CSS os comentários ficam entre /* e */, como os que dividem o estilo.css em partes numeradas. // é de JavaScript e <!-- --> de HTML.","manual":"Anexo A"},{"id":"css-014","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Esta regra tem um ponto e vírgula em falta. O que acontece ao cartão?","codigo":".cartao {\n    background: #ffffff\n    border-radius: 8px;\n    padding: 18px;\n}","linguagem":"css","alternativas":["Toda a regra é ignorada, incluindo o padding.","O fundo e os cantos não se aplicam, mas o padding sim.","Funciona tudo, porque o ponto e vírgula é opcional.","A página deixa de abrir e aparece um erro no browser."],"correta":1,"explicacao":"Sem o ;, o browser lê \"#ffffff border-radius: 8px\" como um único valor inválido e ignora essa declaração. O CSS não dá erro: continua na declaração seguinte.","manual":"5.2"},{"id":"css-015","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"A que elementos se aplica o seletor p?","codigo":"p {\n    color: red;\n}","linguagem":"css","alternativas":["Ao elemento com id=\"p\".","A todos os parágrafos da página.","Aos elementos com class=\"p\".","Só ao primeiro parágrafo da página."],"correta":1,"explicacao":"Um seletor de elemento, sem ponto nem cardinal, aplica-se a todos os elementos com esse nome.","manual":"5.2"},{"id":"css-016","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Que seletor escolhe todos os elementos com class=\"btn\"?","codigo":"","linguagem":"","alternativas":["#btn","btn","*btn",".btn"],"correta":3,"explicacao":"O ponto indica uma classe. # é para id e btn sozinho procuraria elementos <btn>, que não existem.","manual":"5.2"},{"id":"css-017","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Que seletor escolhe o elemento com id=\"erros-js\"?","codigo":"","linguagem":"","alternativas":[".erros-js","erros-js","#erros-js","@erros-js"],"correta":2,"explicacao":"O cardinal (#) seleciona pelo id; o ponto seleciona pela classe.","manual":"5.2"},{"id":"css-018","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Qual é a diferença entre um id e uma classe?","codigo":"","linguagem":"","alternativas":["A classe é de um único elemento; o id pode repetir-se.","O id só serve para o CSS e a classe só para o JavaScript.","O id é de um único elemento na página; a classe pode repetir-se.","Não há diferença: # e . são duas formas de escrever o mesmo."],"correta":2,"explicacao":"Só existe um elemento com cada id em cada página (como diz o comentário do estilo.css). Uma classe, como btn, pode estar em muitos elementos.","manual":"5.2, Anexo A"},{"id":"css-019","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Na Biblioteca, um <a href=\"livros.php\" class=\"btn\"> parece um botão verde, tal como os <button>. Porquê?","codigo":".btn,\nbutton {\n    background: #00713c;\n    color: #ffffff;\n}","linguagem":"css","alternativas":["A regra aplica-se a qualquer elemento com a classe btn, seja <a> ou não.","O browser converte os <a> com classe em <button>.","O seletor button também se aplica aos links que estão dentro de um formulário.","Os links herdam sempre o aspeto dos botões da página."],"correta":0,"explicacao":"Um seletor de classe não olha para o nome do elemento: qualquer elemento com class=\"btn\" recebe a regra. O button aplica-se só aos <button>.","manual":"5.2"},{"id":"css-020","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Tens <div id=\"total\" class=\"caixa\">. Qual destes seletores NÃO apanha este elemento?","codigo":"","linguagem":"","alternativas":["#total",".caixa","div",".total"],"correta":3,"explicacao":"total é o id, por isso seleciona-se com #total. .total procuraria um elemento com class=\"total\".","manual":"5.2"},{"id":"css-021","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Que efeito tem esta combinação de CSS e JavaScript na caixa <div id=\"erros-js\">?","codigo":"/* estilo.css */\n#erros-js {\n    display: none;\n}\n\n// validacao.js, quando há erros\ncaixa.style.display = 'block';","linguagem":"css","alternativas":["Nunca aparece, porque o estilo.css ganha ao JavaScript.","Aparece sempre, porque o display: none só vale no telemóvel.","Começa escondida e só aparece quando o JavaScript encontra erros.","Aparece sempre, porque o JavaScript corre antes do CSS."],"correta":2,"explicacao":"O estilo.css esconde a caixa ao carregar a página. Quando há erros, o validacao.js muda o estilo do próprio elemento para display: block e a caixa aparece.","manual":"6.2, Anexo A"},{"id":"css-022","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"A que elementos se aplica o seletor .topo nav a?","codigo":"","linguagem":"","alternativas":["Aos elementos que são ao mesmo tempo .topo, <nav> e <a>.","Aos <a> dentro de um <nav> dentro de um .topo.","A todos os elementos .topo, a todos os <nav> e a todos os <a>.","Ao primeiro <a> que aparece a seguir a um <nav>."],"correta":1,"explicacao":"Os espaços indicam descendência: lê-se da direita para a esquerda, \"os a dentro de nav dentro de .topo\". Para aplicar a vários seletores usa-se a vírgula.","manual":"5.2"},{"id":"css-023","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Com esta regra, que parágrafo fica cinzento?","codigo":"/* CSS */\n.cartao .meta { color: #6b7780; }\n\n<!-- HTML -->\n<p class=\"meta\">A</p>\n<article class=\"cartao\">\n    <p class=\"meta\">B</p>\n</article>","linguagem":"css","alternativas":["Só o A.","O A e o B.","Nenhum dos dois.","Só o B."],"correta":3,"explicacao":"O espaço em .cartao .meta quer dizer \"um .meta dentro de um .cartao\". O A está fora de qualquer cartão, por isso a regra não se lhe aplica.","manual":"5.2"},{"id":"css-024","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Qual é a diferença entre .formulario input e .formulario, input?","codigo":"","linguagem":"","alternativas":["O primeiro apanha .formulario e todos os input; o segundo só os input dentro de .formulario.","O primeiro só apanha os input dentro de .formulario; o segundo apanha .formulario e todos os input.","São iguais: o espaço e a vírgula têm o mesmo significado.","O primeiro dá erro, porque falta a vírgula entre os dois seletores."],"correta":1,"explicacao":"O espaço é o seletor descendente; a vírgula é o agrupamento, que aplica o mesmo bloco a dois seletores independentes.","manual":"5.2"},{"id":"css-025","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Com este HTML, qual das duas regras se aplica à lista <ul>?","codigo":"/* CSS */\n.msg ul { padding-left: 20px; }\nul.msg { padding-left: 36px; }\n\n<!-- HTML -->\n<div class=\"msg erro\">\n    <ul>\n        <li>O título é obrigatório.</li>\n    </ul>\n</div>","linguagem":"css","alternativas":["Só ul.msg.","Só .msg ul.","As duas.","Nenhuma das duas."],"correta":1,"explicacao":".msg ul (com espaço) apanha um <ul> dentro de um .msg, que é o caso. ul.msg (sem espaço) só apanharia um <ul> que tivesse ele próprio a classe msg.","manual":"5.2, Anexo A"},{"id":"css-026","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"O que seleciona ul.msg, escrito sem espaço?","codigo":"","linguagem":"","alternativas":["Os <ul> que estão dentro de um .msg.","Todos os <ul> e todos os .msg.","Os .msg que estão dentro de um <ul>.","Os <ul> que têm a classe msg."],"correta":3,"explicacao":"Sem espaço, os dois seletores aplicam-se ao mesmo elemento: um <ul> com class=\"msg\". Com espaço seria um descendente.","manual":"Anexo A"},{"id":"css-027","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"O que faz a vírgula nesta regra?","codigo":".btn,\nbutton {\n    cursor: pointer;\n}","linguagem":"css","alternativas":["Aplica o mesmo bloco aos elementos .btn e aos <button>.","Aplica o bloco só aos <button> que estão dentro de um .btn.","Aplica o bloco só aos elementos que são .btn e <button> ao mesmo tempo.","Separa duas propriedades dentro do mesmo bloco."],"correta":0,"explicacao":"A vírgula agrupa seletores: é como escrever duas regras iguais, uma para .btn e outra para button.","manual":"5.2"},{"id":"css-028","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"A que elementos se aplica esta regra?","codigo":".formulario input,\n.formulario select,\n.formulario textarea {\n    padding: 9px 10px;\n}","linguagem":"css","alternativas":["A todos os input, select e textarea da página.","Ao .formulario e a todos os campos da página.","Só aos campos que tenham ao mesmo tempo as três etiquetas.","Aos input, select e textarea que estão dentro de .formulario."],"correta":3,"explicacao":"São três seletores descendentes agrupados com vírgulas. Cada um começa por .formulario, por isso só os campos dentro do formulário são apanhados.","manual":"5.2, Anexo A"},{"id":"css-029","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Um aluno simplificou a regra assim. O que acontece a um <select> que está fora de qualquer formulário?","codigo":".formulario input,\nselect {\n    border: 1px solid #c9d0d4;\n}","linguagem":"css","alternativas":["Não recebe a borda, porque .formulario vale para os dois seletores.","Não recebe a borda, porque a regra fica inválida sem o segundo .formulario.","Só recebe a borda quando o rato está por cima.","Também recebe a borda, porque select ficou sozinho depois da vírgula."],"correta":3,"explicacao":"Cada seletor do grupo é independente. O segundo é só select, que se aplica a todos os <select> da página.","manual":"5.2"},{"id":"css-030","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"O que seleciona .btn.perigo, escrito sem espaço?","codigo":"","linguagem":"","alternativas":["Os elementos .perigo que estão dentro de um .btn.","Todos os elementos .btn e todos os elementos .perigo.","Os elementos que têm as duas classes, btn e perigo.","Os elementos com uma classe chamada \"btn.perigo\"."],"correta":2,"explicacao":"Sem espaço, as duas classes aplicam-se ao mesmo elemento. É assim que se escolhe o botão vermelho de apagar.","manual":"5.2"},{"id":"css-031","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Queres um link com o aspeto de .btn e também o vermelho de .btn.perigo. Que HTML escreves?","codigo":"","linguagem":"","alternativas":["<a href=\"...\" class=\"btn perigo\">Apagar</a>","<a href=\"...\" class=\"btn.perigo\">Apagar</a>","<a href=\"...\" class=\"btn, perigo\">Apagar</a>","<a href=\"...\" class=\"btn\" class=\"perigo\">Apagar</a>"],"correta":0,"explicacao":"Várias classes escrevem-se no mesmo atributo class, separadas por espaços. O ponto só se usa no CSS; um segundo atributo class seria ignorado.","manual":"5.2"},{"id":"css-032","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"O botão continua verde em vez de ficar vermelho. Porquê?","codigo":"/* CSS */\n.btn { background: #00713c; }\n.btn .perigo { background: #c0392b; }\n\n<!-- HTML -->\n<a href=\"...\" class=\"btn perigo\">Apagar</a>","linguagem":"css","alternativas":["A regra .btn ganha porque aparece primeiro no ficheiro.","Um elemento só pode ter uma classe; a segunda é ignorada.","Com espaço, procura um .perigo dentro de um .btn.","O vermelho só se aplica a <button>, nunca a links."],"correta":2,"explicacao":"Para as duas classes no mesmo elemento escreve-se .btn.perigo, sem espaço. Com espaço é um seletor descendente.","manual":"5.2"},{"id":"css-033","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Que regras se aplicam a <div class=\"msg sucesso\">?","codigo":".msg { padding: 12px 16px; border-left: 5px solid; }\n.msg.sucesso { background: #e6f4ec; }\n.msg.erro { background: #fdecea; }","linguagem":"css","alternativas":["Só .msg.sucesso.",".msg e .msg.sucesso.","Só .msg, a primeira classe do atributo.","As três, porque todas começam por .msg."],"correta":1,"explicacao":"O elemento tem as classes msg e sucesso, por isso recebe a regra .msg e a .msg.sucesso. A .msg.erro exige a classe erro, que ele não tem.","manual":"5.2, 9.3"},{"id":"css-034","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"No cabeçalho, $_SESSION['msg']['tipo'] vale 'erro'. Que regras do estilo.css recebe a caixa?","codigo":"<div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\">\n    <?= htmlspecialchars($_SESSION['msg']['texto']) ?>\n</div>","linguagem":"php","alternativas":["Só a regra .msg.erro, por ser a mais específica.","As regras de .msg e as de .msg.erro.","Nenhuma, porque a classe é escrita pelo PHP.","As regras de .msg e as de .msg.sucesso."],"correta":1,"explicacao":"O PHP escreve class=\"msg erro\" no HTML e o browser aplica-lhe as duas regras: .msg dá o espaçamento e a borda, .msg.erro dá o fundo vermelho. Ser mais específica só decide as propriedades em conflito, não apaga as outras.","manual":"9.3, Anexo A"},{"id":"css-035","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Quando se aplica a regra .btn:hover?","codigo":"","linguagem":"","alternativas":["Depois de o utilizador clicar no elemento.","Quando a página acaba de carregar.","Quando o link já foi visitado.","Enquanto o rato está por cima do elemento."],"correta":3,"explicacao":":hover é uma pseudo-classe que só vale enquanto o rato está por cima. Na Biblioteca serve para o botão escurecer.","manual":"5.2"},{"id":"css-036","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Passas o rato por cima de um botão e depois tiras. De que cor fica o fundo?","codigo":".btn { background: #00713c; }\n.btn:hover { background: #005a30; }","linguagem":"css","alternativas":["Fica com a cor de .btn:hover até se recarregar a página.","Fica com a cor de .btn:hover, porque é a regra mais abaixo.","Fica sem fundo, porque as duas regras se anulam.","Volta à cor de .btn quando o rato sai."],"correta":3,"explicacao":"A regra .btn:hover só se aplica durante o hover. Quando o rato sai, só sobra a regra .btn.","manual":"5.2"},{"id":"css-037","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Como se chama o :hover em .btn:hover?","codigo":"","linguagem":"","alternativas":["Seletor de id.","Pseudo-classe.","Seletor descendente.","Media query."],"correta":1,"explicacao":"O manual chama-lhe pseudo-classe: aplica a regra conforme o estado do elemento (aqui, o rato estar por cima).","manual":"5.2"},{"id":"css-038","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Na Biblioteca, quando é que um link do menu fica branco?","codigo":".topo nav a { color: #d5dbdf; }\n.topo nav a:hover { color: #ffffff; }","linguagem":"css","alternativas":["Quando o rato passa por cima dele.","Sempre, porque a segunda regra está mais abaixo.","Quando é o link da página onde estás.","Só no telemóvel, por causa da media query."],"correta":0,"explicacao":"A segunda regra tem :hover, por isso só vale enquanto o rato está por cima. No resto do tempo o link fica com a cor da primeira.","manual":"5.2, Anexo A"},{"id":"css-039","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"A que elementos se aplica o seletor * do início do estilo.css?","codigo":"* {\n    box-sizing: border-box;\n}","linguagem":"css","alternativas":["Só ao elemento <body>.","Só aos elementos que têm uma classe.","A todos os elementos da página.","Só aos elementos que têm um id."],"correta":2,"explicacao":"O asterisco é o seletor universal: escolhe todos os elementos. Por isso o box-sizing vale para a página inteira.","manual":"Anexo A"},{"id":"css-040","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Duas regras dão cores diferentes ao mesmo elemento. Qual é a ordem de força dos seletores, do mais forte para o mais fraco?","codigo":"","linguagem":"","alternativas":["classe, id, elemento.","id, classe, elemento.","elemento, classe, id.","id, elemento, classe."],"correta":1,"explicacao":"Ganha a regra mais específica: o id ganha à classe e a classe ganha ao elemento.","manual":"5.3"},{"id":"css-041","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Duas regras igualmente específicas dão valores diferentes à mesma propriedade. Qual ganha?","codigo":"","linguagem":"","alternativas":["A que aparece mais acima no ficheiro.","A que tem mais propriedades no bloco.","A que aparece mais abaixo no ficheiro.","Nenhuma: o browser usa o valor por omissão."],"correta":2,"explicacao":"Em caso de empate na especificidade, ganha a última, a que está mais abaixo no ficheiro.","manual":"5.3"},{"id":"css-042","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"De que cor fica o texto de <p class=\"destaque\" id=\"total\">Total</p>?","codigo":"#total    { color: green; }\n.destaque { color: blue; }\np         { color: red; }","linguagem":"css","alternativas":["Azul.","Vermelho.","Verde.","Preto, porque as regras se anulam."],"correta":2,"explicacao":"O id é o seletor mais específico e ganha à classe e ao elemento, mesmo estando em cima. A ordem só desempata regras igualmente específicas.","manual":"5.3"},{"id":"css-043","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"De que cor fica o título <h1 class=\"titulo\">Livros</h1>?","codigo":".titulo { color: blue; }\nh1      { color: red; }","linguagem":"css","alternativas":["Vermelho, porque a regra h1 está mais abaixo.","Azul, porque a classe é mais específica do que o elemento.","Vermelho, porque o elemento ganha sempre à classe.","Roxo, porque as duas cores se misturam."],"correta":1,"explicacao":"A classe ganha ao elemento. A posição no ficheiro só conta quando as regras são igualmente específicas.","manual":"5.3"},{"id":"css-044","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Na Biblioteca existem estas duas regras. De que cor ficam os links do menu (dentro de .topo nav)?","codigo":"a {\n    color: #00713c;\n}\n\n.topo nav a {\n    color: #d5dbdf;\n}","linguagem":"css","alternativas":["Com a cor de a, porque se aplica a todos os links da página.","Com a cor de a, porque a regra está mais acima.","Com a cor de .topo nav a, que é mais específica.","Alternam entre as duas cores, link sim, link não."],"correta":2,"explicacao":".topo nav a tem uma classe e é mais específica do que o seletor de elemento a. Os outros links da página ficam com a cor de a.","manual":"5.3, Anexo A"},{"id":"css-045","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"De que cor fica o fundo de <a href=\"livros.php\" class=\"btn secundario\">Voltar</a>?","codigo":".btn { background: #00713c; }\n/* ... */\n.btn.secundario { background: #d5dbdf; }","linguagem":"css","alternativas":["Cinzento claro (o de .btn.secundario).","Verde (o de .btn), porque é a classe principal.","Depende da ordem das classes no atributo class.","Sem fundo, porque as duas regras entram em conflito."],"correta":0,"explicacao":"A regra .btn.secundario é mais específica (duas classes) e, além disso, está mais abaixo. A ordem das classes dentro do atributo class não conta.","manual":"5.3, Anexo A"},{"id":"css-046","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Acrescentaste esta regra no fim do estilo.css. Como ficam os cartões?","codigo":"/* mais acima no ficheiro */\n.cartao {\n    background: #ffffff;\n    border-radius: 8px;\n    padding: 18px;\n}\n\n/* no fim do ficheiro */\n.cartao {\n    background: #eeeeee;\n}","linguagem":"css","alternativas":["Com fundo #eeeeee, mantendo os cantos e o padding da primeira regra.","Com fundo #eeeeee, mas sem cantos arredondados nem padding.","Com fundo #ffffff, porque a primeira regra é a mais completa.","Sem nenhum estilo, porque há duas regras com o mesmo seletor."],"correta":0,"explicacao":"A cascata decide propriedade a propriedade. Só o background está em conflito e ganha a regra mais abaixo; o resto continua a vir da primeira.","manual":"5.3"},{"id":"css-047","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Esta caixa existe na página do registo. Aparece quando a página carrega?","codigo":"/* CSS */\n.msg      { padding: 12px 16px; border-left: 5px solid; }\n.msg.erro { background: #fdecea; }\n#erros-js { display: none; }\n\n<!-- HTML -->\n<div id=\"erros-js\" class=\"msg erro\"></div>","linguagem":"css","alternativas":["Sim: as duas classes ganham ao id, por serem mais.","Não: #erros-js põe display: none e nada o muda.","Sim: .msg.erro está mais acima e por isso ganha.","Só aparece no telemóvel, por causa do display: none."],"correta":1,"explicacao":"As regras somam-se: a caixa recebe o padding, a borda e o fundo das classes, e o display: none do id. Como nenhuma outra regra mexe no display, fica escondida até o JavaScript a mostrar.","manual":"5.3, 6.2, Anexo A"},{"id":"css-048","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Duas regras com o mesmo seletor dão cores diferentes ao texto de .vazio. O que decide qual ganha?","codigo":".vazio { color: #6b7780; }\n/* ... muitas linhas ... */\n.vazio { color: black; }","linguagem":"css","alternativas":["A posição: ganha a que está mais abaixo.","A cor mais escura ganha sempre.","A primeira, porque foi definida antes.","O browser mistura as duas cores."],"correta":0,"explicacao":"Os seletores são iguais, por isso têm a mesma especificidade. Nesse caso ganha a regra que aparece mais abaixo no ficheiro.","manual":"5.3"},{"id":"css-049","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Que propriedade muda a cor do texto?","codigo":"","linguagem":"","alternativas":["background-color","color","font-color","text-color"],"correta":1,"explicacao":"color é a cor do texto; background-color (ou background) é a cor do fundo. font-color e text-color não existem.","manual":"5.2, Anexo B"},{"id":"css-050","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Queres texto branco sobre fundo verde num aviso. Qual é a regra certa?","codigo":"","linguagem":"","alternativas":[".aviso { color: green; background-color: white; }",".aviso { font-color: white; background: green; }",".aviso { text-color: white; color-background: green; }",".aviso { color: white; background-color: green; }"],"correta":3,"explicacao":"color pinta o texto e background-color pinta o fundo. Trocá-las dá texto verde em fundo branco.","manual":"5.2, Anexo B"},{"id":"css-051","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Qual é a diferença entre padding e margin?","codigo":"","linguagem":"","alternativas":["padding é o espaço fora do elemento; margin é o espaço dentro, até ao texto.","padding só existe em botões; margin serve para todos os elementos.","padding é o espaço dentro do elemento; margin é o espaço fora, até aos vizinhos.","São iguais: padding é o nome antigo de margin."],"correta":2,"explicacao":"O padding fica entre o conteúdo e a borda (por isso tem a cor de fundo do elemento). A margin fica do lado de fora da borda e afasta os outros elementos.","manual":"Anexo A"},{"id":"css-052","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"O que quer dizer este padding com dois valores?","codigo":".msg {\n    padding: 12px 16px;\n}","linguagem":"css","alternativas":["12px à esquerda e à direita, 16px em cima e em baixo.","12px em cima e em baixo, 16px à esquerda e à direita.","12px em cima, 16px em baixo e nada dos lados.","Um padding entre 12px e 16px, conforme o ecrã."],"correta":1,"explicacao":"Com dois valores, o primeiro vale para cima e baixo e o segundo para a esquerda e a direita.","manual":"Anexo A"},{"id":"css-053","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"O que fazem estas duas propriedades em conjunto?","codigo":"main {\n    max-width: 960px;\n    margin: 32px auto;\n}","linguagem":"css","alternativas":["Fixam a largura em 960px e encostam o conteúdo à esquerda.","Centram o texto dentro do main, linha a linha.","Limitam a largura do conteúdo e centram-no na horizontal.","Centram o conteúdo na vertical, a meio do ecrã."],"correta":2,"explicacao":"max-width impede que o conteúdo passe de 960px e margin com auto à esquerda e à direita reparte o espaço que sobra, centrando-o. Para centrar texto usa-se text-align: center.","manual":"Anexo A"},{"id":"css-054","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Num telemóvel com 400px de largura, que largura tem o main?","codigo":"main {\n    max-width: 960px;\n    margin: 32px auto;\n    padding: 0 20px;\n}","linguagem":"css","alternativas":["960px, e aparece uma barra de scroll horizontal.","960px reduzidos a metade, por causa do auto.","Zero, porque o ecrã é mais estreito do que o máximo.","A largura do ecrã, porque max-width é só um limite máximo."],"correta":3,"explicacao":"max-width não fixa a largura: só impede que passe de 960px. Num ecrã mais estreito, o main ocupa a largura disponível. Um width: 960px é que obrigaria ao scroll.","manual":"Anexo A"},{"id":"css-055","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"O que faz border-radius: 8px num cartão?","codigo":"","linguagem":"","alternativas":["Põe uma borda de 8px à volta.","Afasta o cartão 8px dos vizinhos.","Põe uma sombra de 8px por baixo.","Arredonda os cantos."],"correta":3,"explicacao":"border-radius arredonda os cantos do elemento. A espessura da borda define-se com border.","manual":"Anexo A"},{"id":"css-056","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Como fica o cartão com esta declaração?","codigo":".cartao {\n    border-top: 4px solid #00713c;\n}","linguagem":"css","alternativas":["Com uma linha contínua de 4px só no topo.","Com uma borda de 4px nos quatro lados.","Afastado 4px do elemento de cima.","Com 4px de espaço entre o topo e o texto."],"correta":0,"explicacao":"border-top só desenha a borda de cima. Os três valores são a espessura, o estilo (solid = linha contínua) e a cor.","manual":"Anexo A"},{"id":"css-057","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Em border: 1px solid #c9d0d4, o que são os três valores?","codigo":"","linguagem":"","alternativas":["A cor, a espessura e o estilo da linha.","A largura, a altura e a cor do elemento.","O padding, a margin e a cor da borda.","A espessura, o estilo da linha e a cor."],"correta":3,"explicacao":"A propriedade border junta espessura (1px), estilo (solid, linha contínua) e cor.","manual":"Anexo A"},{"id":"css-058","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"De que cor fica a borda esquerda de <div class=\"msg sucesso\">?","codigo":".msg {\n    border-left: 5px solid;\n}\n\n.msg.sucesso {\n    border-color: #00713c;\n}","linguagem":"css","alternativas":["Com a cor de .msg.sucesso, numa borda de 5px.","Sem borda, porque .msg não indica a cor.","Com a cor do texto, porque border-color só vale para as outras bordas.","Com 5px nos quatro lados, com a cor de .msg.sucesso."],"correta":0,"explicacao":"A .msg cria uma borda esquerda de 5px sem cor; a .msg.sucesso dá-lhe a cor. Assim a mesma borda fica verde nas mensagens de sucesso e vermelha nas de erro.","manual":"Anexo A, 9.3"},{"id":"css-059","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Que propriedade centra o texto do rodapé na horizontal?","codigo":"","linguagem":"","alternativas":["align-items: center","text-align: center","justify-content: center","margin: center"],"correta":1,"explicacao":"text-align: center centra o texto. align-items e justify-content são do flexbox e alinham elementos-filho, não linhas de texto.","manual":"Anexo A"},{"id":"css-060","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Para que serve text-decoration: none nos links do menu e nos .btn?","codigo":"","linguagem":"","alternativas":["Esconde o link quando o rato não está por cima.","Tira a cor azul dos links visitados.","Impede que o link seja clicado.","Tira o sublinhado que os links têm por omissão."],"correta":3,"explicacao":"Os links aparecem sublinhados por omissão; text-decoration: none tira o sublinhado, o que dá jeito em links com aspeto de botão.","manual":"Anexo A"},{"id":"css-061","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"O que faz cursor: pointer nos botões?","codigo":"","linguagem":"","alternativas":["Faz o botão seguir o rato pela página.","Põe o cursor de texto dentro do botão.","Mostra a mãozinha quando o rato passa por cima.","Muda a cor do botão quando se clica."],"correta":2,"explicacao":"cursor: pointer muda o ponteiro do rato para a mão, mostrando que o elemento é clicável.","manual":"Anexo A"},{"id":"css-062","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Porque é que os .btn usam display: inline-block?","codigo":"","linguagem":"","alternativas":["Ficam escondidos até o rato passar por cima deles.","Ficam na linha do texto, mas aceitam padding.","Ocupam a linha toda, como um parágrafo.","Passam a pôr os seus filhos lado a lado."],"correta":1,"explicacao":"inline-block mantém o botão ao lado do texto e dos outros botões, mas respeita o padding e as dimensões. Para pôr filhos lado a lado é o display: flex no contentor.","manual":"Anexo A"},{"id":"css-063","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"O que acontece a um elemento com display: none?","codigo":"","linguagem":"","alternativas":["Deixa de aparecer e não ocupa espaço na página.","Fica transparente, mas continua a ocupar o seu espaço.","É apagado do ficheiro HTML pelo browser.","Fica por baixo dos outros elementos."],"correta":0,"explicacao":"display: none esconde o elemento por completo: os outros ocupam o seu lugar. O elemento continua no HTML e pode voltar a aparecer, como a caixa #erros-js.","manual":"Anexo A, 6.2"},{"id":"css-064","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Em font-size: 1.7rem, o que quer dizer rem?","codigo":"","linguagem":"","alternativas":["Um número fixo de píxeis do ecrã.","Uma percentagem da largura do elemento-pai.","Um múltiplo do tamanho de letra base da página.","Uma percentagem da altura do ecrã."],"correta":2,"explicacao":"1rem é o tamanho de letra base; 1.7rem é 1,7 vezes esse tamanho e 0.9rem é um pouco menor. px é a unidade fixa e % é relativa ao elemento-pai.","manual":"Anexo A"},{"id":"css-065","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Que largura tem uma tabela com width: 100%?","codigo":".tabela {\n    width: 100%;\n}","linguagem":"css","alternativas":["Toda a largura do ecrã, mesmo que fique cortada.","Toda a largura do elemento onde está.","100 píxeis.","A largura do seu conteúdo, mais 100%."],"correta":1,"explicacao":"Uma percentagem é relativa ao elemento que contém a tabela: aqui, ocupa a largura toda do main.","manual":"Anexo A"},{"id":"css-066","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"O que faz font: inherit nos botões e nos campos do formulário?","codigo":"","linguagem":"","alternativas":["Herdam o tipo de letra do elemento-pai.","Passam o seu tipo de letra a todos os elementos da página.","Ficam com o tipo de letra por omissão do browser.","Mudam o tipo de letra conforme o tamanho do ecrã."],"correta":0,"explicacao":"inherit quer dizer \"herdar do pai\". Os botões e campos têm um tipo de letra próprio do browser; assim ficam iguais ao resto da página.","manual":"Anexo A"},{"id":"css-067","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Que propriedade põe o texto em negrito, como nas etiquetas do formulário?","codigo":"","linguagem":"","alternativas":["font-weight","font-size","font-style","text-decoration"],"correta":0,"explicacao":"font-weight define a grossura da letra (bold ou 600). font-style é para o itálico e font-size para o tamanho.","manual":"Anexo A"},{"id":"css-068","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Para que serve white-space: nowrap nos links do menu?","codigo":".topo nav a {\n    white-space: nowrap;\n}","linguagem":"css","alternativas":["Impede que o texto de um link se parta em duas linhas.","Tira os espaços entre os links do menu.","Esconde o link quando não há espaço.","Impede que os links passem para a linha seguinte."],"correta":0,"explicacao":"nowrap mantém \"A minha conta\" numa só linha. Os links como um todo podem passar para a linha seguinte (o nav tem flex-wrap: wrap), mas não se partem ao meio.","manual":"Anexo A"},{"id":"css-069","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Com esta regra, que largura total ocupa a caixa?","codigo":"* { box-sizing: border-box; }\n\n.caixa {\n    width: 200px;\n    padding: 20px;\n}","linguagem":"css","alternativas":["240px: 200px mais 20px de cada lado.","220px: 200px mais 20px.","200px, com o padding incluído.","160px: 200px menos o padding."],"correta":2,"explicacao":"Com box-sizing: border-box, a largura indicada já inclui o padding e a borda: o conteúdo é que encolhe. Sem ela, o padding somava-se (240px).","manual":"Anexo A"},{"id":"css-070","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Para que serve body { margin: 0; } no estilo.css?","codigo":"","linguagem":"","alternativas":["Centra o conteúdo da página na horizontal.","Tira o espaço entre o texto e a borda do body.","Esconde a barra de scroll da página.","Tira o espaço que o browser põe à volta da página."],"correta":3,"explicacao":"O browser põe uma margem à volta do body; margin: 0 tira-a, para o cabeçalho escuro encostar às bordas da janela.","manual":"Anexo A"},{"id":"css-071","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Para que serve border: none na regra dos botões?","codigo":"","linguagem":"","alternativas":["Tira o espaço entre o texto e a borda.","Tira a borda que o browser põe nos botões.","Esconde o botão até o rato passar por cima.","Tira os cantos arredondados do botão."],"correta":1,"explicacao":"Os <button> têm uma borda por omissão; border: none tira-a. O espaço interior é o padding e os cantos são o border-radius.","manual":"Anexo A"},{"id":"css-072","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Que declaração põe os filhos de um elemento lado a lado?","codigo":"","linguagem":"","alternativas":["display: block","display: flex","display: none","text-align: center"],"correta":1,"explicacao":"display: flex no contentor põe os filhos lado a lado, numa linha. display: block faz o contrário: cada elemento numa linha própria.","manual":"5.4"},{"id":"css-073","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Queres os cartões dos livros lado a lado. Em que elemento pões display: flex?","codigo":"<div class=\"cartoes\">\n    <article class=\"cartao\">...</article>\n    <article class=\"cartao\">...</article>\n    <article class=\"cartao\">...</article>\n</div>","linguagem":"html","alternativas":["No contentor .cartoes.","Em cada .cartao.","No <body>.","No <h2> de cada cartão."],"correta":0,"explicacao":"O flexbox aplica-se ao elemento que contém os outros: são os filhos dele que ficam lado a lado.","manual":"5.4"},{"id":"css-074","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Com muitos livros, os cartões ficam todos numa linha, esmagados. O que falta?","codigo":".cartoes {\n    display: flex;\n    gap: 16px;\n}","linguagem":"css","alternativas":["flex-direction: column","justify-content: space-between","flex-wrap: wrap","display: block"],"correta":2,"explicacao":"flex-wrap: wrap deixa os filhos passar para a linha seguinte quando não cabem, em vez de ficarem esmagados.","manual":"5.4"},{"id":"css-075","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"O que faz gap: 16px num contentor flex?","codigo":"","linguagem":"","alternativas":["Põe 16px de espaço à volta do contentor.","Põe 16px de espaço entre os filhos.","Põe 16px de espaço dentro de cada filho.","Obriga cada filho a ter 16px de largura."],"correta":1,"explicacao":"gap é o espaço entre os filhos. O espaço à volta é a margin e o espaço dentro é o padding.","manual":"5.4"},{"id":"css-076","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"No cabeçalho, o que faz justify-content: space-between?","codigo":".topo {\n    display: flex;\n    justify-content: space-between;\n    align-items: center;\n}","linguagem":"css","alternativas":["Centra os filhos na vertical.","Encosta o primeiro à esquerda e o último à direita.","Põe os filhos uns por baixo dos outros.","Junta todos os filhos no centro da linha, colados uns aos outros."],"correta":1,"explicacao":"space-between distribui os filhos na horizontal: o título fica à esquerda e o menu à direita. A centragem vertical é do align-items.","manual":"5.4"},{"id":"css-077","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Num contentor flex em linha, o que faz align-items: center?","codigo":"","linguagem":"","alternativas":["Centra os filhos na horizontal.","Centra o texto dentro de cada filho.","Põe o contentor a meio da página.","Centra os filhos na vertical."],"correta":3,"explicacao":"align-items: center centra os filhos na vertical, por exemplo o título e o menu que têm alturas diferentes. A distribuição na horizontal é com justify-content.","manual":"5.4"},{"id":"css-078","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Queres que o campo de pesquisa e o botão \"Novo\" fiquem alinhados ao meio, na vertical. O aluno escreveu isto. O que acontece?","codigo":".barra {\n    display: flex;\n    justify-content: center;\n}","linguagem":"css","alternativas":["Ficam juntos ao centro na horizontal, sem alinhamento vertical.","Ficam alinhados ao meio, na vertical, como queria.","Ficam um por baixo do outro, centrados.","Nada muda, porque justify-content só funciona com flex-wrap."],"correta":0,"explicacao":"justify-content trata da horizontal (numa linha). Para centrar na vertical usa-se align-items: center.","manual":"5.4"},{"id":"css-079","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Porque é que, no formulário, as etiquetas e os campos ficam uns por baixo dos outros?","codigo":".formulario {\n    display: flex;\n    flex-direction: column;\n    gap: 6px;\n}","linguagem":"css","alternativas":["gap: 6px obriga cada filho a ficar numa linha própria.","display: flex põe sempre os filhos uns por baixo dos outros.","flex-direction: column põe-nos em coluna.","Os campos de formulário nunca ficam lado a lado."],"correta":2,"explicacao":"Por omissão o flex põe os filhos em linha. Com flex-direction: column ficam em coluna, e o gap passa a ser o espaço vertical entre eles.","manual":"5.4"},{"id":"css-080","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Em flex: 1 1 260px, o que é o 260px?","codigo":".cartao {\n    flex: 1 1 260px;\n}","linguagem":"css","alternativas":["O tamanho com que cada cartão começa.","A largura máxima de cada cartão.","O espaço entre os cartões.","A largura do ecrã a partir da qual há cartões."],"correta":0,"explicacao":"O terceiro valor é o tamanho de partida: cada cartão começa com 260px e depois cresce para ocupar o espaço livre.","manual":"5.4"},{"id":"css-081","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"O que significa cada número em flex: 1 1 260px?","codigo":"","linguagem":"","alternativas":["Uma linha, uma coluna, 260px de largura máxima.","Ordem 1, grupo 1, 260px de espaço entre filhos.","Pode crescer, não pode encolher, nunca passa de 260px.","Pode crescer, pode encolher, começa com 260px."],"correta":3,"explicacao":"O primeiro 1 deixa o cartão crescer para ocupar o espaço livre, o segundo deixa-o encolher se for preciso, e 260px é o tamanho de partida.","manual":"5.4"},{"id":"css-082","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"O main tem 920px úteis para os cartões. Quantos cartões ficam em cada linha?","codigo":".cartoes { display: flex; flex-wrap: wrap; gap: 16px; }\n.cartao  { flex: 1 1 260px; }","linguagem":"css","alternativas":["Quatro, que encolhem para caber.","Três, com um espaço vazio à direita.","Três, que crescem para ocupar a linha toda.","Um, porque o flex-wrap obriga a mudar de linha."],"correta":2,"explicacao":"Três cartões ocupam 3 × 260 + 2 × 16 = 812px e cabem; um quarto já não cabe e passa para a linha seguinte. Como o primeiro valor é 1, os três crescem até preencher a linha.","manual":"5.4"},{"id":"css-083","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Porque é que os cartões NÃO estão lado a lado?","codigo":".cartoes {\n    flex-wrap: wrap;\n    gap: 16px;\n}\n\n.cartao {\n    flex: 1 1 260px;\n}","linguagem":"css","alternativas":["Falta display: flex no .cartoes.","Falta display: flex em cada .cartao.","O gap tem de ser maior do que o flex-basis.","Falta justify-content: space-between."],"correta":0,"explicacao":"flex-wrap, gap e flex só funcionam se o contentor tiver display: flex. Sem ele, os cartões ficam uns por baixo dos outros.","manual":"5.4"},{"id":"css-084","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"O aluno pôs display: flex no sítio errado. O que se vê?","codigo":".cartoes {\n    gap: 16px;\n}\n\n.cartao {\n    display: flex;\n    flex: 1 1 260px;\n}","linguagem":"css","alternativas":["Os cartões ficam lado a lado, como se o flex estivesse no .cartoes.","Os cartões desaparecem, porque o flex não pode estar no filho.","Fica tudo igual, porque display: flex num filho é ignorado.","Os cartões ficam em coluna e o conteúdo de cada um em linha."],"correta":3,"explicacao":"display: flex afeta os filhos do elemento onde está. No .cartao põe lado a lado o título e os parágrafos de cada cartão; os cartões em si continuam em coluna.","manual":"5.4"},{"id":"css-085","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"O .topo já tem display: flex. Porque é que a regra .topo nav também precisa de display: flex?","codigo":"<header class=\"topo\">\n    <a href=\"index.php\">Biblioteca</a>\n    <nav>\n        <a href=\"livros.php\">Livros</a>\n        <a href=\"autores.php\">Autores</a>\n    </nav>\n</header>","linguagem":"html","alternativas":["Sem ela, o <nav> ficava escondido no telemóvel por causa da media query.","Um <nav> não pode estar dentro de um contentor flex.","Não precisa: a regra está lá só para o gap ser maior.","O flex só arruma os filhos diretos, e os links são filhos do <nav>."],"correta":3,"explicacao":"O flex do .topo põe lado a lado os seus filhos: o link do título e o <nav>. Para os links dentro do <nav> ficarem lado a lado, o próprio <nav> tem de ser flex.","manual":"5.4, Anexo A"},{"id":"css-086","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Como fica o campo de pesquisa ao lado do botão \"Pesquisar\"?","codigo":".pesquisa {\n    display: flex;\n    gap: 8px;\n}","linguagem":"css","alternativas":["Um por baixo do outro, com 8px de espaço.","Lado a lado, colados, com 8px de margem à volta.","Lado a lado, com 8px de espaço entre eles.","O campo à esquerda e o botão encostado à direita da página."],"correta":2,"explicacao":"display: flex põe o input e o botão lado a lado e o gap dá 8px entre eles. Encostar às pontas seria justify-content: space-between.","manual":"5.4, Anexo A"},{"id":"css-087","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Na página de detalhe, como ficam a etiqueta (dt) e o valor (dd)?","codigo":".detalhe dl {\n    display: flex;\n    flex-wrap: wrap;\n}\n.detalhe dt { width: 140px; }\n.detalhe dd { width: calc(100% - 140px); margin: 0; }","linguagem":"css","alternativas":["Lado a lado: 140px para a etiqueta e o resto para o valor.","Um por baixo do outro, cada um a ocupar a largura toda da página.","Todos os dt e dd na mesma linha, esmagados.","A etiqueta à direita e o valor à esquerda."],"correta":0,"explicacao":"Um dt (140px) e um dd (100% menos 140px) enchem exatamente uma linha; o par seguinte passa para a linha de baixo por causa do flex-wrap.","manual":"5.4, Anexo A"},{"id":"css-088","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"O que é uma media query?","codigo":"","linguagem":"","alternativas":["Uma consulta à base de dados feita a partir do CSS.","Regras que só se aplicam se o ecrã cumprir uma condição.","Uma regra que se aplica só quando o rato está por cima do elemento.","Um ficheiro CSS separado só para telemóveis."],"correta":1,"explicacao":"Uma media query, como @media (max-width: 600px), aplica as regras lá dentro só quando a condição é verdadeira. A Biblioteca usa-a para o telemóvel, no mesmo estilo.css.","manual":"5.5"},{"id":"css-089","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Quando se aplicam as regras dentro de @media (max-width: 600px)?","codigo":"","linguagem":"","alternativas":["Quando o ecrã tem 600px de largura ou mais.","Só quando o ecrã tem exatamente 600px.","Quando o ecrã tem 600px de largura ou menos.","Quando a página tem mais de 600px de altura."],"correta":2,"explicacao":"max-width quer dizer \"até esta largura\": vale para ecrãs pequenos, como o telemóvel.","manual":"5.5"},{"id":"css-090","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"Se a Biblioteca usasse @media (min-width: 600px), quando se aplicavam as regras?","codigo":"","linguagem":"","alternativas":["Em ecrãs com 600px de largura ou mais.","Em ecrãs com 600px de largura ou menos.","Em todos os ecrãs, porque min e max são iguais.","Só quando a janela é redimensionada."],"correta":0,"explicacao":"min-width é \"a partir desta largura\" (ecrãs grandes); max-width é \"até esta largura\" (ecrãs pequenos).","manual":"5.5"},{"id":"css-091","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Qual é a sintaxe certa de uma media query?","codigo":"","linguagem":"","alternativas":["@media max-width = 600px { .topo { padding: 12px; } }","media(max-width: 600px) .topo { padding: 12px; }",".topo @media (max-width: 600px) { padding: 12px; }","@media (max-width: 600px) { .topo { padding: 12px; } }"],"correta":3,"explicacao":"A media query começa por @media, a condição vai entre parênteses e as regras ficam dentro das chavetas dela.","manual":"5.5"},{"id":"css-092","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Num telemóvel com 400px de largura, que padding tem o .topo?","codigo":".topo {\n    display: flex;\n    padding: 14px 32px;\n}\n\n/* ... no fim do ficheiro ... */\n@media (max-width: 600px) {\n    .topo {\n        padding: 12px 16px;\n    }\n}","linguagem":"css","alternativas":["14px 32px.","26px 48px, a soma dos dois.","Nenhum, porque as regras entram em conflito.","12px 16px."],"correta":3,"explicacao":"As duas regras têm o mesmo seletor; no telemóvel a media query aplica-se e, por estar mais abaixo, ganha.","manual":"5.5, 5.3"},{"id":"css-093","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"No telemóvel, o .topo continua com o fundo escuro e com display: flex?","codigo":".topo {\n    display: flex;\n    padding: 14px 32px;\n    background: #1f2a30;\n}\n\n@media (max-width: 600px) {\n    .topo { padding: 12px 16px; }\n}","linguagem":"css","alternativas":["Não: dentro da media query só valem as propriedades lá escritas.","Não: a media query apaga a regra .topo original no telemóvel.","Só o fundo; o display: flex tem de ser repetido.","Sim: a media query só muda o padding; o resto continua a valer."],"correta":3,"explicacao":"A media query não substitui a regra de fora: só acrescenta ou muda as propriedades que lá estão. Tudo o que não mexe continua igual.","manual":"5.5"},{"id":"css-094","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"O que acontece ao \"Olá, nome\" do menu?","codigo":"@media (max-width: 600px) {\n    .topo .ola {\n        display: none;\n    }\n}","linguagem":"css","alternativas":["Desaparece em todos os ecrãs.","Aparece só em ecrãs até 600px.","Fica invisível, mas continua a ocupar espaço no telemóvel.","Desaparece em ecrãs até 600px e aparece nos maiores."],"correta":3,"explicacao":"No telemóvel não há espaço para o \"Olá\", por isso a media query esconde-o. Num ecrã largo a regra não se aplica e ele aparece.","manual":"5.5"},{"id":"css-095","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"O aluno pôs a media query no INÍCIO do estilo.css, antes da regra .topo. Que padding tem o .topo num telemóvel?","codigo":"@media (max-width: 600px) {\n    .topo { padding: 12px 16px; }\n}\n\n.topo {\n    padding: 14px 32px;\n}","linguagem":"css","alternativas":["14px 32px, porque a regra de fora fica mais abaixo.","12px 16px, porque a media query ganha sempre.","12px 16px, porque é mais específica.","Depende da largura do computador onde se criou o CSS."],"correta":0,"explicacao":"A media query não dá mais força às regras. Com o mesmo seletor ganha a que está mais abaixo, e aqui é a de fora. Por isso a Biblioteca põe a media query no fim do ficheiro.","manual":"5.5, 5.3"},{"id":"css-096","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"No telemóvel, os cartões ficam um por linha. Olhando para o CSS, que regra faz isso?","codigo":"/* fora da media query */\n.cartoes { display: flex; flex-wrap: wrap; gap: 16px; }\n.cartao  { flex: 1 1 260px; }\n\n/* a media query do fim do ficheiro */\n@media (max-width: 600px) {\n    .topo { padding: 12px 16px; }\n    .topo nav { gap: 12px; font-size: 0.95rem; }\n    .topo .ola { display: none; }\n    .pesquisa input { min-width: 0; flex: 1; }\n    .detalhe dt,\n    .detalhe dd { width: 100%; }\n}","linguagem":"css","alternativas":["Uma regra .cartao { width: 100%; } dentro da @media (max-width: 600px).","Uma regra .cartoes { flex-direction: column; } dentro da @media do fim.","Nenhuma: só cabe um de 260px por linha e o flex-wrap passa o resto.","Uma regra .cartoes { display: block; } dentro da @media (max-width: 600px)."],"correta":2,"explicacao":"Não é preciso media query para os cartões: num ecrã estreito só cabe um de 260px por linha, que cresce até ocupar a largura toda.","manual":"5.4, 5.5"},{"id":"css-097","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"No telemóvel, o que muda no campo de pesquisa com estas regras?","codigo":"/* fora */\n.pesquisa input { min-width: 240px; }\n\n@media (max-width: 600px) {\n    .pesquisa input {\n        min-width: 0;\n        flex: 1;\n    }\n}","linguagem":"css","alternativas":["Fica escondido, porque min-width: 0 quer dizer largura zero.","Fica com 240px exatos e o botão passa para baixo.","Ocupa o ecrã todo e o botão desaparece.","Deixa de ter 240px de mínimo e ocupa o espaço livre ao lado do botão."],"correta":3,"explicacao":"min-width: 0 tira o limite mínimo, que num ecrã estreito empurraria o botão. flex: 1 faz o campo crescer para ocupar o espaço que sobra ao lado do botão.","manual":"5.5, Anexo A"},{"id":"css-098","bloco":"web","tema":"CSS","dificuldade":"dificil","pergunta":"Na página de detalhe, como ficam a etiqueta e o valor num telemóvel?","codigo":".detalhe dt { width: 140px; }\n.detalhe dd { width: calc(100% - 140px); }\n\n@media (max-width: 600px) {\n    .detalhe dt,\n    .detalhe dd {\n        width: 100%;\n    }\n}","linguagem":"css","alternativas":["Um por baixo do outro, cada um com a largura toda.","Lado a lado, com 140px para a etiqueta.","Lado a lado, cada um com metade da largura.","Só a etiqueta aparece, porque o valor deixa de caber."],"correta":0,"explicacao":"No telemóvel os dois passam a ocupar 100% da linha e, como o dl tem flex-wrap: wrap, cada um vai para uma linha própria.","manual":"5.5, Anexo A"},{"id":"css-099","bloco":"web","tema":"CSS","dificuldade":"facil","pergunta":"Como vês no computador o aspeto da Biblioteca num telemóvel?","codigo":"","linguagem":"","alternativas":["Ctrl + Shift + N, para abrir uma janela anónima.","F12 e depois Ctrl + Shift + P, escrevendo Disable JavaScript.","F12 e depois Ctrl + Shift + M (modo de dispositivo).","F5 várias vezes, até a página se adaptar."],"correta":2,"explicacao":"Ctrl + Shift + M nas ferramentas de programador (F12) ativa o modo de dispositivo, onde escolhes um telemóvel. Ctrl + Shift + N abre uma janela anónima.","manual":"5.5"},{"id":"css-100","bloco":"web","tema":"CSS","dificuldade":"media","pergunta":"No modo de dispositivo do browser escolhes um ecrã com 375px de largura. Que regras se aplicam?","codigo":"","linguagem":"","alternativas":["As de fora e também as da @media (max-width: 600px).","Só as regras dentro de @media (max-width: 600px).","Só as regras de fora da media query.","Nenhuma, até recarregares a página no telemóvel verdadeiro."],"correta":0,"explicacao":"As regras de fora valem sempre; num ecrã até 600px juntam-se as da media query, que mudam só o que lá está escrito.","manual":"5.5"},{"id":"amostra-003","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"No validacao.js, que instrução impede que o formulário seja enviado quando há erros?","codigo":"form.addEventListener('submit', function (event) {\n    if (erros.length > 0) {\n        ________;\n    }\n});","linguagem":"javascript","alternativas":["event.stopPropagation()","form.cancel()","return true","event.preventDefault()"],"correta":3,"explicacao":"preventDefault() cancela o comportamento normal do evento: neste caso, o envio do formulário. stopPropagation() só impede o evento de subir aos elementos-pai e form.cancel() não existe.","manual":"6.2"},{"id":"js-001","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Na Biblioteca, para que serve o JavaScript do validacao.js?","codigo":"","linguagem":"","alternativas":["Mostrar logo os erros do formulário, antes de o enviar.","Proteger a base de dados contra SQL injection.","Garantir que nenhum pedido chega ao servidor com campos vazios.","Substituir a validação no servidor, que deixa de ser precisa."],"correta":0,"explicacao":"É uma questão de conforto: o utilizador vê os erros sem esperar pelo servidor. Não protege nada, porque pode ser desligado ou contornado.","manual":"6.1"},{"id":"js-002","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Porque é que a validação em JavaScript não chega para proteger a aplicação?","codigo":"","linguagem":"","alternativas":["O JavaScript só corre depois de os dados chegarem ao servidor.","O utilizador pode desligá-lo ou enviar o pedido sem usar o formulário.","O JavaScript não consegue ler o valor dos campos de password.","O JavaScript só funciona em formulários com method=\"get\"."],"correta":1,"explicacao":"O JavaScript corre no browser, que está nas mãos do utilizador: pode desligá-lo ou enviar um pedido feito à mão. Por isso o servidor valida tudo outra vez.","manual":"6.1, 14"},{"id":"js-003","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Desligas o JavaScript no browser e envias o formulário de registo em branco. O que deve acontecer numa aplicação bem feita?","codigo":"","linguagem":"","alternativas":["A conta é criada com os campos vazios, porque ninguém os validou.","Os erros aparecem, agora vindos do servidor, e a página recarrega.","Não acontece nada: sem JavaScript, o botão de enviar deixa de funcionar.","O browser mostra os erros do validacao.js guardados da última vez."],"correta":1,"explicacao":"Sem JavaScript o formulário é enviado e o servidor encontra os erros. É o teste que prova que a validação no servidor funciona sozinha.","manual":"6.3, 16"},{"id":"js-004","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Onde corre o código do ficheiro validacao.js?","codigo":"","linguagem":"","alternativas":["No browser do utilizador.","No servidor Apache, antes do PHP.","No servidor de base de dados.","No interpretador de PHP, no rodapé."],"correta":0,"explicacao":"HTML, CSS e JavaScript correm no browser; o PHP corre no servidor e o SQL no servidor de base de dados.","manual":"1.4"},{"id":"js-005","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Um colega diz: \"Os meus campos têm required e o validacao.js verifica-os, por isso não preciso de validar no PHP.\" O que lhe respondes?","codigo":"","linguagem":"","alternativas":["Está certo, desde que o formulário use method=\"post\".","Está certo, desde que o formulário tenha o atributo novalidate.","Está errado: ambos se contornam e o servidor tem de validar.","Está errado só no login; no registo chega o required."],"correta":2,"explicacao":"O atributo required e o JavaScript são regras do browser e podem ser contornados. A validação no servidor é obrigatória em todos os formulários.","manual":"6.4, 14"},{"id":"js-006","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Que teste prova que a validação no servidor funciona sozinha?","codigo":"","linguagem":"","alternativas":["Enviar o formulário em branco com o JavaScript ligado.","Abrir a consola (F12) e ver se aparecem erros a vermelho.","Retirar o atributo name dos campos obrigatórios.","Desligar o JavaScript e enviar o formulário em branco."],"correta":3,"explicacao":"Com o JavaScript ligado, os erros são apanhados no browser e o servidor nem é testado. Só com o JavaScript desligado se vê que o servidor recusa os dados sozinho.","manual":"6.3, 14"},{"id":"js-007","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Sabendo que a Biblioteca valida os formulários com o validacao.js, para que serve o atributo novalidate no <form>?","codigo":"","linguagem":"","alternativas":["Desliga a validação no servidor enquanto o JavaScript estiver ligado.","Impede que o validacao.js atue sobre esse formulário, que segue sem validação.","Faz com que os campos vazios não sejam enviados ao servidor.","Desliga as mensagens automáticas do browser, para o JavaScript as mostrar."],"correta":3,"explicacao":"Com novalidate o browser não mostra as suas mensagens automáticas, e é o validacao.js que mostra todos os erros juntos e em português. O servidor continua a validar.","manual":"4.2, 6.3"},{"id":"js-008","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Com o JavaScript ligado, envias o registo em branco com o separador Rede (F12) aberto. O que vês?","codigo":"","linguagem":"","alternativas":["Nenhum pedido novo: o envio foi cancelado no browser.","Um POST com código 200, porque o servidor aceitou os dados.","Um POST com código 302 para a página de login.","Um POST com código 500, porque os campos estão vazios."],"correta":0,"explicacao":"O preventDefault() cancela o envio: o pedido não chega ao servidor e a página não recarrega. Os erros são mostrados só pelo browser.","manual":"6.3, 16"},{"id":"js-009","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Com o JavaScript desligado, tentas registar-te sem assinalar a caixa do consentimento. O formulário tem novalidate. O que tem de acontecer?","codigo":"","linguagem":"","alternativas":["A conta é criada, porque o JavaScript não verificou a caixa.","O registo é recusado pelo servidor.","O browser bloqueia o envio, porque a caixa tem required.","A conta é criada, mas sem a data do consentimento."],"correta":1,"explicacao":"O consentimento é verificado no servidor, por isso o registo é recusado mesmo sem JavaScript. O browser não bloqueia, porque o formulário tem novalidate.","manual":"14, 16"},{"id":"js-010","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O que é o DOM?","codigo":"","linguagem":"","alternativas":["O ficheiro de estilos que o JavaScript usa para mudar as cores.","A página vista pelo JavaScript: uma árvore de elementos.","A ligação entre o JavaScript do browser e a base de dados.","A lista de pedidos que o browser fez ao servidor."],"correta":1,"explicacao":"O DOM é a página representada como uma árvore de elementos. Funções como getElementById, querySelectorAll ou appendChild leem-na e alteram-na.","manual":"6.2"},{"id":"js-011","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Qual destas instruções altera o que aparece na página?","codigo":"","linguagem":"","alternativas":["const erros = [];","caixa.appendChild(li);","const anoAtual = new Date().getFullYear();","erros.push('Preenche o campo \"Nome\".');"],"correta":1,"explicacao":"appendChild acrescenta um elemento ao DOM, por isso a página muda. As outras só criam ou alteram variáveis do JavaScript, que não aparecem na página.","manual":"6.2, 6.3"},{"id":"js-012","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Queres obter em JavaScript o elemento <span id=\"total\">. O que escreves?","codigo":"","linguagem":"","alternativas":["document.getElementById('#total')","document.getElementsByClassName('total')","document.querySelectorAll('total')","document.getElementById('total')"],"correta":3,"explicacao":"getElementById recebe o id sem o #. O # só se usa nos seletores CSS, por exemplo em querySelector('#total').","manual":"Anexo B, 6.2"},{"id":"js-013","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"O que devolve document.getElementById('email') numa página sem nenhum elemento com id=\"email\"?","codigo":"","linguagem":"","alternativas":["undefined","Uma lista vazia ([])","Uma string vazia ('')","null"],"correta":3,"explicacao":"Quando não encontra o elemento, getElementById devolve null. É por isso que o validacao.js testa if (!form) e email && ... antes de usar os elementos.","manual":"6.3"},{"id":"js-014","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Na página, o formulário foi escrito como <form id=\"form_principal\" ...> (com sublinhado). Envias com os campos obrigatórios vazios. O que acontece?","codigo":"document.addEventListener('DOMContentLoaded', function () {\n    const form = document.getElementById('form-principal');\n    if (!form) {\n        return;\n    }\n    form.addEventListener('submit', function (event) {\n        // ... validação ...\n    });\n});","linguagem":"javascript","alternativas":["O JavaScript dá um erro e o formulário fica sem poder ser enviado.","O validacao.js não atua: o formulário segue e o servidor mostra os erros.","O validacao.js encontra o formulário pela classe e valida-o da mesma forma.","O browser mostra os erros do JavaScript, mas sem a caixa vermelha."],"correta":1,"explicacao":"Os ids não batem certo, por isso getElementById devolve null e o return termina o código sem ligar o evento. O formulário segue para o servidor, que faz a validação.","manual":"6.3"},{"id":"js-015","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Há erros no formulário, mas o id da caixa está mal escrito no JavaScript. O que acontece?","codigo":"// na página: <ul id=\"erros-js\" class=\"msg erro\"></ul>\nconst caixa = document.getElementById('erros_js');\nif (erros.length > 0) {\n    event.preventDefault();\n    caixa.innerHTML = '';\n    // ... acrescenta os erros à caixa ...\n}","linguagem":"javascript","alternativas":["Os erros aparecem na mesma, porque o browser corrige o id.","O formulário é enviado, porque o preventDefault() não chega a correr.","Os erros aparecem no topo da página, fora da caixa.","O envio é cancelado, mas o código para com um erro e os erros não aparecem."],"correta":3,"explicacao":"caixa fica null. O preventDefault() corre primeiro e cancela o envio; depois caixa.innerHTML dá erro (não se pode usar uma propriedade de null) e nada é mostrado.","manual":"6.3"},{"id":"js-016","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"O campo do email não tem id. O que acontece à regra que verifica se o email tem @?","codigo":"// o campo: <input type=\"email\" name=\"email\" required>\nconst email = document.getElementById('email');\nif (email && email.value !== '' && !email.value.includes('@')) {\n    erros.push('O email não parece válido.');\n}","linguagem":"javascript","alternativas":["Não atua: getElementById devolve null e a condição é falsa.","Atua na mesma, porque getElementById também procura pelo name.","Dá um erro e o formulário deixa de poder ser enviado.","Mostra sempre \"O email não parece válido.\"."],"correta":0,"explicacao":"getElementById procura pelo id, não pelo name. Sem id devolve null, e o email && ... faz a condição falhar logo, sem erro.","manual":"6.2, 6.3"},{"id":"js-017","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O que devolve esta instrução?","codigo":"form.querySelectorAll('[required]')","linguagem":"javascript","alternativas":["Só o primeiro elemento com o atributo required.","Os elementos que têm class=\"required\".","Os campos obrigatórios que já estão preenchidos pelo utilizador.","Todos os elementos do formulário com o atributo required."],"correta":3,"explicacao":"querySelectorAll devolve todos os elementos que correspondem ao seletor CSS. [required] é o seletor de atributo; .required seria o de classe.","manual":"6.2"},{"id":"js-018","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"No validacao.js (excerto em baixo), a etiqueta de um campo é procurada com form.querySelector(...) e não com querySelectorAll(...). Porquê?","codigo":"// 1. Campos obrigatórios (os que têm o atributo required)\nform.querySelectorAll('[required]').forEach(function (campo) {\n    if (campo.type === 'checkbox') {\n        if (!campo.checked) {\n            erros.push('Tens de aceitar a política de privacidade.');\n        }\n    } else if (campo.value.trim() === '') {\n        const label = form.querySelector('label[for=\"' + campo.id + '\"]');\n        const nome = label ? label.textContent : campo.name;\n        erros.push('Preenche o campo \"' + nome.trim() + '\".');\n    }\n});\n\n// 2. Email com formato válido\nconst email = document.getElementById('email');\nif (email && email.value !== '' && !email.value.includes('@')) {\n    erros.push('O email não parece válido.');\n}","linguagem":"javascript","alternativas":["querySelectorAll não aceita seletores com atributos, como [for=\"...\"].","querySelector procura pelo id e querySelectorAll procura pela classe.","Só interessa uma etiqueta, e querySelector devolve só a primeira.","querySelectorAll só funciona fora dos formulários."],"correta":2,"explicacao":"Ambos aceitam qualquer seletor CSS. querySelector devolve um só elemento (o primeiro, ou null); querySelectorAll devolve todos, como no ciclo dos campos com required.","manual":"6.2, 6.3"},{"id":"js-019","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Se campo.id for 'titulo', que seletor CSS é usado nesta linha?","codigo":"const label = form.querySelector('label[for=\"' + campo.id + '\"]');","linguagem":"javascript","alternativas":["label#titulo","label[for=\"titulo\"]","label.titulo","label[for=\"campo.id\"]"],"correta":1,"explicacao":"O + junta os três pedaços de texto e fica label[for=\"titulo\"]: a etiqueta ligada ao campo com id=\"titulo\". campo.id está fora das aspas, por isso é substituído pelo valor.","manual":"6.3"},{"id":"js-020","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Queres obter todos os elementos com class=\"btn\" usando querySelectorAll. Que seletor passas?","codigo":"","linguagem":"","alternativas":["'btn'","'#btn'","'.btn'","'[btn]'"],"correta":2,"explicacao":"querySelectorAll usa seletores CSS: .btn é a classe, #btn seria um id, btn sozinho seria um elemento <btn> e [btn] um atributo.","manual":"5.2, 6.2"},{"id":"js-021","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Este campo obrigatório não tem nenhuma <label>. Se ficar vazio, que erro mostra o validacao.js?","codigo":"// o campo: <input type=\"text\" id=\"isbn\" name=\"isbn\" required>\n} else if (campo.value.trim() === '') {\n    const label = form.querySelector('label[for=\"' + campo.id + '\"]');\n    const nome = label ? label.textContent : campo.name;\n    erros.push('Preenche o campo \"' + nome.trim() + '\".');\n}","linguagem":"javascript","alternativas":["Preenche o campo \"null\".","Preenche o campo \"isbn\".","Preenche o campo \"\".","Nenhum: sem label, o campo é ignorado."],"correta":1,"explicacao":"Sem etiqueta, querySelector devolve null e a condição label ? ... : ... usa o campo.name. O campo continua a ser validado, só muda o nome que aparece.","manual":"6.3"},{"id":"js-022","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Porque se escreve form.querySelectorAll('[required]') e não document.querySelectorAll('[required]')?","codigo":"","linguagem":"","alternativas":["Porque document não tem o método querySelectorAll.","Para que os campos sejam enviados juntos ao servidor.","Para procurar os campos só dentro desse formulário.","Porque [required] só funciona a partir de um form."],"correta":2,"explicacao":"Chamado sobre form, procura apenas dentro desse elemento. Com document procuraria em toda a página, incluindo outros formulários.","manual":"6.2, 6.3"},{"id":"js-023","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Queres que uma função corra quando se clica num botão. O que usas?","codigo":"","linguagem":"","alternativas":["botao.addEventListener('submit', funcao)","botao.addEventListener('click', funcao)","botao.preventDefault('click', funcao)","botao.getElementById('click', funcao)"],"correta":1,"explicacao":"addEventListener liga uma função a um evento; o evento do clique é 'click'. 'submit' é o evento do formulário quando vai ser enviado.","manual":"Anexo B, 6.4"},{"id":"js-024","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Que evento falta para a validação correr quando o formulário vai ser enviado?","codigo":"form.addEventListener('______', function (event) {\n    const erros = [];\n    // ...\n});","linguagem":"javascript","alternativas":["click","DOMContentLoaded","send","submit"],"correta":3,"explicacao":"O evento 'submit' acontece quando o formulário vai ser enviado, e é aí que o preventDefault() o pode cancelar. 'DOMContentLoaded' é o da página carregada.","manual":"6.2, 6.3"},{"id":"js-025","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Para que serve envolver o validacao.js neste código?","codigo":"document.addEventListener('DOMContentLoaded', function () {\n    const form = document.getElementById('form-principal');\n    // ...\n});","linguagem":"javascript","alternativas":["Impede que o código corra quando o JavaScript está desligado.","Faz com que o código corra só depois de o formulário ser enviado.","Pede o ficheiro validacao.js ao servidor só quando o formulário é usado.","Espera que a página esteja carregada, para o formulário já existir."],"correta":3,"explicacao":"DOMContentLoaded espera que a página esteja toda carregada. Sem isto, o getElementById podia correr antes de o formulário existir.","manual":"6.3"},{"id":"js-026","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"O validacao.js começa assim. Imagina-o sem o DOMContentLoaded e ligado no <head>, antes do formulário. O que pode acontecer?","codigo":"document.addEventListener('DOMContentLoaded', function () {\n    const form = document.getElementById('form-principal');\n    if (!form) {\n        return; // esta página não tem formulário para validar\n    }\n    form.addEventListener('submit', function (event) {\n        // ...\n    });\n});","linguagem":"javascript","alternativas":["getElementById('form-principal') devolve null e a validação não atua.","O formulário passa a ser enviado duas vezes.","O browser recusa carregar o ficheiro .js no <head>.","O CSS deixa de ser aplicado à caixa de erros."],"correta":0,"explicacao":"O código correria antes de o formulário existir na página, por isso não o encontraria. O formulário seria enviado sem validação no browser.","manual":"6.3"},{"id":"js-027","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"O que faz este código?","codigo":"const botao = document.getElementById('mostrar');\nbotao.addEventListener('click', function () {\n    document.getElementById('ajuda').style.display = 'block';\n});","linguagem":"javascript","alternativas":["Ao clicar no elemento mostrar, a caixa ajuda passa a ser visível.","Mostra a caixa ajuda logo que a página abre.","Ao clicar no elemento mostrar, a caixa ajuda é escondida.","Ao clicar no elemento mostrar, o formulário é enviado."],"correta":0,"explicacao":"A função só corre quando há um 'click' no elemento com id=\"mostrar\". Nessa altura muda o estilo da caixa para display: block, o que a mostra.","manual":"6.2, 6.4"},{"id":"js-028","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Quando corre a função passada a form.addEventListener('submit', ...)?","codigo":"","linguagem":"","alternativas":["Quando o formulário vai ser enviado, antes de o pedido sair.","Logo que a página acaba de carregar.","Depois de o servidor responder ao formulário.","Sempre que o utilizador escreve uma letra num dos campos do formulário."],"correta":0,"explicacao":"O evento submit dispara antes de o pedido sair. É por isso que o preventDefault() ainda consegue cancelar o envio.","manual":"6.2"},{"id":"js-029","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Dentro de um evento submit, o que faz event.preventDefault()?","codigo":"","linguagem":"","alternativas":["Apaga os valores escritos em todos os campos.","Envia o formulário sem recarregar a página.","Volta a ligar as mensagens automáticas do browser.","Cancela o comportamento normal: o formulário não é enviado."],"correta":3,"explicacao":"preventDefault() cancela o comportamento normal do evento. Num submit, o comportamento normal é enviar o formulário.","manual":"6.2"},{"id":"js-030","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"O programador esqueceu-se de uma linha. O que acontece quando há erros?","codigo":"const caixa = document.getElementById('erros-js');\nif (erros.length > 0) {\n    caixa.innerHTML = '';\n    erros.forEach(function (texto) {\n        const li = document.createElement('li');\n        li.textContent = texto;\n        caixa.appendChild(li);\n    });\n    caixa.style.display = 'block';\n}","linguagem":"javascript","alternativas":["Os erros são escritos na caixa, mas o formulário é enviado na mesma.","O formulário não é enviado, porque o array erros tem mensagens lá dentro.","O browser não envia o formulário, porque a caixa está visível.","Os erros não aparecem e o formulário fica bloqueado."],"correta":0,"explicacao":"Falta event.preventDefault(). Mostrar erros não impede nada: o envio só é cancelado com preventDefault(), por isso a página segue para o servidor.","manual":"6.2, 6.3"},{"id":"js-031","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"No validacao.js, o preventDefault() só é chamado dentro de if (erros.length > 0). O que acontece quando o formulário está bem preenchido?","codigo":"","linguagem":"","alternativas":["O formulário nunca é enviado, porque o submit foi apanhado.","É preciso carregar duas vezes no botão para o enviar.","O formulário é enviado normalmente ao servidor.","O envio fica à espera de uma resposta do JavaScript."],"correta":2,"explicacao":"Ligar uma função ao submit não cancela nada por si. Sem erros, preventDefault() não é chamado e o formulário segue o seu caminho normal.","manual":"6.3"},{"id":"js-032","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Porque é que o validacao.js usa li.textContent = texto e não li.innerHTML = texto?","codigo":"","linguagem":"","alternativas":["textContent é a única forma de escrever dentro de um <li>.","textContent trata tudo como texto, e nenhum HTML é executado.","innerHTML só funciona em elementos que têm um id definido no HTML.","textContent mostra o texto a vermelho, como erro."],"correta":1,"explicacao":"textContent escreve o texto tal como está; innerHTML interpreta-o como HTML. Por isso textContent é a forma segura de escrever texto.","manual":"6.2"},{"id":"js-033","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"O utilizador escreveu <b>Ana</b> no campo nome. O que aparece no elemento ola?","codigo":"const nome = document.getElementById('nome').value;\ndocument.getElementById('ola').textContent = 'Olá, ' + nome;","linguagem":"javascript","alternativas":["Olá, <b>Ana</b>, com as etiquetas à vista, como texto.","Olá, Ana, com o nome em negrito.","Olá, Ana, sem negrito e sem as etiquetas.","Olá, nome, porque a variável fica entre aspas."],"correta":0,"explicacao":"textContent não interpreta HTML: os < e > aparecem como caracteres. Só o innerHTML poria o nome em negrito.","manual":"6.2"},{"id":"js-034","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"O utilizador escreveu <i>Os Maias</i> no campo titulo. O que aparece e que problema tem este código?","codigo":"const titulo = document.getElementById('titulo').value;\ndocument.getElementById('previa').innerHTML = titulo;","linguagem":"javascript","alternativas":["O texto <i>Os Maias</i> com as etiquetas à vista; não há problema.","Os Maias em itálico; não há problema, porque o valor vem de um campo.","Nada: innerHTML só aceita texto que venha do servidor.","Os Maias em itálico: o texto é lido como HTML, e alguém pode injetar código."],"correta":3,"explicacao":"innerHTML interpreta o valor como HTML, por isso o <i> funciona, e um <script> ou outro código também podia entrar. Para texto escrito pelo utilizador usa-se textContent.","manual":"6.2, 14.1"},{"id":"js-035","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Este é o fim do validacao.js, o único sítio onde usa innerHTML. Em que situação o usa, e porque não há perigo?","codigo":"// Se houver erros: impede o envio e mostra-os\nconst caixa = document.getElementById('erros-js');\nif (erros.length > 0) {\n    event.preventDefault();\n    caixa.innerHTML = '';\n    erros.forEach(function (texto) {\n        const li = document.createElement('li');\n        li.textContent = texto;\n        caixa.appendChild(li);\n    });\n    caixa.style.display = 'block';\n    caixa.scrollIntoView({ behavior: 'smooth' });\n}","linguagem":"javascript","alternativas":["Para escrever cada erro dentro de um <li>: o texto é do programador.","Para escrever o nome do campo que vem da label: é HTML da página.","Em caixa.innerHTML = '', para esvaziar a caixa: o valor é fixo.","Para mostrar a caixa de erros: troca o display para block."],"correta":2,"explicacao":"caixa.innerHTML = '' só limpa os erros anteriores, sem escrever nada vindo de fora. Cada erro entra depois com textContent, nunca com innerHTML.","manual":"6.3"},{"id":"js-036","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"No browser, que cuidado tem o mesmo papel que o htmlspecialchars() tem no PHP?","codigo":"","linguagem":"","alternativas":["Escrever o texto com textContent em vez de innerHTML.","Escrever o texto com innerHTML dentro de um if.","Passar o texto por value.trim() antes de o mostrar.","Mostrar o texto com style.display = 'block'."],"correta":0,"explicacao":"htmlspecialchars() faz o browser mostrar o HTML como texto; textContent tem o mesmo efeito no JavaScript. Ambos impedem que HTML escrito por alguém seja executado.","manual":"6.2, 14.1"},{"id":"js-037","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Uma caixa está escondida com display: none no CSS. Que instrução a mostra?","codigo":"","linguagem":"","alternativas":["caixa.style.display = 'none';","caixa.style.display = 'block';","caixa.display = 'visible';","caixa.textContent = 'block';"],"correta":1,"explicacao":"Os estilos de um elemento mudam-se pela propriedade style. display = 'block' mostra a caixa; 'none' esconde-a.","manual":"6.2"},{"id":"js-038","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Porque é que a caixa de erros do JavaScript não aparece enquanto não há erros?","codigo":"/* estilo.css */\n#erros-js {\n    display: none;\n}","linguagem":"css","alternativas":["Está vazia, e o browser esconde sempre as listas vazias.","Só é incluída na página quando o servidor encontra erros de validação.","O validacao.js cria-a com createElement quando há erros.","O CSS dá-lhe display: none, e só o JavaScript a muda para block."],"correta":3,"explicacao":"A caixa <ul id=\"erros-js\"> está sempre na página (vem do erros.php), mas escondida pelo CSS. Quando há erros, o JavaScript faz caixa.style.display = 'block'.","manual":"9.4, Anexo A"},{"id":"js-039","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O que faz document.createElement('li')?","codigo":"","linguagem":"","alternativas":["Procura o primeiro <li> que existe na página.","Cria um novo elemento <li>, que ainda não está na página.","Cria um <li> e mostra-o logo no fim da página.","Apaga todos os elementos <li> da página."],"correta":1,"explicacao":"createElement só cria o elemento. Ele só aparece na página quando é acrescentado a outro com appendChild.","manual":"6.3"},{"id":"js-040","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Neste excerto falta a linha caixa.appendChild(li). O que acontece quando há erros?","codigo":"event.preventDefault();\ncaixa.innerHTML = '';\nerros.forEach(function (texto) {\n    const li = document.createElement('li');\n    li.textContent = texto;\n});\ncaixa.style.display = 'block';","linguagem":"javascript","alternativas":["Os erros aparecem na mesma, porque createElement já os põe na página.","Dá um erro, porque textContent só funciona em elementos da página.","O formulário é enviado, porque o forEach não faz nada.","Os <li> são criados mas não entram na caixa, que aparece vazia."],"correta":3,"explicacao":"Sem appendChild, os elementos ficam só na memória do JavaScript. O envio continua cancelado e a caixa fica visível, mas sem nenhum erro lá dentro.","manual":"6.3"},{"id":"js-041","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Este é o fim do validacao.js. Imagina que se apaga a linha caixa.innerHTML = ''. O utilizador envia duas vezes o formulário com os mesmos erros. O que vê?","codigo":"// Se houver erros: impede o envio e mostra-os\nconst caixa = document.getElementById('erros-js');\nif (erros.length > 0) {\n    event.preventDefault();\n    caixa.innerHTML = '';\n    erros.forEach(function (texto) {\n        const li = document.createElement('li');\n        li.textContent = texto;\n        caixa.appendChild(li);\n    });\n    caixa.style.display = 'block';\n    caixa.scrollIntoView({ behavior: 'smooth' });\n}","linguagem":"javascript","alternativas":["Só os erros do primeiro envio, porque os novos são ignorados pelo browser.","Nenhum erro, porque o segundo envio não é cancelado.","Os erros repetidos: os do primeiro envio ficam e os novos juntam-se.","A caixa volta a ficar escondida no segundo envio."],"correta":2,"explicacao":"appendChild acrescenta sempre ao que já está na caixa. A linha caixa.innerHTML = '' serve para limpar os erros da tentativa anterior.","manual":"6.3"},{"id":"js-042","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Que sequência acrescenta uma mensagem nova a uma lista que já está na página?","codigo":"","linguagem":"","alternativas":["appendChild, depois createElement, depois textContent.","getElementById('li'), depois textContent, depois push.","createElement, depois push, depois style.display.","createElement, depois textContent, depois appendChild."],"correta":3,"explicacao":"Primeiro cria-se o <li>, depois põe-se-lhe o texto e por fim junta-se à lista com appendChild. push serve para arrays, não para elementos da página.","manual":"6.3"},{"id":"js-043","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Como lês em JavaScript o que o utilizador escreveu num campo de texto?","codigo":"","linguagem":"","alternativas":["campo.textContent","campo.name","campo.type","campo.value"],"correta":3,"explicacao":"value é o conteúdo escrito no campo. name é a chave com que o valor vai para o servidor e type é o tipo de campo.","manual":"6.3"},{"id":"js-044","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Porque é que o validacao.js testa campo.value.trim() === '' e não só campo.value === ''?","codigo":"","linguagem":"","alternativas":["Para que um campo só com espaços também conte como vazio.","Para passar as letras maiúsculas a minúsculas.","Para converter o valor do campo num número.","Para cortar o texto ao tamanho máximo definido no maxlength."],"correta":0,"explicacao":"trim() tira os espaços do início e do fim. Um campo com \"   \" fica \"\" e dá o erro de campo obrigatório.","manual":"6.3"},{"id":"js-045","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Que valor fica em tamanho?","codigo":"const nome = '  Ana ';\nconst tamanho = nome.trim().length;","linguagem":"javascript","alternativas":["3","4","5","6"],"correta":0,"explicacao":"trim() tira os dois espaços do início e o do fim, ficando \"Ana\". length conta os caracteres: 3.","manual":"6.3"},{"id":"js-046","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Que propriedade diz se uma checkbox está assinalada?","codigo":"","linguagem":"","alternativas":["value","selected","checked","required"],"correta":2,"explicacao":"checked é true quando a caixa está assinalada. O validacao.js usa if (!campo.checked) para a caixa do consentimento.","manual":"6.3"},{"id":"js-047","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Para que serve o teste campo.type === 'checkbox' neste ciclo?","codigo":"form.querySelectorAll('[required]').forEach(function (campo) {\n    if (campo.type === 'checkbox') {\n        if (!campo.checked) {\n            erros.push('Tens de aceitar a política de privacidade.');\n        }\n    } else if (campo.value.trim() === '') {\n        // ... erro de campo vazio ...\n    }\n});","linguagem":"javascript","alternativas":["Saltar as checkboxes, que nunca são obrigatórias.","Verificar se o campo tem o atributo required.","Assinalar a caixa automaticamente antes do envio.","Tratar a caixa do consentimento à parte, vendo se está assinalada."],"correta":3,"explicacao":"Numa checkbox, \"vazio\" não faz sentido: o que importa é se está assinalada. Os outros campos obrigatórios são verificados pelo valor.","manual":"6.3"},{"id":"js-048","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O campo da password tem o atributo data-minimo=\"8\". Como o lês em JavaScript?","codigo":"","linguagem":"","alternativas":["password.data-minimo","password.minimo","password.dataset.minimo","password.value('minimo')"],"correta":2,"explicacao":"Os atributos data-... leem-se pela propriedade dataset: data-minimo fica dataset.minimo. password.data-minimo seria uma subtração.","manual":"4.2, 6.3"},{"id":"js-049","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"No formulário de login, o campo da password não tem data-minimo. Escreves a password abc. Que erro mostra esta regra?","codigo":"// login: <input type=\"password\" id=\"password\" name=\"password\" required>\nconst password = document.getElementById('password');\nif (password && password.dataset.minimo && password.value !== '' && password.value.length < 8) {\n    erros.push('A password tem de ter pelo menos 8 caracteres.');\n}","linguagem":"javascript","alternativas":["A password tem de ter pelo menos 8 caracteres.","Nenhum: sem data-minimo, a condição é falsa.","Preenche o campo \"Password\".","Dá um erro, porque dataset.minimo não existe."],"correta":1,"explicacao":"Sem o atributo, dataset.minimo não tem valor e o && para aí. É assim que a regra dos 8 caracteres só atua no registo.","manual":"6.3"},{"id":"js-050","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"No registo, a password tem data-minimo e a regra é password.value.length < 8. Escreves Demo1234. O que acontece?","codigo":"","linguagem":"","alternativas":["Dá erro: tem de ter mais de 8 caracteres.","Dá erro: o JavaScript exige um símbolo.","Passa: tem 8 caracteres e 8 < 8 é falso.","Passa só se o email também estiver certo."],"correta":2,"explicacao":"Demo1234 tem exatamente 8 caracteres. A condição < 8 é falsa, por isso a regra não junta nenhum erro.","manual":"6.3"},{"id":"js-051","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Que valor fica em temArroba?","codigo":"const texto = 'ana.gmail.com';\nconst temArroba = texto.includes('@');","linguagem":"javascript","alternativas":["false","true","-1","null"],"correta":0,"explicacao":"includes devolve true se o texto contiver o que se procura e false se não. Aqui é false, e com o ! a condição do validacao.js fica verdadeira: \"O email não parece válido.\"","manual":"6.3"},{"id":"js-052","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"O utilizador escreve ana@ no email. Esta regra mostra \"O email não parece válido.\"?","codigo":"const email = document.getElementById('email');\nif (email && email.value !== '' && !email.value.includes('@')) {\n    erros.push('O email não parece válido.');\n}","linguagem":"javascript","alternativas":["Não: a regra só verifica se o texto tem um @.","Sim: falta o domínio depois do @.","Sim: o type=\"email\" obriga a ter um ponto.","Não: o campo do email não tem required."],"correta":0,"explicacao":"A regra é simples: só procura o @. É uma ajuda ao utilizador; a verificação a sério do email é feita no servidor.","manual":"6.3"},{"id":"js-053","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"No registo, deixas o email vazio (o campo tem required e a label \"Email\"). Com este excerto do validacao.js, quantas mensagens sobre o email aparecem?","codigo":"// 1. Campos obrigatórios (os que têm o atributo required)\nform.querySelectorAll('[required]').forEach(function (campo) {\n    if (campo.type === 'checkbox') {\n        if (!campo.checked) {\n            erros.push('Tens de aceitar a política de privacidade.');\n        }\n    } else if (campo.value.trim() === '') {\n        const label = form.querySelector('label[for=\"' + campo.id + '\"]');\n        const nome = label ? label.textContent : campo.name;\n        erros.push('Preenche o campo \"' + nome.trim() + '\".');\n    }\n});\n\n// 2. Email com formato válido\nconst email = document.getElementById('email');\nif (email && email.value !== '' && !email.value.includes('@')) {\n    erros.push('O email não parece válido.');\n}","linguagem":"javascript","alternativas":["Duas: a do campo vazio e a do formato.","Uma: O email não parece válido.","Nenhuma, porque o email está vazio.","Uma: Preenche o campo \"Email\"."],"correta":3,"explicacao":"O ciclo dos campos com required apanha o campo vazio. A regra do formato tem email.value !== '', por isso não repete o erro.","manual":"6.3"},{"id":"js-054","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Em if (erros.length > 0), o que é erros.length?","codigo":"","linguagem":"","alternativas":["O número de campos que o formulário tem.","O número de caracteres da primeira mensagem.","O número de campos que têm required.","O número de mensagens de erro guardadas no array."],"correta":3,"explicacao":"erros é um array e length diz quantos elementos tem. Se for maior que 0, houve pelo menos um erro e o envio é cancelado.","manual":"6.3"},{"id":"js-055","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O que cria const erros = [];?","codigo":"","linguagem":"","alternativas":["Um texto vazio, para juntar as mensagens.","Um array vazio, para guardar as mensagens de erro.","Um elemento <ul> vazio na página.","Uma variável que vale null."],"correta":1,"explicacao":"[] é um array vazio. Cada regra que falha junta-lhe uma mensagem com push.","manual":"6.3"},{"id":"js-056","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O que faz a segunda linha?","codigo":"const erros = [];\nerros.push('O email não parece válido.');","linguagem":"javascript","alternativas":["Mostra a mensagem na caixa de erros da página.","Substitui todo o conteúdo do array pela mensagem.","Envia a mensagem para o servidor.","Acrescenta a mensagem ao fim do array erros."],"correta":3,"explicacao":"push acrescenta um elemento ao fim do array. As mensagens só aparecem na página mais tarde, com createElement e appendChild.","manual":"6.3"},{"id":"js-057","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Quantos <li> ficam dentro da caixa?","codigo":"const erros = [];\nerros.push('Preenche o campo \"Nome\".');\nerros.push('O email não parece válido.');\ncaixa.innerHTML = '';\nerros.forEach(function (texto) {\n    const li = document.createElement('li');\n    li.textContent = texto;\n    caixa.appendChild(li);\n});","linguagem":"javascript","alternativas":["0","1","2","3"],"correta":2,"explicacao":"O array tem duas mensagens e o forEach corre a função uma vez para cada: cria e acrescenta dois <li>. A caixa foi limpa antes, por isso não há outros.","manual":"6.3"},{"id":"js-058","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Porque é que const erros = []; está dentro da função do submit e não fora dela?","codigo":"","linguagem":"","alternativas":["Porque const só se pode usar dentro de funções.","Para o servidor conseguir ler o array erros.","Para cada tentativa de envio começar com a lista de erros vazia.","Para os erros se irem juntando de uma tentativa de envio para a outra."],"correta":2,"explicacao":"A função corre em cada envio, por isso o array é criado de novo, vazio, de cada vez. Só os erros da tentativa atual contam.","manual":"6.3"},{"id":"js-059","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"O validacao.js declara as variáveis com const. O que quer isto dizer?","codigo":"","linguagem":"","alternativas":["O valor da variável é enviado para o servidor.","A variável não volta a receber outro valor depois de criada.","A variável fica disponível em todas as páginas.","O valor da variável não pode ser lido."],"correta":1,"explicacao":"const cria uma variável que não é reatribuída. Se fosse preciso mudar-lhe o valor mais tarde, usava-se let.","manual":"6.3"},{"id":"js-060","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Com const erros = []; o código faz depois erros.push(...). Isto dá erro?","codigo":"","linguagem":"","alternativas":["Não: push muda o conteúdo do array, não reatribui a variável.","Sim: uma variável const não pode ser alterada de forma nenhuma.","Sim: push só funciona em arrays declarados com let.","Não: push cria um array novo e guarda-o noutra variável."],"correta":0,"explicacao":"const impede erros = outraCoisa, mas não impede alterar o array por dentro. Por isso o validacao.js funciona com const.","manual":"6.3"},{"id":"js-061","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Que método usa o validacao.js para correr uma função para cada campo devolvido por querySelectorAll?","codigo":"","linguagem":"","alternativas":["push","appendChild","forEach","addEventListener"],"correta":2,"explicacao":"forEach percorre a lista e corre a função uma vez para cada elemento, recebendo-o como parâmetro (campo).","manual":"6.3"},{"id":"js-062","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Em campo.type === 'checkbox', o que faz o ===?","codigo":"","linguagem":"","alternativas":["Guarda 'checkbox' em campo.type.","Vê se campo.type contém a palavra 'checkbox'.","Compara se os dois valores são iguais.","Compara só o tamanho dos dois textos."],"correta":2,"explicacao":"=== compara (valor e tipo). Um só = é atribuição: guardaria o valor em vez de comparar.","manual":"6.3"},{"id":"js-063","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Qual é o problema desta condição?","codigo":"if (campo.type = 'checkbox') {\n    if (!campo.checked) {\n        erros.push('Tens de aceitar a política de privacidade.');\n    }\n}","linguagem":"javascript","alternativas":["Usa = (atribuição) em vez de === (comparação).","'checkbox' devia estar entre aspas duplas.","Devia usar == porque === não compara textos.","type não existe nos campos <input>."],"correta":0,"explicacao":"Com um só = o código muda o type do campo para checkbox, e a condição é sempre verdadeira. Para comparar usa-se ===.","manual":"6.3"},{"id":"js-064","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Quando é que email.value !== '' é verdadeiro?","codigo":"","linguagem":"","alternativas":["Quando o campo está vazio.","Quando o campo não existe na página.","Quando o texto tem um @.","Quando o campo tem alguma coisa escrita."],"correta":3,"explicacao":"!== quer dizer \"diferente de\". O valor é diferente de '' quando o utilizador escreveu alguma coisa.","manual":"6.3"},{"id":"js-065","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Porque é que a regra do email começa por email && ...?","codigo":"","linguagem":"","alternativas":["Para verificar se o texto tem um @ antes de o enviar.","Para só atuar se o campo existir; com null, o && para ali.","Para obrigar o utilizador a preencher o email.","Para juntar o email ao texto da mensagem de erro."],"correta":1,"explicacao":"Numa página sem campo de email, getElementById devolve null, que é falso: o && para logo, sem tentar ler email.value (o que daria erro).","manual":"6.3"},{"id":"js-066","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Quando é que esta condição é verdadeira?","codigo":"ano.value < 1450 || ano.value > anoAtual","linguagem":"javascript","alternativas":["Só quando o ano é menor que 1450 e maior que o atual.","Quando o ano é menor que 1450 ou maior que o ano atual.","Quando o ano está entre 1450 e o ano atual.","Quando o campo do ano está vazio."],"correta":1,"explicacao":"|| é \"ou\": basta uma das partes ser verdadeira. A condição apanha os anos fora do intervalo permitido.","manual":"6.3"},{"id":"js-067","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Quando é que o erro é acrescentado?","codigo":"if (!campo.checked) {\n    erros.push('Tens de aceitar a política de privacidade.');\n}","linguagem":"javascript","alternativas":["Quando a caixa não está assinalada.","Quando a caixa está assinalada.","Quando a caixa não tem required.","Quando a caixa não existe na página."],"correta":0,"explicacao":"! inverte o valor: !campo.checked é verdadeiro quando checked é false, ou seja, quando a caixa não foi assinalada.","manual":"6.3"},{"id":"js-068","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Um colega escreveu esta regra do ano com && em vez de ||. O que acontece?","codigo":"const ano = document.getElementById('ano_edicao');\nconst anoAtual = new Date().getFullYear();\nif (ano && ano.value !== '' && (ano.value < 1450 && ano.value > anoAtual)) {\n    erros.push('O ano tem de estar entre 1450 e ' + anoAtual + '.');\n}","linguagem":"javascript","alternativas":["A regra dá sempre erro, mesmo para os anos que estão certos.","A regra funciona da mesma forma, porque && e || são equivalentes.","Nunca dá erro: nenhum ano é menor que 1450 e maior que o atual.","O código para com um erro de sintaxe."],"correta":2,"explicacao":"Com && as duas partes teriam de ser verdadeiras ao mesmo tempo, o que é impossível. Os anos errados passavam sem aviso no browser.","manual":"6.3"},{"id":"js-069","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"A etiqueta do campo é <label for=\"titulo\">Título</label> e o campo ficou vazio. Que mensagem é acrescentada?","codigo":"const label = form.querySelector('label[for=\"' + campo.id + '\"]');\nconst nome = label ? label.textContent : campo.name;\nerros.push('Preenche o campo \"' + nome.trim() + '\".');","linguagem":"javascript","alternativas":["Preenche o campo \"Título\".","Preenche o campo \"titulo\".","Preenche o campo \"nome\".","Preenche o campo \"' + nome.trim() + '\"."],"correta":0,"explicacao":"Há etiqueta, por isso nome é o texto dela (Título). O + junta os pedaços e as aspas duplas ficam dentro do texto, à volta do nome.","manual":"6.3"},{"id":"js-070","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Que operador junta textos em JavaScript, como em 'entre 1450 e ' + anoAtual?","codigo":"","linguagem":"","alternativas":[".","+","&",","],"correta":1,"explicacao":"Em JavaScript os textos juntam-se com +. O ponto (.) é o operador de juntar textos do PHP.","manual":"6.3"},{"id":"js-071","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Sabendo que estamos em 2026 e que o ano escrito foi 2030, que mensagem mostra a regra do ano?","codigo":"const anoAtual = new Date().getFullYear();\n// ... o ano está fora do intervalo ...\nerros.push('O ano tem de estar entre 1450 e ' + anoAtual + '.');","linguagem":"javascript","alternativas":["O ano tem de estar entre 1450 e anoAtual.","O ano tem de estar entre 1450 e 2030.","O ano tem de estar entre 3476.","O ano tem de estar entre 1450 e 2026."],"correta":3,"explicacao":"anoAtual está fora das aspas, por isso é substituído pelo valor (2026). O 1450 faz parte do texto, por isso não há nenhuma soma.","manual":"6.3"},{"id":"js-072","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O que devolve new Date().getFullYear()?","codigo":"","linguagem":"","alternativas":["A data de hoje completa, com dia e mês.","O ano de edição escrito no formulário.","O ano atual, com quatro algarismos.","O número de dias que passaram este ano."],"correta":2,"explicacao":"new Date() é a data e hora atuais; getFullYear() tira-lhe só o ano, por exemplo 2026.","manual":"6.3"},{"id":"js-073","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Escreves 1450 no ano de edição de um livro. O que faz esta regra?","codigo":"const ano = document.getElementById('ano_edicao');\nconst anoAtual = new Date().getFullYear();\nif (ano && ano.value !== '' && (ano.value < 1450 || ano.value > anoAtual)) {\n    erros.push('O ano tem de estar entre 1450 e ' + anoAtual + '.');\n}","linguagem":"javascript","alternativas":["Recusa o ano: tem de ser maior que 1450.","Recusa o ano: ano.value é texto e não se compara.","Aceita o ano: 1450 não é menor que 1450.","Aceita o ano, mas só porque o campo é obrigatório."],"correta":2,"explicacao":"1450 < 1450 é falso e 1450 > anoAtual também, por isso a condição é falsa. O limite 1450 está dentro do intervalo permitido.","manual":"6.3"},{"id":"js-074","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Porque é que o validacao.js calcula o ano com new Date().getFullYear() em vez de escrever o número do ano no código?","codigo":"","linguagem":"","alternativas":["Porque o JavaScript não aceita números com quatro algarismos.","Para a regra continuar certa nos anos seguintes sem mudar o código.","Para o ano vir da base de dados, através do servidor.","Porque o campo ano_edicao só aceita valores calculados."],"correta":1,"explicacao":"O ano atual muda todos os anos. Calculado no momento, o limite fica sempre certo.","manual":"6.3"},{"id":"js-075","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"O que faz confirm('Apagar este livro?')?","codigo":"","linguagem":"","alternativas":["Apaga o livro e mostra uma mensagem de sucesso.","Mostra uma janela com OK e Cancelar e devolve true ou false.","Mostra uma janela só com OK, para avisar o utilizador.","Pede ao servidor que confirme se o livro existe."],"correta":1,"explicacao":"confirm mostra a pergunta com OK e Cancelar. OK devolve true; Cancelar devolve false.","manual":"6.4"},{"id":"js-076","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"O utilizador carrega em Apagar e, na janela, escolhe Cancelar. O que acontece?","codigo":"<form method=\"post\" action=\"livro_apagar.php\"\n      onsubmit=\"return confirm('Apagar este livro?');\">\n    <input type=\"hidden\" name=\"id_livro\" value=\"3\">\n    <button type=\"submit\" class=\"perigo\">Apagar</button>\n</form>","linguagem":"html","alternativas":["O formulário é enviado, mas o servidor não apaga.","O livro é apagado, porque o botão é de submit.","O formulário não é enviado e o livro fica.","A página recarrega e volta a fazer a pergunta."],"correta":2,"explicacao":"Cancelar faz o confirm devolver false, e return false no onsubmit cancela o envio. Nenhum pedido chega ao livro_apagar.php.","manual":"6.4"},{"id":"js-077","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"No onsubmit=\"return confirm('Apagar este livro?');\", o que acontece quando o utilizador carrega em OK?","codigo":"","linguagem":"","alternativas":["confirm devolve true e o livro é apagado no browser.","confirm devolve false e o formulário é enviado na mesma.","confirm devolve true e abre-se um link GET para apagar.","confirm devolve true e o formulário é enviado por POST."],"correta":3,"explicacao":"Com OK, o onsubmit devolve true e o formulário segue o caminho normal: um POST para livro_apagar.php, que apaga no servidor.","manual":"6.4, 4.4"},{"id":"js-078","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Neste formulário falta uma palavra no onsubmit. O que acontece se o utilizador carregar em Cancelar?","codigo":"<form method=\"post\" action=\"livro_apagar.php\"\n      onsubmit=\"confirm('Apagar este livro?');\">\n    <input type=\"hidden\" name=\"id_livro\" value=\"3\">\n    <button type=\"submit\" class=\"perigo\">Apagar</button>\n</form>","linguagem":"html","alternativas":["O formulário é enviado na mesma e o livro é apagado.","O formulário não é enviado, porque o confirm devolveu false.","A janela não chega a aparecer, por faltar o return.","O browser mostra um erro e recarrega a página."],"correta":0,"explicacao":"Sem return, o resultado do confirm é ignorado: a janela aparece, mas o envio não é cancelado. É o return false que impede o envio.","manual":"6.4"},{"id":"js-079","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"A janela de confirmação do Apagar impede que um livro seja apagado por quem não devia?","codigo":"","linguagem":"","alternativas":["Sim: sem carregar em OK, nenhum pedido chega alguma vez ao servidor.","Não: é só conforto; quem pode apagar verifica-se no servidor.","Sim: o confirm só aparece a quem tem sessão iniciada.","Não: mas passa a impedir se o formulário usar GET."],"correta":1,"explicacao":"Com o JavaScript desligado, ou com um pedido feito à mão, o confirm não corre. Como toda a validação no browser, é ajuda ao utilizador; o controlo de acesso está no servidor.","manual":"6.4, 14"},{"id":"js-080","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Como se liga o ficheiro validacao.js a uma página?","codigo":"","linguagem":"","alternativas":["<script href=\"js/validacao.js\"></script>","<script src=\"js/validacao.js\"></script>","<link rel=\"script\" href=\"js/validacao.js\">","<script file=\"js/validacao.js\"></script>"],"correta":1,"explicacao":"O <script> usa src para indicar o ficheiro. href é o atributo do <link>, que serve para a folha de estilos.","manual":"6.3, 9.2"},{"id":"js-081","bloco":"web","tema":"JavaScript","dificuldade":"facil","pergunta":"Este é o includes/rodape.php da Biblioteca. Porque é que o validacao.js chega a todos os formulários?","codigo":"</main>\n<footer class=\"rodape\">\n    Biblioteca · Projeto UC00615 ·\n    <a href=\"privacidade.php\">Política de privacidade</a>\n</footer>\n<script src=\"js/validacao.js\"></script>\n</body>\n</html>","linguagem":"html","alternativas":["Porque o rodapé, onde está o <script>, é incluído por todas as páginas.","Porque o db.php, incluído por todas as páginas, também o carrega.","Porque o browser repete o <script> dentro de cada <form>.","Porque o estilo.css o carrega com @import."],"correta":0,"explicacao":"O rodapé (rodape.php) é incluído por todas as páginas e carrega o script. O mesmo ficheiro serve todos os formulários.","manual":"6.3, 9.2"},{"id":"js-082","bloco":"web","tema":"JavaScript","dificuldade":"media","pergunta":"Abres a lista de livros, que não tem nenhum formulário com id=\"form-principal\". O que faz o validacao.js?","codigo":"const form = document.getElementById('form-principal');\nif (!form) {\n    return; // esta página não tem formulário para validar\n}","linguagem":"javascript","alternativas":["Termina logo no return e não faz mais nada.","Mostra um erro na consola e para a página.","Valida o primeiro formulário que encontrar.","Impede os links da página de funcionar."],"correta":0,"explicacao":"getElementById devolve null, !form é verdadeiro e o return termina a função. O script está em todas as páginas, mas só atua onde há formulário.","manual":"6.3"},{"id":"js-083","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Alguém tirou a verificação if (!form) do validacao.js. O que acontece numa página sem formulário?","codigo":"document.addEventListener('DOMContentLoaded', function () {\n    const form = document.getElementById('form-principal');\n    form.addEventListener('submit', function (event) {\n        // ... validação ...\n    });\n});","linguagem":"javascript","alternativas":["Nada muda, porque o evento nunca acontece.","O script valida os links em vez do formulário.","Dá um erro na consola, porque form é null.","A página deixa de abrir no browser."],"correta":2,"explicacao":"Sem formulário, form é null, e null não tem addEventListener: o JavaScript para com um erro. A página abre na mesma, mas a consola mostra o erro.","manual":"6.3"},{"id":"js-084","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"Envias este formulário em branco. Quantas mensagens mostra o validacao.js?","codigo":"<form method=\"post\" action=\"registo.php\" id=\"form-principal\" novalidate>\n    <label for=\"nome\">Nome</label>\n    <input type=\"text\" id=\"nome\" name=\"nome\" required>\n    <label for=\"email\">Email</label>\n    <input type=\"email\" id=\"email\" name=\"email\" required>\n    <label for=\"password\">Password</label>\n    <input type=\"password\" id=\"password\" name=\"password\" required data-minimo=\"8\">\n    <input type=\"checkbox\" id=\"consentimento\" name=\"consentimento\" required>\n    <button type=\"submit\">Criar conta</button>\n</form>","linguagem":"html","alternativas":["2","3","4","5"],"correta":2,"explicacao":"Há quatro campos com required: nome, email, password e consentimento, e cada um dá uma mensagem. As regras do email e da password não repetem, porque só atuam com o campo preenchido.","manual":"6.3"},{"id":"js-085","bloco":"web","tema":"JavaScript","dificuldade":"dificil","pergunta":"No registo (nome, email, password com data-minimo e consentimento, todos com required), escreves Nome: Ana, Email: ana, Password: 123 e não assinalas o consentimento. Quantas mensagens aparecem?","codigo":"","linguagem":"","alternativas":["1","2","3","4"],"correta":2,"explicacao":"O consentimento por assinalar dá uma, o email sem @ dá outra e a password com menos de 8 caracteres dá a terceira. O nome está preenchido.","manual":"6.3"},{"id":"amostra-004","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Abres livro_ver.php?id=999 e esse livro não existe. Que código de estado a Biblioteca devolve?","codigo":"","linguagem":"","alternativas":["200","302","404","500"],"correta":2,"explicacao":"404 = não encontrado: a página faz http_response_code(404) quando o fetch() devolve false. O 500 é para quando o código rebenta e o 302 é um redirecionamento.","manual":"1.3, 12.3"},{"id":"http-001","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Quais são as três peças de qualquer aplicação web?","codigo":"","linguagem":"","alternativas":["O browser, o servidor e a base de dados.","O HTML, o CSS e o JavaScript.","O browser, o phpMyAdmin e o XAMPP.","O cliente, o editor de código e o servidor."],"correta":0,"explicacao":"Uma aplicação web tem sempre o browser (onde está o utilizador), o servidor (onde corre o programa) e a base de dados (onde ficam os dados).","manual":"1.1"},{"id":"http-002","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"O browser precisa da lista de livros que está na base de dados. A quem a pede?","codigo":"","linguagem":"","alternativas":["Diretamente ao MySQL, através do endereço escrito na barra do browser.","Ao phpMyAdmin, que lhe envia as linhas da tabela.","Ao servidor, que consulta a base de dados e devolve o resultado.","À base de dados, mas só quando o pedido é POST."],"correta":2,"explicacao":"O browser nunca fala diretamente com a base de dados: pede tudo ao servidor, e é o PHP que faz a consulta SQL.","manual":"1.1"},{"id":"http-003","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Escreves localhost/biblioteca/livros.php no browser. Qual é o caminho do pedido?","codigo":"","linguagem":"","alternativas":["Browser consulta o MySQL → o Apache junta o PHP → o browser executa o PHP.","Browser descarrega o livros.php → executa-o e consulta o MySQL sozinho.","Browser → Apache → PHP consulta o MySQL → o HTML gerado volta ao browser.","Browser → Apache → MySQL gera o HTML → o PHP envia-o ao browser."],"correta":2,"explicacao":"O Apache recebe o pedido e entrega o ficheiro ao PHP, que consulta o MySQL e usa as linhas para gerar HTML. Esse HTML é a resposta enviada ao browser.","manual":"1.1"},{"id":"http-004","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Numa página da Biblioteca, escolhes \"Ver código-fonte da página\". O que encontras?","codigo":"","linguagem":"","alternativas":["O código PHP completo, com as consultas SQL.","Só HTML, sem nenhum <?php nem consultas SQL.","O HTML e o PHP, mas sem as consultas SQL.","O PHP, com as passwords trocadas por asteriscos."],"correta":1,"explicacao":"O browser só recebe o HTML que o PHP produziu no servidor. O código PHP e o SQL nunca saem do servidor.","manual":"1.1"},{"id":"http-005","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Porque é que o config/db.php pode ter a password da base de dados sem que o utilizador a veja?","codigo":"","linguagem":"","alternativas":["O browser esconde automaticamente as variáveis com passwords.","O Apache cifra os ficheiros .php antes de os enviar.","O código PHP chega ao browser, mas fica invisível na página.","O PHP corre no servidor e o browser só recebe o HTML gerado."],"correta":3,"explicacao":"O PHP é executado no servidor; ao browser só chega o resultado em HTML. Por isso as credenciais ficam num ficheiro PHP, fora das páginas.","manual":"1.1, 14.2"},{"id":"http-006","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Abres esta página por http://localhost e vês o código-fonte. O que aparece na linha do título?","codigo":"<?php\n$nome = 'Maria';\n?>\n<body>\n    <h1>Olá, <?= $nome ?>!</h1>\n</body>","linguagem":"php","alternativas":["<h1>Olá, Maria!</h1>","<h1>Olá, <?= $nome ?>!</h1>","<h1>Olá, $nome!</h1>","<h1>Olá, <?php echo 'Maria'; ?>!</h1>"],"correta":0,"explicacao":"O PHP corre no servidor e troca <?= $nome ?> pelo valor da variável. O browser só recebe o HTML final, já com \"Maria\".","manual":"2.4"},{"id":"http-007","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Na página ola.php, que mostra date('H:i'), carregas em F5 várias vezes e a hora vai mudando. Porquê?","codigo":"","linguagem":"","alternativas":["O JavaScript do browser atualiza a hora sozinho.","O browser guarda a página e só muda a hora localmente.","O PHP corre outra vez no servidor em cada pedido.","O MySQL envia a hora certa sempre que a página carrega."],"correta":2,"explicacao":"Cada F5 é um novo pedido: o servidor executa o PHP de novo e gera HTML com a hora desse momento.","manual":"2.4"},{"id":"http-008","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"O que tem sempre um pedido HTTP?","codigo":"","linguagem":"","alternativas":["Um método e um endereço.","Um método e um código de estado.","Um endereço e uma consulta SQL.","Um cookie e um formulário."],"correta":0,"explicacao":"Cada pedido tem um método (nesta UC, GET ou POST) e um endereço. O código de estado vem na resposta, não no pedido.","manual":"1.2"},{"id":"http-009","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Num pedido GET, onde vão os dados enviados?","codigo":"","linguagem":"","alternativas":["No corpo do pedido, escondidos.","Num cookie criado pelo formulário.","No endereço, depois do ?","No código de estado da resposta."],"correta":2,"explicacao":"Em GET os dados vão no URL, por exemplo livros.php?q=mar. Em POST vão no corpo do pedido e não aparecem no endereço.","manual":"1.2"},{"id":"http-010","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Fazes login com este formulário e, no endereço, não aparecem nem o email nem a password. Porquê?","codigo":"<form method=\"post\" action=\"login.php\">\n    <input type=\"email\" id=\"email\" name=\"email\">\n    <input type=\"password\" id=\"password\" name=\"password\">\n    <button type=\"submit\">Entrar</button>\n</form>","linguagem":"html","alternativas":["O campo é type=\"password\", e o browser nunca envia esse tipo de campo.","O formulário usa POST, que envia os dados no corpo do pedido.","O PHP limpa o endereço depois de ler os dados.","O action aponta para a própria página login.php."],"correta":1,"explicacao":"Com method=\"post\" os dados viajam no corpo do pedido. O type=\"password\" só mostra pontos no ecrã; o valor é enviado na mesma.","manual":"1.2, 4.2"},{"id":"http-011","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Que pedido faz o browser quando clicas neste link?","codigo":"<a href=\"livro_ver.php?id=3\">Ver detalhe →</a>","linguagem":"html","alternativas":["Um POST, com id=3 no corpo do pedido.","Um GET, com id=3 no corpo do pedido.","Um POST, porque leva um parâmetro.","Um GET, com id=3 no endereço."],"correta":3,"explicacao":"Um link é sempre um pedido GET, e os dados vão no URL depois do ?. Ter parâmetros não o transforma em POST.","manual":"1.2, 4.4"},{"id":"http-012","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Qual destas formas faz um pedido POST?","codigo":"","linguagem":"","alternativas":["Um link <a href> com ?id= no fim.","Escrever o endereço na barra do browser.","Abrir uma página guardada nos favoritos.","Um formulário com method=\"post\"."],"correta":3,"explicacao":"POST só se faz com um formulário com method=\"post\". Links, endereços escritos e favoritos são sempre pedidos GET.","manual":"1.2"},{"id":"http-013","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Depois de enviar um formulário, carregas em F5 e o browser avisa \"Confirmar reenvio do formulário\". O que significa?","codigo":"","linguagem":"","alternativas":["A sessão expirou e é preciso iniciar sessão de novo.","O formulário tem erros e vai ser validado outra vez pelo browser.","A página veio de um POST, e o F5 vai enviá-lo outra vez.","A página foi apagada e o servidor devolveu 404."],"correta":2,"explicacao":"Repetir um POST pode criar o registo duas vezes, e o browser avisa disso. É o problema que o Post/Redirect/Get resolve.","manual":"1.2, 9.5"},{"id":"http-014","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Que valor tem o method do formulário de pesquisa dos livros?","codigo":"<form method=\"____\" action=\"livros.php\">\n    <input type=\"search\" name=\"q\">\n    <button type=\"submit\">Pesquisar</button>\n</form>","linguagem":"html","alternativas":["method=\"get\", porque só lê dados.","method=\"post\", porque envia texto.","method=\"search\", próprio das pesquisas.","method=\"post\", para esconder o texto pesquisado."],"correta":0,"explicacao":"Pesquisar não altera nada, por isso é GET: o texto vai no endereço. type=\"search\" existe no <input>, mas \"search\" não é um método.","manual":"1.2, 12.2"},{"id":"http-015","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Escreves \"mar\" na caixa e carregas em Pesquisar. Que endereço aparece no browser?","codigo":"<form method=\"get\" action=\"livros.php\">\n    <input type=\"search\" name=\"q\"\n           placeholder=\"Pesquisar por título\">\n    <button type=\"submit\">Pesquisar</button>\n</form>","linguagem":"html","alternativas":["livros.php?search=mar","livros.php","livros.php#q=mar","livros.php?q=mar"],"correta":3,"explicacao":"Com method=\"get\", cada campo vai no URL depois do ?, com o seu name como chave: ?q=mar. O type do campo não conta e, sem GET, nada iria para o endereço.","manual":"12.2"},{"id":"http-016","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"O endereço é livros.php?q=mar. O que falta para o PHP ler o texto pesquisado?","codigo":"$q = trim(________ ?? '');","linguagem":"php","alternativas":["$_GET['q']","$_POST['q']","$_GET['search']","$_SESSION['q']"],"correta":0,"explicacao":"Os dados de um pedido GET vêm do URL e leem-se em $_GET, com a chave do name do campo (q).","manual":"12.2"},{"id":"http-017","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Envias a um colega, que também tem sessão iniciada, o endereço livros.php?q=mar. O que vê ele?","codigo":"","linguagem":"","alternativas":["A lista completa, porque a pesquisa só existe no teu browser.","Um erro, porque a pesquisa tem de ser reenviada por POST.","A caixa de pesquisa vazia e nenhum livro.","A mesma pesquisa: os livros com \"mar\" no título."],"correta":3,"explicacao":"Como a pesquisa é GET, o texto faz parte do endereço. Quem abre esse endereço faz exatamente o mesmo pedido.","manual":"1.2, 12.2"},{"id":"http-018","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Porque é que apagar um livro com este link é perigoso?","codigo":"<a href=\"livro_apagar.php?id_livro=3\" class=\"btn perigo\">Apagar</a>","linguagem":"html","alternativas":["Os links não conseguem enviar o id do livro ao servidor.","O link faz um POST, que se repete sempre que alguém carrega em F5 na página.","O browser bloqueia os links que contêm a palavra apagar.","Um robô ou uma pré-visualização pode seguir o link e apagar o livro."],"correta":3,"explicacao":"Um link é um GET, e um GET nunca deve alterar dados: basta alguém ou alguma coisa seguir o link para o livro desaparecer. Apagar é sempre um formulário POST.","manual":"1.2"},{"id":"http-019","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Qual destas ações pode ser feita com um simples link?","codigo":"","linguagem":"","alternativas":["Apagar um livro.","Gravar as alterações de um livro.","Criar uma conta.","Abrir a ficha de um livro."],"correta":3,"explicacao":"Navegar faz-se com links (GET). Tudo o que altera dados (criar, editar, apagar) faz-se com um formulário POST.","manual":"4.4"},{"id":"http-020","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Na página de detalhe, porque é que \"Editar\" é um link e \"Apagar\" é um formulário?","codigo":"<a href=\"livro_editar.php?id=7\" class=\"btn\">Editar</a>\n<form method=\"post\" action=\"livro_apagar.php\">\n    <input type=\"hidden\" name=\"id_livro\" value=\"7\">\n    <button type=\"submit\" class=\"perigo\">Apagar</button>\n</form>","linguagem":"html","alternativas":["Os links só funcionam para páginas sem PHP.","Editar só abre o formulário (GET); apagar altera dados (POST).","O formulário chega mais depressa ao servidor do que um link normal.","Editar não precisa do id do livro; apagar precisa."],"correta":1,"explicacao":"O link Editar apenas mostra o formulário de edição, que é ler. Apagar muda a base de dados, por isso é POST, mesmo sendo só um botão.","manual":"4.4"},{"id":"http-021","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Alguém escreve no browser livro_apagar.php?id_livro=3. O que acontece?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/auth.php';\n\nif ($_SERVER['REQUEST_METHOD'] !== 'POST') {\n    header('Location: livros.php');\n    exit;\n}","linguagem":"php","alternativas":["O livro 3 é apagado, porque o id vai no endereço.","É mandado para a lista e nada é apagado.","Recebe um 404, porque a página não existe em GET.","Recebe um 500, porque falta o corpo do pedido."],"correta":1,"explicacao":"Escrever um endereço faz um GET. A página só aceita POST: em qualquer outro caso redireciona para livros.php e o exit impede que o DELETE corra.","manual":"12.6, 1.2"},{"id":"http-022","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"O livro_novo.php recebe pedidos GET e POST. Qual é a diferença?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/auth.php';\n\nif ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    // validar; se estiver tudo bem, INSERT e redirecionar\n}\n// mostrar o formulário","linguagem":"php","alternativas":["Em GET grava o livro novo; em POST mostra o formulário.","Em GET mostra o formulário; em POST grava o livro novo.","Em GET mostra a lista dos livros; em POST mostra a ficha do livro.","Em GET valida os campos; em POST mostra os erros."],"correta":1,"explicacao":"Pedir a página (GET) mostra o formulário vazio; enviar o formulário (POST) faz o INSERT. A mesma página trata os dois casos.","manual":"12.1"},{"id":"http-023","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Gravar as alterações de um livro em livro_editar.php?id=7: que método e que SQL?","codigo":"","linguagem":"","alternativas":["GET, com UPDATE livros SET ... WHERE id_livro = ?","POST, com INSERT INTO livros (...) VALUES (...)","POST, com UPDATE livros SET ... WHERE id_livro = ?","GET, com SELECT ... WHERE id_livro = ?"],"correta":2,"explicacao":"Gravar altera dados, por isso é POST, e alterar um registo existente é UPDATE com WHERE. O GET à mesma página só mostra o formulário (SELECT).","manual":"12.1"},{"id":"http-024","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Qual destas linhas do mapa de páginas está ERRADA?","codigo":"","linguagem":"","alternativas":["Ver o detalhe → GET livro_ver.php?id=7","Listar e pesquisar → GET livros.php?q=...","Apagar → GET livro_apagar.php?id=7","Gravar o livro novo → POST livro_novo.php"],"correta":2,"explicacao":"Apagar altera dados e tem de ser POST, com o id num campo escondido. Ver, listar e pesquisar só leem, por isso são GET.","manual":"12.1"},{"id":"http-025","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"O que quer dizer o código de estado 200?","codigo":"","linguagem":"","alternativas":["O servidor mandou o browser ir a outra página.","A página pedida não existe.","A página foi encontrada e enviada.","Houve um erro de programação no servidor."],"correta":2,"explicacao":"200 é OK: correu bem. 302 é redirecionamento, 404 é não encontrado e 500 é erro no servidor.","manual":"1.3"},{"id":"http-026","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Quando aparece o código 500?","codigo":"","linguagem":"","alternativas":["Quando o utilizador não tem sessão iniciada.","Quando se pede um livro que não existe.","Quando o servidor manda o browser ir a outra página depois de gravar.","Quando o código rebenta ou a base de dados está desligada."],"correta":3,"explicacao":"500 é erro no servidor: um erro de programação ou a base de dados desligada. Livro inexistente é 404 e redirecionar é 302.","manual":"1.3"},{"id":"http-027","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Que código de estado indica que o servidor mandou o browser ir a outra página?","codigo":"","linguagem":"","alternativas":["200","302","404","500"],"correta":1,"explicacao":"302 é o redirecionamento, usado depois de gravar (capítulo 9). 200 é OK, 404 é não encontrado e 500 é erro no servidor.","manual":"1.3"},{"id":"http-028","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Queres ver o método e o código de estado de cada pedido que a página faz. O que usas?","codigo":"","linguagem":"","alternativas":["F12, separador Rede (Network).","Ver código-fonte da página.","O phpMyAdmin, separador SQL.","O XAMPP Control Panel, botão Start."],"correta":0,"explicacao":"Nas ferramentas de programador (F12), o separador Rede mostra cada pedido, o seu método (GET ou POST) e o código de estado da resposta.","manual":"1.3"},{"id":"http-029","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Com o separador Rede aberto, crias um livro com sucesso. Que dois pedidos vês, por esta ordem?","codigo":"","linguagem":"","alternativas":["POST livro_novo.php → 302; depois GET livro_ver.php → 200","GET livro_novo.php → 302; depois POST livro_ver.php?id=7 → 200","POST livro_novo.php → 200; depois GET livros.php → 302","POST livro_novo.php → 404; depois GET livro_ver.php → 200"],"correta":0,"explicacao":"O formulário faz um POST; o servidor grava e responde 302. O browser segue o redirecionamento com um GET à página do livro, que responde 200.","manual":"1.3, 9.5"},{"id":"http-030","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Porque é que, depois de gravar, o servidor responde com um redirecionamento em vez de uma página?","codigo":"mensagem('sucesso', 'Livro criado.');\nheader('Location: livro_ver.php?id=' . $id);\nexit;","linguagem":"php","alternativas":["Para o último pedido ser um GET e o F5 não reenviar o formulário.","Porque um pedido POST não pode receber HTML como resposta.","Para o browser poder guardar a página gravada nos favoritos do utilizador.","Porque o código 200 só existe na resposta a pedidos GET."],"correta":0,"explicacao":"É o padrão Post/Redirect/Get: depois do redirecionamento, a última coisa pedida foi um GET, e repetir um GET não faz mal nenhum.","manual":"9.5"},{"id":"http-031","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Que código de estado recebe quem abre livro_ver.php?id=abc?","codigo":"$id = (int) ($_GET['id'] ?? 0);\n// ... SELECT ... WHERE l.id_livro = ?\nif (!$livro) {\n    http_response_code(404);\n    // mostra \"Livro não encontrado\"\n}","linguagem":"php","alternativas":["500, porque o id não é um número.","200, com a ficha do primeiro livro da lista ordenada.","302, de volta à lista de livros.","404, porque (int) 'abc' dá 0 e não há livro 0."],"correta":3,"explicacao":"O (int) converte \"abc\" em 0, a consulta não encontra nenhum livro e a página responde 404 com uma mensagem própria, em vez de rebentar.","manual":"12.3"},{"id":"http-032","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Abres localhost/biblioteca/livro.php (sem o s) e aparece Not Found. Qual é a causa provável?","codigo":"","linguagem":"","alternativas":["O MySQL está desligado no XAMPP.","O endereço não bate certo com o nome do ficheiro.","Falta o session_start() no topo da página.","Há um erro de sintaxe no código PHP do ficheiro pedido."],"correta":1,"explicacao":"Not Found (404) quer dizer que o servidor não encontrou o ficheiro pedido: confirma o nome, as maiúsculas e a pasta dentro de htdocs.","manual":"17.1, 1.3"},{"id":"http-033","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Desligas o MySQL no XAMPP e abres a lista de livros. Que código de estado é de esperar?","codigo":"","linguagem":"","alternativas":["500, porque o código rebenta sem a base de dados.","404, porque os livros deixam de ser encontrados.","302, porque o servidor manda para a página inicial.","200, com a mensagem \"Não foi encontrado nenhum livro\"."],"correta":0,"explicacao":"O código 500 aparece quando o código rebenta, por exemplo com a base de dados desligada. O 404 é para uma página ou registo que não existe.","manual":"1.3"},{"id":"http-034","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"No separador Rede vês \"POST login.php → 302\". O que te diz isto?","codigo":"if ($utilizador && password_verify($password, $utilizador['password_hash'])) {\n    // guardar o utilizador na sessão\n    header('Location: livros.php');\n    exit;\n}\n$erros[] = 'Email ou password errados.';","linguagem":"php","alternativas":["O login falhou e a página de destino da resposta não foi encontrada.","O servidor rebentou ao verificar a password.","Os dados do login foram enviados no endereço.","O login foi aceite e o browser foi mandado para outra página."],"correta":3,"explicacao":"No login.php, só o login correto faz header('Location: livros.php'), que dá 302. Com a password errada, a página é mostrada outra vez com o erro.","manual":"10.4, 1.3"},{"id":"http-035","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Onde corre o PHP?","codigo":"","linguagem":"","alternativas":["No browser, depois do HTML.","No servidor (Apache).","No servidor de base de dados.","No browser, através do JavaScript."],"correta":1,"explicacao":"O PHP corre no servidor: recebe os pedidos, fala com a base de dados e gera o HTML que vai para o browser.","manual":"1.4"},{"id":"http-036","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Onde corre o validacao.js?","codigo":"","linguagem":"","alternativas":["No servidor Apache, antes do PHP.","No browser.","No MySQL, ao gravar os dados.","No servidor, ao receber o POST."],"correta":1,"explicacao":"O JavaScript (tal como o HTML e o CSS) corre no browser. Serve para validar os formulários antes de os enviar.","manual":"1.4"},{"id":"http-037","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Qual destas associações está ERRADA?","codigo":"","linguagem":"","alternativas":["CSS — corre no browser, para o aspeto das páginas.","SQL — corre no browser, para mostrar os livros.","PHP — corre no servidor, para gerar o HTML.","HTML — corre no browser, para a estrutura e os formulários."],"correta":1,"explicacao":"O SQL corre no servidor de base de dados (MySQL), a pedido do PHP. O browser só trata do HTML, do CSS e do JavaScript.","manual":"1.4"},{"id":"http-038","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Quem executa a consulta SELECT ... FROM livros?","codigo":"","linguagem":"","alternativas":["O MySQL, a pedido do PHP.","O browser, quando recebe a página.","O Apache, sem passar pelo PHP.","O JavaScript, antes de enviar o formulário."],"correta":0,"explicacao":"O SQL corre no servidor de base de dados. É o PHP que lhe envia a consulta e recebe as linhas.","manual":"1.4, 1.1"},{"id":"http-039","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Que tecnologia gera o HTML que o browser recebe na lista de livros?","codigo":"","linguagem":"","alternativas":["O JavaScript, no browser.","O MySQL, no servidor de base de dados.","O CSS, no browser.","O PHP, no servidor."],"correta":3,"explicacao":"O PHP usa as linhas devolvidas pelo MySQL para gerar o HTML. O MySQL só devolve dados e o CSS só trata do aspeto.","manual":"1.4, 1.1"},{"id":"http-040","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Para que serve a validação em JavaScript na Biblioteca?","codigo":"","linguagem":"","alternativas":["Garantir que não chegam dados inválidos ao servidor.","Substituir a validação no servidor nos formulários mais simples da aplicação.","Dar resposta imediata ao utilizador: é conforto, não segurança.","Proteger a base de dados contra SQL injection."],"correta":2,"explicacao":"O JavaScript mostra logo os erros, sem esperar pelo servidor. Mas pode ser desligado ou contornado, por isso a segurança tem de estar no servidor.","manual":"6.1, 1.4"},{"id":"http-041","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Se o validacao.js já verifica os campos, porque é que o servidor valida tudo outra vez?","codigo":"","linguagem":"","alternativas":["O JavaScript pode ser desligado, ou o pedido enviado sem o formulário.","O JavaScript só consegue validar os formulários que usam method=\"get\".","O browser apaga os valores que o JavaScript já validou.","O validacao.js só corre depois de os dados chegarem ao servidor."],"correta":0,"explicacao":"A validação no browser pode ser contornada. Só o que é verificado no servidor é garantido.","manual":"6.1"},{"id":"http-042","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Desligas o JavaScript e envias o formulário de registo em branco. O que tem de acontecer?","codigo":"","linguagem":"","alternativas":["A conta é criada com os campos vazios.","Os erros aparecem sem a página recarregar.","Aparecem os erros, agora vindos do servidor.","Aparece um erro 500, por faltar o JavaScript."],"correta":2,"explicacao":"Sem JavaScript, o formulário chega ao servidor, que valida e mostra os erros. Os erros sem recarregar só existem com o JavaScript ligado.","manual":"16, 6.1"},{"id":"http-043","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Este campo tem required. Isso garante que nunca chega vazio ao servidor?","codigo":"<input type=\"text\" id=\"titulo\" name=\"titulo\"\n       maxlength=\"200\" required>","linguagem":"html","alternativas":["Sim: o browser recusa sempre enviar o formulário.","Sim, desde que o formulário use method=\"post\".","Não, porque o required só funciona nos formulários com method=\"get\".","Não: o required pode ser contornado, por isso o servidor valida."],"correta":3,"explicacao":"required é uma regra do browser, e o browser está nas mãos do utilizador. A validação no servidor é obrigatória.","manual":"14, 1.4"},{"id":"http-044","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Em que pasta tem de estar o projeto para o Apache do XAMPP o servir?","codigo":"","linguagem":"","alternativas":["C:\\xampp\\htdocs","C:\\xampp\\mysql\\data","C:\\xampp\\php","Na pasta Documentos do utilizador"],"correta":0,"explicacao":"O Apache só serve os ficheiros que estão dentro de C:\\xampp\\htdocs. Cada pasta lá dentro passa a ter um endereço em http://localhost/.","manual":"2.3"},{"id":"http-045","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"O ficheiro está em C:\\xampp\\htdocs\\biblioteca\\css\\estilo.css. Que endereço o abre?","codigo":"","linguagem":"","alternativas":["http://localhost/htdocs/biblioteca/css/estilo.css","http://localhost/biblioteca/css/estilo.css","file:///biblioteca/css/estilo.css","http://localhost/xampp/biblioteca/css/estilo.css"],"correta":1,"explicacao":"A pasta htdocs corresponde a http://localhost/, por isso não entra no endereço: o resto do caminho mantém-se.","manual":"2.3"},{"id":"http-046","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Abres o livros.php com duplo clique e o endereço começa por file:///C:/... O que vês?","codigo":"","linguagem":"","alternativas":["A página normal, mas sem a folha de estilos.","O código PHP em bruto, porque o PHP não corre.","Um erro 404, porque o ficheiro não está no servidor.","A página normal, se o Apache estiver ligado."],"correta":1,"explicacao":"Com file:/// o ficheiro não passa pelo Apache, por isso o PHP não é executado. Tem de ser sempre http://localhost/....","manual":"2.4, 17.1"},{"id":"http-047","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"No XAMPP, que componentes fazem de servidor web e de base de dados?","codigo":"","linguagem":"","alternativas":["phpMyAdmin e Apache.","PHP e phpMyAdmin.","Apache e Visual Studio Code.","Apache e MySQL/MariaDB."],"correta":3,"explicacao":"O Apache é o servidor web e o MySQL/MariaDB é a base de dados. O phpMyAdmin é só uma ferramenta para gerir a base de dados no browser.","manual":"2.1"},{"id":"http-048","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Qual destes botões Apagar está feito da forma correta?","codigo":"","linguagem":"","alternativas":["Um <a href=\"livro_apagar.php?id_livro=3\" class=\"btn\"> com o texto Apagar.","Um <form method=\"get\"> com o id num <input type=\"hidden\"> e um botão type=\"submit\".","Um <button> com onclick que abre livro_apagar.php?id_livro=3.","Um <form method=\"post\"> com o id num <input type=\"hidden\"> e um botão submit."],"correta":3,"explicacao":"Apagar altera dados: tem de ser um formulário POST. As outras três fazem um GET, que pode ser seguido por robôs ou repetido sem querer.","manual":"4.4, 1.2"},{"id":"http-049","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"Escreves diretamente na barra do browser livro_editar.php?id=7. Que pedido fazes?","codigo":"","linguagem":"","alternativas":["Um POST, porque a página edita dados.","Um POST, com o id no corpo do pedido.","Um GET, igual ao de clicar no link Editar.","Nenhum: só se chega lá clicando no botão Editar."],"correta":2,"explicacao":"Escrever um endereço é sempre um GET. Por isso o GET de livro_editar.php só mostra o formulário; gravar é que é POST.","manual":"1.2, 12.1"},{"id":"http-050","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Este formulário cria livros novos. Qual é o problema?","codigo":"<form method=\"get\" action=\"livro_novo.php\">\n    <label for=\"titulo\">Título</label>\n    <input type=\"text\" id=\"titulo\" name=\"titulo\">\n    <button type=\"submit\">Gravar</button>\n</form>","linguagem":"html","alternativas":["Usa GET: o pedido pode repetir-se e criar o livro duas vezes.","Falta o atributo id no <form>, sem o qual o servidor não recebe nada.","O action não pode apontar para a mesma página que mostra o formulário.","Com GET o campo titulo não chega ao servidor, por isso nada é gravado."],"correta":0,"explicacao":"Um formulário que cria dados usa method=\"post\". Com GET o título iria no endereço e qualquer repetição do pedido criava outro livro.","manual":"1.2, 4.2"},{"id":"http-051","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Em que caso a Biblioteca responde com 200 a um POST deste formulário?","codigo":"if ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    // ... validar e preencher $erros\n    if (!$erros) {\n        // INSERT INTO livros ...\n        header(\"Location: livro_ver.php?id=$novoId\");\n        exit;\n    }\n}\n// mostrar o formulário (com os erros, se houver)","linguagem":"php","alternativas":["Quando o livro novo é gravado com sucesso na base de dados.","Quando a validação falha e o formulário reaparece com os erros.","Quando o livro que se tentou editar já não existe na base de dados.","Quando o código PHP rebenta a meio da gravação."],"correta":1,"explicacao":"Só o sucesso redireciona (302). Quando a validação falha, a página é mostrada logo com os erros e os valores escritos, e isso é uma resposta 200.","manual":"9.5, 1.3"},{"id":"http-052","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"O que é o código de estado de uma resposta HTTP?","codigo":"","linguagem":"","alternativas":["O número da linha onde o PHP falhou.","O identificador da sessão do utilizador.","Um número que diz como correu o pedido.","O id do registo criado na base de dados."],"correta":2,"explicacao":"Cada resposta traz um código de estado: 200, 302, 404, 500… O número da linha do erro aparece na mensagem do PHP, não no código.","manual":"1.3"},{"id":"http-053","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Sem sessão iniciada, abres livros.php e acabas no login. Que código recebeste primeiro?","codigo":"<?php\n// includes/auth.php\nif (!isset($_SESSION['id_utilizador'])) {\n    mensagem('erro', 'Tens de iniciar sessão para ver essa página.');\n    header('Location: login.php');\n    exit;\n}","linguagem":"php","alternativas":["404, porque a página não existe para quem não entrou.","500, porque a sessão não foi encontrada.","302, porque o servidor redireciona para o login.","200, com a lista de livros vazia."],"correta":2,"explicacao":"O header('Location: ...') responde com um redirecionamento (302). O browser faz depois um GET a login.php, que responde 200.","manual":"11.2, 1.3"},{"id":"http-054","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Qual destas afirmações sobre GET e POST está certa?","codigo":"","linguagem":"","alternativas":["Um link faz POST quando tem parâmetros depois do ?.","Um formulário faz sempre POST, seja qual for o valor do atributo method.","Um formulário pode usar GET ou POST; um link faz sempre GET.","Escrever um endereço na barra do browser faz um POST."],"correta":2,"explicacao":"O formulário escolhe o método com o atributo method (a pesquisa usa get, o registo usa post). Um link é sempre um pedido GET.","manual":"1.2, 4.4"},{"id":"http-055","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Mudaram a pesquisa dos livros para este formulário. O que se perde?","codigo":"<form method=\"post\" action=\"livros.php\">\n    <input type=\"search\" name=\"q\">\n    <button type=\"submit\">Pesquisar</button>\n</form>","linguagem":"html","alternativas":["O texto deixa de ir no URL: a pesquisa já não se guarda nem partilha.","Deixa de ser possível usar o LIKE na consulta SQL que faz a pesquisa.","O texto pesquisado deixa de chegar ao servidor.","A pesquisa passa a apagar os livros que não encontra."],"correta":0,"explicacao":"Com POST o texto vai no corpo do pedido. Continua a chegar (em $_POST), mas o endereço deixa de ter ?q=..., por isso não vai para os favoritos nem se partilha.","manual":"1.2, 12.2"},{"id":"http-056","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Qual é o papel do Apache na Biblioteca?","codigo":"","linguagem":"","alternativas":["Guardar as tabelas dos utilizadores e dos livros.","Executar o JavaScript que valida os formulários antes do envio.","Desenhar as páginas no ecrã do utilizador.","Receber os pedidos e entregar os ficheiros .php ao PHP."],"correta":3,"explicacao":"O Apache é o servidor web: recebe o pedido do browser e, se o ficheiro é PHP, entrega-o ao interpretador. Os dados ficam no MySQL e o JavaScript corre no browser.","manual":"1.1, 2.1"},{"id":"http-057","bloco":"dados","tema":"HTTP","dificuldade":"facil","pergunta":"No endereço livros.php?q=mar, o que separa o ponto de interrogação?","codigo":"","linguagem":"","alternativas":["A página pedida dos dados enviados por GET.","O nome da pasta do nome do ficheiro.","O método do pedido (GET ou POST) do endereço da página.","O endereço do servidor da base de dados."],"correta":0,"explicacao":"Num pedido GET os dados vão no URL depois do ?, no formato nome=valor. Aqui, q=mar chega ao PHP em $_GET['q'].","manual":"1.2"},{"id":"http-058","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Pesquisas um título que não existe. O que devolve o servidor?","codigo":"<?php if (count($livros) === 0): ?>\n    <p class=\"vazio\">Não foi encontrado nenhum livro.</p>\n<?php else: ?>\n    <!-- cartões dos livros -->\n<?php endif; ?>","linguagem":"php","alternativas":["Código 404, porque a pesquisa feita não encontrou nenhum livro na base.","Código 200, com a mensagem \"Não foi encontrado nenhum livro.\"","Código 500, porque a consulta não devolveu linhas.","Código 302, de volta à lista completa de livros."],"correta":1,"explicacao":"A página livros.php existe e correu bem: só não há resultados. A resposta é 200 e a página mostra uma mensagem própria em vez de uma lista vazia.","manual":"12.2, 1.3"},{"id":"http-059","bloco":"dados","tema":"HTTP","dificuldade":"media","pergunta":"Porque é que o formulário de login usa method=\"post\"?","codigo":"","linguagem":"","alternativas":["Com GET o servidor não consegue ler os campos do formulário.","O password_verify() só funciona com dados que vêm de POST.","Envia dados para iniciar sessão; com GET a password ia no endereço.","Com POST a password é cifrada pelo browser antes de sair do computador."],"correta":2,"explicacao":"Fazer login é um dos casos de POST. Com GET, os campos iam no URL, incluindo a password, e ficavam no histórico do browser.","manual":"1.2"},{"id":"http-060","bloco":"dados","tema":"HTTP","dificuldade":"dificil","pergunta":"Como chega ao servidor o id do livro quando carregas em Apagar?","codigo":"<form method=\"post\" action=\"livro_apagar.php\">\n    <input type=\"hidden\" name=\"id_livro\" value=\"7\">\n    <button type=\"submit\" class=\"perigo\">Apagar</button>\n</form>","linguagem":"html","alternativas":["No endereço do pedido, como livro_apagar.php?id_livro=7.","No corpo do pedido POST, lido em $_POST['id_livro'].","Num cookie, lido em $_COOKIE['id_livro'].","No corpo do pedido, lido em $_GET['id_livro']."],"correta":1,"explicacao":"O <input type=\"hidden\"> é enviado como qualquer campo, mas sem aparecer. Como o formulário é POST, vai no corpo do pedido e lê-se em $_POST.","manual":"4.2, 4.4"},{"id":"amostra-005","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Sabendo que a autora Ana ainda não tem nenhum livro, o que mostra esta consulta para ela?","codigo":"SELECT a.nome, COUNT(l.id_livro) AS total_livros\nFROM autores a\nLEFT JOIN livros l ON l.id_autor = a.id_autor\nGROUP BY a.id_autor, a.nome;","linguagem":"sql","alternativas":["A Ana não aparece, porque não tem livros.","Ana | 0","Ana | 1","Ana | NULL"],"correta":1,"explicacao":"O LEFT JOIN mantém todos os autores, mesmo sem livros. O COUNT(l.id_livro) só conta valores não nulos, por isso dá 0. Com JOIN, a Ana não apareceria.","manual":"3.7, 13.1"},{"id":"amostra-006","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Numa clínica veterinária, um tutor tem vários animais e cada animal tem um só tutor. Onde fica a chave estrangeira?","codigo":"","linguagem":"","alternativas":["Na tabela animais, numa coluna id_tutor.","Na tabela tutores, numa coluna id_animal.","Nas duas tabelas, uma em cada.","Numa terceira tabela, obrigatoriamente."],"correta":0,"explicacao":"Numa relação 1:N, a chave estrangeira fica sempre do lado N (animais). Um tutor não pode ter id_animal, porque teria de guardar vários números na mesma célula.","manual":"3.3, 13.4"},{"id":"sql-001","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Numa tabela da base de dados, o que representa cada linha?","codigo":"","linguagem":"","alternativas":["Uma característica comum a todos os registos, como o título.","Um registo: uma das coisas guardadas, por exemplo um livro.","O tipo de dados que uma coluna aceita.","A ligação entre duas tabelas diferentes."],"correta":1,"explicacao":"Uma tabela guarda um tipo de coisa: cada linha é uma dessas coisas (um livro) e cada coluna é uma característica (o título, o ano).","manual":"3.1"},{"id":"sql-002","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Na tabela `livros`, o que é `titulo`?","codigo":"","linguagem":"","alternativas":["Uma coluna: uma característica que todos os livros têm.","A chave primária da tabela livros.","Uma tabela ligada à tabela livros.","Uma linha da tabela, com os dados de um livro."],"correta":0,"explicacao":"As colunas são as características (titulo, ano_edicao, isbn…); as linhas são os livros. A chave primária de livros é id_livro.","manual":"3.1"},{"id":"sql-003","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Qual é a regra para decidir que tabelas criar?","codigo":"","linguagem":"","alternativas":["Usa-se uma só tabela com todas as colunas, para evitar o JOIN.","Cria-se uma tabela para cada formulário da aplicação.","Cria-se uma tabela para cada página PHP da aplicação.","Cada tabela guarda um tipo de coisa: utilizadores, autores, livros."],"correta":3,"explicacao":"Uma tabela corresponde a um tipo de coisa, e não a páginas ou formulários. Juntar tudo numa tabela obrigaria a repetir dados; as tabelas relacionadas juntam-se com JOIN.","manual":"3.1"},{"id":"sql-004","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"No teu projeto, além das duas entidades relacionadas em 1:N, que tabela podes manter igual à da Biblioteca?","codigo":"","linguagem":"","alternativas":["sessoes, para guardar a $_SESSION","livros, porque é a tabela do lado N","utilizadores, para o registo e o login","autores, porque todos os projetos têm autores"],"correta":2,"explicacao":"O manual diz para trocar autores e livros pelas tuas entidades; a tabela utilizadores (registo e login) pode ficar igual.","manual":"3.7, 3.1"},{"id":"sql-005","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Porque é que a base de dados é a primeira coisa a fazer?","codigo":"","linguagem":"","alternativas":["Porque o Apache não arranca enquanto não houver uma base de dados criada.","Porque o phpMyAdmin só deixa criar tabelas antes de existirem ficheiros PHP.","Porque tudo depende dela: um bom modelo de dados simplifica o código.","Porque o CSS e o JavaScript leem os dados diretamente das tabelas."],"correta":2,"explicacao":"O manual começa pela base de dados porque as páginas dependem do modelo: se estiver bem pensado, o código fica simples; se estiver mal, cada página precisa de remendos.","manual":"3"},{"id":"sql-006","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que é a chave primária de uma tabela?","codigo":"","linguagem":"","alternativas":["A coluna pela qual a tabela fica ordenada.","A primeira coluna escrita no CREATE TABLE.","A coluna que liga a tabela a outra tabela.","A coluna que identifica cada linha de forma única."],"correta":3,"explicacao":"A chave primária (PK) identifica cada linha: não há dois livros com o mesmo id_livro. A coluna que liga a outra tabela é a chave estrangeira.","manual":"3.2"},{"id":"sql-007","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que faz o AUTO_INCREMENT nesta coluna?","codigo":"id_livro INT AUTO_INCREMENT PRIMARY KEY","linguagem":"sql","alternativas":["Obriga o programa a calcular o próximo id antes de cada INSERT.","A base de dados escolhe o número seguinte sempre que se insere uma linha.","Soma 1 ao id_livro sempre que o livro é editado.","Impede que o id_livro seja usado como chave estrangeira."],"correta":1,"explicacao":"Com AUTO_INCREMENT é a base de dados que escolhe o número (1, 2, 3…) a cada INSERT. Editar a linha não muda o id.","manual":"3.2"},{"id":"sql-008","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Porque é que este INSERT não indica a coluna `id_autor`?","codigo":"INSERT INTO autores (nome, nacionalidade)\nVALUES (?, ?);","linguagem":"sql","alternativas":["Porque id_autor é AUTO_INCREMENT: a base de dados gera-o.","Porque o PHP calcula o id com COUNT(*) + 1 e junta-o sozinho.","Porque o id_autor é preenchido depois, com um UPDATE.","Porque a chave primária pode ficar NULL até haver livros."],"correta":0,"explicacao":"A chave primária com AUTO_INCREMENT é escolhida pela base de dados, por isso nunca a envias no INSERT. Calcular o id à mão daria problemas quando se apagam linhas.","manual":"3.2, 3.7"},{"id":"sql-009","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"O base_dados.sql insere 6 livros numa tabela `livros` acabada de criar, sem indicar o `id_livro`. Que ids ficam?","codigo":"","linguagem":"","alternativas":["Números ao acaso, desde que não se repitam","Ficam todos NULL, porque o INSERT não os envia","0, 1, 2, 3, 4 e 5, pela ordem do INSERT","1, 2, 3, 4, 5 e 6, pela ordem do INSERT"],"correta":3,"explicacao":"O AUTO_INCREMENT começa em 1 e vai somando 1 a cada linha inserida. É por isso que, nos INSERT de exemplo, o autor 1 é o José Saramago (o primeiro a ser inserido).","manual":"3.2, 3.5"},{"id":"sql-010","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Na tabela `livros`, a coluna `id_autor` tem os valores 1, 1, 2, 2, 3, 4. Podia ser a chave primária de livros?","codigo":"","linguagem":"","alternativas":["Sim, desde que a coluna seja NOT NULL.","Sim, porque é do tipo INT, como as outras chaves primárias.","Não: tem valores repetidos, e a chave primária é única em cada linha.","Não, porque uma chave primária tem de ser do tipo VARCHAR."],"correta":2,"explicacao":"A chave primária identifica cada linha de forma única, por isso não pode ter valores repetidos. id_autor repete-se porque um autor tem vários livros: é a chave estrangeira.","manual":"3.2"},{"id":"sql-011","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Porque é que a página de detalhe procura o livro com `WHERE l.id_livro = ?` e não pelo título?","codigo":"","linguagem":"","alternativas":["Porque id_livro é a chave primária: identifica um só livro, sem dúvidas.","Porque o título só pode ser comparado com LIKE e nunca com =.","Porque o título fica guardado em hash e não se consegue comparar.","Porque uma coluna VARCHAR não pode aparecer numa cláusula WHERE."],"correta":0,"explicacao":"O título não é único (podem existir dois livros com o mesmo título); a chave primária garante que o WHERE encontra exatamente uma linha.","manual":"3.2, 12.3"},{"id":"sql-012","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Depois de importar o base_dados.sql (4 autores), inseres dois autores novos. Que `id_autor` recebe o primeiro deles?","codigo":"","linguagem":"","alternativas":["0","1","4","5"],"correta":3,"explicacao":"O AUTO_INCREMENT continua a partir do último número usado: os autores de exemplo ficaram com 1 a 4, por isso o seguinte é o 5 (e o outro novo fica com 6).","manual":"3.2, 3.7"},{"id":"sql-013","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que é uma chave estrangeira?","codigo":"","linguagem":"","alternativas":["Uma coluna copiada de outra base de dados.","Uma coluna que guarda o id de uma linha de outra tabela.","Uma coluna cujos valores não se podem repetir.","A coluna que identifica cada linha da própria tabela."],"correta":1,"explicacao":"A chave estrangeira (FK) guarda o id do lado 1 numa coluna da tabela do lado N, como livros.id_autor. A coluna que identifica a própria linha é a chave primária; a que impede repetidos é UNIQUE.","manual":"3.3"},{"id":"sql-014","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Um autor pode ter vários livros, mas cada livro tem um só autor. Que relação é esta?","codigo":"","linguagem":"","alternativas":["N:N (muitos para muitos)","Nenhuma: são tabelas independentes","1:N (um para muitos)","1:1 (um para um)"],"correta":2,"explicacao":"Um autor → vários livros, cada livro → um autor: é uma relação de um para muitos, escrita 1:N.","manual":"3.3"},{"id":"sql-015","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Numa relação 1:N, em que tabela fica a chave estrangeira?","codigo":"","linguagem":"","alternativas":["Na tabela do lado N.","Nas duas tabelas, uma em cada.","Na tabela do lado 1.","Numa terceira tabela, só com as duas chaves."],"correta":0,"explicacao":"A FK fica sempre do lado N (livros.id_autor). Do lado 1 seria preciso guardar vários números na mesma célula.","manual":"3.3, Anexo B"},{"id":"sql-016","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Numa loja, uma categoria tem vários produtos e cada produto pertence a uma só categoria. Que coluna é a chave estrangeira?","codigo":"","linguagem":"","alternativas":["categorias.id_categoria","produtos.id_categoria","produtos.id_produto","categorias.id_produto"],"correta":1,"explicacao":"Pergunta \"uma categoria tem vários produtos?\": sim, por isso a FK fica em produtos, a guardar o id da categoria. produtos.id_produto e categorias.id_categoria são chaves primárias.","manual":"3.3, 13.4"},{"id":"sql-017","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Um cliente faz várias encomendas e cada encomenda é de um só cliente. O que deves criar?","codigo":"","linguagem":"","alternativas":["Uma coluna encomendas em clientes, com os ids separados por vírgulas.","As colunas id_cliente e id_encomenda na tabela clientes.","Uma coluna id_cliente na tabela encomendas.","Uma coluna id_encomenda na tabela clientes."],"correta":2,"explicacao":"\"Um cliente tem várias encomendas?\" Sim, logo a FK fica em encomendas. Guardar vários ids numa célula de clientes é exatamente o erro que a regra evita.","manual":"3.3, 3.7"},{"id":"sql-018","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Porque é que a tabela `autores` não pode ter uma coluna `id_livro`?","codigo":"","linguagem":"","alternativas":["Porque o MySQL não deixa duas tabelas terem colunas com nomes parecidos.","Porque um autor tem vários livros: teria de guardar vários números na mesma célula.","Porque id_livro já é a chave primária de livros e não pode aparecer noutra tabela.","Porque as chaves estrangeiras só podem ser do tipo VARCHAR."],"correta":1,"explicacao":"É a \"regra para nunca te enganares\" do manual: a FK fica sempre do lado N. Uma PK pode perfeitamente aparecer noutra tabela, como FK; aqui o problema é o lado.","manual":"3.3"},{"id":"sql-019","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Numa escola, uma turma tem vários alunos e cada aluno está numa só turma. Qual é a tabela do lado N?","codigo":"","linguagem":"","alternativas":["alunos","As duas são do lado N","Depende da tabela que for criada primeiro","turmas"],"correta":0,"explicacao":"O lado N é o dos \"vários\": alunos. É lá que fica a chave estrangeira id_turma.","manual":"3.3"},{"id":"sql-020","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Um tutor pode ter vários animais e cada animal tem um só tutor. O que está errado neste desenho?","codigo":"CREATE TABLE tutores (\n    id_tutor  INT AUTO_INCREMENT PRIMARY KEY,\n    nome      VARCHAR(100) NOT NULL,\n    id_animal INT NOT NULL\n);","linguagem":"sql","alternativas":["id_tutor devia ser VARCHAR, porque identifica uma pessoa.","Nada: a chave estrangeira pode ficar em qualquer das duas tabelas.","Falta UNIQUE em id_animal, para o tutor não repetir animais.","A FK está do lado 1: devia ser id_tutor na tabela animais."],"correta":3,"explicacao":"Com id_animal em tutores, cada tutor só poderia ter um animal. A FK fica do lado N: animais.id_tutor.","manual":"3.3"},{"id":"sql-021","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Na tabela `animais`, qual é a chave primária e qual é a chave estrangeira?","codigo":"CREATE TABLE animais (\n    id_animal INT AUTO_INCREMENT PRIMARY KEY,\n    id_tutor  INT NOT NULL,\n    nome      VARCHAR(80) NOT NULL,\n    CONSTRAINT fk_animais_tutores\n        FOREIGN KEY (id_tutor) REFERENCES tutores (id_tutor)\n        ON DELETE RESTRICT\n);","linguagem":"sql","alternativas":["PK: id_tutor; FK: id_animal","PK: id_animal; FK: nome","PK: id_animal; FK: fk_animais_tutores","PK: id_animal; FK: id_tutor"],"correta":3,"explicacao":"A PK está assinalada com PRIMARY KEY (id_animal) e a FK com FOREIGN KEY (id_tutor) REFERENCES tutores. É o mesmo desenho de livros/autores.","manual":"3.2, 3.3"},{"id":"sql-022","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Na Biblioteca, a tabela livros é criada assim. Qual destas colunas é a chave estrangeira?","codigo":"CREATE TABLE livros (\n    id_livro   INT AUTO_INCREMENT PRIMARY KEY,\n    id_autor   INT          NOT NULL,\n    titulo     VARCHAR(200) NOT NULL,\n    isbn       VARCHAR(13)  NULL UNIQUE,\n    ano_edicao SMALLINT     NULL,\n    sinopse    TEXT         NULL,\n    CONSTRAINT fk_livros_autores\n        FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n        ON DELETE RESTRICT\n);","linguagem":"sql","alternativas":["autores.id_autor","livros.id_autor","livros.id_livro","utilizadores.id_utilizador"],"correta":1,"explicacao":"livros.id_autor guarda o id do autor de cada livro. autores.id_autor, livros.id_livro e utilizadores.id_utilizador são chaves primárias.","manual":"3.3"},{"id":"sql-023","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Sabendo que a Sophia de Mello Breyner Andresen foi a segunda autora inserida, que títulos devolve esta consulta com os dados de exemplo?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo FROM livros WHERE id_autor = 2;","linguagem":"sql","alternativas":["A Menina do Mar e O Cavaleiro da Dinamarca","Memorial do Convento e Ensaio sobre a Cegueira","Ensaio sobre a Cegueira","Nenhum: id_autor = 2 é o id do segundo livro"],"correta":0,"explicacao":"A Sophia ficou com id_autor = 2 (AUTO_INCREMENT) e os seus dois livros têm id_autor = 2. O WHERE filtra pela FK, não pelo id do livro.","manual":"3.3, 3.5"},{"id":"sql-024","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Inseriste a autora Ana (id 5) e ainda não lhe associaste nenhum livro. O que há sobre ela na tabela `livros`?","codigo":"","linguagem":"","alternativas":["Uma coluna nova chamada id_autor_5.","Uma linha criada automaticamente pela chave estrangeira.","Nada: só aparece quando um livro tiver id_autor = 5.","Uma linha com id_autor = 5 e titulo a NULL."],"correta":2,"explicacao":"A FK está do lado N: é cada livro que diz qual é o seu autor. Um autor sem livros simplesmente não aparece em livros.","manual":"3.3"},{"id":"sql-025","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Onde está guardada a informação de que \"Os Maias\" é de Eça de Queirós?","codigo":"Dados de exemplo (base_dados.sql)\n\nautores\nid_autor | nome                             | nacionalidade\n1        | José Saramago                    | Portuguesa\n2        | Sophia de Mello Breyner Andresen | Portuguesa\n3        | Eça de Queirós                   | Portuguesa\n4        | Machado de Assis                 | Brasileira\n\nlivros\nid_livro | id_autor | titulo                   | isbn          | ano_edicao\n1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n5        | 3        | Os Maias                 | 9789722036597 | 1888\n6        | 4        | Dom Casmurro             | 9788535910681 | 1899","linguagem":"tabela","alternativas":["Na coluna id_autor da linha de \"Os Maias\", que vale 3.","No id_livro de \"Os Maias\", que é igual ao id do autor.","Numa coluna livros, na linha de Eça de Queirós em autores.","Numa terceira tabela que junta autores e livros."],"correta":0,"explicacao":"A relação guarda-se do lado N: a linha do livro tem id_autor = 3, o id de Eça de Queirós. É essa coluna que o JOIN usa.","manual":"3.3, 3.5"},{"id":"sql-026","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Numa clínica veterinária (tutores 1:N animais), que regra corresponde a \"um autor com livros não se apaga\"?","codigo":"","linguagem":"","alternativas":["Um animal com tutor não se apaga.","Um animal só se apaga junto com o tutor.","Um tutor sem animais não se apaga.","Um tutor com animais não se apaga."],"correta":3,"explicacao":"O lado 1 (tutores) faz o papel dos autores; com ON DELETE RESTRICT, não se apaga o \"pai\" enquanto tiver \"filhos\" (animais).","manual":"13.4"},{"id":"sql-027","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Com a tabela livros criada assim, o que acontece quando se tenta apagar um autor que ainda tem livros?","codigo":"CREATE TABLE livros (\n    id_livro   INT AUTO_INCREMENT PRIMARY KEY,\n    id_autor   INT          NOT NULL,\n    titulo     VARCHAR(200) NOT NULL,\n    isbn       VARCHAR(13)  NULL UNIQUE,\n    ano_edicao SMALLINT     NULL,\n    sinopse    TEXT         NULL,\n    CONSTRAINT fk_livros_autores\n        FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n        ON DELETE RESTRICT\n);","linguagem":"sql","alternativas":["Apaga o autor e todos os livros dele.","Apaga o autor e os livros ficam com id_autor a NULL.","A base de dados recusa, por causa do ON DELETE RESTRICT.","Apaga o autor e os livros ficam com id_autor = 0."],"correta":2,"explicacao":"A FK fk_livros_autores tem ON DELETE RESTRICT: enquanto o autor tiver livros, o DELETE é recusado. Apagar também os livros seria o CASCADE.","manual":"3.3, 13.3"},{"id":"sql-028","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Que opção da chave estrangeira apaga o autor e também todos os seus livros?","codigo":"","linguagem":"","alternativas":["ON DELETE SET NULL","ON DELETE CASCADE","UNIQUE na coluna id_autor","ON DELETE RESTRICT"],"correta":1,"explicacao":"CASCADE propaga o apagamento aos \"filhos\". O manual chama-lhe perigoso na Biblioteca, porque se perdem livros por engano.","manual":"3.3"},{"id":"sql-029","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Na Biblioteca, a tabela livros é criada assim. Porque é que ON DELETE SET NULL não serve aqui?","codigo":"CREATE TABLE livros (\n    id_livro   INT AUTO_INCREMENT PRIMARY KEY,\n    id_autor   INT          NOT NULL,\n    titulo     VARCHAR(200) NOT NULL,\n    isbn       VARCHAR(13)  NULL UNIQUE,\n    ano_edicao SMALLINT     NULL,\n    sinopse    TEXT         NULL,\n    CONSTRAINT fk_livros_autores\n        FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n        ON DELETE RESTRICT\n);","linguagem":"sql","alternativas":["Porque SET NULL apaga também os livros, sem avisar.","Porque SET NULL só funciona com colunas VARCHAR.","Porque livros.id_autor é NOT NULL: o autor é obrigatório.","Porque o MySQL não aceita SET NULL em chaves estrangeiras."],"correta":2,"explicacao":"SET NULL deixaria os livros com id_autor vazio, mas a coluna é NOT NULL (cada livro tem de ter autor). Quem apaga os livros é o CASCADE.","manual":"3.3"},{"id":"sql-030","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Porque é que a Biblioteca usa ON DELETE RESTRICT e não CASCADE?","codigo":"","linguagem":"","alternativas":["Porque o CASCADE impede que se insiram livros novos.","Porque o CASCADE fica lento quando há muitos livros.","Porque o RESTRICT apaga primeiro os livros e só depois o autor.","Para não se perderem livros por engano ao apagar um autor."],"correta":3,"explicacao":"Com CASCADE, apagar um autor levava todos os livros dele. O RESTRICT recusa o apagamento enquanto houver livros, e nada se perde.","manual":"3.3"},{"id":"sql-031","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, o que acontece a esta instrução?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nDELETE FROM autores WHERE id_autor = 1;","linguagem":"sql","alternativas":["Apaga o José Saramago e os livros dele ficam sem autor.","Dá erro e nada é apagado: o José Saramago tem livros.","Apaga o José Saramago e os livros passam para o autor 2.","Apaga o José Saramago e os seus dois livros."],"correta":1,"explicacao":"É a experiência do manual: a FK tem ON DELETE RESTRICT e o autor 1 tem dois livros, por isso a base de dados recusa e não apaga nada.","manual":"3.3, 3.7"},{"id":"sql-032","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Se a chave estrangeira fosse ON DELETE CASCADE, quantos livros ficavam depois desta instrução, com os dados de exemplo?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nDELETE FROM autores WHERE id_autor = 2;","linguagem":"sql","alternativas":["Nenhum","4","5","6"],"correta":1,"explicacao":"Com CASCADE, apagar a Sophia (autor 2) apagava também os seus 2 livros: dos 6 ficavam 4. Com o RESTRICT da Biblioteca, a instrução seria recusada e ficavam os 6.","manual":"3.3, 3.5"},{"id":"sql-033","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Este é o fim do autor_apagar.php. Quem impede que se apague um autor que tem livros?","codigo":"try {\n    $stmt = $pdo->prepare('DELETE FROM autores WHERE id_autor = ?');\n    $stmt->execute([(int) ($_POST['id_autor'] ?? 0)]);\n    mensagem('sucesso', 'Autor apagado.');\n} catch (PDOException $e) {\n    mensagem('erro', 'Não é possível apagar este autor, porque tem livros registados.');\n}\nheader('Location: autores.php');\nexit;","linguagem":"php","alternativas":["A base de dados (ON DELETE RESTRICT); o PHP só apanha o erro.","O JavaScript, com o confirm() do botão Apagar.","Um SELECT COUNT(*) que o código faz sempre antes do DELETE.","O phpMyAdmin, que vigia as tabelas enquanto a aplicação corre."],"correta":0,"explicacao":"Não é o código que verifica se o autor tem livros: é a chave estrangeira. O PHP apanha a exceção e mostra \"Não é possível apagar este autor\".","manual":"13.3"},{"id":"sql-034","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Qual é a vantagem de ser a própria base de dados a garantir o ON DELETE RESTRICT?","codigo":"","linguagem":"","alternativas":["Deixa de ser preciso o WHERE no DELETE dos autores.","O formulário de apagar pode passar a ser um simples link.","A regra vale mesmo que alguém apague o autor no phpMyAdmin.","Os livros do autor são apagados mais depressa."],"correta":2,"explicacao":"Como a regra está na FK, nenhuma forma de apagar a contorna: nem a aplicação, nem o phpMyAdmin. O WHERE e o POST continuam a ser obrigatórios.","manual":"13.3"},{"id":"sql-035","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Nesta parte do CREATE TABLE livros, o que indica `REFERENCES autores (id_autor)`?","codigo":"CONSTRAINT fk_livros_autores\n    FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n    ON DELETE RESTRICT","linguagem":"sql","alternativas":["A tabela e a coluna para onde a chave estrangeira aponta.","O nome que se dá à restrição da chave estrangeira.","A coluna de livros que passa a ser a chave primária.","A tabela que é apagada em conjunto com a tabela livros."],"correta":0,"explicacao":"FOREIGN KEY (id_autor) é a coluna de livros; REFERENCES autores (id_autor) diz que os valores têm de existir na chave primária de autores. O nome da restrição é fk_livros_autores.","manual":"3.3, 3.5"},{"id":"sql-036","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Nesta instrução, o que é `fk_livros_autores`?","codigo":"CONSTRAINT fk_livros_autores\n    FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n    ON DELETE RESTRICT","linguagem":"sql","alternativas":["Uma coluna nova criada na tabela livros.","O nome do índice UNIQUE do ISBN.","Uma terceira tabela que liga livros e autores.","O nome dado à chave estrangeira."],"correta":3,"explicacao":"CONSTRAINT dá um nome à restrição: a chave estrangeira chama-se fk_livros_autores. Não cria tabelas nem colunas.","manual":"3.5"},{"id":"sql-037","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Numa loja, cada produto pertence a uma categoria. O que completa a chave estrangeira?","codigo":"CREATE TABLE produtos (\n    id_produto   INT AUTO_INCREMENT PRIMARY KEY,\n    id_categoria INT NOT NULL,\n    nome         VARCHAR(120) NOT NULL,\n    CONSTRAINT fk_produtos_categorias\n        ____________________\n        ON DELETE RESTRICT\n);","linguagem":"sql","alternativas":["FOREIGN KEY (categorias.id_categoria) REFERENCES produtos (id_categoria)","PRIMARY KEY (id_categoria) REFERENCES categorias (id_categoria)","FOREIGN KEY (id_categoria) REFERENCES categorias (id_categoria)","FOREIGN KEY (id_produto) REFERENCES categorias (id_categoria)"],"correta":2,"explicacao":"Primeiro FOREIGN KEY com a coluna de produtos que guarda o id (id_categoria), depois REFERENCES com a tabela e a chave primária do lado 1, tal como em livros/autores.","manual":"3.3, 3.5, 13.4"},{"id":"sql-038","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Imagina que a tabela livros era assim. O que acontecia aos livros de Eça de Queirós ao apagá-lo?","codigo":"id_autor INT NULL,\n...\nCONSTRAINT fk_livros_autores\n    FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n    ON DELETE SET NULL","linguagem":"sql","alternativas":["O DELETE do autor era recusado.","Passavam para o autor com o id seguinte.","Eram apagados junto com o autor.","Ficavam na tabela, com id_autor vazio (NULL)."],"correta":3,"explicacao":"SET NULL apaga o autor e deixa os livros com id_autor vazio. Apagar os livros é o CASCADE; recusar é o RESTRICT.","manual":"3.3"},{"id":"sql-039","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, porque é que este INSERT falha?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nINSERT INTO livros (id_autor, titulo)\nVALUES (9, 'Livro de teste');","linguagem":"sql","alternativas":["Não existe nenhum autor com id_autor = 9.","Falta enviar o id_livro da nova linha.","O título tem de ter pelo menos 20 caracteres.","Faltam o isbn, o ano_edicao e a sinopse."],"correta":0,"explicacao":"A chave estrangeira obriga a que id_autor exista em autores (há só 4). As restantes colunas são AUTO_INCREMENT ou opcionais (NULL). É também por isto que validar_livro() confirma que o autor existe.","manual":"3.3, 8.5"},{"id":"sql-040","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo e a FK com ON DELETE RESTRICT, o que acontece a esta instrução?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nDELETE FROM autores;","linguagem":"sql","alternativas":["Apaga os 4 autores e deixa os livros sem autor.","Dá erro e nada é apagado: todos têm livros.","Apaga os 4 autores e, com eles, os 6 livros.","Pede confirmação e depois apaga os 4 autores."],"correta":1,"explicacao":"Sem WHERE, o DELETE tentaria apagar todos os autores, mas todos têm livros e o RESTRICT recusa. A base de dados nunca pede confirmação: isso só existe se a aplicação a puser.","manual":"3.3, 3.7"},{"id":"sql-041","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Que tipo de dados serve para guardar a sinopse de um livro, um texto longo?","codigo":"","linguagem":"","alternativas":["VARCHAR(13)","DATETIME","TEXT","SMALLINT"],"correta":2,"explicacao":"TEXT é para texto longo. VARCHAR(n) é para texto curto até n caracteres (VARCHAR(13) é o ISBN), SMALLINT para inteiros pequenos e DATETIME para data e hora.","manual":"3.4"},{"id":"sql-042","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Segundo a tabela de tipos do manual (em baixo), que tipo serve para guardar um ano de edição, como 1888?","codigo":"Tipo        | Guarda\n------------+------------------------------\nINT         | Números inteiros\nSMALLINT    | Inteiros pequenos (até 32 767)\nVARCHAR(n)  | Texto curto, até n caracteres\nTEXT        | Texto longo\nDATETIME    | Data e hora","linguagem":"tabela","alternativas":["SMALLINT","DATETIME","TEXT","VARCHAR(200)"],"correta":0,"explicacao":"SMALLINT guarda inteiros pequenos (até 32 767), o que chega para um ano. DATETIME guarda data e hora completas.","manual":"3.4"},{"id":"sql-043","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que quer dizer `VARCHAR(200)` em `titulo VARCHAR(200)`?","codigo":"","linguagem":"","alternativas":["Texto com exatamente 200 caracteres.","Texto longo guardado em blocos de 200.","Um número inteiro até 200.","Texto curto com, no máximo, 200 caracteres."],"correta":3,"explicacao":"VARCHAR(n) guarda texto curto até n caracteres; um título mais curto ocupa só o que precisa. Para texto longo usa-se TEXT.","manual":"3.4"},{"id":"sql-044","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Que tipo de dados guarda a data e a hora, como em `criado_em`?","codigo":"","linguagem":"","alternativas":["INT","DATETIME","VARCHAR(20)","SMALLINT"],"correta":1,"explicacao":"DATETIME guarda data e hora (consentimento_em, criado_em). Com DEFAULT CURRENT_TIMESTAMP, fica a data e hora do momento.","manual":"3.4"},{"id":"sql-045","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"A validação no servidor diz \"O título é obrigatório e não pode ter mais de 200 caracteres\". Com que definição da coluna bate certo?","codigo":"","linguagem":"","alternativas":["titulo VARCHAR(200) NULL UNIQUE","titulo SMALLINT NOT NULL","titulo VARCHAR(200) NOT NULL","titulo TEXT NULL"],"correta":2,"explicacao":"Obrigatório = NOT NULL; até 200 caracteres = VARCHAR(200). A validação do PHP repete as regras da coluna para dar uma mensagem clara antes de a base de dados recusar.","manual":"3.4, 12.4"},{"id":"sql-046","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Qual deve ser o tipo da coluna `livros.id_autor`, a chave estrangeira?","codigo":"CREATE TABLE autores (\n    id_autor INT AUTO_INCREMENT PRIMARY KEY,\n    ...\n);\nCREATE TABLE livros (\n    ...\n    id_autor ____ NOT NULL,","linguagem":"sql","alternativas":["TEXT, porque um autor pode ter muitos livros","INT, como autores.id_autor","VARCHAR(120), porque guarda o nome do autor","SMALLINT, porque há poucos autores"],"correta":1,"explicacao":"A FK guarda o id do autor, que é um INT; por isso também é INT. O nome do autor fica só na tabela autores.","manual":"3.4, 3.5"},{"id":"sql-047","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Segundo a tabela de tipos do manual (em baixo), qual destes pares coluna → tipo está correto?","codigo":"Tipo        | Guarda\n------------+------------------------------\nINT         | Números inteiros\nSMALLINT    | Inteiros pequenos (até 32 767)\nVARCHAR(n)  | Texto curto, até n caracteres\nTEXT        | Texto longo\nDATETIME    | Data e hora","linguagem":"tabela","alternativas":["criado_em → SMALLINT","ano_edicao → DATETIME","id_livro → VARCHAR(13)","sinopse → TEXT"],"correta":3,"explicacao":"A sinopse é texto longo (TEXT). O ano é SMALLINT, criado_em é DATETIME e id_livro é INT.","manual":"3.4"},{"id":"sql-048","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que significa NOT NULL numa coluna?","codigo":"","linguagem":"","alternativas":["A coluna é obrigatória: não pode ficar vazia.","A coluna é preenchida automaticamente.","A coluna não pode ter o valor zero.","A coluna não pode ter valores repetidos."],"correta":0,"explicacao":"NOT NULL torna a coluna obrigatória. Impedir repetidos é o UNIQUE; preencher sozinho é o AUTO_INCREMENT ou o DEFAULT.","manual":"3.4"},{"id":"sql-049","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Para impedir que dois utilizadores se registem com o mesmo email, que restrição usas na coluna?","codigo":"","linguagem":"","alternativas":["DEFAULT","AUTO_INCREMENT","NOT NULL","UNIQUE"],"correta":3,"explicacao":"UNIQUE impede duas linhas com o mesmo valor. NOT NULL só obriga a que haja valor.","manual":"3.4, Anexo B"},{"id":"sql-050","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"O que faz DEFAULT CURRENT_TIMESTAMP nesta coluna?","codigo":"criado_em DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP","linguagem":"sql","alternativas":["Atualiza a data sempre que a linha é alterada.","Obriga o PHP a enviar a data e hora atual em cada INSERT.","Sem valor no INSERT, fica a data e hora do momento.","Guarda a data em que a tabela foi criada."],"correta":2,"explicacao":"DEFAULT é o valor usado quando o INSERT não indica a coluna. Por isso o INSERT do utilizador de teste não envia criado_em.","manual":"3.4"},{"id":"sql-051","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Na tabela `livros`, criada como em baixo, que colunas são opcionais?","codigo":"CREATE TABLE livros (\n    id_livro   INT AUTO_INCREMENT PRIMARY KEY,\n    id_autor   INT          NOT NULL,\n    titulo     VARCHAR(200) NOT NULL,\n    isbn       VARCHAR(13)  NULL UNIQUE,\n    ano_edicao SMALLINT     NULL,\n    sinopse    TEXT         NULL,\n    CONSTRAINT fk_livros_autores\n        FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n        ON DELETE RESTRICT\n);","linguagem":"sql","alternativas":["id_autor e isbn","isbn, ano_edicao e sinopse","titulo e sinopse","id_livro e ano_edicao"],"correta":1,"explicacao":"As opcionais estão declaradas como NULL: isbn, ano_edicao e sinopse. O título e o autor são NOT NULL e o id_livro é a chave primária.","manual":"3.4, 3.5"},{"id":"sql-052","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Que colunas tem um INSERT nesta tabela de enviar obrigatoriamente?","codigo":"CREATE TABLE utilizadores (\n    id_utilizador    INT AUTO_INCREMENT PRIMARY KEY,\n    nome             VARCHAR(100) NOT NULL,\n    email            VARCHAR(150) NOT NULL UNIQUE,\n    password_hash    VARCHAR(255) NOT NULL,\n    consentimento_em DATETIME     NOT NULL,\n    criado_em        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP\n);","linguagem":"sql","alternativas":["nome, email, password_hash e consentimento_em","As seis colunas, porque todas são NOT NULL","Só email e password_hash, as usadas no login","id_utilizador, nome, email e password_hash"],"correta":0,"explicacao":"O id é AUTO_INCREMENT e criado_em tem DEFAULT, por isso podem ficar de fora. As outras quatro são NOT NULL sem valor por omissão: é exatamente o INSERT do utilizador de teste.","manual":"3.4, 3.5"},{"id":"sql-053","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Já existe o utilizador demo@biblioteca.pt. A base de dados usa o collation utf8mb4_unicode_ci. O que acontece a este INSERT?","codigo":"INSERT INTO utilizadores (nome, email, password_hash, consentimento_em)\nVALUES ('Outro', 'DEMO@biblioteca.pt', '...', NOW());","linguagem":"sql","alternativas":["É aceite, mas o email fica gravado em minúsculas.","É aceite, porque as maiúsculas tornam o email diferente.","É recusado (Duplicate entry): o _ci ignora maiúsculas.","É recusado porque o email tem de estar em minúsculas."],"correta":2,"explicacao":"O collation utf8mb4_unicode_ci compara texto sem distinguir maiúsculas de minúsculas, por isso o UNIQUE vê o mesmo email e dá o erro 1062.","manual":"3.4, 3.5, 17.2"},{"id":"sql-054","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Nesta coluna, o que significa a combinação de NULL com UNIQUE?","codigo":"isbn VARCHAR(13) NULL UNIQUE","linguagem":"sql","alternativas":["O ISBN é opcional, mas, quando existe, não pode repetir-se.","O ISBN só não pode repetir-se dentro do mesmo autor.","O ISBN fica sempre vazio até o livro ser editado.","O ISBN é obrigatório e não pode repetir-se."],"correta":0,"explicacao":"NULL torna a coluna opcional; UNIQUE impede dois livros com o mesmo ISBN.","manual":"3.4"},{"id":"sql-055","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"O `email` dos utilizadores é NOT NULL e UNIQUE. Isso faz dele a chave primária da tabela?","codigo":"","linguagem":"","alternativas":["Sim, mas só depois do primeiro utilizador se registar.","Sim: qualquer coluna UNIQUE passa a ser a chave primária.","Não, porque uma coluna UNIQUE não pode ser NOT NULL.","Não: a chave primária continua a ser id_utilizador."],"correta":3,"explicacao":"UNIQUE só impede emails repetidos. A chave primária é a definida com PRIMARY KEY (id_utilizador INT AUTO_INCREMENT PRIMARY KEY).","manual":"3.2, 3.4"},{"id":"sql-056","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Que valor fica na coluna `nacionalidade` depois deste INSERT?","codigo":"CREATE TABLE autores (\n    id_autor      INT AUTO_INCREMENT PRIMARY KEY,\n    nome          VARCHAR(120) NOT NULL,\n    nacionalidade VARCHAR(60)  NULL\n);\n\nINSERT INTO autores (nome) VALUES ('Ana');","linguagem":"sql","alternativas":["O texto 'NULL' entre plicas.","NULL, porque a coluna é opcional.","'Portuguesa', o valor mais frequente.","Nenhum: dá erro por faltar uma coluna."],"correta":1,"explicacao":"nacionalidade é VARCHAR(60) NULL: se o INSERT não a indicar, fica vazia (NULL). Só as colunas NOT NULL sem DEFAULT têm de ir no INSERT.","manual":"3.4"},{"id":"sql-057","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"O que acontece a este INSERT?","codigo":"CREATE TABLE livros (\n    id_livro   INT AUTO_INCREMENT PRIMARY KEY,\n    id_autor   INT          NOT NULL,\n    titulo     VARCHAR(200) NOT NULL,\n    isbn       VARCHAR(13)  NULL UNIQUE,\n    ano_edicao SMALLINT     NULL,\n    sinopse    TEXT         NULL,\n    ...\n);\n\nINSERT INTO livros (id_autor, isbn)\nVALUES (1, '9780000000000');","linguagem":"sql","alternativas":["É aceite, com o titulo vazio ('').","É recusado: titulo é NOT NULL e não foi enviado.","É aceite, com o titulo a NULL.","É aceite, porque só o id_autor é obrigatório."],"correta":1,"explicacao":"titulo é NOT NULL e não tem DEFAULT, por isso é obrigatório no INSERT. O autor 1 existe e o ISBN é novo, por isso essas partes estavam bem.","manual":"3.4"},{"id":"sql-058","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Para que serve `SET NAMES utf8mb4;` no início do base_dados.sql?","codigo":"","linguagem":"","alternativas":["Cria uma base de dados chamada utf8mb4.","Define a password do utilizador root do MySQL.","Faz com que os acentos sejam lidos corretamente.","Converte todas as tabelas existentes para letras minúsculas."],"correta":2,"explicacao":"Sem SET NAMES utf8mb4, \"José\" pode aparecer como \"JosÃ©\". É uma das soluções do erro de acentos estragados.","manual":"3.5, 17.2"},{"id":"sql-059","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"A tua base de dados biblioteca já tem livros que inseriste à mão. O base_dados.sql começa assim. O que acontece se o voltares a importar?","codigo":"DROP DATABASE IF EXISTS biblioteca;\nCREATE DATABASE biblioteca CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\nUSE biblioteca;","linguagem":"sql","alternativas":["Perdem-se: o DROP DATABASE apaga tudo antes de criar de novo.","Os dados de exemplo juntam-se aos livros que já lá estavam.","Dá erro, porque a base de dados biblioteca já existe no MySQL.","Só são recriadas as tabelas que estiverem vazias."],"correta":0,"explicacao":"O ficheiro começa por DROP DATABASE IF EXISTS biblioteca: apaga a base de dados com tudo o que lá estava e depois cria-a de raiz.","manual":"3.5"},{"id":"sql-060","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Porque é que o base_dados.sql começa por `DROP DATABASE IF EXISTS biblioteca;`?","codigo":"","linguagem":"","alternativas":["Para o phpMyAdmin não pedir a password do root.","Para guardar uma cópia de segurança antes de criar as tabelas.","Para apagar só as tabelas que estiverem vazias.","Para poder ser importado várias vezes com o mesmo resultado."],"correta":3,"explicacao":"Apagar e criar de novo garante que cada importação dá o mesmo resultado. A contrapartida é que apaga os dados que lá estavam.","manual":"3.5"},{"id":"sql-061","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que faz a última linha deste excerto?","codigo":"DROP DATABASE IF EXISTS biblioteca;\nCREATE DATABASE biblioteca CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;\nUSE biblioteca;","linguagem":"sql","alternativas":["Escolhe a base de dados onde correm as instruções seguintes.","Dá permissões a um utilizador chamado biblioteca.","Importa o ficheiro biblioteca.sql.","Cria a base de dados biblioteca."],"correta":0,"explicacao":"Quem cria é o CREATE DATABASE; o USE escolhe a base de dados onde vão ser criadas as tabelas e inseridos os dados.","manual":"3.5"},{"id":"sql-062","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Porque é que no base_dados.sql a tabela `autores` é criada antes da tabela `livros`?","codigo":"","linguagem":"","alternativas":["Porque as tabelas têm de ser criadas por ordem alfabética.","Porque o AUTO_INCREMENT só funciona na primeira tabela do ficheiro.","Porque autores tem menos colunas do que livros.","Porque a FK de livros aponta para autores, que tem de existir."],"correta":3,"explicacao":"A FOREIGN KEY de livros diz REFERENCES autores (id_autor); essa tabela tem de existir antes. Cria-se primeiro o lado 1 e depois o lado N.","manual":"3.5"},{"id":"sql-063","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Este excerto de um base_dados.sql, com as tabelas vazias, dá erro. Porquê?","codigo":"INSERT INTO livros (id_autor, titulo) VALUES (1, 'Os Maias');\nINSERT INTO autores (nome) VALUES ('Eça de Queirós');","linguagem":"sql","alternativas":["O primeiro INSERT falha: falta o id_livro.","O primeiro INSERT falha: ainda não existe o autor 1.","O segundo INSERT falha: falta a nacionalidade.","O segundo INSERT falha: o autor tem de ter o id 1 escrito."],"correta":1,"explicacao":"A FK exige que o id_autor do livro exista em autores. Os autores têm de ser inseridos antes dos livros. A nacionalidade é NULL e os ids são AUTO_INCREMENT.","manual":"3.3, 3.5"},{"id":"sql-064","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"No INSERT do utilizador de teste, o que é o texto que começa por `$2y$12$`?","codigo":"","linguagem":"","alternativas":["A password Demo1234 encriptada com a função md5().","O identificador da sessão do utilizador de teste no browser.","O hash da password Demo1234, calculado com password_hash().","A password Demo1234 codificada em base64."],"correta":2,"explicacao":"Nunca se guarda a password: guarda-se o hash. O texto começado por $2 é o resultado de password_hash(), que depois é confirmado com password_verify().","manual":"3.5"},{"id":"sql-065","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Porque é que o base_dados.sql inclui um utilizador de teste?","codigo":"","linguagem":"","alternativas":["Para servir de chave estrangeira aos livros.","Para o phpMyAdmin conseguir importar o ficheiro.","Para quem importa o ficheiro poder logo entrar na aplicação.","Porque o MySQL exige pelo menos uma linha em cada tabela."],"correta":2,"explicacao":"Com demo@biblioteca.pt / Demo1234, o formador entra logo depois de importar. Nenhuma tabela precisa de ter linhas.","manual":"3.5, 18.1"},{"id":"sql-066","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Como importas o base_dados.sql no phpMyAdmin?","codigo":"","linguagem":"","alternativas":["No separador Importar, escolhes o ficheiro e carregas em Importar.","Copias o ficheiro para a pasta C:\\xampp\\htdocs e recarregas a página.","No separador SQL, escreves o nome do ficheiro e carregas em Executar.","Abres o ficheiro no browser, com duplo clique."],"correta":0,"explicacao":"Abres http://localhost/phpmyadmin, separador Importar, escolhes o ficheiro e carregas em Importar; à esquerda aparece a base de dados com as tabelas.","manual":"3.6"},{"id":"sql-067","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Antes de entregar, que teste deves fazer ao teu base_dados.sql?","codigo":"","linguagem":"","alternativas":["Abrir o ficheiro no browser para ver se aparece sem erros.","Correr só os INSERT, para não apagar o que já tens.","Exportar a base de dados e comparar o tamanho dos ficheiros.","Apagar a base de dados no phpMyAdmin e importar o ficheiro de raiz."],"correta":3,"explicacao":"Se a importação de raiz falhar no teu computador, também falha no do formador. O ficheiro tem de criar tudo: base de dados, tabelas, chaves e dados de exemplo.","manual":"18.1"},{"id":"sql-068","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"No `CREATE DATABASE biblioteca CHARACTER SET utf8mb4 ...`, para que serve o utf8mb4?","codigo":"","linguagem":"","alternativas":["Limitar cada coluna de texto a 4 caracteres.","Guardar texto com acentos sem os estragar.","Ordenar os livros pela data de criação.","Encriptar os dados guardados nas tabelas."],"correta":1,"explicacao":"utf8mb4 é a codificação do texto: guarda bem \"José\" ou \"Eça\". Tem de bater certo com o SET NAMES do .sql e o charset=utf8mb4 da ligação.","manual":"3.5, 17.2"},{"id":"sql-069","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"O teu base_dados.sql tem de criar tudo de raiz. O que deve conter?","codigo":"","linguagem":"","alternativas":["Uma cópia dos ficheiros PHP, para a aplicação funcionar.","Só os INSERT, porque o formador já tem as tabelas criadas.","A base de dados, as tabelas, as chaves e dados de exemplo.","Só os CREATE TABLE: os dados são inseridos pelo formador à mão."],"correta":2,"explicacao":"O manual pede um ficheiro que crie a base de dados, as tabelas, as chaves e alguns dados de exemplo, incluindo um utilizador de teste.","manual":"18.1, 3.5"},{"id":"sql-070","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Que instrução SQL lê dados de uma tabela?","codigo":"","linguagem":"","alternativas":["INSERT","SELECT","UPDATE","READ FROM"],"correta":1,"explicacao":"SELECT lê; INSERT acrescenta e UPDATE altera. READ é o R de CRUD, mas não é uma instrução SQL.","manual":"3.7"},{"id":"sql-071","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, que títulos devolve esta consulta?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo FROM livros\nWHERE titulo LIKE '%mar%';","linguagem":"sql","alternativas":["A Menina do Mar e O Cavaleiro da Dinamarca","Nenhum, porque \"Mar\" tem maiúscula","Só A Menina do Mar","A Menina do Mar e Memorial do Convento"],"correta":0,"explicacao":"%mar% encontra \"mar\" em qualquer posição: \"Mar\" e \"Dinamarca\". O collation utf8mb4_unicode_ci não distingue maiúsculas. \"Memorial\" tem \"mor\", não \"mar\".","manual":"12.2, 3.5"},{"id":"sql-072","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que encontra `titulo LIKE '%texto%'`?","codigo":"","linguagem":"","alternativas":["Só os títulos que acabam em \"texto\".","Só os títulos exatamente iguais a \"texto\".","Só os títulos que começam por \"texto\".","Os títulos que contêm \"texto\" em qualquer posição."],"correta":3,"explicacao":"O % substitui qualquer sequência de caracteres (incluindo nenhuma). Com % antes e depois, o texto pode estar em qualquer posição.","manual":"12.2"},{"id":"sql-073","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Que padrão encontra os títulos que começam por \"O\"?","codigo":"","linguagem":"","alternativas":["LIKE '%O'","LIKE 'O%'","LIKE '%O%'","LIKE 'O'"],"correta":1,"explicacao":"'O%' = começa por O e depois qualquer coisa. '%O' é \"acaba em O\", '%O%' é \"contém O\" e 'O' sem % só encontra o título igual a \"O\".","manual":"12.2"},{"id":"sql-074","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, quantos títulos começam pela letra indicada?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo FROM livros\nWHERE titulo LIKE 'o%';","linguagem":"sql","alternativas":["Nenhuma","1","2","3"],"correta":2,"explicacao":"Começam por \"o\" (sem distinguir maiúsculas, por causa do _ci): \"O Cavaleiro da Dinamarca\" e \"Os Maias\".","manual":"12.2, 3.5"},{"id":"sql-075","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Pesquisas \"do\" na lista de livros. Quantos cartões aparecem?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo FROM livros\nWHERE titulo LIKE '%do%';","linguagem":"sql","alternativas":["Nenhum","1","2","3"],"correta":3,"explicacao":"Contêm \"do\": \"Memorial do Convento\", \"A Menina do Mar\" e \"Dom Casmurro\" (o \"Do\" de \"Dom\" conta, porque o _ci não distingue maiúsculas). \"da Dinamarca\" tem \"da\", não \"do\".","manual":"12.2, 3.5"},{"id":"sql-076","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Pesquisas \"ca\" na lista de livros. Que títulos aparecem?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo FROM livros\nWHERE titulo LIKE '%ca%';","linguagem":"sql","alternativas":["O Cavaleiro da Dinamarca e Dom Casmurro","Só O Cavaleiro da Dinamarca","Ensaio sobre a Cegueira e Dom Casmurro","Nenhum, porque nenhum título começa por \"ca\""],"correta":0,"explicacao":"\"Cavaleiro\" e \"Dinamarca\" estão no mesmo título; \"Casmurro\" também tem \"ca\". \"Cegueira\" tem \"ce\". Com % dos dois lados, não interessa onde está.","manual":"12.2, 3.5"},{"id":"sql-077","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Pesquisas \"MAR\" em vez de \"mar\", e o valor passado ao `LIKE ?` fica '%MAR%'. Comparado com a pesquisa \"mar\", o resultado é…","codigo":"","linguagem":"","alternativas":["O mesmo: o collation utf8mb4_unicode_ci não distingue maiúsculas.","Vazio: nenhum título tem MAR em maiúsculas.","Um erro, porque o LIKE só aceita letras minúsculas.","Só \"A Menina do Mar\", porque é o único com M maiúsculo."],"correta":0,"explicacao":"A base de dados foi criada com COLLATE utf8mb4_unicode_ci; o \"ci\" (case insensitive) faz com que \"MAR\", \"Mar\" e \"mar\" sejam iguais nas comparações.","manual":"12.2, 3.5"},{"id":"sql-078","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"A caixa de pesquisa está vazia, por isso o valor passado ao `LIKE ?` fica '%%'. O que devolve a consulta?","codigo":"","linguagem":"","alternativas":["Só os livros sem título","Todos os livros","Nenhum livro","Um erro de sintaxe"],"correta":1,"explicacao":"Com o texto vazio, o padrão é \"qualquer coisa\": %% encontra tudo. É por isso que a lista mostra todos os livros antes de se pesquisar.","manual":"12.2"},{"id":"sql-079","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que faz `ORDER BY titulo` numa consulta?","codigo":"","linguagem":"","alternativas":["Junta numa só linha os livros com o mesmo título.","Ordena os resultados pelo título, de Z para A.","Mostra só os livros que têm título.","Ordena os resultados pelo título, por ordem crescente (A→Z)."],"correta":3,"explicacao":"Sem mais nada, o ORDER BY ordena por ordem crescente. Para decrescente acrescenta-se DESC; filtrar é o WHERE e agrupar é o GROUP BY.","manual":"3.7"},{"id":"sql-080","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Queres mostrar os livros do mais recente para o mais antigo. O que escreves?","codigo":"","linguagem":"","alternativas":["ORDER BY ano_edicao","ORDER BY ano_edicao DESCENDING","ORDER BY ano_edicao DESC","ORDER BY DESC ano_edicao"],"correta":2,"explicacao":"DESC vem depois da coluna e inverte a ordem (maior ano primeiro). Sem DESC, a ordem é crescente: do mais antigo para o mais recente.","manual":"3.7"},{"id":"sql-081","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, qual é o primeiro título que aparece?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo FROM livros\nORDER BY ano_edicao;","linguagem":"sql","alternativas":["A Menina do Mar","Memorial do Convento","Os Maias","Dom Casmurro"],"correta":2,"explicacao":"Ordem crescente do ano: Os Maias (1888) vem antes de Dom Casmurro (1899). \"A Menina do Mar\" seria a primeira por título e \"Memorial do Convento\" a primeira inserida.","manual":"3.7, 3.5"},{"id":"sql-082","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"A lista de livros usa `ORDER BY l.titulo`. Com os dados de exemplo, qual é o primeiro cartão?","codigo":"Dados de exemplo (base_dados.sql)\n\nlivros\nid_livro | id_autor | titulo                   | isbn          | ano_edicao\n1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n5        | 3        | Os Maias                 | 9789722036597 | 1888\n6        | 4        | Dom Casmurro             | 9788535910681 | 1899","linguagem":"tabela","alternativas":["Os Maias","A Menina do Mar","Dom Casmurro","Memorial do Convento"],"correta":1,"explicacao":"Por ordem alfabética do título, \"A Menina do Mar\" vem primeiro. \"Memorial do Convento\" é o primeiro inserido (id 1), mas o ORDER BY não segue o id.","manual":"12.2, 3.5"},{"id":"sql-083","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, que título aparece em último lugar?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo, ano_edicao FROM livros\nWHERE ano_edicao > 1950\nORDER BY ano_edicao DESC;","linguagem":"sql","alternativas":["Os Maias","Ensaio sobre a Cegueira","O Cavaleiro da Dinamarca","A Menina do Mar"],"correta":3,"explicacao":"O WHERE deixa 1958, 1964, 1982 e 1995. Com DESC, o mais recente (Ensaio, 1995) vem primeiro e o mais antigo, A Menina do Mar (1958), fica em último. Os Maias (1888) nem passa no WHERE.","manual":"3.7, 3.5"},{"id":"sql-084","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Qual é a ordem correta das cláusulas de um SELECT?","codigo":"","linguagem":"","alternativas":["SELECT … FROM … WHERE … ORDER BY …","SELECT … WHERE … FROM … ORDER BY …","FROM … SELECT … WHERE … ORDER BY …","SELECT … FROM … ORDER BY … WHERE …"],"correta":0,"explicacao":"Primeiro o que se quer (SELECT), de onde (FROM), o filtro (WHERE) e, no fim, a ordenação (ORDER BY).","manual":"3.7, 12.2"},{"id":"sql-085","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Esta consulta dá erro de sintaxe. Qual é o problema?","codigo":"SELECT id_livro, titulo FROM livros\nORDER BY titulo\nWHERE titulo LIKE ?;","linguagem":"sql","alternativas":["Falta o JOIN com a tabela autores.","O LIKE não aceita um ? no lugar do valor.","O WHERE tem de vir antes do ORDER BY.","O ORDER BY só funciona com colunas numéricas."],"correta":2,"explicacao":"A ordem é SELECT … FROM … WHERE … ORDER BY. O LIKE ? é exatamente o que a Biblioteca usa, e ordenar por texto é normal.","manual":"3.7, 17.2"},{"id":"sql-086","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Esta consulta verifica se o autor escolhido existe. Que valor devolve com os dados de exemplo, se o ? for 9?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n\nSELECT COUNT(*) FROM autores WHERE id_autor = ?;","linguagem":"sql","alternativas":["0","1","9","NULL"],"correta":0,"explicacao":"Não há nenhum autor com id 9 (só 1 a 4), por isso o COUNT dá 0 e a validação mostra \"Escolhe um autor da lista\". Com um id existente daria 1.","manual":"12.4"},{"id":"sql-087","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Em `FROM livros l JOIN autores a`, o que são `l` e `a`?","codigo":"","linguagem":"","alternativas":["Os nomes das chaves primárias das duas tabelas.","Alias: nomes curtos das tabelas, usados como l.titulo e a.nome.","Letras obrigatórias: livros tem de ser l e autores tem de ser a.","Variáveis PHP onde fica guardado o resultado."],"correta":1,"explicacao":"Um alias de tabela é um nome curto para escrever menos e para dizer de que tabela é cada coluna (l.id_autor, a.id_autor). As letras escolhem-se à vontade.","manual":"3.7, 12.2"},{"id":"sql-088","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que faz `AS autor` em `SELECT l.titulo, a.nome AS autor`?","codigo":"","linguagem":"","alternativas":["Filtra os nomes que contêm a palavra autor.","Cria uma coluna autor na tabela autores.","Muda o nome da tabela autores para autor.","Dá à coluna a.nome o nome autor no resultado."],"correta":3,"explicacao":"AS dá um nome à coluna no resultado (no PHP lê-se $livro['autor']). Não altera a tabela.","manual":"12.2"},{"id":"sql-089","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Quantos nomes devolve esta consulta com os dados de exemplo?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n\nSELECT nome FROM autores\nWHERE nacionalidade = 'portuguesa';","linguagem":"sql","alternativas":["Nenhum","1","3","4"],"correta":2,"explicacao":"Saramago, Sophia e Eça têm \"Portuguesa\". O collation _ci não distingue maiúsculas, por isso 'portuguesa' encontra-os. Machado de Assis é \"Brasileira\".","manual":"3.5, 3.7"},{"id":"sql-090","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Com os dados de exemplo, que títulos devolve esta consulta?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT titulo FROM livros\nWHERE ano_edicao < 1900;","linguagem":"sql","alternativas":["Nenhum: < não se usa com anos","Os Maias e Dom Casmurro","Os Maias, Dom Casmurro e A Menina do Mar","Só Os Maias"],"correta":1,"explicacao":"Os Maias (1888) e Dom Casmurro (1899) são anteriores a 1900. A Menina do Mar é de 1958.","manual":"3.7, 3.5"},{"id":"sql-091","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"O que devolve esta consulta se não existir nenhum livro com id 99?","codigo":"SELECT * FROM livros WHERE id_livro = 99;","linguagem":"sql","alternativas":["Nenhuma linha: o resultado vem vazio.","Um erro, porque o id não existe.","Uma linha com todas as colunas a NULL.","O último livro da tabela."],"correta":0,"explicacao":"Um WHERE que não encontra nada não é um erro: devolve zero linhas. Na Biblioteca, o fetch() dá false e a página responde com 404.","manual":"12.3"},{"id":"sql-092","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Na consulta da página de detalhe, o que significa `l.*`?","codigo":"SELECT l.*, a.nome AS autor, a.nacionalidade\nFROM livros l\nJOIN autores a ON l.id_autor = a.id_autor\nWHERE l.id_livro = ?","linguagem":"sql","alternativas":["Só a chave primária da tabela livros.","Todas as colunas das duas tabelas.","Todas as linhas de livros, sem filtro.","Todas as colunas da tabela livros."],"correta":3,"explicacao":"O * quer dizer \"todas as colunas\" e o l. limita-o à tabela com alias l (livros). Do autor só vêm nome e nacionalidade; as linhas continuam filtradas pelo WHERE.","manual":"8.2, 12.3"},{"id":"sql-093","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Para que serve o JOIN?","codigo":"","linguagem":"","alternativas":["Juntar duas colunas de texto numa só coluna.","Juntar numa consulta as linhas relacionadas de duas tabelas.","Copiar as linhas de uma tabela para outra, de vez.","Juntar dois ficheiros .sql num só."],"correta":1,"explicacao":"O JOIN junta, por exemplo, a cada livro o nome do seu autor, numa só consulta. Não altera as tabelas.","manual":"3.7, Anexo B"},{"id":"sql-094","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Esta consulta junta a cada livro o seu autor. Quantas linhas tem o resultado, com os dados de exemplo?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT l.titulo, a.nome\nFROM livros l\nJOIN autores a ON l.id_autor = a.id_autor;","linguagem":"sql","alternativas":["4","6","10","24"],"correta":1,"explicacao":"Uma linha por livro que tenha autor correspondente: os 6 livros, cada um com o nome do seu autor. Não é 4 + 6 nem 4 × 6.","manual":"3.7, 3.5"},{"id":"sql-095","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Num JOIN, o que indica `ON l.id_autor = a.id_autor`?","codigo":"","linguagem":"","alternativas":["Que a coluna id_autor passa a ser UNIQUE.","A ordem pela qual as linhas aparecem.","Que só aparecem livros cujo id_livro é igual ao id do autor.","Como se juntam as linhas: FK do livro = PK do autor."],"correta":3,"explicacao":"O ON diz que linha de autores corresponde a cada livro: aquela cujo id_autor é igual ao id_autor guardado no livro.","manual":"3.7"},{"id":"sql-096","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Qual é a diferença entre JOIN e LEFT JOIN?","codigo":"","linguagem":"","alternativas":["O LEFT JOIN mantém todas as linhas da tabela da esquerda.","O LEFT JOIN junta da direita para a esquerda, com o mesmo resultado.","O LEFT JOIN mostra só as linhas que não têm correspondência.","O JOIN mostra todas as linhas das duas tabelas, com ou sem correspondência."],"correta":0,"explicacao":"O JOIN só devolve linhas com correspondência; o LEFT JOIN devolve todas as da esquerda e põe NULL nas colunas da direita quando não há correspondência.","manual":"3.7"},{"id":"sql-097","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Inseriste a autora Ana, sem livros. Com os 6 livros de exemplo, quantas linhas devolve esta consulta?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT a.nome, l.titulo\nFROM autores a\nJOIN livros l ON l.id_autor = a.id_autor;","linguagem":"sql","alternativas":["4","5","6","7"],"correta":2,"explicacao":"O JOIN só devolve linhas com correspondência: os 6 livros com o seu autor. A Ana não tem livros, por isso não aparece.","manual":"3.7"},{"id":"sql-098","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Inseriste a autora Ana, sem livros. O que devolve esta consulta para ela?","codigo":"SELECT a.nome, l.titulo\nFROM autores a\nLEFT JOIN livros l ON l.id_autor = a.id_autor;","linguagem":"sql","alternativas":["Uma linha com o nome Ana e titulo vazio ('').","Seis linhas com Ana, uma por cada livro.","Uma linha com o nome Ana e titulo a NULL.","Nada: a Ana não aparece, porque não tem livros."],"correta":2,"explicacao":"O LEFT JOIN mantém todos os autores (a tabela da esquerda). Quando não há livro correspondente, as colunas de livros vêm a NULL.","manual":"3.7"},{"id":"sql-099","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, que resultado dá esta consulta?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT a.nome, COUNT(l.id_livro) AS total_livros\nFROM autores a\nLEFT JOIN livros l ON l.id_autor = a.id_autor\nGROUP BY a.id_autor, a.nome;","linguagem":"sql","alternativas":["4 linhas, todas com o total 6","6 linhas, uma por livro, todas com total 1","1 linha com o total 6","4 linhas: Saramago 2, Sophia 2, Eça 1, Machado 1"],"correta":3,"explicacao":"O GROUP BY faz uma linha por autor e o COUNT conta os livros de cada um: dois do Saramago, dois da Sophia, um do Eça e um do Machado.","manual":"13.1, 3.5"},{"id":"sql-100","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Na lista de autores, para que serve o `GROUP BY a.id_autor, a.nome`?","codigo":"","linguagem":"","alternativas":["Fazer uma linha por autor, para o COUNT contar os livros de cada um.","Juntar numa linha os autores com o mesmo nome e a mesma nacionalidade.","Ordenar os autores pelo nome, de A a Z.","Apagar os autores que aparecem repetidos."],"correta":0,"explicacao":"Sem GROUP BY, o COUNT contaria tudo numa só linha. A ordenação é feita pelo ORDER BY a.nome.","manual":"13.1"},{"id":"sql-101","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Porque é que a lista de autores conta com `COUNT(l.id_livro)` e não com `COUNT(*)`?","codigo":"","linguagem":"","alternativas":["Com COUNT(*), os autores sem livros desapareciam da lista.","Com COUNT(*), um autor sem livros aparecia com 1 em vez de 0.","COUNT(*) contaria os livros de todos os autores juntos.","COUNT(*) não pode ser usado depois de um LEFT JOIN."],"correta":1,"explicacao":"No LEFT JOIN, o autor sem livros tem uma linha com as colunas de livros a NULL. COUNT(*) conta essa linha (1); COUNT(l.id_livro) não conta NULL e dá 0.","manual":"13.1"},{"id":"sql-102","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Que FROM usas para mostrar todos os autores, incluindo os que ainda não têm livros?","codigo":"","linguagem":"","alternativas":["FROM autores a LEFT JOIN livros l ON l.id_autor = a.id_autor","FROM autores a JOIN livros l ON l.id_autor = a.id_autor","FROM livros l LEFT JOIN autores a ON l.id_autor = a.id_autor","FROM autores a JOIN livros l ON l.id_livro = a.id_autor"],"correta":0,"explicacao":"O LEFT JOIN guarda todas as linhas da tabela da esquerda, por isso autores tem de estar à esquerda. Com livros à esquerda, ficariam todos os livros, não todos os autores.","manual":"3.7, 13.1"},{"id":"sql-103","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, quantos livros de autores portugueses lista esta consulta?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT l.titulo, a.nome\nFROM livros l\nJOIN autores a ON l.id_autor = a.id_autor\nWHERE a.nacionalidade = 'Portuguesa';","linguagem":"sql","alternativas":["3","4","5","6"],"correta":2,"explicacao":"Os autores portugueses são Saramago (2 livros), Sophia (2) e Eça (1): 5 livros. Só o Dom Casmurro, de Machado de Assis, fica de fora. Conta-se livros, não autores.","manual":"3.7, 3.5"},{"id":"sql-104","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Com os dados de exemplo, que título devolve esta consulta?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT l.titulo\nFROM livros l\nJOIN autores a ON l.id_autor = a.id_autor\nWHERE a.nome LIKE '%Assis%';","linguagem":"sql","alternativas":["Os Maias","Memorial do Convento","Nenhum, porque titulo não contém Assis","Dom Casmurro"],"correta":3,"explicacao":"O WHERE filtra pela coluna do autor (a.nome), que só está disponível graças ao JOIN. Machado de Assis tem um livro: Dom Casmurro.","manual":"3.7, 3.5"},{"id":"sql-105","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Porque é que a consulta da página de detalhe de um livro faz JOIN com `autores`?","codigo":"","linguagem":"","alternativas":["Para verificar se o utilizador tem sessão iniciada.","Para mostrar o nome e a nacionalidade do autor.","Para proteger a consulta contra SQL injection.","Para contar quantos livros tem o autor."],"correta":1,"explicacao":"A tabela livros só tem o id_autor; o nome e a nacionalidade estão em autores. Quem protege da injeção são os parâmetros ?, não o JOIN.","manual":"12.3"},{"id":"sql-106","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Qual é a ordem correta das cláusulas numa consulta com LEFT JOIN e contagem?","codigo":"","linguagem":"","alternativas":["FROM … LEFT JOIN … ON … GROUP BY … ORDER BY …","FROM … GROUP BY … LEFT JOIN … ON … ORDER BY …","FROM … LEFT JOIN … ON … ORDER BY … GROUP BY …","FROM … ON … LEFT JOIN … GROUP BY … ORDER BY …"],"correta":0,"explicacao":"Na lista de autores: FROM autores a LEFT JOIN livros l ON … GROUP BY … ORDER BY a.nome. O ORDER BY é sempre o último; o ON vem logo a seguir ao JOIN.","manual":"13.1"},{"id":"sql-107","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, qual é a primeira linha desta consulta?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nSELECT a.nome, COUNT(l.id_livro) AS total_livros\nFROM autores a\nLEFT JOIN livros l ON l.id_autor = a.id_autor\nGROUP BY a.id_autor, a.nome\nORDER BY a.nome;","linguagem":"sql","alternativas":["Sophia de Mello Breyner Andresen, 2","José Saramago, 2","Eça de Queirós, 1","Machado de Assis, 1"],"correta":2,"explicacao":"ORDER BY a.nome ordena alfabeticamente: Eça vem antes de José, Machado e Sophia. O José Saramago seria o primeiro só se a ordem fosse pelo id.","manual":"13.1, 3.5"},{"id":"sql-108","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Que instrução acrescenta uma linha nova a uma tabela?","codigo":"","linguagem":"","alternativas":["UPDATE … SET …","ADD INTO … VALUES …","CREATE ROW … VALUES …","INSERT INTO … VALUES …"],"correta":3,"explicacao":"INSERT INTO tabela (colunas) VALUES (valores) acrescenta uma linha. UPDATE altera linhas que já existem.","manual":"3.7, Anexo B"},{"id":"sql-109","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Qual destes INSERT está escrito corretamente?","codigo":"","linguagem":"","alternativas":["INSERT INTO autores VALUES (nome = 'Ana', nacionalidade = 'Portuguesa')","INSERT INTO autores (nome, nacionalidade) VALUES ('Ana', 'Portuguesa')","INSERT INTO autores (nome, nacionalidade) ('Ana', 'Portuguesa')","INSERT INTO autores SET (nome, nacionalidade) VALUES ('Ana', 'Portuguesa')"],"correta":1,"explicacao":"A forma é INSERT INTO tabela (colunas) VALUES (valores). Falta o VALUES na segunda, e o \"coluna = valor\" é do UPDATE … SET.","manual":"3.7"},{"id":"sql-110","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, o que acontece a este INSERT?","codigo":"-- Na tabela livros (base_dados.sql):\n--   titulo VARCHAR(200) NOT NULL\n--   isbn   VARCHAR(13)  NULL UNIQUE\n\n-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nINSERT INTO livros (titulo, id_autor, isbn)\nVALUES ('Os Maias', 3, '9789722036597');","linguagem":"sql","alternativas":["Substitui o \"Os Maias\" que já estava na tabela.","Fica um segundo \"Os Maias\", com o mesmo ISBN.","É recusado (Duplicate entry): o ISBN é UNIQUE.","É recusado porque já existe um livro com esse título."],"correta":2,"explicacao":"O ISBN 9789722036597 já pertence a \"Os Maias\" e a coluna é UNIQUE: erro 23000 / 1062. O título não é UNIQUE, por isso não seria ele a causa.","manual":"3.4, 8.5, 17.2"},{"id":"sql-111","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, o que acontece a este INSERT?","codigo":"-- Na tabela livros (base_dados.sql):\n--   titulo VARCHAR(200) NOT NULL\n--   isbn   VARCHAR(13)  NULL UNIQUE\n\n-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nINSERT INTO livros (titulo, id_autor)\nVALUES ('Os Maias', 3);","linguagem":"sql","alternativas":["É recusado: já existe um livro com esse título.","Substitui o livro \"Os Maias\" que já existe.","É recusado: falta o ISBN, que é UNIQUE.","É aceite: o título não é UNIQUE e o ISBN fica NULL."],"correta":3,"explicacao":"Só o ISBN é UNIQUE, e é opcional (NULL). Por isso pode haver dois livros com o mesmo título; fica um novo livro com o id seguinte.","manual":"3.4, 3.5"},{"id":"sql-112","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Num INSERT, por que ordem têm de aparecer os valores do VALUES?","codigo":"INSERT INTO livros (titulo, id_autor, isbn, ano_edicao, sinopse)\nVALUES (?, ?, ?, ?, ?)","linguagem":"sql","alternativas":["Pela ordem das colunas escritas entre parênteses a seguir à tabela.","Por ordem alfabética do nome das colunas.","Por qualquer ordem: o MySQL descobre pelo tipo de dados.","Pela ordem do CREATE TABLE, seja qual for a lista de colunas."],"correta":0,"explicacao":"O primeiro valor vai para a primeira coluna da lista, o segundo para a segunda, e assim por diante. Com ?, os valores do execute() seguem a mesma ordem.","manual":"3.7, 8.2"},{"id":"sql-113","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Que instrução altera os dados de uma linha que já existe?","codigo":"","linguagem":"","alternativas":["ALTER … SET … WHERE …","UPDATE … SET … WHERE …","INSERT INTO … WHERE …","CHANGE … VALUES … WHERE …"],"correta":1,"explicacao":"UPDATE tabela SET coluna = valor WHERE condição altera as linhas escolhidas pelo WHERE.","manual":"3.7, Anexo B"},{"id":"sql-114","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, o que faz esta instrução?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nUPDATE livros SET ano_edicao = 1990;","linguagem":"sql","alternativas":["Altera os 6 livros: todos ficam com 1990.","Altera só os livros sem ano de edição.","Não altera nada: o MySQL exige WHERE.","Altera só o primeiro livro da tabela."],"correta":0,"explicacao":"Um UPDATE sem WHERE altera todas as linhas da tabela, sem pedir confirmação. Por isso o manual diz para escrever sempre o WHERE primeiro.","manual":"3.7"},{"id":"sql-115","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Qual destes UPDATE muda a nacionalidade do autor com id 4?","codigo":"","linguagem":"","alternativas":["UPDATE autores WHERE id_autor = 4 SET nacionalidade = 'Brasileira'","UPDATE autores SET nacionalidade = 'Brasileira' AND id_autor = 4","UPDATE autores SET nacionalidade = 'Brasileira' WHERE id_autor = 4","UPDATE TABLE autores SET nacionalidade = 'Brasileira' WHERE id_autor = 4"],"correta":2,"explicacao":"A ordem é UPDATE tabela SET coluna = valor WHERE condição. Não se escreve TABLE depois de UPDATE; o WHERE vem sempre no fim; e um \"AND id_autor = 4\" no SET não é um filtro.","manual":"3.7"},{"id":"sql-116","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, depois desta instrução, quantos livros tem a Sophia de Mello Breyner (autor 2)?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nUPDATE livros SET id_autor = 2\nWHERE id_autor = 1;","linguagem":"sql","alternativas":["Nenhum","2","4","6"],"correta":2,"explicacao":"Os 2 livros do Saramago (id_autor = 1) passam a ter id_autor = 2 e juntam-se aos 2 da Sophia: 4. O UPDATE não apaga nem cria livros.","manual":"3.3, 3.5"},{"id":"sql-117","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Em livro_editar.php, porque é que o `WHERE id_livro = ?` do UPDATE é indispensável?","codigo":"UPDATE livros\nSET titulo = ?, id_autor = ?, isbn = ?, ano_edicao = ?, sinopse = ?\nWHERE id_livro = ?","linguagem":"sql","alternativas":["Sem ele, a chave estrangeira recusava a alteração do livro.","Sem ele, só o primeiro livro da tabela era alterado.","Sem ele, o UPDATE criava um livro novo.","Sem ele, todos os livros ficavam iguais ao formulário."],"correta":3,"explicacao":"O WHERE escolhe a linha a alterar. Sem WHERE, o UPDATE aplica-se a todas as linhas; nunca cria linhas novas, isso é o INSERT.","manual":"12.5"},{"id":"sql-118","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Quantos valores leva esta instrução, e por que ordem?","codigo":"UPDATE autores SET nome = ?, nacionalidade = ?\nWHERE id_autor = ?","linguagem":"sql","alternativas":["Três: o nome, a nacionalidade e o id_autor, pela ordem dos ?.","Três, por qualquer ordem: cada ? sabe a que coluna pertence.","Dois: o id_autor do WHERE não conta como valor.","Três, começando pelo id_autor, porque é a chave primária."],"correta":0,"explicacao":"Os ? são os lugares dos valores e são preenchidos pela ordem em que aparecem: primeiro os do SET, por último o do WHERE.","manual":"3.7, 8.2"},{"id":"sql-119","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Com os dados de exemplo, quantas linhas altera esta instrução?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nUPDATE livros SET sinopse = NULL\nWHERE id_autor = 1;","linguagem":"sql","alternativas":["1","2","4","6"],"correta":1,"explicacao":"O WHERE escolhe os livros do autor 1 (José Saramago): Memorial do Convento e Ensaio sobre a Cegueira. A sinopse pode ficar NULL porque é opcional.","manual":"3.7, 3.5"},{"id":"sql-120","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, o que acontece a esta instrução?","codigo":"-- Na tabela livros (base_dados.sql):\n--   titulo VARCHAR(200) NOT NULL\n--   isbn   VARCHAR(13)  NULL UNIQUE\n\n-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nUPDATE livros SET isbn = '9789722036597'\nWHERE id_livro = 6;","linguagem":"sql","alternativas":["É recusada porque o ISBN não se pode alterar depois de criado.","É aceite: o UNIQUE só é verificado no INSERT.","É aceite e o outro livro fica com o ISBN a NULL.","É recusada: esse ISBN já existe e a coluna é UNIQUE."],"correta":3,"explicacao":"O UNIQUE vale também no UPDATE: o ISBN de \"Os Maias\" não pode ficar repetido no livro 6. É por isso que livro_editar.php também apanha o erro 23000.","manual":"3.4, 12.5"},{"id":"sql-121","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Qual destas instruções apaga um livro?","codigo":"","linguagem":"","alternativas":["DROP livros WHERE id_livro = ?","REMOVE FROM livros WHERE id_livro = ?","DELETE FROM livros WHERE id_livro = ?","DELETE * FROM livros WHERE id_livro = ?"],"correta":2,"explicacao":"Apaga-se com DELETE FROM tabela WHERE condição. O WHERE com a chave primária garante que só sai aquele livro.","manual":"3.7, Anexo B"},{"id":"sql-122","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"O que faz esta instrução?","codigo":"DELETE FROM livros;","linguagem":"sql","alternativas":["Dá erro, porque falta o WHERE.","Apaga a tabela livros, incluindo a sua estrutura.","Apaga só o livro com o id mais alto.","Apaga todos os livros, sem pedir confirmação."],"correta":3,"explicacao":"Sem WHERE, o DELETE apaga todas as linhas, mas a tabela continua a existir (vazia). Apagar a própria tabela ou base de dados é o DROP.","manual":"3.7"},{"id":"sql-123","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, o que acontece a esta instrução?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nDELETE FROM livros WHERE id_autor = 1;","linguagem":"sql","alternativas":["Apaga 2 livros; depois disso o Saramago já pode ser apagado.","É recusada pelo ON DELETE RESTRICT.","Apaga só o primeiro livro que encontrar com id_autor = 1 e para.","Apaga 2 livros e também o autor 1."],"correta":0,"explicacao":"O RESTRICT impede apagar o \"pai\" (autor), não os \"filhos\" (livros). Saem os 2 livros do Saramago e o autor fica sem livros, por isso já pode ser apagado.","manual":"3.3, 3.7"},{"id":"sql-124","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Executas `DELETE FROM livros WHERE id_livro = 3;` duas vezes seguidas. O que acontece na segunda vez?","codigo":"","linguagem":"","alternativas":["Dá erro, porque o livro 3 já não existe.","Não apaga nada (0 linhas afetadas) e não dá erro.","Apaga o livro 4, que passou a ter o id 3.","Volta a criar o livro 3 e apaga-o de novo."],"correta":1,"explicacao":"Um WHERE que não encontra linhas não é erro: afeta 0 linhas. Os ids não mudam quando se apaga. É assim que livro_apagar.php sabe que \"O livro já não existia\".","manual":"12.6"},{"id":"sql-125","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, corres este DELETE. Depois, quantos autores aparecem com 0 livros na lista de autores (LEFT JOIN + COUNT)?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- autores\n-- id_autor | nome                             | nacionalidade\n-- 1        | José Saramago                    | Portuguesa\n-- 2        | Sophia de Mello Breyner Andresen | Portuguesa\n-- 3        | Eça de Queirós                   | Portuguesa\n-- 4        | Machado de Assis                 | Brasileira\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nDELETE FROM livros WHERE ano_edicao < 1900;","linguagem":"sql","alternativas":["Nenhum","1","2","4"],"correta":2,"explicacao":"Saem Os Maias (1888) e Dom Casmurro (1899), os únicos livros de Eça e de Machado. Esses dois autores continuam na tabela e aparecem com 0 graças ao LEFT JOIN.","manual":"13.1, 3.5"},{"id":"sql-126","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Com os dados de exemplo, quantos livros apaga esta instrução?","codigo":"-- Dados de exemplo (base_dados.sql)\n--\n-- livros\n-- id_livro | id_autor | titulo                   | isbn          | ano_edicao\n-- 1        | 1        | Memorial do Convento     | 9789720046710 | 1982\n-- 2        | 1        | Ensaio sobre a Cegueira  | 9789720046727 | 1995\n-- 3        | 2        | A Menina do Mar          | 9789720726421 | 1958\n-- 4        | 2        | O Cavaleiro da Dinamarca | 9789720726438 | 1964\n-- 5        | 3        | Os Maias                 | 9789722036597 | 1888\n-- 6        | 4        | Dom Casmurro             | 9788535910681 | 1899\n\nDELETE FROM livros WHERE titulo LIKE '%a%';","linguagem":"sql","alternativas":["Nenhum","1","2","6"],"correta":3,"explicacao":"Todos os 6 títulos têm pelo menos um \"a\" (sem distinguir maiúsculas). Um WHERE com LIKE pode apanhar muito mais do que parece; para apagar um livro usa-se o id.","manual":"3.7, 12.2"},{"id":"sql-127","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Inseriste a autora Ana, que não tem livros. O que acontece a `DELETE FROM autores WHERE id_autor = 5;`?","codigo":"","linguagem":"","alternativas":["A Ana é apagada: o RESTRICT só impede apagar autores com livros.","É recusado: o RESTRICT impede apagar qualquer autor.","É recusado: é preciso apagar antes os livros de todos os autores.","A Ana é apagada e os livros dos outros autores ficam com NULL."],"correta":0,"explicacao":"O ON DELETE RESTRICT só atua quando há livros a apontar para aquele autor. Sem livros, nada o impede.","manual":"3.3, 13.3"},{"id":"sql-128","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Tentas registar um email que já existe numa coluna UNIQUE. Que erro aparece?","codigo":"","linguagem":"","alternativas":["1049 Unknown database","1062 Duplicate entry","2002 Connection refused","1451 Cannot delete or update a parent row"],"correta":1,"explicacao":"Duplicate entry (1062, SQLSTATE 23000) = valor repetido num campo UNIQUE. O 1451 aparece quando a chave estrangeira impede apagar.","manual":"17.2"},{"id":"sql-129","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Ao apagar um autor aparece \"SQLSTATE[23000] … 1451 Cannot delete or update a parent row\". O que quer dizer?","codigo":"","linguagem":"","alternativas":["A FK impede apagar o \"pai\", que ainda tem livros.","O MySQL está desligado no XAMPP Control Panel.","O DELETE não tem WHERE e ia apagar todos os autores.","O autor já tinha sido apagado noutro separador."],"correta":0,"explicacao":"O \"parent row\" é o autor; os livros são os \"filhos\". Com ON DELETE RESTRICT, a base de dados recusa e o código apanha o erro com try/catch.","manual":"17.2, 13.3"},{"id":"sql-130","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"O que significa o código de erro 23000?","codigo":"","linguagem":"","alternativas":["Ligação recusada, porque o MySQL está desligado.","Erro de sintaxe no SQL, como uma cláusula fora de ordem.","Página não encontrada no servidor.","Violação de uma regra: UNIQUE ou chave estrangeira."],"correta":3,"explicacao":"23000 junta os casos em que uma regra da base de dados é violada: valor repetido num UNIQUE (1062) ou FK que impede a operação (1451).","manual":"8.5, 17.2"},{"id":"sql-131","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Esta consulta dá \"SQLSTATE[42S22] … Unknown column\". Qual é a causa provável?","codigo":"SELECT id_livro, titlo FROM livros\nORDER BY titlo;","linguagem":"sql","alternativas":["O MySQL está desligado.","O nome de uma coluna está mal escrito no SQL.","O valor do título tem acentos.","A tabela livros ainda não tem nenhuma linha."],"correta":1,"explicacao":"\"titlo\" não existe: é \"titulo\" mal escrito. A solução é comparar o SQL com o base_dados.sql.","manual":"17.2"},{"id":"sql-132","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Aparece \"SQLSTATE[HY000] [1049] Unknown database 'biblioteca'\". O que fazes?","codigo":"","linguagem":"","alternativas":["Ligas o MySQL no XAMPP Control Panel e recarregas a página.","Tiras a password do root no db.php.","Importas o base_dados.sql ou corriges o nome no db.php.","Corriges o nome da coluna no SELECT."],"correta":2,"explicacao":"Unknown database = a base de dados não existe (não foi importada) ou o nome está errado. MySQL desligado é o 2002; utilizador ou password errados é o 1045.","manual":"17.2"},{"id":"sql-133","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Na aplicação, \"José\" aparece como \"JosÃ©\". O que corrige o problema?","codigo":"","linguagem":"","alternativas":["Trocar a coluna nome de VARCHAR(120) para TEXT.","Usar utf8mb4 em todo o percurso, do .sql à ligação.","Acrescentar ORDER BY nome ao SELECT dos autores.","Aplicar htmlspecialchars() ao nome antes de o gravar na base."],"correta":1,"explicacao":"Acentos estragados vêm de gravar ou ler com a codificação errada. A solução é utf8mb4 em todo o percurso.","manual":"17.2, 3.5"},{"id":"sql-134","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Aparece \"SQLSTATE[HY093]: Invalid parameter number\". Qual é a causa provável?","codigo":"","linguagem":"","alternativas":["Um nome de coluna está mal escrito no SELECT ou no INSERT.","O MySQL está desligado.","O número de ? não bate certo com o número de valores.","Um valor repetido numa coluna UNIQUE."],"correta":2,"explicacao":"Cada ? precisa de um valor, pela mesma ordem. A solução do manual é contar os dois.","manual":"17.2, 8.2"},{"id":"sql-135","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"dificil","pergunta":"Esta consulta deveria pesquisar livros pelo texto passado no lugar do ?. Qual é o problema?","codigo":"SELECT titulo FROM livros\nWHERE titulo LIKE '%?%';","linguagem":"sql","alternativas":["Entre plicas, o ? é texto normal; o SQL devia ser LIKE ?.","O LIKE não pode ser usado com % dos dois lados da palavra.","Falta ORDER BY, obrigatório numa pesquisa com LIKE.","O ? tem de ser escrito como :titulo."],"correta":0,"explicacao":"Entre plicas, ? é um carácter normal. O SQL certo é LIKE ? e o valor passado é '%' . $q . '%', como em livros.php.","manual":"12.2, 8.4"},{"id":"sql-136","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"Qual destes erros indica que o MySQL está desligado no XAMPP?","codigo":"","linguagem":"","alternativas":["SQLSTATE[42S22] … Unknown column","SQLSTATE[23000] … 1062 Duplicate entry","SQLSTATE[HY000] [1049] Unknown database","SQLSTATE[HY000] [2002] … connection refused"],"correta":3,"explicacao":"Connection refused (2002) = não há MySQL a responder: carrega em Start no MySQL do XAMPP Control Panel.","manual":"17.2"},{"id":"sql-137","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"No SQL da Biblioteca aparecem `?`, como em `VALUES (?, ?)`. O que são?","codigo":"","linguagem":"","alternativas":["Os lugares onde o programa põe os valores.","Colunas cujo nome ainda não se sabe.","Caracteres especiais do LIKE, como o %.","Valores opcionais que podem ficar vazios."],"correta":0,"explicacao":"Os ? marcam onde entram os valores, que são enviados à parte. É isso que protege contra a injeção de SQL.","manual":"3.7"},{"id":"sql-138","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Em livro_editar.php, que SQL corre no pedido GET, antes de se mostrar o formulário?","codigo":"","linguagem":"","alternativas":["INSERT INTO livros … VALUES (…)","DELETE FROM livros WHERE id_livro = ?","UPDATE livros SET … WHERE id_livro = ?","SELECT * FROM livros WHERE id_livro = ?"],"correta":3,"explicacao":"No GET, a página lê o livro para preencher o formulário. O UPDATE só corre no POST, quando se gravam as alterações.","manual":"12.1, 12.5"},{"id":"sql-139","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"media","pergunta":"Que instruções SQL alteram dados e, por isso, só devem correr depois de um pedido POST?","codigo":"","linguagem":"","alternativas":["SELECT, INSERT, UPDATE e DELETE","INSERT, UPDATE e DELETE","SELECT, UPDATE e DELETE","SELECT, INSERT e UPDATE"],"correta":1,"explicacao":"No mapa das páginas, gravar, alterar e apagar são todos POST. O SELECT só lê dados, por isso funciona com GET (lista, pesquisa, detalhe).","manual":"12.1, 4.4"},{"id":"sql-140","bloco":"dados","tema":"SQL e Base de dados","dificuldade":"facil","pergunta":"CRUD são as quatro operações sobre uma tabela. Que instruções SQL lhes correspondem?","codigo":"","linguagem":"","alternativas":["CREATE DATABASE, SELECT, SET e DELETE","INSERT, SELECT, ALTER e DROP","INSERT, SELECT, UPDATE e DELETE","CREATE TABLE, SELECT, UPDATE e DROP"],"correta":2,"explicacao":"Create = INSERT, Read = SELECT, Update = UPDATE, Delete = DELETE. CREATE TABLE e DROP mexem na estrutura, não nos dados.","manual":"12"},{"id":"amostra-007","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"O que acontece se alguém pesquisar ' OR 1=1 --  neste código?","codigo":"$q = $_GET['q'];\n$sql = \"SELECT * FROM livros WHERE titulo LIKE '%$q%'\";\n$livros = $pdo->query($sql)->fetchAll();","linguagem":"php","alternativas":["Dá um erro de sintaxe e não aparece nenhum livro.","Devolve todos os livros da tabela.","Procura um livro com esse título estranho e não encontra nenhum.","O PDO deteta o ataque e recusa a consulta."],"correta":1,"explicacao":"A variável entra no texto do SQL: a plica fecha o texto, o OR 1=1 é sempre verdadeiro e o -- comenta o resto. É SQL injection. Com prepare() e execute(), a consulta procuraria esse título e não encontraria nada.","manual":"8.4"},{"id":"seg-001","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O dossier exige as seis medidas de segurança em baixo. Qual destas proteções NÃO é uma delas?","codigo":"As seis medidas de segurança do dossier\n\n1. Passwords com hash\n2. Consultas preparadas\n3. Validação no servidor\n4. Controlo de acesso\n5. Consentimento no registo\n6. Política de privacidade acessível","linguagem":"tabela","alternativas":["Ligação HTTPS com certificado.","Consultas preparadas contra SQL injection.","Consentimento no registo.","Política de privacidade acessível."],"correta":0,"explicacao":"As seis medidas são: passwords com hash, consultas preparadas, validação no servidor, controlo de acesso, consentimento no registo e política de privacidade acessível. O HTTPS aparece no manual só como algo que faltaria numa aplicação real.","manual":"14, 14.3"},{"id":"seg-002","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O manual avisa: \"Sem as passwords com hash ou sem as consultas preparadas, o projeto não passa dos 49 pontos.\" Porque é que estas duas medidas pesam tanto?","codigo":"","linguagem":"","alternativas":["Porque são as únicas que o formador consegue testar.","Sem elas, as passwords ficam legíveis e a base de dados fica aberta a SQL injection.","Porque sem elas a aplicação não chega a arrancar.","Porque são as duas medidas que o RGPD exige."],"correta":1,"explicacao":"Sem hash, quem vê a tabela utilizadores lê as passwords de todos. Sem consultas preparadas, um texto como ' OR 1=1 -- muda o SQL e dá para entrar sem password ou ler a base de dados toda. São as duas falhas mais graves, por isso o manual diz que sem elas o projeto não passa dos 49 pontos.","manual":"14"},{"id":"seg-003","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"O manual avisa: \"Sem as passwords com hash ou sem as consultas preparadas, o projeto não passa dos 49 pontos.\" No phpMyAdmin, a tabela utilizadores tem a coluna password com valores como Demo1234. Que medida falha e com que consequência?","codigo":"","linguagem":"","alternativas":["Passwords com hash; perde-se só a cotação dessa medida.","Consultas preparadas; o projeto não passa dos 49 pontos.","Passwords com hash; o projeto não passa dos 49 pontos.","Consentimento no registo; perde-se só essa cotação."],"correta":2,"explicacao":"A password está guardada em claro, por isso falha a medida das passwords com hash. É uma das duas medidas sem as quais o projeto não passa dos 49 pontos, não uma simples cotação perdida.","manual":"14, 10.1"},{"id":"seg-004","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Como confirmas, no phpMyAdmin, que as passwords estão guardadas com hash?","codigo":"","linguagem":"","alternativas":["Os valores da coluna aparecem escondidos com asteriscos.","Os valores da coluna password_hash começam por $2.","A coluna tem o tipo PASSWORD em vez de VARCHAR.","A coluna está vazia, porque o hash fica na sessão."],"correta":1,"explicacao":"O password_hash() usa o bcrypt, que produz textos começados por $2y$. Se vires a password escrita tal como foi registada, a medida falha.","manual":"14, 16"},{"id":"seg-005","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Como testas a medida \"validação no servidor\"?","codigo":"","linguagem":"","alternativas":["Envias os formulários vazios com o JavaScript ligado.","Desligas o JavaScript e envias os formulários vazios.","Abres os formulários numa janela anónima e envias.","Abres os formulários numa janela anónima e envias-os vazios."],"correta":1,"explicacao":"Com o JavaScript ligado, quem encontra os erros é o browser. Só com ele desligado é que o pedido chega ao servidor e se prova que o servidor valida sozinho.","manual":"14, 6.1"},{"id":"seg-006","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Como testas a medida \"controlo de acesso\"?","codigo":"","linguagem":"","alternativas":["Com sessão iniciada, confirmas que o menu mostra os links certos.","Fazes logout e confirmas que os links do menu desaparecem.","Numa janela anónima, abres o endereço de cada página restrita.","Desligas o JavaScript e tentas abrir a lista pelo menu."],"correta":2,"explicacao":"Na janela anónima não há sessão. Escrever o endereço à mão é o que faria um atacante: tens de ser mandado para o login. Ver o menu não prova nada, porque esconder links não é controlo de acesso.","manual":"14, 11.3"},{"id":"seg-007","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Qual destes testes prova que o consentimento é verificado no servidor?","codigo":"","linguagem":"","alternativas":["Registar sem assinalar a caixa, com o JavaScript ligado.","Confirmar no phpMyAdmin que existe a coluna consentimento_em.","Abrir o registo e confirmar que a caixa vem já assinalada.","Registar sem assinalar a caixa, com o JavaScript desligado."],"correta":3,"explicacao":"Com o JavaScript ligado, quem recusa é o browser. Desligado, só o servidor pode recusar o registo. E a caixa tem de vir desmarcada: uma caixa já assinalada não é consentimento.","manual":"14, 16"},{"id":"seg-008","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"No teste, pesquisas ' OR 1=1 -- e confirmas que não devolve tudo nem dá erro. Que medida obrigatória estás a testar?","codigo":"","linguagem":"","alternativas":["As consultas preparadas.","A validação no servidor.","O controlo de acesso.","As passwords com hash."],"correta":0,"explicacao":"Este teste tenta uma injeção de SQL pela caixa de pesquisa. Só não resulta se a consulta usar prepare() com ? e execute().","manual":"14, 16"},{"id":"seg-009","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Na tabela das seis medidas do manual (em baixo), onde está a validação no servidor?","codigo":"Medida                   | Onde está na Biblioteca\n-------------------------+---------------------------------------------\nPasswords com hash       | password_hash() no registo, password_verify() no login\nConsultas preparadas     | Todas as consultas: prepare() + execute([...])\nValidação no servidor    | registo.php, validar_livro(), autor_form.php\nControlo de acesso       | includes/auth.php\nConsentimento no registo | Caixa desmarcada, verificada no servidor; data em consentimento_em\nPolítica de privacidade  | privacidade.php, com link no rodapé e no registo","linguagem":"tabela","alternativas":["No validacao.js, ligado no rodapé de todas as páginas.","Nos atributos required e maxlength dos campos do formulário.","No PHP que verifica os dados antes do INSERT ou do UPDATE.","Nas restrições UNIQUE e NOT NULL da base de dados."],"correta":2,"explicacao":"A validação no servidor está no PHP: registo.php, validar_livro() e autor_form.php. O validacao.js e o required correm no browser e podem ser contornados.","manual":"14, 12.4"},{"id":"seg-010","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Na Biblioteca, que consultas são feitas com prepare() e execute()?","codigo":"","linguagem":"","alternativas":["Só as que recebem dados de formulários POST.","Todas, sem exceção.","Só as do login e do registo, onde há passwords.","Só os DELETE e os UPDATE, que alteram dados."],"correta":1,"explicacao":"A medida diz \"todas as consultas: prepare() + execute([...])\". Até uma consulta sem valores, como a lista de autores, é feita assim.","manual":"14, 8.2"},{"id":"seg-011","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"O dossier exige as seis medidas de segurança em baixo. Qual destas proteções é usada em todas as páginas da Biblioteca, mas NÃO está na lista?","codigo":"As seis medidas de segurança do dossier\n\n1. Passwords com hash\n2. Consultas preparadas\n3. Validação no servidor\n4. Controlo de acesso\n5. Consentimento no registo\n6. Política de privacidade acessível","linguagem":"tabela","alternativas":["Escapar os dados com htmlspecialchars() ao mostrá-los.","Guardar as passwords com password_hash().","Verificar a sessão no topo das páginas com o includes/auth.php.","Validar os dados no servidor antes de gravar."],"correta":0,"explicacao":"O htmlspecialchars() é explicado à parte, na secção 14.1 (XSS). As outras três estão na tabela das seis medidas.","manual":"14, 14.1"},{"id":"seg-012","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"No registo.php, a conta é gravada assim. Como fica provado que o utilizador deu o consentimento?","codigo":"// 3. Guardar: a password nunca é guardada, só o seu hash\nif (!$erros) {\n    $hash = password_hash($password, PASSWORD_DEFAULT);\n    $stmt = $pdo->prepare(\n        'INSERT INTO utilizadores (nome, email, password_hash, consentimento_em)\n         VALUES (?, ?, ?, NOW())'\n    );\n    $stmt->execute([$nome, $email, $hash]);\n\n    mensagem('sucesso', 'Conta criada. Já podes iniciar sessão.');\n    header('Location: login.php');\n    exit;\n}","linguagem":"php","alternativas":["Fica guardado um cookie no browser com a resposta.","O email de confirmação fica na tabela utilizadores.","A caixa assinalada fica guardada na sessão.","A data fica guardada na coluna consentimento_em."],"correta":3,"explicacao":"O servidor verifica a caixa e grava a data com NOW() na coluna consentimento_em. É isso que permite provar que o utilizador aceitou a política.","manual":"14, 15.2"},{"id":"seg-013","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O que é a injeção de SQL (SQL injection)?","codigo":"","linguagem":"","alternativas":["Inserir muitos registos de uma vez para encher a base de dados.","Gravar um script que corre no browser de quem abre a página.","Escrever num campo um texto que altera o SQL executado.","Ler a password da base de dados no código-fonte da página."],"correta":2,"explicacao":"Quando o valor é colado ao texto do SQL, quem escreve no campo pode fechar o texto e acrescentar código SQL seu. Gravar um script para outros utilizadores é XSS, outro ataque.","manual":"8.4"},{"id":"seg-014","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Alguém escreve ' OR 1=1 -- na caixa de pesquisa. Que SQL chega à base de dados?","codigo":"$q = $_GET['q'];\n$sql = \"SELECT * FROM livros WHERE titulo LIKE '%$q%'\";\n$livros = $pdo->query($sql)->fetchAll();","linguagem":"php","alternativas":["SELECT * FROM livros WHERE titulo LIKE '%$q%'","SELECT * FROM livros WHERE titulo LIKE '%' OR 1=1 -- %'","SELECT * FROM livros WHERE titulo LIKE '%\\' OR 1=1 -- %'","SELECT * FROM livros WHERE titulo LIKE ?"],"correta":1,"explicacao":"Dentro de aspas duplas, o PHP substitui $q pelo texto escrito, tal como está: nada é escapado. A plica fecha o texto, o OR 1=1 é sempre verdadeiro e o -- comenta o resto.","manual":"8.4"},{"id":"seg-015","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"No ataque ' OR 1=1 -- , para que serve a plica do início?","codigo":"","linguagem":"","alternativas":["Abre um comentário que anula o resto da consulta.","Indica ao MySQL que o valor que vem a seguir é um número inteiro.","Escapa o OR para não ser lido como texto.","Fecha o texto que o SQL tinha aberto; o resto passa a ser lido como código."],"correta":3,"explicacao":"O SQL tinha LIKE '%...%'. A plica do atacante fecha esse texto antes do tempo, e o OR 1=1 fica fora das plicas, como código SQL. O comentário é o --.","manual":"8.4"},{"id":"seg-016","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"No ataque ' OR 1=1 -- , o que faz o -- ?","codigo":"","linguagem":"","alternativas":["Transforma o resto da linha num comentário, que é ignorado.","Subtrai o valor seguinte ao resultado da pesquisa.","Fecha a plica que o SQL tinha aberto antes do valor.","Termina a consulta atual e começa a seguir uma segunda consulta."],"correta":0,"explicacao":"Em SQL, -- inicia um comentário. Assim, a plica e o % que o código original punha depois do valor deixam de contar e a consulta não dá erro.","manual":"8.4"},{"id":"seg-017","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Porque é que, com o OR 1=1, esta consulta devolve todas as linhas?","codigo":"SELECT * FROM livros WHERE titulo LIKE '%' OR 1=1 -- %'","linguagem":"sql","alternativas":["Porque 1=1 é sempre verdadeiro, para qualquer linha.","Porque o OR desliga o WHERE e o ORDER BY da consulta.","Porque 1=1 seleciona a primeira coluna de cada tabela.","Porque o MySQL ignora as condições que vêm depois do LIKE."],"correta":0,"explicacao":"Com OR, basta uma das condições ser verdadeira. Como 1=1 é verdadeiro para qualquer linha, todas as linhas passam no WHERE.","manual":"8.4"},{"id":"seg-018","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Segundo o manual, o mesmo truque usado numa página de login vulnerável permite…","codigo":"","linguagem":"","alternativas":["descobrir a password original a partir do hash.","entrar sem saber a password.","executar um script no browser de quem abre o login.","apagar o cookie de sessão dos outros utilizadores."],"correta":1,"explicacao":"Se o email e a password forem juntados ao SQL, a condição passa a ser sempre verdadeira e o login aceita o atacante. Executar scripts no browser de outros é XSS.","manual":"8.4"},{"id":"seg-019","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Alguém envia id_livro com o valor 0 OR 1=1 para esta página. O que acontece?","codigo":"$id = $_POST['id_livro'];\n$pdo->query(\"DELETE FROM livros WHERE id_livro = $id\");","linguagem":"php","alternativas":["Não apaga nada, porque o id não é um número.","Apaga só o livro com o id 0, que não existe.","Dá um erro 404, porque a página só aceita números.","Apaga todas as linhas da tabela, e não só uma."],"correta":3,"explicacao":"Com um OR 1=1 injetado, o WHERE do DELETE fica verdadeiro para todas as linhas. O manual resume: \"com um DELETE, apaga a tabela\".","manual":"8.4"},{"id":"seg-020","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Qual é a defesa contra a injeção de SQL usada no projeto?","codigo":"","linguagem":"","alternativas":["Validar os campos no browser com JavaScript.","Passar todos os valores por htmlspecialchars() antes do query().","Consultas preparadas: prepare() com ? e execute() com os valores.","Guardar os valores na base de dados com password_hash()."],"correta":2,"explicacao":"O SQL vai com ? no lugar dos valores, e os valores vão à parte no execute(). O htmlspecialchars() é a defesa contra XSS, não contra a injeção de SQL.","manual":"8.4, 14"},{"id":"seg-021","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Porque é que as consultas preparadas impedem a injeção de SQL?","codigo":"","linguagem":"","alternativas":["O PDO apaga do valor as plicas e os traços antes de o juntar ao SQL.","O prepare() cifra o valor antes de o enviar à base de dados.","O execute() só aceita números, por isso o texto é recusado.","O valor vai à parte e é tratado como texto, nunca como código."],"correta":3,"explicacao":"Com parâmetros, o valor nunca é colado ao SQL: a base de dados trata-o sempre como texto, nunca como código. Nada é apagado nem cifrado.","manual":"8.4"},{"id":"seg-022","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Este código usa prepare(). Está protegido contra a injeção de SQL?","codigo":"$id = $_GET['id'];\n$stmt = $pdo->prepare(\"DELETE FROM livros WHERE id_livro = $id\");\n$stmt->execute();","linguagem":"php","alternativas":["Sim: qualquer consulta feita com prepare() fica protegida.","Não: a variável está dentro do texto do SQL.","Sim, porque um id é sempre um número inteiro.","Não, mas basta trocar as aspas duplas por plicas."],"correta":1,"explicacao":"O prepare() só protege os valores passados no execute() no lugar dos ?. Aqui o $id é colado ao SQL antes. Com plicas, $id nem seria substituído e a consulta daria erro.","manual":"8.4"},{"id":"seg-023","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"O $id já foi convertido com (int). Este código cumpre a regra do manual?","codigo":"$id = (int) ($_GET['id'] ?? 0);\n$stmt = $pdo->query(\"SELECT * FROM livros WHERE id_livro = $id\");\n$livro = $stmt->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["Não: nenhuma variável entra no SQL, nem os ids.","Sim: o (int) garante que só chega um número ao SQL.","Sim, porque o id vem de $_GET e não de $_POST.","Não: faltava htmlspecialchars($id) antes da consulta."],"correta":0,"explicacao":"A regra é simples: nenhuma variável dentro do texto do SQL, nem as do próprio site, nem os ids, nem os números. Faz-se prepare('... WHERE id_livro = ?') e execute([$id]).","manual":"8.4, 14.2"},{"id":"seg-024","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Queres pesquisar os títulos que contêm o texto $q. Qual é a forma segura?","codigo":"","linguagem":"","alternativas":["prepare(\"... WHERE titulo LIKE '%$q%'\") e execute()","prepare('... WHERE titulo LIKE %?%') e execute([$q])","prepare('... WHERE titulo LIKE ?') e execute(['%' . $q . '%'])","query(\"... WHERE titulo LIKE '%\" . $q . \"%'\")"],"correta":2,"explicacao":"Os % são acrescentados ao valor, não ao SQL. O SQL fica só com o ?, e o texto completo (%mar%) vai no execute().","manual":"8.4, 12.2"},{"id":"seg-025","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Qual destas instruções cumpre a regra \"nenhuma variável dentro do SQL\"?","codigo":"","linguagem":"","alternativas":["$pdo->prepare(\"UPDATE livros SET titulo = ? WHERE id_livro = $id\")","$pdo->prepare('UPDATE livros SET titulo = ? WHERE id_livro = ?')","$pdo->query(\"UPDATE livros SET titulo = '$titulo' WHERE id_livro = 1\")","$pdo->prepare('UPDATE livros SET titulo = ' . $titulo . ' WHERE id_livro = ?')"],"correta":1,"explicacao":"Se vires um $ dentro das aspas do SQL, ou um texto juntado com o ponto, está mal. Só a que tem ? em todos os valores está certa; os valores seguem depois no execute().","manual":"8.4"},{"id":"seg-026","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Onde está o problema deste login?","codigo":"$email = $_POST['email'] ?? '';\n$sql = \"SELECT * FROM utilizadores WHERE email = '$email'\";\n$utilizador = $pdo->query($sql)->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["O email entra no texto do SQL: uma plica no campo muda a consulta.","Falta passar o $email por htmlspecialchars() antes de fazer a consulta.","Devia ser $_GET['email'], porque é um SELECT.","As aspas duplas impedem que $email seja substituído."],"correta":0,"explicacao":"É injeção de SQL: o valor é colado ao SQL e o query() executa-o assim. Corrige-se com prepare('... WHERE email = ?') e execute([$email]). As aspas duplas fazem precisamente a substituição.","manual":"8.4"},{"id":"seg-027","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Com este código, alguém pesquisa ' OR 1=1 -- . O que procura a base de dados?","codigo":"$stmt = $pdo->prepare('SELECT * FROM livros WHERE titulo LIKE ?');\n$stmt->execute(['%' . $q . '%']);\n$livros = $stmt->fetchAll(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["Todos os livros, porque 1=1 é sempre verdadeiro.","Nada: o execute() recusa valores com plicas e dá erro.","Títulos que contêm OR 1=1, sem a plica e sem o --.","Títulos que contêm o texto ' OR 1=1 -- , tal e qual."],"correta":3,"explicacao":"Com parâmetros, o valor é só texto: a base de dados procura um título com esse texto estranho e não encontra nenhum. É o resultado esperado no teste: não devolve tudo e não dá erro.","manual":"8.4, 16"},{"id":"seg-028","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Num projeto, a pesquisa ' OR 1=1 -- devolve todos os registos. O que concluis?","codigo":"","linguagem":"","alternativas":["Está correto: com quase nada escrito, o LIKE encontra tudo.","Falta htmlspecialchars() no value da caixa de pesquisa.","Há uma consulta que junta o texto da pesquisa ao SQL.","O formulário de pesquisa devia usar POST em vez de GET."],"correta":2,"explicacao":"Com consultas preparadas, este teste não devolve tudo nem dá erro. Se devolve tudo, o OR 1=1 foi executado como código: a consulta não usa parâmetros.","manual":"8.4, 16"},{"id":"seg-029","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O que é o cross-site scripting (XSS)?","codigo":"","linguagem":"","alternativas":["Alterar o SQL escrevendo uma plica num campo de texto.","Fazer um robô seguir um link que apaga dados.","Descobrir que emails têm conta pela mensagem do login.","Gravar um script que corre no browser de quem abrir a página."],"correta":3,"explicacao":"No XSS, alguém grava por exemplo um título com <script>...</script>. Se for escrito na página tal como está, o browser de quem a abrir executa esse script.","manual":"14.1"},{"id":"seg-030","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Qual é a diferença entre a injeção de SQL e o XSS?","codigo":"","linguagem":"","alternativas":["A de SQL ataca a base de dados; o XSS ataca os outros utilizadores.","A injeção de SQL ataca os utilizadores; o XSS ataca a base de dados.","Os dois atacam a base de dados, mas por campos diferentes.","Os dois atacam o servidor, e evitam-se ambos com consultas preparadas."],"correta":0,"explicacao":"A injeção de SQL altera a consulta feita à base de dados. O XSS põe um script na página que outro utilizador abre, e é no browser dele que o ataque acontece.","manual":"14.1"},{"id":"seg-031","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Que par ataque → defesa está certo?","codigo":"","linguagem":"","alternativas":["Injeção de SQL → htmlspecialchars(); XSS → consultas preparadas.","Injeção de SQL → password_hash(); XSS → atributo required nos campos.","Injeção de SQL → consultas preparadas; XSS → htmlspecialchars().","Injeção de SQL e XSS → validação em JavaScript."],"correta":2,"explicacao":"Cada ataque tem a sua defesa: os parâmetros separam os valores do SQL; o htmlspecialchars() faz o browser mostrar como texto o HTML escrito pelo utilizador.","manual":"8.4, 14.1"},{"id":"seg-032","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Segundo o manual, o que pode fazer, por exemplo, um script injetado por XSS?","codigo":"","linguagem":"","alternativas":["Apagar a tabela dos livros na base de dados.","Roubar o cookie da sessão de quem abre a página.","Ler o código PHP das páginas no servidor.","Descobrir a password do MySQL guardada no db.php."],"correta":1,"explicacao":"O script corre no browser da vítima, por isso chega ao que o browser tem, como o cookie da sessão. Não chega ao código PHP nem à base de dados.","manual":"14.1"},{"id":"seg-033","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Um script injetado por XSS rouba o cookie de sessão (PHPSESSID) de um utilizador. O que consegue o atacante com ele?","codigo":"","linguagem":"","alternativas":["Ler a password do utilizador, que vai guardada no cookie.","Apagar diretamente a base de dados no servidor.","Fazer pedidos como se fosse esse utilizador, com a sessão dele.","Ver o código PHP das páginas da aplicação."],"correta":2,"explicacao":"O cookie leva o identificador da sessão: quem o envia é tratado pelo servidor como o dono dessa sessão. A password nunca vai no cookie; os dados da sessão ficam no servidor.","manual":"14.1, 10.3"},{"id":"seg-034","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"As consultas são todas preparadas, mas a lista mostra os títulos sem escapar. Alguém grava um livro com <script> no título. Quem é afetado?","codigo":"","linguagem":"","alternativas":["Só a base de dados, que fica com a tabela estragada.","Quem abrir a lista dos livros.","Só o utilizador que gravou o livro.","Ninguém, porque o INSERT foi feito com prepare()."],"correta":1,"explicacao":"O prepare() grava o título com segurança, mas não o torna inofensivo ao mostrar. O script corre no browser de todos os que abrem a página. É por isso que XSS e injeção de SQL têm defesas diferentes.","manual":"14.1"},{"id":"seg-035","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Gravas um registo com <script>alert(1)</script> num campo de texto. O que tem de acontecer numa aplicação protegida?","codigo":"","linguagem":"","alternativas":["O texto aparece tal e qual e não abre nenhuma janela.","Abre uma janela com 1, o que prova que foi gravado.","O registo é recusado com um erro de SQL.","O campo aparece vazio, porque o script foi apagado."],"correta":0,"explicacao":"É o teste 20. Com htmlspecialchars(), os < e > são escritos como &lt; e &gt; e o browser mostra o texto em vez de o executar. Se abrir a janela, há XSS.","manual":"16, 14.1"},{"id":"seg-036","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Porque é que não se guarda a password tal como foi escrita?","codigo":"","linguagem":"","alternativas":["Porque o VARCHAR não aceita caracteres especiais nem letras acentuadas.","Porque a password ocupa mais espaço do que o seu hash.","Porque o login ficaria mais lento com a password em claro.","Se a base de dados for roubada, o atacante fica com as passwords."],"correta":3,"explicacao":"E como muitas pessoas usam a mesma password em vários sites, o atacante ficaria também com o acesso ao email e ao banco delas. Por isso guarda-se só o hash.","manual":"10.1"},{"id":"seg-037","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O que é o hash de uma password?","codigo":"","linguagem":"","alternativas":["A password cifrada, que se decifra com a chave guardada no db.php.","O resultado de uma função que não se pode reverter.","A password escrita noutra codificação, como o base64.","Uma cópia da password guardada na sessão do utilizador."],"correta":1,"explicacao":"O hash é um texto de tamanho fixo calculado a partir da password, e a partir dele não há forma de chegar à password. Não há nenhuma chave para o \"decifrar\".","manual":"10.1"},{"id":"seg-038","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Um colega guarda as passwords assim, porque \"na base de dados ficam ilegíveis\". Está bem?","codigo":"$guardar = base64_encode($password);","linguagem":"php","alternativas":["Não: o base64 não é um hash, só reescreve o texto.","Sim: ninguém consegue ler a password na base de dados.","Sim, desde que a ligação use charset=utf8mb4.","Não, porque o base64 é demasiado lento para o login."],"correta":0,"explicacao":"O base64 desfaz-se de imediato: é só outra representação do mesmo texto. Para passwords usa-se sempre password_hash().","manual":"10.1"},{"id":"seg-039","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Um colega guarda as passwords assim. Porque é que md5() e sha1() não servem para isto?","codigo":"$hash = md5($password);","linguagem":"php","alternativas":["São reversíveis: dá para decifrar o hash.","Geram textos maiores do que a coluna aceita.","Só funcionam com passwords até 8 caracteres.","São rápidos demais e, por isso, fáceis de atacar."],"correta":3,"explicacao":"Um hash rápido deixa o atacante experimentar milhões de passwords. O bcrypt do password_hash() tem um custo que o torna lento de atacar.","manual":"10.1"},{"id":"seg-040","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Se o hash não é reversível, como se confirma a password no login?","codigo":"","linguagem":"","alternativas":["Decifra-se o hash guardado e compara-se com o que foi escrito.","Compara-se o texto escrito diretamente com a coluna password_hash.","Calcula-se o hash da password escrita e compara-se com o guardado.","Lê-se a password original guardada na sessão no momento do registo."],"correta":2,"explicacao":"No login compara-se, não se \"decifra\". O password_verify() calcula o hash da password escrita com o sal guardado e vê se dá o mesmo.","manual":"10.1"},{"id":"seg-041","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Registas duas contas com a mesma password. Como são os hashes guardados?","codigo":"","linguagem":"","alternativas":["Iguais, porque a função de hash é sempre a mesma.","Iguais, e por isso o UNIQUE recusa a segunda conta.","Diferentes, porque cada hash inclui o email da conta.","Diferentes, por causa do sal aleatório de cada hash."],"correta":3,"explicacao":"O password_hash() usa um sal, um valor aleatório que fica dentro do próprio hash. Com sais diferentes, a mesma password dá hashes diferentes.","manual":"10.1"},{"id":"seg-042","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O browser já valida os formulários. Porque é obrigatório validar outra vez no servidor?","codigo":"","linguagem":"","alternativas":["Porque o browser não consegue validar o formato do email.","Porque o JavaScript só corre depois de o pedido chegar ao servidor.","Dá para desligar o JavaScript ou enviar o pedido sem o formulário.","Porque o servidor mostra os erros mais depressa do que o browser."],"correta":2,"explicacao":"Tudo o que corre no browser está nas mãos do utilizador. Só o servidor garante que os dados são verificados.","manual":"6.1, 14"},{"id":"seg-043","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Este campo tem required. O que podes concluir?","codigo":"<input type=\"text\" id=\"titulo\" name=\"titulo\" required>","linguagem":"html","alternativas":["O browser pede o valor, mas o servidor tem de validar na mesma.","O campo nunca pode chegar vazio ao servidor, venha o pedido de onde vier.","A validação deste campo no servidor é dispensável.","O campo passa a ser verificado pela base de dados."],"correta":0,"explicacao":"O required pode ser contornado: basta desligar a validação do browser ou enviar o pedido sem passar pelo formulário. A validação no servidor continua obrigatória.","manual":"14, 6.4"},{"id":"seg-044","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"O campo título tem maxlength=\"200\". O servidor ainda precisa de verificar o tamanho?","codigo":"<input type=\"text\" name=\"titulo\" maxlength=\"200\" required>","linguagem":"html","alternativas":["Não: o browser não deixa escrever mais de 200 caracteres.","Sim: o maxlength também pode ser contornado.","Não: a base de dados corta o texto que sobrar.","Só quando o JavaScript estiver desligado."],"correta":1,"explicacao":"Por isso validar_livro() confirma que o título não passa de 200 caracteres com mb_strlen(). Qualquer limite posto no HTML é só conforto para o utilizador.","manual":"12.4, 14"},{"id":"seg-045","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Para que serve, então, a validação em JavaScript?","codigo":"","linguagem":"","alternativas":["Impedir que cheguem dados maliciosos ao servidor.","Proteger os campos de texto contra a injeção de SQL.","Dar resposta imediata ao utilizador, sem esperar pelo servidor.","Substituir a validação no servidor nos formulários simples."],"correta":2,"explicacao":"O manual diz que é uma questão de conforto, e não de segurança. A segurança depende da validação no servidor.","manual":"6.1"},{"id":"seg-046","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Envias o registo em branco com o JavaScript desligado e a página recarrega com os erros. O que prova este teste?","codigo":"","linguagem":"","alternativas":["Que o validacao.js está mal ligado no rodapé.","Que a validação no servidor funciona sozinha.","Que os campos não têm o atributo required.","Que o formulário usa GET em vez de POST."],"correta":1,"explicacao":"Sem JavaScript, os erros só podem vir do servidor; por isso a página recarrega. Com o JavaScript ligado, os erros aparecem sem recarregar.","manual":"6.1, 16"},{"id":"seg-047","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"O formulário do livro tem uma lista de autores. Porque é que validar_livro() confirma na base de dados que o autor existe?","codigo":"","linguagem":"","alternativas":["Alguém pode alterar o formulário e enviar um id_autor fora da lista.","Porque a lista de autores pode vir vazia quando o JavaScript está desligado.","Porque o select envia o nome do autor, e não o seu id.","Porque o (int) pode transformar o id do autor num texto."],"correta":0,"explicacao":"O servidor não pode confiar no que o formulário mostrou: o pedido pode trazer id_autor=999. Por isso conta, com uma consulta preparada, se esse autor existe.","manual":"12.4"},{"id":"seg-048","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"O que deve verificar a validação no servidor antes do INSERT ou do UPDATE?","codigo":"","linguagem":"","alternativas":["Só os campos que não têm required no HTML.","Só o formato do email, que o browser não verifica bem.","Só se o utilizador tem a sessão iniciada.","Campos vazios, tamanhos, formatos e valores das listas."],"correta":3,"explicacao":"O servidor tem de verificar tudo de novo, incluindo os campos que já têm required e os valores que vêm de listas. A sessão é assunto do controlo de acesso.","manual":"12.4, 14"},{"id":"seg-049","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Todos os campos deste formulário têm required no HTML. Que medida falta neste código?","codigo":"if ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    $titulo = trim($_POST['titulo'] ?? '');\n    $stmt = $pdo->prepare('INSERT INTO livros (titulo, id_autor) VALUES (?, ?)');\n    $stmt->execute([$titulo, (int) ($_POST['id_autor'] ?? 0)]);\n}","linguagem":"php","alternativas":["As consultas preparadas: os valores deviam ir dentro do texto do prepare().","A validação no servidor: podem chegar campos vazios ou inválidos.","O htmlspecialchars() no título antes de o gravar.","Não falta nada: o required garante os campos preenchidos."],"correta":1,"explicacao":"A consulta está preparada, mas nada verifica se o título vem vazio ou se o autor existe. O required pode ser contornado.","manual":"14, 12.4"},{"id":"seg-050","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Esconder o link \"Livros\" do menu a quem não tem sessão é controlo de acesso?","codigo":"","linguagem":"","alternativas":["Sim: sem o link, ninguém consegue chegar à página.","Sim, desde que o link fique escondido também no telemóvel.","Não: qualquer pessoa pode escrever o endereço no browser.","Não, porque o link devia ser escondido com JavaScript."],"correta":2,"explicacao":"Esconder um link ou um botão não protege nada: a página continua a responder a quem a pedir diretamente.","manual":"11.1"},{"id":"seg-051","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O que é, segundo o manual, controlar o acesso?","codigo":"","linguagem":"","alternativas":["O servidor verificar, em cada pedido, a sessão e a permissão.","O browser esconder as páginas restritas com CSS.","O servidor verificar a sessão só no momento do login.","O JavaScript mandar para o login quem não tem sessão."],"correta":0,"explicacao":"A verificação tem de ser no servidor e repetida em cada pedido, porque cada pedido HTTP é independente. CSS e JavaScript correm no browser e podem ser contornados.","manual":"11.1, 14"},{"id":"seg-052","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Para que serve esta linha do login, logo depois de a password ser confirmada?","codigo":"session_regenerate_id(true);","linguagem":"php","alternativas":["Apaga a mensagem de sucesso guardada na sessão anterior.","Permite ao utilizador manter dois logins abertos ao mesmo tempo, em dois browsers.","Cifra o cookie da sessão com a password do utilizador.","Muda o identificador da sessão, para um fixado antes do login não servir."],"correta":3,"explicacao":"Protege contra o ataque em que alguém fixa o identificador de sessão antes do login e o reutiliza depois. É uma das boas práticas da secção 14.2.","manual":"10.4, 14.2"},{"id":"seg-053","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Para que serve este bloco no início da livro_apagar.php?","codigo":"if ($_SERVER['REQUEST_METHOD'] !== 'POST') {\n    header('Location: livros.php');\n    exit;\n}","linguagem":"php","alternativas":["Impede que quem não tem sessão consiga apagar livros.","Garante que um GET, como um link, nunca apaga nada.","Evita que o F5 apague o mesmo livro duas vezes.","Mostra a confirmação antes de o livro ser apagado."],"correta":1,"explicacao":"Apagar altera dados, por isso só se aceita POST; um pedido GET volta para a lista sem apagar nada. Quem trata da sessão é o auth.php, incluído antes deste bloco.","manual":"12.6, 14.2"},{"id":"seg-054","bloco":"dados","tema":"Segurança","dificuldade":"dificil","pergunta":"Este login funciona. Que problema de segurança tem?","codigo":"if (!$utilizador) {\n    $erros[] = 'Esse email não está registado.';\n} elseif (!password_verify($password, $utilizador['password_hash'])) {\n    $erros[] = 'A password está errada.';\n}","linguagem":"php","alternativas":["Mostra a password em claro na mensagem de erro.","Permite a injeção de SQL pelo campo do email.","Guarda a password errada na sessão do utilizador.","Permite descobrir que emails têm conta na aplicação."],"correta":3,"explicacao":"As duas mensagens dizem a um atacante se o email existe. A boa prática é uma só mensagem para os dois casos: \"Email ou password errados.\"","manual":"10.4, 14.2"},{"id":"seg-055","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Que problema tem este botão para apagar?","codigo":"<a href=\"livro_apagar.php?id=3\">Apagar</a>","linguagem":"html","alternativas":["Um link não consegue enviar o id do livro ao servidor.","Falta o atributo method=\"delete\" no link para o servidor saber o que fazer.","Um GET não deve alterar dados: um robô pode seguir o link.","O id devia ir no texto do link e não no href."],"correta":2,"explicacao":"Basta um robô de pesquisa ou uma pré-visualização seguir o link para o livro desaparecer. Na Biblioteca, apagar é um formulário POST, com confirmação antes.","manual":"1.2, 14.2"},{"id":"seg-056","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Que duas boas práticas mostra este formulário?","codigo":"<form method=\"post\" action=\"livro_apagar.php\"\n      onsubmit=\"return confirm('Apagar este livro?');\">\n    <input type=\"hidden\" name=\"id_livro\" value=\"7\">\n    <button type=\"submit\">Apagar</button>\n</form>","linguagem":"html","alternativas":["POST para alterar dados e confirmação antes de apagar.","POST para cifrar o id e validação do id no browser.","Campo escondido para proteger o id e confirmação no servidor.","GET para apagar e confirmação feita pelo JavaScript."],"correta":0,"explicacao":"Tudo o que altera dados vai por POST, e o confirm() pede confirmação antes de enviar. O campo hidden não esconde nada de quem vê o código-fonte, e o POST não cifra o id.","manual":"14.2, 6.4"},{"id":"seg-057","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Porque é que as credenciais da base de dados ficam só no config/db.php?","codigo":"$host = 'localhost';\n$bd   = 'biblioteca';\n$user = 'root';\n$pass = '';","linguagem":"php","alternativas":["Porque o browser lê o db.php para se ligar ao MySQL.","Porque o new PDO() só funciona num ficheiro chamado db.php.","Ficam fora das páginas e, se mudarem, muda-se só um ficheiro.","Para o utilizador as poder ver no código-fonte se precisar."],"correta":2,"explicacao":"Ter as credenciais num só ficheiro, incluído pelas páginas, é uma das boas práticas da secção 14.2. O browser nunca fala com a base de dados nem recebe o PHP.","manual":"8.1, 14.2"},{"id":"seg-058","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O db.php tem a password do MySQL. Um utilizador vê-a com \"Ver código-fonte da página\"?","codigo":"","linguagem":"","alternativas":["Sim, se o db.php for incluído com require.","Não: o browser só recebe o HTML que o PHP produziu.","Sim, porque o PHP segue para o browser com o HTML.","Não, porque o XAMPP cifra o ficheiro db.php."],"correta":1,"explicacao":"O PHP corre no servidor; ao browser só chega o resultado. É por isso que o PHP pode ter a password da base de dados sem que o utilizador a veja.","manual":"1.1"},{"id":"seg-059","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"O id_livro vem de um campo hidden que o próprio site escreveu. Porque é convertido com (int) na mesma?","codigo":"$stmt = $pdo->prepare('DELETE FROM livros WHERE id_livro = ?');\n$stmt->execute([(int) ($_POST['id_livro'] ?? 0)]);","linguagem":"php","alternativas":["Porque o pedido pode ser alterado e trazer outra coisa que não um número.","Porque o campo hidden envia sempre o valor cifrado.","Porque o execute() só aceita valores do tipo inteiro.","Porque sem (int) o valor era juntado ao texto do SQL."],"correta":0,"explicacao":"Quem faz o pedido pode mudar qualquer campo, incluindo os escondidos. Converter os ids com (int) antes de os usar é uma das boas práticas da secção 14.2; a proteção contra a injeção continua a ser o ?.","manual":"12.6, 14.2"},{"id":"seg-060","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"O manual lista estas boas práticas, que já estão no código da Biblioteca. Qual das opções NÃO é uma delas?","codigo":"14.2 Outras boas práticas que já estão no código\n\n- Um novo identificador de sessão no login.\n- A mesma mensagem para email inexistente e para password errada.\n- POST para tudo o que altera dados, e confirmação antes de apagar.\n- As credenciais num só ficheiro (config/db.php), fora das páginas.\n- Os ids convertidos em inteiros com (int) antes de serem usados.","linguagem":"tabela","alternativas":["Um novo identificador de sessão no login.","Os ids convertidos em inteiros com (int).","As credenciais num só ficheiro, fora das páginas.","Um limite de tentativas de login."],"correta":3,"explicacao":"O limite de tentativas é uma das coisas que, segundo o manual, ficariam a faltar numa aplicação real. As outras três estão na lista da secção 14.2.","manual":"14.2, 14.3"},{"id":"seg-061","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Numa aplicação publicada na internet, para que seria preciso o HTTPS?","codigo":"","linguagem":"","alternativas":["Para guardar as passwords com hash na base de dados.","Para que as passwords não viajem em claro pela rede.","Para impedir a injeção de SQL nos formulários.","Para esconder o código PHP de quem vê o código-fonte."],"correta":1,"explicacao":"Sem HTTPS, o que o formulário envia, incluindo a password, viaja tal como foi escrito. O hash protege a password guardada, não a que viaja.","manual":"14.3"},{"id":"seg-062","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"Para que serviriam os tokens CSRF nos formulários?","codigo":"","linguagem":"","alternativas":["Impedir que um script corra no browser de outro utilizador.","Impedir que o formulário seja reenviado ao carregar em F5 depois de gravar.","Impedir que uma plica num campo altere o SQL.","Impedir que outro site envie formulários em nome do utilizador."],"correta":3,"explicacao":"É o que diz a secção 14.3. As outras opções descrevem o XSS, o problema que o Post/Redirect/Get resolve e a injeção de SQL.","manual":"14.3"},{"id":"seg-063","bloco":"dados","tema":"Segurança","dificuldade":"media","pergunta":"Qual destas medidas, que faltariam numa aplicação real, trava quem experimenta muitas passwords seguidas na mesma conta?","codigo":"","linguagem":"","alternativas":["Um limite de tentativas de login.","Tokens CSRF nos formulários.","O HTTPS em todas as páginas.","A mesma mensagem para email e password errados."],"correta":0,"explicacao":"Limitar as tentativas impede que se adivinhe a password à força de tentar. A mensagem igual só esconde que emails existem, e já está na Biblioteca.","manual":"14.3"},{"id":"seg-064","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"O HTTPS, os tokens CSRF e o limite de tentativas são obrigatórios no projeto?","codigo":"","linguagem":"","alternativas":["Sim: fazem parte das seis medidas obrigatórias.","Só o HTTPS, porque a aplicação guarda passwords dos utilizadores.","Não: segundo o manual, só faltariam numa aplicação real.","Só os tokens CSRF, porque há formulários POST."],"correta":2,"explicacao":"A secção 14.3 diz que não é obrigatório no projeto, mas que é bom saber que existe. As obrigatórias são as seis medidas.","manual":"14.3"},{"id":"seg-065","bloco":"dados","tema":"Segurança","dificuldade":"facil","pergunta":"No projeto, a password só tem de ter 8 caracteres. Segundo o manual, o que exigiria uma aplicação real?","codigo":"","linguagem":"","alternativas":["Que a password fosse guardada com md5().","Uma política de passwords mais exigente.","Que a regra dos 8 caracteres fosse só no browser.","Que a password ficasse guardada na sessão."],"correta":1,"explicacao":"A política de passwords mais exigente é uma das quatro coisas da secção 14.3, com o HTTPS, os tokens CSRF e o limite de tentativas.","manual":"14.3"},{"id":"amostra-008","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"No formulário de registo, qual é a forma correta de pedir o consentimento?","codigo":"","linguagem":"","alternativas":["Uma caixa já marcada, para o utilizador não se esquecer.","Uma frase \"Ao criares conta, aceitas a política\", sem caixa.","Uma caixa desmarcada, verificada só no JavaScript.","Uma caixa desmarcada, com link para a política, verificada também no servidor."],"correta":3,"explicacao":"Uma caixa já marcada não é consentimento. Tem de estar desmarcada, ter link para a política e ser verificada no servidor (o JavaScript pode ser desligado). A data fica em consentimento_em.","manual":"15.2"},{"id":"rgpd-001","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"A que aplicações se aplica o RGPD?","codigo":"","linguagem":"","alternativas":["Só às aplicações publicadas na internet e abertas a qualquer pessoa.","Só às empresas com muitos clientes registados.","Só às aplicações que guardam dados bancários.","A qualquer aplicação que guarde dados de pessoas, mesmo de formação."],"correta":3,"explicacao":"O RGPD aplica-se a qualquer aplicação que guarde dados de pessoas, incluindo um projeto de formação como a Biblioteca.","manual":"15"},{"id":"rgpd-002","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"O que diz o princípio da minimização?","codigo":"","linguagem":"","alternativas":["Os dados guardam-se no menor número de tabelas possível, para ocupar menos espaço.","As colunas usam sempre o tipo de dados mais pequeno.","Recolhe-se tudo, mas só se mostra o necessário.","Só se recolhem os dados necessários para a finalidade declarada."],"correta":3,"explicacao":"Minimização é não recolher nenhum dado \"porque sim\": cada dado tem de ter uma finalidade. Não tem nada a ver com o tamanho das tabelas ou das colunas.","manual":"15.1"},{"id":"rgpd-003","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Um colega quer pedir no registo a data de nascimento e o telefone, \"para o caso de virem a ser úteis\". O que lhe dizes?","codigo":"","linguagem":"","alternativas":["Sim, desde que sejam campos opcionais.","Não: se não sabes para que serve, não recolhes.","Sim, desde que fiquem numa tabela à parte.","Sim, desde que sejam validados também no servidor."],"correta":1,"explicacao":"Pelo princípio da minimização, só se recolhe o que tem uma finalidade declarada. Ser opcional ou estar noutra tabela não muda isso.","manual":"15.1"},{"id":"rgpd-004","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Antes de acrescentar uma coluna com um dado pessoal, que perguntas tens de saber responder?","codigo":"","linguagem":"","alternativas":["Que tipo de dados usar e quantos caracteres pode ter.","Para que serve o dado e quanto tempo fica guardado.","Se a coluna fica NULL ou NOT NULL na tabela.","Em que página aparece e com que classe CSS."],"correta":1,"explicacao":"Cada dado pessoal tem de ter uma finalidade e um prazo de conservação: é o que vai para a tabela da secção 6.2 do dossier.","manual":"15.1"},{"id":"rgpd-005","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"No dossier, a secção 6.2 tem uma linha por cada dado pessoal que a aplicação guarda. Além do próprio dado, o que se indica em cada linha?","codigo":"","linguagem":"","alternativas":["A finalidade e o prazo de conservação.","O tipo de dados e o tamanho da coluna.","O ficheiro PHP onde o dado é lido e gravado.","Se é chave primária ou estrangeira."],"correta":0,"explicacao":"A tabela tem três colunas: o dado, para que serve e quanto tempo fica guardado. Tipos e chaves são da base de dados, não do RGPD.","manual":"15.1"},{"id":"rgpd-006","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Na Biblioteca, o utilizador pode apagar a conta e, com ela, os seus dados. Que prazo de conservação faz sentido declarar para o email?","codigo":"","linguagem":"","alternativas":["Até a conta ser apagada.","Até um ano depois do último login.","Até ao fim de cada sessão.","Para sempre, por ser a chave do login."],"correta":0,"explicacao":"Nome, email e hash da password ficam até a conta ser apagada. Quando o utilizador a apaga em \"A minha conta\", os dados desaparecem.","manual":"15.1"},{"id":"rgpd-007","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"No login.php, o utilizador é procurado assim. Que finalidade declara a Biblioteca para o email?","codigo":"// 1. Procurar o utilizador pelo email\n$stmt = $pdo->prepare('SELECT id_utilizador, nome, password_hash FROM utilizadores WHERE email = ?');\n$stmt->execute([$email]);\n$utilizador = $stmt->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["Iniciar sessão.","Enviar novidades da biblioteca.","Identificar o autor de cada livro.","Confirmar a idade do utilizador."],"correta":0,"explicacao":"O email serve para iniciar sessão. Usá-lo para outra coisa, como enviar novidades, seria uma finalidade nova que teria de ser declarada.","manual":"15.1"},{"id":"rgpd-008","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Para que serve guardar a data do consentimento?","codigo":"","linguagem":"","alternativas":["Para provar que o utilizador aceitou a política.","Para saber quando a sessão expira.","Para contar há quanto tempo o utilizador não entra.","Para ordenar os utilizadores por antiguidade."],"correta":0,"explicacao":"A data em consentimento_em é a prova de que o utilizador aceitou a política de privacidade, e quando o fez.","manual":"15.1, 15.2"},{"id":"rgpd-009","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Porque é que a página \"A minha conta\" não mostra a password?","codigo":"<p>Estes são todos os dados pessoais que a aplicação guarda sobre ti:</p>\n<dl>\n    <dt>Nome</dt>            <dd><?= htmlspecialchars($eu['nome']) ?></dd>\n    <dt>Email</dt>           <dd><?= htmlspecialchars($eu['email']) ?></dd>\n    <dt>Conta criada em</dt> <dd><?= $eu['criado_em'] ?></dd>\n    <dt>Consentimento</dt>   <dd>Aceitaste a política em <?= $eu['consentimento_em'] ?></dd>\n</dl>","linguagem":"php","alternativas":["A password não é guardada: só o seu hash.","É escondida por segurança, com asteriscos.","Só o administrador a pode consultar.","Só aparece depois de a confirmares de novo."],"correta":0,"explicacao":"A aplicação não tem a password para mostrar: guarda apenas o hash, e a partir do hash não se chega à password. A própria página explica isso ao utilizador.","manual":"15.4, 10.1"},{"id":"rgpd-010","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"A tabela de dados pessoais da Biblioteca (manual, 15.1) tem este formato. Como fica descrita a linha da password (dado — para que serve — observação)?","codigo":"6.2 Dados pessoais que a aplicação guarda\n\nDado            | Para que serve           | Quanto tempo fica guardado\n----------------+--------------------------+---------------------------\nNome            | Identificar o utilizador | Até a conta ser apagada\n                | na aplicação             |\n(…)","linguagem":"tabela","alternativas":["Hash da password — autenticação — a password em si nunca é guardada.","Password — autenticação — guardada cifrada para a poder recuperar.","Password — autenticação — guardada em claro até ao primeiro login.","Hash da password — não entra na tabela, por não ser um dado pessoal do utilizador."],"correta":0,"explicacao":"O dado guardado é o hash, com a finalidade de autenticação e o prazo \"até a conta ser apagada\". A password nunca é guardada nem pode ser recuperada.","manual":"15.1"},{"id":"rgpd-011","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Uma caixa de consentimento que já vem assinalada é válida?","codigo":"","linguagem":"","alternativas":["Sim, desde que o utilizador a possa desmarcar depois.","Sim, desde que tenha um link para a política.","Não: o utilizador tem de a assinalar ele próprio.","Não, porque o consentimento tem de ser um botão."],"correta":2,"explicacao":"O consentimento pede-se com uma caixa desmarcada por omissão. Uma caixa já assinalada não é consentimento.","manual":"15.2"},{"id":"rgpd-012","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Qual é o problema deste excerto do formulário de registo?","codigo":"<label class=\"check\" for=\"consentimento\">\n    <input type=\"checkbox\" id=\"consentimento\"\n           name=\"consentimento\" checked>\n    <span>Li e aceito a <a href=\"privacidade.php\"\n          target=\"_blank\">política de privacidade</a>.</span>\n</label>","linguagem":"html","alternativas":["O link da política devia abrir no mesmo separador.","A caixa vem já assinalada por causa do checked.","Falta o atributo value com o texto \"sim\".","A caixa devia ser type=\"radio\" e não checkbox."],"correta":1,"explicacao":"O atributo checked faz a caixa aparecer assinalada, e isso não é consentimento: o utilizador tem de a assinalar ele próprio. O link noutro separador está certo.","manual":"15.2, 4.2"},{"id":"rgpd-013","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"No registo, porque é que o link para a política tem target=\"_blank\"?","codigo":"<span>Li e aceito a <a href=\"privacidade.php\" target=\"_blank\">política\n      de privacidade</a>.</span>","linguagem":"html","alternativas":["Para a política não ficar no histórico do browser.","Para o servidor ficar a saber que o utilizador a leu.","Para a política só abrir depois de criada a conta.","Para abrir noutro separador sem perder o formulário."],"correta":3,"explicacao":"A política abre noutro separador, para o utilizador a poder ler antes de aceitar sem perder o que já escreveu no registo.","manual":"15.2"},{"id":"rgpd-014","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"A caixa do consentimento já tem required. Porque é que o registo.php faz também esta verificação?","codigo":"if (!isset($_POST['consentimento'])) {\n    $erros[] = 'Tens de aceitar a política de privacidade.';\n}","linguagem":"php","alternativas":["O required não funciona em caixas de verificação.","Sem isto, a coluna consentimento_em ficava a NULL na base de dados.","O required e o JavaScript podem ser desligados ou contornados.","O isset() é que faz aparecer a caixa no browser."],"correta":2,"explicacao":"O consentimento tem de ser verificado no servidor, não só no browser. Quem desligar o JavaScript ou enviar o pedido diretamente passa por cima do required.","manual":"15.2, 10.2"},{"id":"rgpd-015","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Onde fica guardado o momento em que o utilizador deu o consentimento?","codigo":"","linguagem":"","alternativas":["Na sessão, em $_SESSION['consentimento'].","Na coluna consentimento_em da tabela utilizadores.","Num cookie guardado no browser do utilizador.","No ficheiro privacidade.php, numa lista de quem aceitou."],"correta":1,"explicacao":"A data fica na base de dados, em consentimento_em, junto da conta. A sessão e os cookies desaparecem; a prova tem de ficar guardada.","manual":"15.2"},{"id":"rgpd-016","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Que valor fica em consentimento_em quando este registo é gravado?","codigo":"$stmt = $pdo->prepare(\n    'INSERT INTO utilizadores (nome, email, password_hash, consentimento_em)\n     VALUES (?, ?, ?, NOW())'\n);\n$stmt->execute([$nome, $email, $hash]);","linguagem":"php","alternativas":["NULL, porque não está no execute().","A data em que a política foi aberta no outro separador.","A data e a hora do momento do registo.","A data e a hora do último login."],"correta":2,"explicacao":"NOW() é escrito no próprio SQL e dá a data e a hora do momento em que o INSERT corre. Só os três ? recebem valores do execute().","manual":"10.2, 15.2"},{"id":"rgpd-017","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Na tabela utilizadores, porque é que consentimento_em é NOT NULL?","codigo":"CREATE TABLE utilizadores (\n    id_utilizador    INT AUTO_INCREMENT PRIMARY KEY,\n    nome             VARCHAR(100) NOT NULL,\n    email            VARCHAR(150) NOT NULL UNIQUE,\n    password_hash    VARCHAR(255) NOT NULL,\n    consentimento_em DATETIME     NOT NULL,\n    criado_em        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP\n);","linguagem":"sql","alternativas":["Para o MySQL a preencher sozinho com a data e a hora atuais.","Para impedir dois registos com a mesma data.","Para a data ser atualizada em cada login.","Não pode haver conta sem o consentimento registado."],"correta":3,"explicacao":"NOT NULL torna a coluna obrigatória: não se cria nenhuma conta sem a data do consentimento. Quem preenche a data sozinho é o DEFAULT CURRENT_TIMESTAMP, e só o criado_em o tem.","manual":"3.4, 15.2"},{"id":"rgpd-018","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Como se testa a medida \"consentimento no registo\"?","codigo":"","linguagem":"","alternativas":["Registar sem assinalar a caixa, com o JavaScript desligado.","Procurar a caixa do consentimento no rodapé de todas as páginas.","Ver no phpMyAdmin se a coluna começa por $2.","Abrir o registo numa janela anónima do browser."],"correta":0,"explicacao":"Com o JavaScript desligado, só o servidor pode recusar. Se o registo for aceite sem a caixa assinalada, a verificação no servidor falta.","manual":"14, 16"},{"id":"rgpd-019","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Que campo se usa no registo para pedir o consentimento?","codigo":"","linguagem":"","alternativas":["<input type=\"radio\">","<input type=\"hidden\">","<input type=\"checkbox\" checked>","<input type=\"checkbox\">"],"correta":3,"explicacao":"O consentimento é uma caixa de verificação (checkbox), desmarcada por omissão. Com checked já vinha assinalada, e isso não é consentimento.","manual":"4.2, 15.2"},{"id":"rgpd-020","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"O que tem de dizer a política de privacidade?","codigo":"","linguagem":"","alternativas":["Que tabelas existem, que tipos de dados usam e que chaves estrangeiras as ligam entre si.","Quem fez o projeto, em que linguagem foi escrito e como se instala o XAMPP.","Que medidas de segurança existem, que hash se usa e onde fica o servidor.","Que dados se recolhem, para quê, com que base legal, por quanto tempo e que direitos há."],"correta":3,"explicacao":"A política explica ao utilizador o que acontece aos seus dados: quais, para quê, com que base legal, durante quanto tempo e que direitos tem.","manual":"15.3"},{"id":"rgpd-021","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Como deve estar escrita a política de privacidade?","codigo":"","linguagem":"","alternativas":["Em linguagem simples, que o utilizador perceba.","Em linguagem jurídica, com os artigos do RGPD.","Em inglês, por ser um regulamento europeu.","Em linguagem técnica, com os nomes das tabelas e das colunas."],"correta":0,"explicacao":"A política é para o utilizador: tem de dizer, em linguagem simples, o que se faz com os seus dados.","manual":"15.3"},{"id":"rgpd-022","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Onde tem de estar o link para a política de privacidade?","codigo":"","linguagem":"","alternativas":["Só no formulário de registo.","No rodapé de todas as páginas e no registo.","Só no menu do cabeçalho, para quem tem sessão iniciada.","Só na página \"A minha conta\"."],"correta":1,"explicacao":"A política tem de estar acessível em todas as páginas, com e sem sessão, pelo link do rodapé, e também no registo, junto da caixa do consentimento.","manual":"15.3, 14"},{"id":"rgpd-023","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Porque é que pôr o link neste ficheiro chega para a política estar em todas as páginas?","codigo":"</main>\n<footer class=\"rodape\">\n    Biblioteca · Projeto UC00615 ·\n    <a href=\"privacidade.php\">Política de privacidade</a>\n</footer>\n<script src=\"js/validacao.js\"></script>\n</body>\n</html>","linguagem":"html","alternativas":["O validacao.js copia o link para as outras páginas.","O browser guarda o link e mostra-o nas páginas seguintes.","Todas as páginas incluem este rodapé, com ou sem sessão.","O link abre a política noutro separador do browser."],"correta":2,"explicacao":"O rodape.php é incluído no fim de todas as páginas. Escrito uma vez, o link aparece em toda a aplicação, tenha o utilizador sessão ou não.","manual":"9.2, 14"},{"id":"rgpd-024","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Se o link da política estivesse só aqui, no menu do cabeçalho, qual era o problema?","codigo":"<?php if (isset($_SESSION['id_utilizador'])): ?>\n    <a href=\"livros.php\">Livros</a>\n    <a href=\"privacidade.php\">Privacidade</a>\n<?php else: ?>\n    <a href=\"login.php\">Entrar</a>\n    <a href=\"registo.php\">Criar conta</a>\n<?php endif; ?>","linguagem":"php","alternativas":["O link não aparecia a quem ainda não tem sessão.","O link aparecia duas vezes nas páginas restritas.","A política deixava de abrir noutro separador.","O link deixava de aparecer a quem tem sessão."],"correta":0,"explicacao":"O link está dentro do if da sessão, por isso só quem entrou o vê. A política tem de estar acessível em todas as páginas, com e sem sessão, até antes do registo.","manual":"14, 16"},{"id":"rgpd-025","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"A página privacidade.php deve incluir o auth.php, como as páginas restritas?","codigo":"","linguagem":"","alternativas":["Sim: só quem tem conta precisa de a ler.","Não: tem de abrir com e sem sessão, até antes do registo.","Sim: mostra os dados pessoais de quem a abre.","Não, mas só deve abrir a partir do link do formulário de registo."],"correta":1,"explicacao":"Quem se vai registar tem de poder ler a política antes de aceitar. Por isso o link está em todas as páginas e a página não pode pedir login.","manual":"15.3, 14"},{"id":"rgpd-026","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"A página \"A minha conta\" mostra todos os dados guardados sobre o utilizador. Que direito cumpre?","codigo":"","linguagem":"","alternativas":["O direito ao apagamento.","O direito de acesso.","O direito de retificação.","O direito à portabilidade."],"correta":1,"explicacao":"Mostrar ao utilizador os dados que se guardam sobre ele é o direito de acesso. O botão para apagar a conta cumpre o direito ao apagamento.","manual":"15.4"},{"id":"rgpd-027","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Para cumprir o direito de acesso, o que deve mostrar a página \"A minha conta\"?","codigo":"","linguagem":"","alternativas":["Só o nome e o email, por segurança.","Os dados de todos os utilizadores registados.","Todos os dados pessoais guardados sobre o utilizador.","Os livros e os autores que o utilizador criou na aplicação."],"correta":2,"explicacao":"O direito de acesso é o utilizador ver tudo o que a aplicação guarda sobre ele, e só sobre ele.","manual":"15.4"},{"id":"rgpd-028","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Porque é que a consulta da página \"A minha conta\" usa o id da sessão e não um ?id= no endereço?","codigo":"$stmt = $pdo->prepare('SELECT nome, email, consentimento_em, criado_em\n                       FROM utilizadores WHERE id_utilizador = ?');\n$stmt->execute([$_SESSION['id_utilizador']]);\n$eu = $stmt->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["O $_GET não pode ser usado em consultas com prepare() e execute().","Com ?id= qualquer pessoa podia ver os dados de outra conta.","O id que vem no endereço chega sempre como 0.","A sessão é lida mais depressa do que o endereço."],"correta":1,"explicacao":"O id da sessão foi posto pelo servidor no login e o utilizador não o pode alterar. Um id no endereço podia ser trocado à mão para ver os dados de outra pessoa.","manual":"15.4, 10.3"},{"id":"rgpd-029","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Porque é que a página \"A minha conta\" começa assim?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/auth.php';","linguagem":"php","alternativas":["O RGPD obriga todas as páginas a pedir login.","O auth.php é que mostra os dados ao utilizador.","Mostra e apaga dados de quem tem sessão: tem de ser restrita.","Sem o auth.php a página não carrega a folha de estilos do site."],"correta":2,"explicacao":"A página trabalha sobre os dados de quem iniciou sessão. Sem o auth.php, qualquer visitante podia chegar a ela.","manual":"15.4, 11.2"},{"id":"rgpd-030","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Porque é que \"A minha conta\" também mostra a data do consentimento?","codigo":"<p>Estes são todos os dados pessoais que a aplicação guarda sobre ti:</p>\n<dl>\n    <dt>Nome</dt>            <dd><?= htmlspecialchars($eu['nome']) ?></dd>\n    <dt>Email</dt>           <dd><?= htmlspecialchars($eu['email']) ?></dd>\n    <dt>Conta criada em</dt> <dd><?= $eu['criado_em'] ?></dd>\n    <dt>Consentimento</dt>   <dd>Aceitaste a política em <?= $eu['consentimento_em'] ?></dd>\n</dl>","linguagem":"php","alternativas":["Para o utilizador poder alterar a data, se quiser.","Também é um dado pessoal guardado, e o acesso mostra todos.","Porque é a data em que a sessão vai expirar.","Porque a política obriga a renovar o consentimento todos os anos."],"correta":1,"explicacao":"O direito de acesso cobre todos os dados guardados sobre o utilizador, e a data do consentimento é um deles. A página mostra tudo, exceto a password, que não é guardada.","manual":"15.4, 15.1"},{"id":"rgpd-031","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"O utilizador pede para apagar a conta. O que tem de acontecer?","codigo":"","linguagem":"","alternativas":["Os seus dados pessoais são eliminados e ele é informado.","A conta fica desativada, mas os dados mantêm-se.","Os dados são apagados só ao fim de um ano.","Apaga-se o hash da password, mas o nome e o email ficam guardados."],"correta":0,"explicacao":"É o direito ao apagamento: os dados pessoais são eliminados e o utilizador recebe uma mensagem a dizer que foram apagados.","manual":"15.4"},{"id":"rgpd-032","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"O botão \"Apagar a minha conta\" está num formulário. Que método usa, e porquê?","codigo":"","linguagem":"","alternativas":["GET, porque é só um botão.","GET, para se poder partilhar.","POST, porque o GET não aceita botões.","POST, porque altera dados."],"correta":3,"explicacao":"Apagar a conta altera a base de dados, por isso é um formulário POST. Um GET nunca deve alterar dados.","manual":"15.4, 1.2"},{"id":"rgpd-033","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Depois do DELETE, para que servem as duas linhas a seguir?","codigo":"$stmt = $pdo->prepare('DELETE FROM utilizadores WHERE id_utilizador = ?');\n$stmt->execute([$_SESSION['id_utilizador']]);\n\n$_SESSION = [];\nsession_destroy();","linguagem":"php","alternativas":["Para apagar a linha do utilizador na tabela.","Para o browser apagar o histórico de pedidos.","Para impedir que se crie uma nova conta com o mesmo email.","Para quem apagou a conta deixar de ter sessão iniciada."],"correta":3,"explicacao":"O DELETE apaga os dados na base de dados. A sessão é outra coisa: tem de ser esvaziada e destruída, senão o utilizador continuava \"dentro\" de uma conta que já não existe.","manual":"15.4, 10.5"},{"id":"rgpd-034","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"Nesta versão do apagar conta, o id vem do formulário. Qual é o problema?","codigo":"// conta.php (versão alterada)\n$stmt = $pdo->prepare('DELETE FROM utilizadores WHERE id_utilizador = ?');\n$stmt->execute([$_POST['id_utilizador']]);","linguagem":"php","alternativas":["O DELETE devia ser pedido com um link GET e não com um formulário POST.","Mudando o id enviado, podia apagar-se a conta de outra pessoa.","Falta o WHERE, por isso apagava todas as contas.","O $_POST não pode ser usado dentro do execute()."],"correta":1,"explicacao":"O utilizador controla tudo o que o formulário envia. A conta a apagar tem de ser a de quem tem sessão, por isso usa-se $_SESSION['id_utilizador'].","manual":"15.4"},{"id":"rgpd-035","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Como se testa o direito ao apagamento antes de entregar?","codigo":"","linguagem":"","alternativas":["Fazer logout e abrir \"A minha conta\" sem sessão.","Apagar a própria conta e tentar entrar outra vez.","Apagar um livro e confirmar a mensagem de sucesso.","Apagar a linha da conta no phpMyAdmin."],"correta":1,"explicacao":"O teste 22 é apagar a própria conta na aplicação e tentar entrar de novo: a conta já não existe.","manual":"16"},{"id":"rgpd-036","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"A Maria apagou a conta e tenta entrar com o mesmo email e password. Que mensagem vê?","codigo":"// login.php\nif ($utilizador && password_verify($password, $utilizador['password_hash'])) {\n    // guardar o utilizador na sessão\n    header('Location: livros.php');\n    exit;\n}\n// Mensagem igual nos dois casos: não se revela se o email existe\n$erros[] = 'Email ou password errados.';","linguagem":"php","alternativas":["\"A tua conta foi apagada.\"","\"Já existe uma conta com esse email.\"","\"Email ou password errados.\"","\"Tens de iniciar sessão para ver essa página.\""],"correta":2,"explicacao":"A linha da Maria já não existe, por isso o login não a encontra e mostra a mensagem de sempre. A aplicação não guarda nada sobre contas apagadas.","manual":"10.4, 16"},{"id":"rgpd-037","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Porque é que conta.php chama session_start() logo a seguir ao session_destroy()?","codigo":"$_SESSION = [];\nsession_destroy();\nsession_start();\nmensagem('sucesso', 'A tua conta e os teus dados pessoais foram apagados.');\nheader('Location: index.php');\nexit;","linguagem":"php","alternativas":["Para o utilizador continuar com sessão iniciada.","Porque o session_destroy() fecha o PHP.","Para voltar a criar a conta que foi apagada.","Para levar a mensagem até à página seguinte."],"correta":3,"explicacao":"A sessão nova está vazia e serve só para levar a mensagem até ao index.php. É assim que o utilizador é informado de que os dados foram apagados.","manual":"15.4, 10.5"},{"id":"rgpd-038","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Para que serve o confirm() no formulário de apagar a conta?","codigo":"<form method=\"post\" action=\"conta.php\"\n      onsubmit=\"return confirm('Apagar a conta? Esta ação não pode ser desfeita.');\">\n    <button type=\"submit\" class=\"perigo\">Apagar a minha conta</button>\n</form>","linguagem":"html","alternativas":["Verificar no servidor se a conta ainda existe.","Mostrar os dados antes de os apagar.","Pedir confirmação, porque a ação não se pode desfazer.","Substituir a verificação da sessão que é feita no servidor."],"correta":2,"explicacao":"O confirm() corre no browser e evita apagar a conta por engano. Não é segurança: o servidor continua a usar o id da sessão.","manual":"15.4"},{"id":"rgpd-039","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"A tabela 6.2 do dossier tem este formato (em baixo, uma linha de exemplo). Uma clínica veterinária guarda o telefone dos tutores dos animais, que não têm conta. Esses dados entram na tabela?","codigo":"6.2 Dados pessoais que a aplicação guarda\n\nDado            | Para que serve           | Quanto tempo fica guardado\n----------------+--------------------------+---------------------------\nNome e email    | Identificar quem usa a   | Até a conta ser apagada\ndo utilizador   | aplicação e fazer login  |\n(…)","linguagem":"tabela","alternativas":["Não, porque os tutores não têm conta.","Não, porque um telefone não é dado pessoal.","Sim, com a sua finalidade e o seu prazo.","Só se os tutores fizerem login."],"correta":2,"explicacao":"Os dados de outras pessoas guardados pela aplicação também contam: entram na tabela da secção 6.2, com finalidade e prazo de conservação.","manual":"15.4"},{"id":"rgpd-040","bloco":"dados","tema":"RGPD","dificuldade":"dificil","pergunta":"A tabela 6.2 do dossier tem este formato (em baixo, uma linha de exemplo). Numa loja com clientes e encomendas, qual destas linhas (dado — para que serve — quanto tempo fica guardado) está bem preenchida?","codigo":"6.2 Dados pessoais que a aplicação guarda\n\nDado            | Para que serve           | Quanto tempo fica guardado\n----------------+--------------------------+---------------------------\nNome e telefone | Contactar o dono do      | Enquanto for cliente;\ndo tutor        | animal                   | apagado a pedido\n(…)","linguagem":"tabela","alternativas":["Morada do cliente — pode vir a ser útil — para sempre","Data de nascimento — sem finalidade definida — até a conta ser apagada","Morada do cliente — enviar as encomendas — até a conta ser apagada","Telefone do cliente — enviar as encomendas — VARCHAR(20)"],"correta":2,"explicacao":"Cada dado precisa de uma finalidade concreta e de um prazo. \"Pode vir a ser útil\" não é finalidade, e VARCHAR(20) é um tipo de dados, não um prazo.","manual":"15.1"},{"id":"rgpd-041","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"A tabela utilizadores da Biblioteca é esta. Que dados pessoais tem a Biblioteca de declarar na tabela 6.2?","codigo":"CREATE TABLE utilizadores (\n    id_utilizador    INT AUTO_INCREMENT PRIMARY KEY,\n    nome             VARCHAR(100) NOT NULL,\n    email            VARCHAR(150) NOT NULL UNIQUE,\n    password_hash    VARCHAR(255) NOT NULL,\n    consentimento_em DATETIME     NOT NULL,\n    criado_em        DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP\n);","linguagem":"sql","alternativas":["Nome e email: o hash e a data são técnicos e não contam.","Nome, email, password e livros criados.","Só o email, que é o que identifica a pessoa.","Nome, email, hash da password e data do consentimento."],"correta":3,"explicacao":"A tabela da Biblioteca tem quatro dados, cada um com finalidade e prazo. A password não é guardada, só o hash, e os livros não são dados pessoais.","manual":"15.1"},{"id":"rgpd-042","bloco":"dados","tema":"RGPD","dificuldade":"media","pergunta":"Um colega diz que o nome é dispensável, porque o login usa o email. Vendo onde a Biblioteca usa o nome (em baixo), que finalidade declara para ele?","codigo":"// login.php, depois de confirmar a password\n$_SESSION['nome'] = $utilizador['nome'];\n\n// includes/cabecalho.php, no menu\n<span class=\"ola\">Olá, <?= htmlspecialchars($_SESSION['nome']) ?></span>","linguagem":"php","alternativas":["Iniciar sessão quando o email falha.","Provar que aceitou a política.","Identificar o utilizador na aplicação.","Recuperar a password, se o utilizador a esquecer."],"correta":2,"explicacao":"Na tabela da Biblioteca, o nome serve para identificar o utilizador na aplicação (por exemplo, o \"Olá\" no menu). O email é que serve para iniciar sessão.","manual":"15.1"},{"id":"rgpd-043","bloco":"dados","tema":"RGPD","dificuldade":"facil","pergunta":"Destas seis medidas de segurança do dossier, quais são as do RGPD?","codigo":"As seis medidas de segurança do dossier\n\n1. Passwords com hash\n2. Consultas preparadas\n3. Validação no servidor\n4. Controlo de acesso\n5. Consentimento no registo\n6. Política de privacidade acessível","linguagem":"tabela","alternativas":["Consentimento no registo e política de privacidade acessível.","Passwords com hash e consultas preparadas.","Controlo de acesso e validação no servidor.","Consultas preparadas e política de privacidade acessível a todos."],"correta":0,"explicacao":"O consentimento no registo e a política de privacidade acessível são as duas medidas ligadas ao RGPD. As outras quatro protegem contra ataques e dados inválidos.","manual":"14"},{"id":"amostra-009","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que mostra este código?","codigo":"<?php\n$titulo = 'Os Maias';\necho 'Livro: $titulo';","linguagem":"php","alternativas":["Livro: Os Maias","Livro: $titulo","Livro: ","Dá erro, porque falta o ponto para juntar os textos."],"correta":1,"explicacao":"Com aspas simples, o texto é literal e a variável não é substituída. Com aspas duplas (\"Livro: $titulo\"), apareceria Livro: Os Maias.","manual":"7.2"},{"id":"php-001","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Onde é executado o código PHP de uma página da Biblioteca?","codigo":"","linguagem":"","alternativas":["No browser, depois de a página ser descarregada do servidor.","No servidor (Apache), que envia ao browser o HTML gerado.","No MySQL, juntamente com as consultas SQL.","Parte no servidor e parte no browser, conforme o código."],"correta":1,"explicacao":"O Apache entrega o ficheiro ao interpretador de PHP, que corre no servidor e gera HTML. O browser só recebe esse HTML.","manual":"1.1, 1.4"},{"id":"php-002","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Sabendo que $nome vale 'Maria', o que aparece no código-fonte da página (Ver código-fonte) no lugar desta linha?","codigo":"<h1>Olá, <?= $nome ?>!</h1>","linguagem":"php","alternativas":["<h1>Olá, <?= $nome ?>!</h1>","<h1>Olá, $nome!</h1>","<h1>Olá, !</h1>","<h1>Olá, Maria!</h1>"],"correta":3,"explicacao":"O PHP corre no servidor e substitui o bloco pelo valor. O browser nunca vê o <?= ... ?>, só o HTML que resultou.","manual":"2.4"},{"id":"php-004","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"No ola.php, $hora = date('H:i'). Porque é que a hora mostrada muda quando carregas em F5?","codigo":"","linguagem":"","alternativas":["Porque o PHP corre de novo no servidor a cada pedido.","Porque o browser atualiza a variável $hora sozinho.","Porque o JavaScript da página recalcula a hora.","Porque a hora fica na sessão e é somada a cada pedido."],"correta":0,"explicacao":"Cada F5 é um pedido novo: o servidor executa o ficheiro outra vez e gera HTML novo com a hora desse momento.","manual":"2.4"},{"id":"php-005","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"O config/db.php tem a password da base de dados. Porque é que o utilizador não a consegue ver?","codigo":"","linguagem":"","alternativas":["O Apache cifra automaticamente todas as variáveis com $.","O browser só recebe o HTML que o PHP produz, nunca o código.","O browser esconde as linhas de código que começam por $.","Os ficheiros da pasta config não podem ser pedidos por endereço."],"correta":1,"explicacao":"O código PHP fica no servidor; ao browser só chega o resultado. É por isso que as credenciais podem estar no db.php.","manual":"1.1"},{"id":"php-006","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Num ficheiro .php, o que acontece ao texto que está fora de <?php ... ?>?","codigo":"","linguagem":"","alternativas":["É ignorado e não chega ao browser.","Dá erro de sintaxe, porque não é PHP.","É executado como PHP na mesma.","É enviado para o browser tal como está."],"correta":3,"explicacao":"Um .php pode misturar HTML e PHP: só o que está entre <?php e ?> é executado; o resto segue tal e qual para o browser.","manual":"7.1"},{"id":"php-007","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que é enviado ao browser por este ficheiro?","codigo":"<p>Início</p>\n<?php\n$nome = 'Sophia';\n// echo 'Olá';\n?>\n<p><?= $nome ?></p>","linguagem":"php","alternativas":["<p>Início</p>, Olá e <p>Sophia</p>","<p>Início</p> e <p>Sophia</p>","Só <p>Sophia</p>","<p>Início</p> e <p>$nome</p>"],"correta":1,"explicacao":"O HTML fora do bloco vai tal e qual, a linha com // é um comentário e não corre, e o <?= $nome ?> é substituído por Sophia.","manual":"7.1"},{"id":"php-008","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Como começa um bloco de código PHP?","codigo":"","linguagem":"","alternativas":["<php>","<?php","<script type=\"php\">","<!--php"],"correta":1,"explicacao":"O código PHP fica entre <?php e ?>. As outras formas não são reconhecidas pelo interpretador.","manual":"7.1, Anexo B"},{"id":"php-009","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"<?= $titulo ?> é um atalho para qual destas formas?","codigo":"","linguagem":"","alternativas":["<?php return $titulo; ?>","<?php $titulo = ''; ?>","<?php echo $titulo; ?>","<?php isset($titulo); ?>"],"correta":2,"explicacao":"O <?= ... ?> escreve um valor no meio do HTML: é o mesmo que um echo dentro de um bloco PHP.","manual":"7.1"},{"id":"php-010","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Qual destas linhas NÃO escreve o título na página?","codigo":"","linguagem":"","alternativas":["<h1><?= $titulo ?></h1>","<h1><?php $titulo; ?></h1>","<h1><?php echo $titulo; ?></h1>","<h1><?php echo \"$titulo\"; ?></h1>"],"correta":1,"explicacao":"Escrever só a variável não a envia para a página: falta o echo. O <?= faz o echo sozinho, e as aspas duplas substituem a variável.","manual":"7.1"},{"id":"php-011","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Numa linha da lista, $livro['id_livro'] vale 7. Que endereço fica no href que chega ao browser?","codigo":"<a href=\"livro_ver.php?id=<?= $livro['id_livro'] ?>\">Ver detalhe →</a>","linguagem":"php","alternativas":["livro_ver.php?id=<?= $livro['id_livro'] ?>","livro_ver.php?id=$livro['id_livro']","livro_ver.php?id=7","livro_ver.php?id="],"correta":2,"explicacao":"O PHP corre antes de a página sair do servidor e o <?= ... ?> é trocado pelo valor. O browser recebe um link normal.","manual":"7.1, 12.2"},{"id":"php-012","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Sabendo que $_SESSION['msg']['tipo'] vale 'sucesso', como fica o atributo class no HTML enviado?","codigo":"<div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\">","linguagem":"php","alternativas":["class=\"msg\"","class=\"msg tipo\"","class=\"sucesso\"","class=\"msg sucesso\""],"correta":3,"explicacao":"O valor é escrito dentro do atributo, a seguir a \"msg \". É assim que o tipo da mensagem passa a ser uma classe CSS (verde ou vermelho).","manual":"7.1, 9.3"},{"id":"php-013","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Em PHP, que instrução escreve texto na página?","codigo":"","linguagem":"","alternativas":["write('Olá');","document.write('Olá');","echo 'Olá';","console.log('Olá');"],"correta":2,"explicacao":"echo escreve na página que vai para o browser. document.write e console.log são de JavaScript, que corre no browser.","manual":"7.1, Anexo B"},{"id":"php-014","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Este código dá \"Parse error: syntax error\". Qual é a causa?","codigo":"<?php\n$titulo = 'Os Maias'\n$ano = 1888;\necho $titulo;","linguagem":"php","alternativas":["As variáveis têm de ser declaradas com var.","O texto tem de estar entre aspas duplas.","Falta o ; no fim da linha 2.","Falta o ?> no fim do ficheiro."],"correta":2,"explicacao":"Cada instrução termina com ;. Quando o erro aparece numa linha, convém ver também a anterior: é lá que costuma faltar o ;.","manual":"7.1, 17.1"},{"id":"php-015","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que faz esta linha num bloco PHP?","codigo":"// echo $titulo;","linguagem":"php","alternativas":["Escreve o título dentro de um comentário HTML.","Escreve o texto \"echo $titulo;\" na página.","Nada: é um comentário e não é executada.","Dá erro, porque em PHP os comentários usam <!-- -->."],"correta":2,"explicacao":"O // começa um comentário de uma linha: serve para quem lê o código e não é executado.","manual":"7.1"},{"id":"php-016","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"O que vê o utilizador quando o PHP executa esta linha?","codigo":"echo '<h1>Livro não encontrado</h1>';","linguagem":"php","alternativas":["O texto <h1>Livro não encontrado</h1>, com as etiquetas visíveis.","Nada, porque o echo não pode escrever HTML.","Um título h1 com o texto \"Livro não encontrado\".","Um erro, porque o HTML tem de estar fora do bloco PHP."],"correta":2,"explicacao":"O echo envia o texto para a resposta e o browser interpreta-o como HTML. É assim que a livro_ver.php mostra a mensagem de livro não encontrado.","manual":"7.1, 12.3"},{"id":"php-017","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Porque é que o config/db.php começa por <?php mas não termina com ?>?","codigo":"","linguagem":"","alternativas":["Porque o ?> só pode aparecer em ficheiros que tenham HTML.","Porque o PDO fecha o bloco PHP automaticamente no fim.","Para um espaço depois do ?> não ir para o browser.","Para o ficheiro não poder ser aberto diretamente no browser."],"correta":2,"explicacao":"Num ficheiro só com PHP, um espaço ou linha em branco depois do ?> seria enviado ao browser, e a partir daí o header() já não funciona.","manual":"7.1"},{"id":"php-018","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Ao gravar um livro aparece \"Cannot modify header information - headers already sent\". O config/db.php acaba assim, com uma linha em branco no fim. Qual é a solução indicada no manual?","codigo":"$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);\n?>\n\n","linguagem":"php","alternativas":["Tirar o ?> do fim, porque o ficheiro só tem PHP.","Trocar o require do db.php por include.","Pôr o header() depois do require do cabeçalho.","Escrever exit; antes do ?> do db.php."],"correta":0,"explicacao":"A linha em branco depois do ?> é enviada ao browser antes do header(). Sem o ?> no fim de um ficheiro só PHP, isso não pode acontecer.","manual":"7.1, 17.1"},{"id":"php-019","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Qual destes ficheiros, por ter só código PHP, não deve fechar com ?> no fim?","codigo":"","linguagem":"","alternativas":["includes/cabecalho.php, que é o topo HTML da página.","includes/auth.php, que só verifica a sessão.","includes/rodape.php, que fecha o HTML da página.","includes/livro_form.php, que tem o formulário."],"correta":1,"explicacao":"O auth.php não tem HTML nenhum, tal como o db.php e o inicio.php. Os outros misturam HTML com PHP e usam ?> para voltar ao HTML.","manual":"7.1, 11.2"},{"id":"php-020","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Como começa o nome de uma variável em PHP?","codigo":"","linguagem":"","alternativas":["Por @, como em @titulo.","Pela palavra var, como em var titulo.","Por #, como em #titulo.","Por $, como em $titulo."],"correta":3,"explicacao":"Em PHP todas as variáveis começam por $: $titulo, $erros, $pdo, $_POST...","manual":"7.2, Anexo B"},{"id":"php-021","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Que tipo de valor fica em $ativo depois de $ativo = true; ?","codigo":"","linguagem":"","alternativas":["string (texto)","int (número inteiro)","boolean (verdadeiro ou falso)","null (sem valor)"],"correta":2,"explicacao":"true e false são os dois valores do tipo boolean. Sem aspas, true não é texto.","manual":"7.2"},{"id":"php-022","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"O que guarda $isbn depois de $isbn = null; ?","codigo":"","linguagem":"","alternativas":["O texto 'null', com quatro letras.","O número 0.","Um texto vazio, igual a ''.","Nada: null é \"sem valor\"."],"correta":3,"explicacao":"null é o valor especial \"sem valor\". Na base de dados corresponde ao NULL, que a Biblioteca usa nos campos opcionais vazios.","manual":"7.2"},{"id":"php-023","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Abres livro_ver.php?id=3. Que valor tem $_GET['id']?","codigo":"","linguagem":"","alternativas":["O número inteiro 3.","O valor true.","O texto 'id=3'.","O texto '3'."],"correta":3,"explicacao":"Tudo o que vem do endereço ou de um formulário chega como texto. Por isso a Biblioteca faz (int) quando precisa de um número.","manual":"7.5"},{"id":"php-024","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Qual é a diferença entre aspas simples e aspas duplas num texto PHP?","codigo":"","linguagem":"","alternativas":["Nas simples as variáveis são substituídas; nas duplas o texto é literal.","Nenhuma: as duas substituem as variáveis da mesma forma.","As duplas servem só para escrever HTML e as simples só para escrever SQL.","Nas duplas as variáveis são substituídas; nas simples o texto é literal."],"correta":3,"explicacao":"echo \"Livro: $titulo\" mostra o valor; echo 'Livro: $titulo' mostra $titulo tal e qual.","manual":"7.2"},{"id":"php-025","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"O que mostra este código?","codigo":"<?php\n$autor = 'Eça de Queirós';\necho \"Autor: $autor\";","linguagem":"php","alternativas":["Autor: $autor","Autor: ","Autor: Eça de Queirós","Autor: autor"],"correta":2,"explicacao":"Com aspas duplas, o PHP substitui $autor pelo seu valor. Com aspas simples apareceria $autor literalmente.","manual":"7.2"},{"id":"php-026","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"A livro_novo.php redireciona assim, com $novoId a valer 12. Se a linha fosse escrita com aspas simples, para onde ia o browser?","codigo":"header(\"Location: livro_ver.php?id=$novoId\");\nexit;","linguagem":"php","alternativas":["Para livro_ver.php?id=12, exatamente igual.","Para livro_ver.php?id= sem nenhum número.","Para lado nenhum: o header() só aceita aspas simples.","Para livro_ver.php?id=$novoId, escrito tal e qual."],"correta":3,"explicacao":"Nas aspas simples o texto é literal, por isso o $novoId não seria substituído. Esta linha precisa de aspas duplas (ou de concatenação).","manual":"7.2, 12.4"},{"id":"php-027","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Qual destas linhas produz exatamente o mesmo texto que esta?","codigo":"$msg = \"O ano tem de estar entre 1450 e $anoAtual.\";","linguagem":"php","alternativas":["$msg = 'O ano tem de estar entre 1450 e $anoAtual.';","$msg = 'O ano tem de estar entre 1450 e ' . $anoAtual . '.';","$msg = 'O ano tem de estar entre 1450 e ' + $anoAtual + '.';","$msg = \"O ano tem de estar entre 1450 e \" $anoAtual \".\";"],"correta":1,"explicacao":"Com aspas simples o valor tem de ser juntado com o ponto. O + não junta textos e duas partes lado a lado sem operador dão erro.","manual":"7.2, 12.4"},{"id":"php-028","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Porque é que este echo usa aspas simples por fora?","codigo":"echo '<a href=\"livros.php\">Voltar à lista</a>';","linguagem":"php","alternativas":["Porque o echo só aceita textos com aspas simples por fora.","Para o link abrir num separador novo.","Porque as aspas duplas tornariam o link inseguro.","Para as aspas duplas do href não fecharem o texto."],"correta":3,"explicacao":"O texto tem aspas duplas lá dentro (no atributo href). Delimitá-lo com aspas simples evita que essas aspas terminem o texto antes do tempo.","manual":"7.2, 12.3"},{"id":"php-029","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Que operador junta dois textos em PHP?","codigo":"","linguagem":"","alternativas":["O ponto: 'Olá, ' . $nome","O mais: 'Olá, ' + $nome","O e comercial: 'Olá, ' & $nome","A função concat('Olá, ', $nome)"],"correta":0,"explicacao":"Em PHP a concatenação faz-se com o ponto. O + é só para somar números (em JavaScript é que o + junta textos).","manual":"7.2"},{"id":"php-030","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Na pesquisa, $q vale 'mar'. Que valor fica em $padrao?","codigo":"$padrao = '%' . $q . '%';","linguagem":"php","alternativas":["%$q%","%mar%","%q%","mar"],"correta":1,"explicacao":"O ponto junta os três pedaços: o %, o valor de $q e outro %. É este texto que vai para o LIKE ?.","manual":"7.2, 12.2"},{"id":"php-031","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"No login, o nome do utilizador é Maria. Que texto fica guardado na mensagem?","codigo":"mensagem('sucesso', 'Sessão iniciada. Bem-vindo, ' . $utilizador['nome'] . '!');","linguagem":"php","alternativas":["Sessão iniciada. Bem-vindo, $utilizador['nome']!","Sessão iniciada. Bem-vindo, . Maria . !","Sessão iniciada. Bem-vindo, nome!","Sessão iniciada. Bem-vindo, Maria!"],"correta":3,"explicacao":"O ponto junta o texto fixo, o valor de $utilizador['nome'] e o ponto de exclamação. Os pontos do operador não fazem parte do resultado.","manual":"7.2, 10.4"},{"id":"php-032","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"O que acontece com esta linha?","codigo":"echo 'Os ' + 'Maias';","linguagem":"php","alternativas":["Mostra Os Maias, como em JavaScript.","Mostra OsMaias, sem o espaço.","Dá erro: o + não junta textos.","Mostra Os + Maias."],"correta":2,"explicacao":"Em PHP o + é só aritmético. Para juntar textos usa-se o ponto: 'Os ' . 'Maias'.","manual":"7.2"},{"id":"php-033","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que mostra este código?","codigo":"$ano = 1888;\necho 'Edição de ' . $ano;","linguagem":"php","alternativas":["Edição de $ano","Edição de 1888","Dá erro: não se junta texto com número.","1888"],"correta":1,"explicacao":"O ponto junta o texto com o número, que é convertido em texto. A variável não está dentro das aspas, por isso é o valor que aparece.","manual":"7.2"},{"id":"php-034","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que faz a instrução $erros[] = 'O título é obrigatório.'; ?","codigo":"","linguagem":"","alternativas":["Substitui o array inteiro por esse texto.","Cria uma variável nova chamada erros[].","Apaga o último elemento do array $erros.","Acrescenta esse texto no fim do array $erros."],"correta":3,"explicacao":"Os [] vazios acrescentam um elemento no fim. É assim que a validação junta todos os erros numa lista.","manual":"7.2"},{"id":"php-035","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"O que mostra este código?","codigo":"$erros = [];\n$erros[] = 'O título é obrigatório.';\n$erros[] = 'Escolhe um autor da lista.';\necho count($erros);","linguagem":"php","alternativas":["1","2","0","Escolhe um autor da lista."],"correta":1,"explicacao":"O array começa vazio e recebe dois elementos. count() devolve quantos elementos tem.","manual":"7.2, 7.4"},{"id":"php-036","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que mostra este código?","codigo":"$erros = [];\n$erros[] = 'O nome é obrigatório.';\n$erros[] = 'O email não é válido.';\necho $erros[1];","linguagem":"php","alternativas":["O email não é válido.","O nome é obrigatório.","Nada, porque a posição 1 não existe.","2"],"correta":0,"explicacao":"Num array indexado as posições começam em 0: o primeiro erro está em $erros[0] e o segundo em $erros[1].","manual":"7.2"},{"id":"php-037","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que devolve count($erros)?","codigo":"","linguagem":"","alternativas":["Quantos elementos tem o array.","O último elemento do array.","O maior valor do array.","A posição do primeiro elemento."],"correta":0,"explicacao":"count() conta os elementos de um array. Com um array vazio dá 0.","manual":"7.4"},{"id":"php-038","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Porque é que o registo.php começa com $erros = []; antes de validar?","codigo":"","linguagem":"","alternativas":["Para apagar as mensagens guardadas na sessão.","Para começar com uma lista de erros vazia.","Para desligar a validação no browser.","Para criar uma tabela de erros na base de dados."],"correta":1,"explicacao":"Cada validação que falha faz $erros[] = ...; no fim, se o array continuar vazio, não houve erros. Começar com [] garante também que a variável existe.","manual":"7.2, 10.2"},{"id":"php-039","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Com $livro = ['titulo' => 'Os Maias', 'ano_edicao' => 1888];, como obténs o 1888?","codigo":"","linguagem":"","alternativas":["$livro[1888]","$livro.ano_edicao","$livro['ano_edicao']","$livro('ano_edicao')"],"correta":2,"explicacao":"Num array associativo cada valor tem uma chave e lê-se com o nome da chave entre parênteses retos.","manual":"7.2"},{"id":"php-040","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Com fetch(PDO::FETCH_ASSOC), em que forma chega ao PHP uma linha da tabela livros?","codigo":"","linguagem":"","alternativas":["Um texto com os valores separados por vírgulas.","Um array indexado, só com as posições 0, 1, 2...","Uma variável separada para cada coluna ($titulo, $isbn...).","Um array associativo, com o nome de cada coluna como chave."],"correta":3,"explicacao":"Por isso se escreve $livro['titulo'] ou $livro['id_livro']: a chave é o nome da coluna (ou o alias do AS).","manual":"7.2, 8.2"},{"id":"php-041","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que mostra este código?","codigo":"$livro = ['titulo' => 'Os Maias', 'ano_edicao' => 1888];\necho count($livro);","linguagem":"php","alternativas":["4","1","1888","2"],"correta":3,"explicacao":"O array tem dois elementos (dois pares chave => valor). count() conta os elementos, não as chaves e os valores em separado.","manual":"7.2, 7.4"},{"id":"php-042","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Depois de mensagem('erro', 'Esse livro não existe.');, que valor tem $_SESSION['msg']['texto']?","codigo":"function mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}","linguagem":"php","alternativas":["erro","Esse livro não existe.","texto","A palavra msg"],"correta":1,"explicacao":"$_SESSION['msg'] é um array associativo com duas chaves. A chave 'texto' recebe o segundo argumento da função.","manual":"7.2, 7.4"},{"id":"php-043","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que mostra este código?","codigo":"$livros = [\n    ['titulo' => 'Os Maias'],\n    ['titulo' => 'O Primo Basílio'],\n];\necho $livros[1]['titulo'];","linguagem":"php","alternativas":["Os Maias","O Primo Basílio","titulo","Dá erro: não se usam dois [] seguidos."],"correta":1,"explicacao":"É um array de linhas, como o que o fetchAll() devolve. [1] escolhe a segunda linha e ['titulo'] a coluna dessa linha.","manual":"7.2, 8.2"},{"id":"php-044","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Que valor fica em $erros depois deste código?","codigo":"$ano = 1300;\n$erros = [];\nif ($ano < 1450) {\n    $erros[] = 'Ano inválido.';\n} elseif ($ano > 2026) {\n    $erros[] = 'O ano está no futuro.';\n} else {\n    echo 'Ano aceite.';\n}","linguagem":"php","alternativas":["['Ano inválido.']","['Ano inválido.', 'O ano está no futuro.']","[] e aparece \"Ano aceite.\"","['O ano está no futuro.']"],"correta":0,"explicacao":"1300 < 1450, por isso entra no primeiro bloco. Quando uma condição é verdadeira, o elseif e o else já não são testados.","manual":"7.3"},{"id":"php-045","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Para que serve o elseif?","codigo":"","linguagem":"","alternativas":["Repetir o bloco enquanto a condição for verdadeira.","Executar sempre um bloco no fim do if.","Testar outra condição quando a anterior foi falsa.","Testar a mesma condição uma segunda vez."],"correta":2,"explicacao":"if / elseif / else escolhe um só caminho: o elseif só é avaliado se o if anterior for falso.","manual":"7.3"},{"id":"php-046","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Em que caso esta condição acrescenta o erro?","codigo":"if ($nome === '' || mb_strlen($nome) > 100) {\n    $erros[] = 'O nome é obrigatório e não pode ter mais de 100 caracteres.';\n}","linguagem":"php","alternativas":["Só quando o nome está vazio e tem mais de 100 caracteres.","Quando o nome está vazio ou tem mais de 100 caracteres.","Quando o nome tem 100 caracteres ou menos.","Só quando o campo nome não veio no pedido."],"correta":1,"explicacao":"O || quer dizer \"ou\": basta uma das duas condições ser verdadeira para o erro ser acrescentado.","manual":"7.3, 10.2"},{"id":"php-047","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que faz foreach ($livros as $livro) { ... }?","codigo":"","linguagem":"","alternativas":["Conta quantos elementos tem o array $livros.","Corre o bloco uma vez por elemento.","Procura no array o livro com um certo título.","Repete o bloco enquanto $livro for verdadeiro."],"correta":1,"explicacao":"O foreach corre o bloco uma vez por elemento. É assim que a lista mostra todas as linhas que vieram da base de dados.","manual":"7.3"},{"id":"php-048","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que mostra este código?","codigo":"$autores = ['Saramago', 'Sophia', 'Eça'];\nforeach ($autores as $autor) {\n    echo $autor . ';';\n}","linguagem":"php","alternativas":["Saramago;Sophia;Eça","Saramago;Sophia;Eça;","Eça;","Saramago;"],"correta":1,"explicacao":"O bloco corre três vezes, uma por elemento, e cada vez escreve o nome seguido de ;. Também há ; depois do último.","manual":"7.3"},{"id":"php-049","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Sabendo que $erros tem três mensagens, o que gera este excerto?","codigo":"<ul>\n<?php foreach ($erros as $erro): ?>\n    <li><?= htmlspecialchars($erro) ?></li>\n<?php endforeach; ?>\n</ul>","linguagem":"php","alternativas":["Uma lista com três <li>, um por erro.","Uma lista com um só <li> com os três erros.","Uma lista vazia, porque falta o echo.","Três listas <ul>, cada uma com um <li>."],"correta":0,"explicacao":"Só o que está entre o foreach e o endforeach se repete: o <li> aparece uma vez por erro. O <?= já faz o echo.","manual":"7.3, 9.4"},{"id":"php-050","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Dentro de foreach ($livros as $livro), como se escreve o título do livro da volta atual?","codigo":"","linguagem":"","alternativas":["<?= htmlspecialchars($livro['titulo']) ?>","<?= htmlspecialchars($livros['titulo']) ?>","<?= htmlspecialchars($titulo) ?>","<?= htmlspecialchars($livros->titulo) ?>"],"correta":0,"explicacao":"Em cada volta, $livro é uma linha (array associativo). $livros é a lista inteira e não tem a chave 'titulo'.","manual":"7.3"},{"id":"php-051","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Na sintaxe com dois pontos, if (...): ... , como se fecha o if?","codigo":"","linguagem":"","alternativas":["<?php end if; ?>","<?php endif; ?>","<?php fi; ?>","<?php close; ?>"],"correta":1,"explicacao":"A sintaxe alternativa usa : no início e endif; (ou endforeach;) no fim, em vez das chavetas.","manual":"7.3"},{"id":"php-052","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Porque é que a Biblioteca usa if (...): ... endif; no meio do HTML?","codigo":"","linguagem":"","alternativas":["É igual às chavetas, mas lê-se melhor no HTML.","Porque as chavetas dão erro quando há HTML no meio.","Porque é executada mais depressa do que as chavetas.","Porque só esta forma permite usar o else."],"correta":0,"explicacao":"As duas formas são equivalentes. Com HTML pelo meio, um endif; ou endforeach; diz logo o que está a fechar, o que uma } sozinha não diz.","manual":"7.3"},{"id":"php-053","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"A pesquisa não encontrou nada: $livros é um array vazio. O que aparece nesta parte da página?","codigo":"<?php if (count($livros) === 0): ?>\n    <p class=\"vazio\">Não foi encontrado nenhum livro.</p>\n<?php else: ?>\n    <?php foreach ($livros as $livro): ?>\n        <h2><?= htmlspecialchars($livro['titulo']) ?></h2>\n    <?php endforeach; ?>\n<?php endif; ?>","linguagem":"php","alternativas":["Um <h2> vazio, porque o foreach corre uma vez.","Nada, porque o if e o else se anulam.","Só o parágrafo \"Não foi encontrado nenhum livro.\"","O parágrafo e a seguir um erro do foreach."],"correta":2,"explicacao":"count([]) é 0, por isso entra no if e mostra a mensagem. O else, com o foreach, nem chega a ser executado.","manual":"7.3, 12.2"},{"id":"php-054","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Para um livro com ano_edicao a NULL, o que escreve esta linha depois do nome do autor?","codigo":"<?php if ($livro['ano_edicao']): ?> · <?= $livro['ano_edicao'] ?><?php endif; ?>","linguagem":"php","alternativas":["Só o ponto ·, sem o ano.","· null","Nada: nem o ponto · nem o ano.","· 0"],"correta":2,"explicacao":"NULL conta como falso, por isso tudo o que está entre o if e o endif (incluindo o HTML do ·) é saltado.","manual":"7.3, 12.2"},{"id":"php-055","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Este excerto dá erro de sintaxe. Porquê?","codigo":"<?php foreach ($autores as $autor): ?>\n    <li><?= htmlspecialchars($autor['nome']) ?></li>\n<?php endif; ?>","linguagem":"php","alternativas":["Falta um ; logo a seguir a foreach (...).","Os dois pontos têm de ser trocados por uma chaveta {.","O foreach fecha com endforeach, não endif.","O <li> tem de ficar dentro de um echo."],"correta":2,"explicacao":"Na sintaxe alternativa cada abertura tem o seu fecho: if: ... endif; e foreach: ... endforeach;.","manual":"7.3"},{"id":"php-056","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Qual destas formas cria uma função própria em PHP?","codigo":"","linguagem":"","alternativas":["def mensagem($tipo, $texto): ...","function mensagem($tipo, $texto) { ... }","new function mensagem($tipo, $texto) { ... }","mensagem = function[$tipo, $texto] { ... }"],"correta":1,"explicacao":"Define-se com a palavra function, o nome, os parâmetros entre parênteses e o corpo entre chavetas, como a mensagem() do inicio.php.","manual":"7.4"},{"id":"php-057","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Esta é a função mensagem() do includes/inicio.php, e o bloco do cabeçalho que a mostra. O que faz a função?","codigo":"// includes/inicio.php\nfunction mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}\n\n// includes/cabecalho.php (logo a seguir ao <main>)\n<?php if (isset($_SESSION['msg'])): ?>\n    <div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\">\n        <?= htmlspecialchars($_SESSION['msg']['texto']) ?>\n    </div>\n    <?php unset($_SESSION['msg']); // mostra-se uma vez e apaga-se ?>\n<?php endif; ?>","linguagem":"php","alternativas":["Escreve logo a mensagem na página com echo.","Guarda-a na sessão para a página seguinte.","Grava a mensagem numa tabela da base de dados.","Mostra a mensagem num alert() do browser."],"correta":1,"explicacao":"A função só guarda o tipo e o texto em $_SESSION['msg']. Depois do redirecionamento, o cabeçalho mostra-a e apaga-a.","manual":"7.4, 9.3"},{"id":"php-058","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Para que serve o return $erros; no fim de validar_livro()?","codigo":"","linguagem":"","alternativas":["Volta à página anterior, como o botão Voltar.","Termina a página inteira, como o exit.","Escreve a lista de erros na página.","Devolve a lista de erros a quem chamou a função."],"correta":3,"explicacao":"O return entrega um valor a quem chamou: em $erros = validar_livro($pdo, $livro); o array devolvido fica em $erros.","manual":"7.4, 12.4"},{"id":"php-059","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que mostra este código?","codigo":"function resumo($erros)\n{\n    return count($erros) . ' erro(s)';\n}\necho resumo(['O título é obrigatório.', 'O email não é válido.']);","linguagem":"php","alternativas":["count($erros) erro(s)","1 erro(s)","2 erro(s)","Nada, porque a função não tem echo."],"correta":2,"explicacao":"A função devolve o texto \"2 erro(s)\" e é o echo de fora que o escreve. O return entrega o valor, não o mostra.","manual":"7.4"},{"id":"php-060","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Alguém escreveu mensagem('Livro criado.', 'sucesso');. Que valor fica em $_SESSION['msg']['texto']?","codigo":"function mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}","linguagem":"php","alternativas":["Livro criado.","sucesso","Livro criado. sucesso","Fica vazio, porque os argumentos estão trocados."],"correta":1,"explicacao":"Os argumentos passam pela ordem: o primeiro vai para $tipo e o segundo para $texto. Os nomes não contam, só a posição.","manual":"7.4"},{"id":"php-061","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que faz trim() a um texto como '  Os Maias  '?","codigo":"","linguagem":"","alternativas":["Tira todos os espaços, também os do meio.","Passa o texto para minúsculas.","Corta o texto aos 100 caracteres.","Tira os espaços do início e do fim."],"correta":3,"explicacao":"trim('  Os Maias  ') dá 'Os Maias': o espaço do meio fica. Assim, um campo só com espaços passa a '' e é apanhado como vazio.","manual":"7.4"},{"id":"php-062","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Porque é que a validação do nome usa mb_strlen() e não strlen()?","codigo":"","linguagem":"","alternativas":["Porque mb_strlen() tira os espaços antes de contar.","Porque strlen() só funciona com números.","Porque mb_strlen() conta bem as letras acentuadas.","Porque mb_strlen() conta palavras e não letras."],"correta":2,"explicacao":"As duas dão o comprimento de um texto, mas só a versão mb_ conta bem os acentos (ç, ã, é). strlen() dá um valor maior com acentos.","manual":"7.4"},{"id":"php-063","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"No registo, o utilizador não assinalou a caixa do consentimento. O que acontece nesta verificação?","codigo":"if (!isset($_POST['consentimento'])) {\n    $erros[] = 'Tens de aceitar a política de privacidade.';\n}","linguagem":"php","alternativas":["isset() dá true, porque o campo existe no formulário, e passa.","Não vem no pedido: isset() dá false e junta o erro.","Aparece o aviso \"Undefined array key\" e a página para.","O campo chega com o valor 'off' e a verificação passa."],"correta":1,"explicacao":"Uma caixa de seleção desmarcada não é enviada. isset() verifica se a chave existe, sem dar aviso quando não existe.","manual":"7.4, 7.5, 10.2"},{"id":"php-065","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"A validação do ISBN usa esta expressão regular. Qual destes valores é aceite?","codigo":"preg_match('/^[0-9]{10}([0-9]{3})?$/', $isbn)","linguagem":"php","alternativas":["9789722036290","978-972-20-3629-0","978972203629","97897220362901"],"correta":0,"explicacao":"A expressão aceita só algarismos, 10 ou 13 (10 mais 3 opcionais). Os hífenes não são algarismos e 12 ou 14 algarismos não servem.","manual":"7.4, 12.4"},{"id":"php-066","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que devolve date('Y')?","codigo":"","linguagem":"","alternativas":["O ano atual, por exemplo 2026.","A data completa de hoje.","O dia da semana de hoje.","O ano de edição do livro."],"correta":0,"explicacao":"date('Y') dá o ano atual. A Biblioteca usa-o para não aceitar anos de edição no futuro.","manual":"7.4"},{"id":"php-067","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Porque é que a sinopse se mostra com nl2br(htmlspecialchars(...)) e não com htmlspecialchars(nl2br(...))?","codigo":"","linguagem":"","alternativas":["Ao contrário, as mudanças de linha eram apagadas do texto.","Ao contrário, os <br> seriam escapados e apareciam como texto.","É indiferente: a ordem das duas funções não muda nada.","O nl2br() dá erro se o texto não vier já escapado."],"correta":1,"explicacao":"Primeiro escapa-se o texto do utilizador e só depois se acrescentam os <br>. Se fosse ao contrário, os <br> criados seriam escapados e viam-se como texto.","manual":"7.4, 12.3"},{"id":"php-068","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que faz nl2br($texto)?","codigo":"","linguagem":"","alternativas":["Transforma as mudanças de linha em <br>.","Tira todas as mudanças de linha do texto.","Transforma as etiquetas <br> em mudanças de linha.","Divide o texto num array, uma linha por posição."],"correta":0,"explicacao":"No HTML, uma mudança de linha normal não aparece. nl2br() acrescenta um <br> em cada uma, para a sinopse manter os parágrafos.","manual":"7.4"},{"id":"php-069","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Para que serve http_response_code(404) na livro_ver.php, quando o livro não existe?","codigo":"","linguagem":"","alternativas":["Muda o código de estado da resposta para 404.","Redireciona o browser para uma página 404.php.","Termina a página, tal como o exit.","Escreve o número 404 no topo da página."],"correta":0,"explicacao":"A página continua a mostrar a mensagem própria, mas a resposta passa a dizer \"não encontrado\" em vez de 200.","manual":"7.4, 12.3"},{"id":"php-070","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Quando aparece a caixa de erros deste excerto?","codigo":"<?php if (!empty($erros)): ?>\n    <div class=\"msg erro\">...</div>\n<?php endif; ?>","linguagem":"php","alternativas":["Sempre, mesmo quando $erros está vazio.","Só quando $erros tem pelo menos um erro.","Só quando a variável $erros não existe.","Só quando há exatamente um erro."],"correta":1,"explicacao":"empty() é verdadeiro para um array vazio; com o ! a condição só é verdadeira quando há erros.","manual":"7.4, 9.4"},{"id":"php-071","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Porque é que a validação do ano faz $anoAtual = (int) date('Y');?","codigo":"","linguagem":"","alternativas":["Para arredondar o ano para a década mais próxima.","Para tirar o mês e o dia da data devolvida.","Para o ano ficar sempre com quatro algarismos.","Porque date() devolve um texto."],"correta":3,"explicacao":"date() devolve sempre um texto (por exemplo '2026'). O (int) converte-o num número inteiro para as comparações.","manual":"7.4, 12.4"},{"id":"php-072","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Com $erros = [];, que valores dão isset($erros) e empty($erros)?","codigo":"","linguagem":"","alternativas":["isset dá true e empty dá true.","isset dá false e empty dá true.","isset dá true e empty dá false.","isset dá false e empty dá false."],"correta":0,"explicacao":"isset() vê se a variável existe (existe, é um array); empty() vê se está vazia (está, não tem elementos).","manual":"7.4"},{"id":"php-073","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Abres livro_ver.php?id=3. Como lês o 3 no PHP?","codigo":"","linguagem":"","alternativas":["$_GET['id']","$_POST['id']","$_SERVER['id']","$_SESSION['id']"],"correta":0,"explicacao":"Os valores do endereço, depois do ?, ficam em $_GET. Em $_POST só estão os campos de formulários com method=\"post\".","manual":"7.5, Anexo B"},{"id":"php-074","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O pedido é livro_ver.php?id=3. O que mostra este código?","codigo":"if ($_GET['id'] === 3) {\n    echo 'igual';\n} else {\n    echo 'diferente';\n}","linguagem":"php","alternativas":["igual","diferente","Nada, porque falta o (int).","Dá erro: não se compara texto com número."],"correta":1,"explicacao":"$_GET['id'] é o texto '3' e o === compara também o tipo: texto e inteiro nunca são idênticos. É uma das razões para fazer (int).","manual":"7.5"},{"id":"php-075","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Um formulário com method=\"post\" tem o campo <input id=\"campo-titulo\" name=\"titulo\">. Como lês o valor no servidor?","codigo":"","linguagem":"","alternativas":["$_POST['campo-titulo']","$_GET['titulo']","$_POST['input']","$_POST['titulo']"],"correta":3,"explicacao":"A chave em $_POST é o atributo name. O id serve para o <label for>, o CSS e o JavaScript.","manual":"7.5, 4.2"},{"id":"php-076","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Para que serve if ($_SERVER['REQUEST_METHOD'] === 'POST') { ... } numa página com formulário?","codigo":"","linguagem":"","alternativas":["Para verificar se o utilizador tem sessão iniciada.","Para impedir que o formulário seja enviado duas vezes.","Para guardar na base de dados o método do formulário.","Para só ler e gravar o formulário quando ele foi enviado."],"correta":3,"explicacao":"A mesma página serve para mostrar o formulário (GET) e para o receber (POST). O bloco só corre quando há dados enviados.","manual":"7.5, 7.8"},{"id":"php-077","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Abres livro_novo.php a partir de um link. O que acontece?","codigo":"","linguagem":"","alternativas":["O método é POST, o livro é validado e aparecem logo os erros.","O método é GET e o PHP grava um livro vazio.","O método é LINK e o formulário vem já preenchido.","É um GET: salta o bloco do POST e mostra o formulário vazio."],"correta":3,"explicacao":"Seguir um link é sempre um GET. O if do REQUEST_METHOD só é verdadeiro quando o formulário é enviado com method=\"post\".","manual":"7.5, 12.4"},{"id":"php-078","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que significa o !== em if ($_SERVER['REQUEST_METHOD'] !== 'POST')?","codigo":"","linguagem":"","alternativas":["Igual no valor e no tipo.","Atribuir um valor novo.","Menor ou igual.","Diferente (no valor ou no tipo)."],"correta":3,"explicacao":"!== é o contrário de ===: a condição é verdadeira se o método não for 'POST'. Na livro_apagar.php, isso manda o GET de volta para a lista.","manual":"7.5, 12.6"},{"id":"php-079","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Porque é que ler_livro() faz (int) ($_POST['id_autor'] ?? 0)?","codigo":"","linguagem":"","alternativas":["Para cifrar o id do autor antes de o gravar.","Porque a caixa de seleção envia o nome do autor e não o id.","Para o browser não deixar o campo vazio.","Os campos chegam como texto e o (int) dá um inteiro."],"correta":3,"explicacao":"Tudo o que vem do formulário é texto. O (int) garante um inteiro; se o valor faltar ou não for número, fica 0.","manual":"7.5, 12.4"},{"id":"php-080","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que contém $_SESSION?","codigo":"","linguagem":"","alternativas":["Os dados da sessão do utilizador, guardados no servidor.","Os campos do último formulário enviado.","Os cookies do browser, guardados no computador do utilizador.","Os valores do endereço, depois do ?."],"correta":0,"explicacao":"$_SESSION guarda dados entre pedidos (como o id do utilizador). Os campos do formulário estão em $_POST e os do endereço em $_GET.","manual":"7.5, 10.3"},{"id":"php-081","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"A pesquisa é um formulário com method=\"get\" e o campo name=\"q\". Pesquisas \"mar\". Onde vai o texto e como se lê?","codigo":"","linguagem":"","alternativas":["No corpo do pedido, lido com $_POST['q'].","No endereço (?q=mar), lido com $_POST['q'].","No endereço (?q=mar), lido com $_GET['q'].","Na sessão, lido com $_SESSION['q']."],"correta":2,"explicacao":"Com method=\"get\" os campos vão no URL e leem-se em $_GET. Por isso uma pesquisa pode ir para os favoritos.","manual":"7.5, 12.2"},{"id":"php-082","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que faz $_POST['nome'] ?? ''?","codigo":"","linguagem":"","alternativas":["Dá '' se $_POST['nome'] não existir.","Compara $_POST['nome'] com ''.","Apaga o campo nome de $_POST.","Dá erro se o nome vier vazio."],"correta":0,"explicacao":"O ?? dá um valor por omissão quando o da esquerda não existe (ou é null). Assim não aparece o aviso de chave indefinida.","manual":"7.5"},{"id":"php-083","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Um campo não veio no pedido. O que acontece se a linha for escrita sem o ?? ''?","codigo":"$nome = trim($_POST['nome']);","linguagem":"php","alternativas":["$nome fica com o texto 'nome'.","A resposta passa a ter o código 404.","Aparece o aviso Undefined array key \"nome\".","Nada: $_POST['nome'] vale '' por omissão."],"correta":2,"explicacao":"Ler uma chave que não existe dá o aviso \"Undefined array key\". O ?? '' evita-o, dando um texto vazio.","manual":"7.5, 17.1"},{"id":"php-084","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que mostra este código?","codigo":"$isbn = '';\necho $isbn ?? 'sem ISBN';","linguagem":"php","alternativas":["Nada (um texto vazio).","sem ISBN","null","Dá erro, porque $isbn está vazio."],"correta":0,"explicacao":"O ?? só usa o valor da direita quando a variável não existe ou é null. Um texto vazio existe, por isso fica o ''. Para \"vazio\" é que se usa o ?:.","manual":"7.5, 12.4"},{"id":"php-085","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Na página de detalhe, um livro tem o ISBN a NULL. O que aparece nesta linha?","codigo":"<dd><?= htmlspecialchars($livro['isbn'] ?? '—') ?></dd>","linguagem":"php","alternativas":["<dd>—</dd>","<dd>null</dd>","<dd></dd>","<dd>0</dd>"],"correta":0,"explicacao":"O NULL da base de dados chega ao PHP como null, e o ?? substitui-o pelo valor da direita, o travessão.","manual":"7.5, 12.3"},{"id":"php-086","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Alguém abre livro_ver.php?id=abc. Que valor fica em $id?","codigo":"$id = (int) ($_GET['id'] ?? 0);","linguagem":"php","alternativas":["0","'abc'","null","1"],"correta":0,"explicacao":"O (int) converte o texto num inteiro; um texto sem algarismos dá 0, que não é o id de nenhum livro.","manual":"7.5, 12.3"},{"id":"php-087","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"O que faz o (int) em (int) ($_GET['id'] ?? 0)?","codigo":"","linguagem":"","alternativas":["Verifica se é inteiro e dá erro se não for.","Arredonda o valor para cima.","Converte o valor num número inteiro.","Conta os algarismos do valor."],"correta":2,"explicacao":"O (int) não valida nem dá erro: converte. Assim, mesmo um valor estranho passa a ser um inteiro seguro.","manual":"7.5"},{"id":"php-088","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"Alguém abre livro_ver.php sem nada depois do nome (sem ?id=). O que acontece?","codigo":"$id = (int) ($_GET['id'] ?? 0);\n// ... SELECT ... WHERE l.id_livro = ?  com [$id]\nif (!$livro) {\n    http_response_code(404);\n    // ... mostra \"Livro não encontrado\"\n}","linguagem":"php","alternativas":["$id fica 0, nenhum livro tem esse id e a resposta é 404.","Aparece Undefined array key \"id\" e a página para.","$id fica null e é mostrado o primeiro livro da tabela.","O PHP redireciona sozinho para a lista de livros."],"correta":0,"explicacao":"O ?? dá 0 quando o id não vem, e o (int) mantém-no 0. O fetch() devolve false e a página responde 404.","manual":"7.5, 12.3"},{"id":"php-089","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"O ISBN foi deixado em branco, por isso $livro['isbn'] é ''. Que valor vai para o execute()?","codigo":"$livro['isbn'] ?: null","linguagem":"php","alternativas":["''","O texto 'null'","0","null"],"correta":3,"explicacao":"O ?: usa o valor da direita quando o da esquerda é vazio (falso). Assim o campo opcional fica NULL na base de dados.","manual":"7.5, 12.4"},{"id":"php-090","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Porque é que a livro_novo.php grava $livro['sinopse'] ?: null e não só $livro['sinopse']?","codigo":"","linguagem":"","alternativas":["Para os opcionais vazios ficarem NULL na tabela.","Para proteger a consulta contra a injeção de SQL.","Para tornar a sinopse um campo obrigatório.","Para converter a sinopse num número inteiro."],"correta":0,"explicacao":"Um campo opcional em branco chega como ''. Com o ?: passa a null, e na tabela fica NULL (\"sem valor\").","manual":"7.5, 12.4"},{"id":"php-091","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Qual é a diferença entre == e === em PHP?","codigo":"","linguagem":"","alternativas":["== compara o valor e o tipo; === só compara o valor.","== atribui um valor; === compara dois valores.","=== compara o valor e o tipo; == só compara o valor.","=== só serve para textos; == só para números."],"correta":2,"explicacao":"'3' == 3 é verdadeiro, mas '3' === 3 é falso, porque um é texto e o outro inteiro. A atribuição é o = simples.","manual":"7.5"},{"id":"php-092","bloco":"php","tema":"PHP essencial","dificuldade":"media","pergunta":"Quando é executado o bloco que grava o livro?","codigo":"$erros = validar_livro($pdo, $livro);\nif (!$erros) {\n    // INSERT ...\n}","linguagem":"php","alternativas":["Quando $erros está vazio: um array vazio conta como falso.","Quando $erros tem pelo menos uma mensagem de erro lá dentro.","Sempre, porque a variável $erros existe.","Nunca, porque o ! não se aplica a arrays."],"correta":0,"explicacao":"validar_livro() devolve um array vazio quando está tudo certo. Um array vazio é falso, por isso !$erros é verdadeiro e grava.","manual":"7.3, 12.4"},{"id":"php-093","bloco":"php","tema":"PHP essencial","dificuldade":"dificil","pergunta":"O que mostra este código?","codigo":"$erros = [];\n$erros[] = 'O email não é válido.';\nif (!$erros) {\n    echo 'Gravado';\n} else {\n    echo count($erros) . ' erro(s)';\n}","linguagem":"php","alternativas":["Gravado","0 erro(s)","Gravado1 erro(s)","1 erro(s)"],"correta":3,"explicacao":"O array tem um elemento, por isso é verdadeiro e !$erros é falso: corre o else, que mostra a contagem.","manual":"7.3, 7.4"},{"id":"php-094","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Em $stmt->execute([$id]), o que indica a seta ->?","codigo":"","linguagem":"","alternativas":["Atribui o valor da direita à variável $stmt.","Associa uma chave a um valor num array.","Chama o método execute() do objeto $stmt.","Compara se os dois lados são iguais."],"correta":2,"explicacao":"A -> usa-se com objetos como $pdo e $stmt: $pdo->prepare(...), $stmt->fetch(...). O => é que associa chaves a valores.","manual":"8.2"},{"id":"php-095","bloco":"php","tema":"PHP essencial","dificuldade":"facil","pergunta":"Em ['titulo' => 'Os Maias'], o que faz o =>?","codigo":"","linguagem":"","alternativas":["Compara se 'titulo' é maior ou igual ao valor.","Chama um método sobre o texto 'titulo'.","Associa a chave 'titulo' ao valor 'Os Maias'.","Copia o valor de 'titulo' para 'Os Maias'."],"correta":2,"explicacao":"É assim que se escrevem arrays associativos (chave => valor), como a linha de um livro ou a mensagem guardada na sessão.","manual":"7.2"},{"id":"amostra-010","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"Uma página faz a inclusão de includes/rodape.php, mas esse ficheiro não existe. Qual é a diferença entre usar include e require?","codigo":"","linguagem":"","alternativas":["O require dá um erro fatal e para a página; o include dá um aviso e continua.","O include dá um erro fatal e para a página; o require dá um aviso e continua.","Não há diferença: os dois param a página.","O include é mais rápido, por isso mostra a página sem o rodapé."],"correta":0,"explicacao":"A diferença só se vê quando o ficheiro falta: o require para com erro fatal e o include só avisa. A Biblioteca usa sempre require, porque sem esses ficheiros a página não funciona.","manual":"7.6"},{"id":"inc-001","bloco":"php","tema":"include e require","dificuldade":"facil","pergunta":"O que faz require 'includes/cabecalho.php'; numa página?","codigo":"","linguagem":"","alternativas":["Abre o ficheiro numa janela nova do browser, ao lado da página.","Insere ali esse ficheiro, como se lá estivesse escrito.","Redireciona o browser para esse ficheiro, como o header().","Copia o ficheiro para a pasta da página."],"correta":1,"explicacao":"include e require inserem outro ficheiro naquele ponto. O resultado é uma só página, sem pedido nem redirecionamento.","manual":"7.6"},{"id":"inc-002","bloco":"php","tema":"include e require","dificuldade":"facil","pergunta":"Para que usa a Biblioteca include/require?","codigo":"","linguagem":"","alternativas":["Para carregar a folha de estilos no browser.","Para partilhar cabeçalho, rodapé e ligação.","Para redirecionar depois de gravar um formulário.","Para proteger as consultas contra injeção de SQL."],"correta":1,"explicacao":"Escreve-se uma vez (cabeçalho, rodapé, db.php) e todas as páginas reutilizam. O CSS liga-se com <link> e o redirecionamento faz-se com header().","manual":"7.6, 9.2"},{"id":"inc-003","bloco":"php","tema":"include e require","dificuldade":"facil","pergunta":"Em PHP, que instrução reutiliza o ficheiro header.php no topo de todas as páginas?","codigo":"","linguagem":"","alternativas":["header('Location: header.php');","<link rel=\"import\" href=\"header.php\">","echo 'header.php';","include 'header.php';"],"correta":3,"explicacao":"include (ou require) insere o ficheiro do cabeçalho. O header('Location: ...') é outra coisa: manda o browser ir a outra página.","manual":"7.8, Anexo B"},{"id":"inc-004","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"O ficheiro menu.php não existe. O que acontece quando se abre esta página?","codigo":"<?php\ninclude 'menu.php';\necho 'Fim da página';","linguagem":"php","alternativas":["Dá um erro fatal e \"Fim da página\" não aparece.","Aparece um aviso e depois \"Fim da página\".","Não aparece aviso nenhum e só se vê \"Fim da página\".","A resposta é um 404 e a página não é mostrada."],"correta":1,"explicacao":"Quando o ficheiro falta, o include dá só um aviso e continua. Com require seria um erro fatal e a página parava ali.","manual":"7.6"},{"id":"inc-005","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"Porque é que a Biblioteca usa sempre require e nunca include?","codigo":"","linguagem":"","alternativas":["Porque o require é o único que aceita caminhos com pastas.","Porque o include não deixa usar as variáveis do ficheiro incluído.","Porque o include é mais lento e só se usa em ficheiros HTML.","Sem esses ficheiros a página não funciona, por isso é melhor parar."],"correta":3,"explicacao":"Se faltar o inicio.php ou o auth.php, continuar seria pior (sem ligação ou sem proteção). O require gera um erro fatal e para.","manual":"7.6"},{"id":"inc-006","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"Uma página restrita faz require 'includes/auth.php';, mas alguém apagou esse ficheiro. O que acontece?","codigo":"","linguagem":"","alternativas":["Erro fatal: a página para e não mostra nada da área restrita.","Aparece um aviso e a página abre para toda a gente.","O PHP salta a verificação e manda para o login.","A página abre normalmente, porque o auth.php é opcional."],"correta":0,"explicacao":"Com require, a falta do ficheiro é um erro fatal. Com include, a página continuaria sem verificação e ficaria aberta a todos.","manual":"7.6, 11.2"},{"id":"inc-007","bloco":"php","tema":"include e require","dificuldade":"facil","pergunta":"Este é o includes/inicio.php, incluído na primeira linha de cada página. Que três coisas faz?","codigo":"<?php\n// Incluído na PRIMEIRA linha de todas as páginas.\nsession_start();\nrequire __DIR__ . '/../config/db.php';\n\n// Guarda uma mensagem para mostrar na página seguinte (depois do redirect)\nfunction mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}","linguagem":"php","alternativas":["session_start(), require do db.php e a função mensagem().","session_start(), o cabeçalho HTML e o rodapé.","Verifica o login, abre o <html> e liga o CSS.","Cria a base de dados, as tabelas e os dados de exemplo."],"correta":0,"explicacao":"Ativa a sessão, liga à base de dados (cria o $pdo) e define a função mensagem(). O cabeçalho e o controlo de acesso estão noutros ficheiros.","manual":"9.1"},{"id":"inc-008","bloco":"php","tema":"include e require","dificuldade":"dificil","pergunta":"Porque é que o inicio.php usa __DIR__ para incluir a ligação?","codigo":"require __DIR__ . '/../config/db.php';","linguagem":"php","alternativas":["__DIR__ é a pasta htdocs, por isso o caminho começa sempre na raiz do servidor.","__DIR__ impede que o db.php seja incluído mais do que uma vez.","__DIR__ é a pasta do próprio inicio.php, por isso o caminho não depende da página.","__DIR__ esconde o caminho do ficheiro para o browser não o ver."],"correta":2,"explicacao":"Assim, o caminho para config/db.php funciona seja qual for a página que inclui o inicio.php.","manual":"9.1"},{"id":"inc-009","bloco":"php","tema":"include e require","dificuldade":"dificil","pergunta":"Que valor tem $titulo dentro do cabeçalho, nesta ordem?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/cabecalho.php';\n$titulo = 'Livros';","linguagem":"php","alternativas":["Nenhum: quando o cabeçalho corre, $titulo ainda não existe.","'Livros', porque o PHP lê o ficheiro todo antes de correr.","'Livros', porque o cabeçalho é incluído no fim da página.","O nome do ficheiro, que o require põe em $titulo."],"correta":0,"explicacao":"O ficheiro incluído corre naquele ponto e só vê as variáveis já definidas. Por isso cada página define $titulo antes do require do cabeçalho.","manual":"9.2, 7.6"},{"id":"inc-010","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"Este é um excerto do includes/livro_form.php, partilhado por livro_novo.php e livro_editar.php. Que variáveis tem a página de definir antes de o incluir?","codigo":"<?php require 'includes/erros.php'; // mostra a lista $erros ?>\n\n<form method=\"post\" action=\"<?= $acao ?>\" id=\"form-principal\" class=\"formulario\" novalidate>\n    <label for=\"titulo\">Título</label>\n    <input type=\"text\" id=\"titulo\" name=\"titulo\" maxlength=\"200\" required\n           value=\"<?= htmlspecialchars($livro['titulo']) ?>\">\n\n    <label for=\"id_autor\">Autor</label>\n    <select id=\"id_autor\" name=\"id_autor\" required>\n        <option value=\"\">— escolhe —</option>\n        <?php foreach ($autores as $autor): ?>\n            <?php $sel = $autor['id_autor'] == $livro['id_autor'] ? 'selected' : ''; ?>\n            <option value=\"<?= $autor['id_autor'] ?>\" <?= $sel ?>><?= htmlspecialchars($autor['nome']) ?></option>\n        <?php endforeach; ?>\n    </select>\n    <!-- ... isbn, ano_edicao e sinopse, também com $livro[...] ... -->\n    <button type=\"submit\">Guardar</button>\n</form>","linguagem":"php","alternativas":["Só $titulo, porque o resto vem do formulário.","$pdo e $stmt, para o formulário fazer a consulta.","$livro, $autores, $erros e $acao.","Nenhuma: o livro_form.php cria as suas variáveis."],"correta":2,"explicacao":"O formulário usa $livro (os valores), $autores (a lista da caixa), $erros (via erros.php) e $acao (para onde envia). A página prepara-os primeiro.","manual":"12.4"},{"id":"inc-011","bloco":"php","tema":"include e require","dificuldade":"dificil","pergunta":"Na livro_editar.php, aberta com ?id=7, que action fica no formulário que o livro_form.php escreve?","codigo":"$acao = \"livro_editar.php?id=$id\";\n// ...\n<form method=\"post\" action=\"<?= $acao ?>\" ...>","linguagem":"php","alternativas":["livro_novo.php","livro_editar.php?id=7","livro_form.php","livro_editar.php?id=$id"],"correta":1,"explicacao":"O livro_form.php vê a variável $acao da página que o inclui. Com aspas duplas, o $id foi substituído por 7.","manual":"12.4, 12.5"},{"id":"inc-012","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"A página faz require 'includes/inicio.php'; (em baixo) e logo a seguir usa $pdo->prepare(...). De onde vem o $pdo?","codigo":"<?php\n// Incluído na PRIMEIRA linha de todas as páginas.\nsession_start();\nrequire __DIR__ . '/../config/db.php';\n\n// Guarda uma mensagem para mostrar na página seguinte (depois do redirect)\nfunction mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}","linguagem":"php","alternativas":["Do browser, que envia a ligação em cada pedido.","Da sessão, onde o login guardou a ligação.","O PHP cria-o sozinho quando encontra $pdo->prepare.","Do db.php, que o inicio.php inclui."],"correta":3,"explicacao":"O código incluído funciona como se estivesse escrito na página, por isso o $pdo criado no db.php pode ser usado logo a seguir.","manual":"7.6, 8.1, 9.1"},{"id":"inc-013","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"Uma página da Biblioteca precisa da sessão e do $pdo, só abre com login, trata um formulário que acaba num redirecionamento e mostra HTML. Qual é a ordem certa das partes?","codigo":"","linguagem":"","alternativas":["cabeçalho, inicio.php, auth.php, tratar o POST, rodapé.","auth.php, inicio.php, cabeçalho, tratar o POST, rodapé.","inicio.php, cabeçalho, auth.php, tratar o POST, preparar os dados.","inicio.php, auth.php, tratar o POST, preparar dados, cabeçalho."],"correta":3,"explicacao":"Primeiro processa-se, depois mostra-se: sessão e ligação, proteção, POST, dados para mostrar e só no fim o HTML (cabeçalho ... rodapé).","manual":"7.8"},{"id":"inc-014","bloco":"php","tema":"include e require","dificuldade":"dificil","pergunta":"Alguém trocou a ordem destas duas linhas e abriu a página sem sessão iniciada. O que acontece?","codigo":"<?php\nrequire 'includes/auth.php';\nrequire 'includes/inicio.php';","linguagem":"php","alternativas":["Funciona igual: a ordem dos require não importa.","Mostra a página sem verificar o acesso e sem mensagem.","Erro: mensagem() ainda não existe e não há sessão.","O auth.php inclui o inicio.php sozinho e continua."],"correta":2,"explicacao":"O auth.php usa $_SESSION e chama mensagem(), que só existem depois do inicio.php. Por isso o inicio.php vem sempre na primeira linha.","manual":"7.8, 9.1, 11.2"},{"id":"inc-015","bloco":"php","tema":"include e require","dificuldade":"dificil","pergunta":"Uma página faz require do cabeçalho e só depois trata o POST, que acaba em header('Location: livros.php');. O que acontece ao gravar?","codigo":"","linguagem":"","alternativas":["Funciona: o header() envia sempre o redirecionamento primeiro.","O livro não é gravado, porque o POST é apagado pelo cabeçalho.","O browser mostra o cabeçalho duas vezes e depois redireciona.","\"headers already sent\": o HTML já saiu e não redireciona."],"correta":3,"explicacao":"O cabeçalho escreve HTML. Depois disso o header() já não consegue mudar a resposta. Processa-se o POST antes do require do cabeçalho.","manual":"7.8, 17.1"},{"id":"inc-016","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"Uma página nova começa assim e, mesmo com login feito, és sempre mandado para o login. Qual é a causa?","codigo":"<?php\nrequire 'config/db.php';\nif (!isset($_SESSION['id_utilizador'])) {\n    header('Location: login.php');\n    exit;\n}","linguagem":"php","alternativas":["Falta o inicio.php, que faz o session_start().","O require do db.php devia ser um include.","O isset() só funciona com dados de formulários.","Falta o require do cabeçalho antes da verificação."],"correta":0,"explicacao":"Sem session_start(), $_SESSION está vazio nesta página. Por isso todas as páginas começam por require 'includes/inicio.php';.","manual":"17.1, 9.1"},{"id":"inc-017","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"O cabecalho.php começa logo por <!DOCTYPE html>, sem <?php. Isso funciona quando é incluído?","codigo":"","linguagem":"","alternativas":["Não: um ficheiro incluído tem de começar por <?php.","Sim: o que está fora de <?php ?> é enviado tal e qual.","Só se for incluído com include, não com require.","Só se o HTML for escrito dentro de um echo."],"correta":1,"explicacao":"Um ficheiro incluído é tratado como qualquer .php: o HTML vai para o browser e os blocos <?php ... ?> são executados.","manual":"7.1, 9.2"},{"id":"inc-018","bloco":"php","tema":"include e require","dificuldade":"facil","pergunta":"Queres acrescentar um link ao menu de todas as páginas da Biblioteca. Onde o fazes?","codigo":"","linguagem":"","alternativas":["Em cada página, logo a seguir ao require.","No includes/inicio.php, junto ao session_start().","Só no includes/cabecalho.php.","No includes/rodape.php, que fecha o menu."],"correta":2,"explicacao":"O menu está no cabeçalho, que todas as páginas incluem. Muda-se num sítio e a alteração aparece em todas.","manual":"9.2"},{"id":"inc-019","bloco":"php","tema":"include e require","dificuldade":"facil","pergunta":"Mudaste a password da base de dados. Que ficheiro tens de alterar?","codigo":"","linguagem":"","alternativas":["Todas as páginas que fazem consultas.","O includes/inicio.php e o includes/auth.php.","Só o config/db.php.","O base_dados.sql, voltando a importá-lo."],"correta":2,"explicacao":"As credenciais estão num único ficheiro, incluído por todas as páginas através do inicio.php.","manual":"8.1, 7.6"},{"id":"inc-020","bloco":"php","tema":"include e require","dificuldade":"media","pergunta":"Criaste a página autores.php mas esqueceste-te do require 'includes/auth.php';. Qual é a consequência?","codigo":"","linguagem":"","alternativas":["Fica aberta a quem não tem sessão iniciada.","A página dá erro fatal e não abre para ninguém.","Só os utilizadores com sessão a conseguem ver.","O menu deixa de mostrar o link Autores."],"correta":0,"explicacao":"A proteção só existe onde o auth.php é incluído. Esconder o link do menu não chega: qualquer um pode escrever o endereço.","manual":"11.2"},{"id":"amostra-011","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Depois de inserir um livro novo, queres redirecionar para a página dele. Como obténs o id que o AUTO_INCREMENT gerou?","codigo":"$stmt = $pdo->prepare('INSERT INTO livros (titulo, id_autor) VALUES (?, ?)');\n$stmt->execute([$titulo, $idAutor]);\n$novoId = ________;","linguagem":"php","alternativas":["$stmt->rowCount()","$_POST['id_livro']","$pdo->lastInsertId()","$stmt->fetchColumn()"],"correta":2,"explicacao":"lastInsertId() devolve o id gerado pelo último INSERT. rowCount() diz quantas linhas um UPDATE ou um DELETE afetou, e o formulário nunca envia o id de um livro novo.","manual":"8.2, 12.4"},{"id":"pdo-001","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Porque é que a Biblioteca põe a ligação à base de dados num único ficheiro, config/db.php, incluído pelas páginas?","codigo":"","linguagem":"","alternativas":["Se as credenciais mudarem, muda-se só num sítio.","Porque o PDO só funciona dentro da pasta config.","Para a password do MySQL ficar cifrada.","Porque cada página só pode abrir uma ligação."],"correta":0,"explicacao":"O db.php é o único ficheiro com as credenciais: todas as páginas o incluem e usam o $pdo que ele cria. Se a password mudar, altera-se só ali.","manual":"8.1, 14.2"},{"id":"pdo-002","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Qual destas linhas abre corretamente uma ligação ao MySQL com PDO?","codigo":"","linguagem":"","alternativas":["$pdo = PDO::connect(\"localhost\", \"loja\", $user, $pass);","$pdo = new PDO(\"server=localhost\", \"database=loja\", $user, $pass);","$pdo = new PDO(\"mysql:host=localhost;dbname=loja\", $user, $pass);","$pdo = mysql_connect(\"mysql:host=localhost;dbname=loja\");"],"correta":2,"explicacao":"A ligação cria-se com new PDO(DSN, utilizador, password). O DSN junta numa só string o tipo de base de dados, o servidor e o nome da base de dados.","manual":"8.1, Anexo B"},{"id":"pdo-003","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Qual é a ordem dos argumentos de new PDO(...) no db.php?","codigo":"","linguagem":"","alternativas":["utilizador, password, DSN","DSN, password, utilizador","DSN, utilizador, password","servidor, utilizador, base de dados"],"correta":2,"explicacao":"Primeiro o DSN (\"mysql:host=...;dbname=...;charset=utf8mb4\"), depois o utilizador e por fim a password.","manual":"8.1"},{"id":"pdo-004","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"No DSN `mysql:host=localhost;dbname=biblioteca;charset=utf8mb4`, para que serve `charset=utf8mb4`?","codigo":"","linguagem":"","alternativas":["Para os acentos serem enviados e lidos corretamente.","Para cifrar os dados que passam na ligação.","Para escolher o motor de tabelas do MySQL.","Para limitar cada texto a 4 caracteres por palavra."],"correta":0,"explicacao":"O charset define a codificação dos textos trocados com o MySQL. Sem ele, um nome como \"José\" pode aparecer estragado.","manual":"8.1"},{"id":"pdo-005","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"No mesmo DSN, o que indica `dbname=biblioteca`?","codigo":"mysql:host=localhost;dbname=biblioteca;charset=utf8mb4","linguagem":"php","alternativas":["O nome do utilizador do MySQL.","O nome da tabela principal.","O nome da base de dados a usar.","A pasta do projeto dentro do htdocs."],"correta":2,"explicacao":"O DSN diz o tipo de base de dados (mysql), o servidor (host), o nome da base de dados (dbname) e o charset. O utilizador e a password vão nos argumentos seguintes do new PDO.","manual":"8.1"},{"id":"pdo-006","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"A base de dados está no mesmo computador que o XAMPP. Que valor leva `host` no DSN?","codigo":"","linguagem":"","alternativas":["localhost","htdocs","phpmyadmin","biblioteca"],"correta":0,"explicacao":"host é o servidor onde corre o MySQL: no XAMPP é o próprio computador, localhost. biblioteca seria o valor de dbname.","manual":"8.1"},{"id":"pdo-007","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"No XAMPP, por omissão, com que utilizador e password se liga a aplicação ao MySQL?","codigo":"","linguagem":"","alternativas":["root, sem password","admin, com a password admin","root, com a password root","o email e a password do utilizador de teste"],"correta":0,"explicacao":"No XAMPP o utilizador root não tem password por omissão, por isso o db.php tem $pass = ''. Os dados do utilizador de teste servem para o login na aplicação, não para o MySQL.","manual":"8.1, 17.2"},{"id":"pdo-008","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"O que faz esta linha do db.php?","codigo":"$pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);","linguagem":"php","alternativas":["Esconde do utilizador final todos os erros da base de dados.","Faz o PDO repetir as consultas que falham.","Faz o PDO lançar uma exceção quando uma consulta falha.","Mostra os erros de SQL num alert() no browser."],"correta":2,"explicacao":"Com ERRMODE_EXCEPTION, uma consulta que falha lança uma PDOException, que se pode apanhar com try/catch ou que faz a página parar com a mensagem do erro.","manual":"8.1"},{"id":"pdo-009","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Antes do PHP 8, o PDO vinha em modo silencioso por omissão. Nessa versão, sem a linha do setAttribute(...ERRMODE_EXCEPTION), o que acontecia a um SELECT com um nome de coluna mal escrito?","codigo":"","linguagem":"","alternativas":["Falhava em silêncio e ficavas sem saber porquê.","O PHP corrigia sozinho o nome da coluna.","A página respondia sempre com o código 404.","A ligação nem chegava a abrir e aparecia o erro 2002."],"correta":0,"explicacao":"Sem ERRMODE_EXCEPTION, uma consulta errada falhava em silêncio. Com ele, o PDO lança uma exceção e vês logo o erro (por exemplo, 42S22 Unknown column). Desde o PHP 8 este já é o modo por omissão, mas o db.php escreve-o na mesma, para ficar explícito.","manual":"8.1"},{"id":"pdo-010","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"A página livros.php usa `$pdo` sem nunca escrever `new PDO`. Porque é que funciona?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/auth.php';\n\n$stmt = $pdo->prepare('SELECT titulo FROM livros');","linguagem":"php","alternativas":["O $pdo é uma variável especial que o PHP cria em todas as páginas.","O inicio.php faz require do db.php, que cria a variável $pdo.","O auth.php abre a ligação quando confirma a sessão.","O XAMPP cria o $pdo quando o MySQL arranca."],"correta":1,"explicacao":"O require insere o código do ficheiro naquele ponto. O inicio.php inclui o config/db.php, que guarda a ligação em $pdo, e essa variável fica disponível na página.","manual":"8.1, 9.1"},{"id":"pdo-011","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Criaste uma página nova que começa logo por `$stmt = $pdo->prepare(...)`, sem nenhum require. O que acontece?","codigo":"","linguagem":"","alternativas":["Dá erro, porque nessa página o $pdo não existe.","O PDO liga-se sozinho como root, sem password.","Funciona, porque o $pdo fica guardado na sessão.","Dá o erro SQLSTATE[HY000] [1045] Access denied."],"correta":0,"explicacao":"O $pdo só existe nas páginas que incluem o db.php (na Biblioteca, através do inicio.php). Não fica na sessão nem é criado automaticamente.","manual":"8.1, 9.1"},{"id":"pdo-012","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Quais são, por ordem, os três passos de uma consulta na Biblioteca?","codigo":"","linguagem":"","alternativas":["execute() com os valores, prepare() com ?, ler o resultado","query() com o SQL, prepare() com ?, ler o resultado","prepare() com ?, execute() com os valores, ler o resultado","prepare() com os valores, execute() com ?, ler o resultado"],"correta":2,"explicacao":"Prepara-se o SQL com ? no lugar dos valores, executa-se passando os valores num array e lê-se o resultado com fetch(), fetchAll() ou fetchColumn().","manual":"8.2"},{"id":"pdo-013","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"O que devolve `$pdo->prepare($sql)`?","codigo":"","linguagem":"","alternativas":["As linhas encontradas, num array associativo.","O número de linhas afetadas pela consulta.","O id gerado pelo último INSERT na tabela.","Uma consulta preparada ($stmt), pronta a executar."],"correta":3,"explicacao":"O prepare() só prepara o SQL e devolve o $stmt. As linhas só se obtêm depois do execute(), com os métodos fetch.","manual":"8.2"},{"id":"pdo-014","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Como é que o execute() sabe que valor vai para cada `?`?","codigo":"","linguagem":"","alternativas":["Pela ordem em que os ? aparecem no SQL.","Pela ordem alfabética dos nomes das colunas.","Pela ordem das colunas na tabela.","Pela ordem dos campos no formulário HTML."],"correta":0,"explicacao":"O primeiro valor do array vai para o primeiro ?, o segundo para o segundo, e assim por diante. Por isso a ordem do array tem de seguir a ordem dos ? no SQL.","manual":"8.2"},{"id":"pdo-015","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Qual é o problema deste código?","codigo":"$stmt = $pdo->prepare('UPDATE autores SET nome = ?, nacionalidade = ? WHERE id_autor = ?');\n$stmt->execute([$id, $nome, $nacionalidade]);","linguagem":"php","alternativas":["Os valores fogem à ordem dos ?: o id iria para o nome.","Faltam plicas à volta de cada ? no SQL.","O execute() só aceita um valor de cada vez.","Um UPDATE não pode ser preparado: tem de se usar query()."],"correta":0,"explicacao":"Os valores entram pela ordem dos ?: aqui o nome ficaria com o id e o WHERE usaria a nacionalidade. O certo é execute([$nome, $nacionalidade, $id]).","manual":"8.2, 3.7"},{"id":"pdo-016","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"O que está mal nesta consulta?","codigo":"$stmt = $pdo->prepare(\"SELECT * FROM livros WHERE titulo = '?'\");\n$stmt->execute([$titulo]);","linguagem":"php","alternativas":["Faltam aspas à volta de $titulo dentro do array do execute().","O ? não leva plicas: assim é o texto '?' e não um parâmetro.","Com o sinal =, o ? só aceita valores numéricos.","O prepare() não aceita SQL entre aspas duplas."],"correta":1,"explicacao":"O ? indica o lugar de um valor e escreve-se sem plicas: a base de dados já trata o valor como texto. Entre plicas, '?' passa a ser um texto qualquer: a consulta fica sem parâmetros e o execute() falha com HY093.","manual":"8.2"},{"id":"pdo-017","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Queres ordenar a lista pela coluna que o utilizador escolhe. Este código faz isso?","codigo":"$stmt = $pdo->prepare('SELECT titulo, ano_edicao FROM livros ORDER BY ?');\n$stmt->execute([$coluna]);","linguagem":"php","alternativas":["Sim: o ? pode substituir qualquer parte do SQL.","Sim, desde que $coluna venha de $_GET.","Não: o ORDER BY tem de vir antes do FROM.","Não: o ? substitui valores, não nomes de colunas."],"correta":3,"explicacao":"Os ? são os lugares onde se põem valores. Um nome de coluna, de tabela ou uma palavra do SQL não pode ser passado como parâmetro.","manual":"8.2, 3.7"},{"id":"pdo-018","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"A lista de autores não tem nenhum `?`. Que linha falta para a consulta funcionar?","codigo":"$stmt = $pdo->prepare('SELECT id_autor, nome FROM autores ORDER BY nome');\n// ________\nreturn $stmt->fetchAll(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["$pdo->execute($stmt);","$stmt->query();","$stmt->fetch();","$stmt->execute();"],"correta":3,"explicacao":"Mesmo sem valores, a consulta preparada tem de ser executada antes de se lerem as linhas. Como não há ?, o execute() não leva array.","manual":"12.4, 8.2"},{"id":"pdo-019","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Qual é o problema deste código?","codigo":"$stmt = $pdo->prepare('SELECT titulo FROM livros ORDER BY titulo');\n$livros = $stmt->execute();\nforeach ($livros as $livro) {\n    echo $livro['titulo'];\n}","linguagem":"php","alternativas":["O execute() não devolve as linhas: lêem-se com fetchAll().","Falta pôr pelo menos um ? no SELECT para o execute() funcionar.","O foreach não funciona com resultados do PDO.","Falta passar um array vazio ao execute()."],"correta":0,"explicacao":"O execute() só executa a consulta (devolve true ou false). As linhas obtêm-se depois, com $stmt->fetchAll(PDO::FETCH_ASSOC), que é o terceiro passo.","manual":"8.2"},{"id":"pdo-020","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Que SQL preparado grava um autor novo?","codigo":"","linguagem":"","alternativas":["INSERT INTO autores (nome, nacionalidade) VALUES (?, ?)","INSERT INTO autores VALUES (nome = ?, nacionalidade = ?)","INSERT INTO autores (?, ?) VALUES (nome, nacionalidade)","UPDATE autores SET nome = ?, nacionalidade = ?"],"correta":0,"explicacao":"O INSERT indica as colunas e, em VALUES, um ? por cada valor. Os ? não podem ocupar o lugar dos nomes das colunas, e o UPDATE altera linhas que já existem.","manual":"3.7, 8.2"},{"id":"pdo-021","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Num projeto de clínica veterinária, qual é o SQL preparado certo para apagar um animal?","codigo":"","linguagem":"","alternativas":["DELETE FROM animais WHERE id_animal = '?'","DELETE FROM animais WHERE id_animal = ?","DELETE * FROM animais WHERE id_animal = ?","DELETE animais WHERE id_animal = ?"],"correta":1,"explicacao":"O DELETE usa FROM, um WHERE com a chave primária e um ? no lugar do valor, sem plicas. DELETE * e DELETE sem FROM não são SQL válido no MySQL, e '?' seria um texto, não um parâmetro.","manual":"3.7, 13.4"},{"id":"pdo-022","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Um autor chama-se `O'Neill`. Com prepare() e execute(), o que acontece ao gravar?","codigo":"$stmt = $pdo->prepare('INSERT INTO autores (nome) VALUES (?)');\n$stmt->execute([$nome]);","linguagem":"php","alternativas":["Dá erro de sintaxe SQL por causa da plica.","A plica é removida antes de gravar.","É gravado tal e qual, com a plica.","O nome é gravado como NULL."],"correta":2,"explicacao":"Com parâmetros, a base de dados recebe o SQL e os valores em separado e trata o valor sempre como texto. A plica não \"fecha\" nada: fica guardada como parte do nome.","manual":"8.4"},{"id":"pdo-023","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Que método se usa para obter todas as linhas de uma lista, como a dos livros?","codigo":"","linguagem":"","alternativas":["$stmt->fetch(PDO::FETCH_ASSOC)","$stmt->fetchColumn()","$stmt->fetchAll(PDO::FETCH_ASSOC)","$stmt->rowCount()"],"correta":2,"explicacao":"fetchAll() devolve todas as linhas num array de arrays associativos. fetch() dá só a próxima linha e fetchColumn() só o valor da primeira coluna.","manual":"8.2, Anexo B"},{"id":"pdo-024","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"O que quer dizer `PDO::FETCH_ASSOC` num fetch() ou fetchAll()?","codigo":"","linguagem":"","alternativas":["Cada linha vem como array com os nomes das colunas como chaves.","Devolve apenas o valor da primeira coluna de cada linha da consulta.","Junta as linhas de duas tabelas que estão associadas.","Devolve as linhas ordenadas pela chave primária."],"correta":0,"explicacao":"Com FETCH_ASSOC, cada linha é um array associativo: lê-se com $livro['titulo']. Juntar tabelas é trabalho do JOIN, no SQL.","manual":"8.2"},{"id":"pdo-025","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Que valor fica em `$livro` se não existir nenhum livro com o id 999?","codigo":"$stmt = $pdo->prepare('SELECT * FROM livros WHERE id_livro = ?');\n$stmt->execute([999]);\n$livro = $stmt->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["false","Um array vazio","null","0"],"correta":0,"explicacao":"fetch() devolve a próxima linha ou false se não houver nenhuma. É por isso que o livro_ver.php testa if (!$livro).","manual":"8.2, 12.3"},{"id":"pdo-026","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"A pesquisa não encontrou nenhum livro. O que fica em `$livros`?","codigo":"$stmt->execute(['%xyz%']);\n$livros = $stmt->fetchAll(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["false","Um array vazio","null","Um array com uma linha vazia"],"correta":1,"explicacao":"fetchAll() devolve sempre um array: sem resultados, fica vazio. Por isso a lista testa count($livros) === 0 para mostrar \"Não foi encontrado nenhum livro.\"","manual":"8.2, 12.2"},{"id":"pdo-027","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Sabendo que o autor 1 tem dois livros, o que mostra este código?","codigo":"$stmt = $pdo->prepare('SELECT COUNT(*) FROM livros WHERE id_autor = ?');\n$stmt->execute([1]);\necho $stmt->fetchColumn();","linguagem":"php","alternativas":["Array","1","2","COUNT(*)"],"correta":2,"explicacao":"fetchColumn() devolve o valor da primeira coluna da linha, aqui o resultado do COUNT(*). Não é um array, por isso o echo mostra o número.","manual":"8.2"},{"id":"pdo-028","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Sabendo que o autor 3 é o Eça de Queirós, o que mostra este código?","codigo":"$stmt = $pdo->prepare('SELECT nome FROM autores WHERE id_autor = ?');\n$stmt->execute([3]);\n$autor = $stmt->fetch(PDO::FETCH_ASSOC);\necho $autor;","linguagem":"php","alternativas":["Eça de Queirós","3","nome","Array"],"correta":3,"explicacao":"fetch() devolve a linha inteira como array associativo. Para mostrar o nome é preciso escolher a chave: $autor['nome'].","manual":"8.2"},{"id":"pdo-029","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Sabendo que a autora 2 tem \"A Menina do Mar\" e \"O Cavaleiro da Dinamarca\", o que mostra este código?","codigo":"$stmt = $pdo->prepare('SELECT titulo FROM livros WHERE id_autor = ? ORDER BY titulo');\n$stmt->execute([2]);\n$livros = $stmt->fetchAll(PDO::FETCH_ASSOC);\necho $livros[1]['titulo'];","linguagem":"php","alternativas":["A Menina do Mar","Os dois títulos, um a seguir ao outro","Array","O Cavaleiro da Dinamarca"],"correta":3,"explicacao":"fetchAll() devolve uma lista de linhas que começa no índice 0. Por ordem de título, a posição 0 é \"A Menina do Mar\" e a posição 1 é \"O Cavaleiro da Dinamarca\".","manual":"8.2"},{"id":"pdo-030","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Com esta consulta, como se lê o nome do autor depois do fetch?","codigo":"$stmt = $pdo->prepare(\n    'SELECT l.titulo, a.nome AS autor\n     FROM livros l\n     JOIN autores a ON l.id_autor = a.id_autor\n     WHERE l.id_livro = ?'\n);\n$stmt->execute([$id]);\n$livro = $stmt->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["$livro['a.nome']","$livro['autor']","$livro['nome']","$livro->autor"],"correta":1,"explicacao":"O AS autor dá à coluna o nome autor, e é essa a chave do array associativo. O prefixo a. só existe dentro do SQL.","manual":"8.2, 12.2"},{"id":"pdo-031","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"No login, porque se usa fetch() e não fetchAll() para procurar o utilizador pelo email?","codigo":"","linguagem":"","alternativas":["Porque o fetchAll() não funciona com WHERE.","Porque o fetch() já compara a password escrita.","Porque o fetchAll() devolve só a primeira coluna de cada linha.","Porque se espera no máximo uma linha: o email é UNIQUE."],"correta":3,"explicacao":"Como o email é UNIQUE, a consulta devolve uma linha ou nenhuma: fetch() dá essa linha ou false. A password é comparada a seguir com password_verify().","manual":"8.2, 10.4"},{"id":"pdo-032","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"No registo, o que significa este `if` ser verdadeiro?","codigo":"$stmt = $pdo->prepare('SELECT id_utilizador FROM utilizadores WHERE email = ?');\n$stmt->execute([$email]);\nif ($stmt->fetch()) {\n    $erros[] = 'Já existe uma conta com esse email.';\n}","linguagem":"php","alternativas":["O email tem um formato válido.","A consulta correu sem erros.","A conta acabou de ser criada.","Já existe um utilizador com esse email."],"correta":3,"explicacao":"fetch() devolve a linha encontrada (verdadeiro) ou false se não houver nenhuma. Se encontrou uma linha, o email já está registado.","manual":"10.2, 8.2"},{"id":"pdo-033","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"A coluna email já é UNIQUE. Porque é que o registo faz um SELECT antes do INSERT?","codigo":"","linguagem":"","alternativas":["Porque sem o SELECT a restrição UNIQUE não funciona.","Para o INSERT seguinte ser executado mais depressa.","Porque o PDO não deixa fazer um INSERT sem um SELECT.","Para dar ao utilizador uma mensagem mais clara."],"correta":3,"explicacao":"A base de dados recusaria o email repetido de qualquer forma, por causa do UNIQUE. O SELECT serve só para dar ao utilizador a mensagem \"Já existe uma conta com esse email.\"","manual":"10.2"},{"id":"pdo-034","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Na validação do autor, porque se usa fetchColumn()?","codigo":"$stmt = $pdo->prepare('SELECT COUNT(*) FROM autores WHERE id_autor = ?');\n$stmt->execute([$livro['id_autor']]);\nif ($stmt->fetchColumn() == 0) { ... }","linguagem":"php","alternativas":["Dá diretamente o valor da única coluna: o número contado.","Devolve true se o autor existir e false se o autor não existir.","Conta quantas colunas tem a tabela autores.","É o único método que funciona com COUNT(*)."],"correta":0,"explicacao":"O COUNT(*) devolve uma linha com uma só coluna. fetchColumn() lê esse valor sem ser preciso tirar o número de dentro de um array.","manual":"8.2, 12.4"},{"id":"pdo-035","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Para que serve `$pdo->lastInsertId()`?","codigo":"","linguagem":"","alternativas":["Dá o maior id que existe na tabela.","Dá o número de linhas inseridas.","Dá o id gerado pelo último INSERT.","Apaga a última linha que foi inserida."],"correta":2,"explicacao":"lastInsertId() devolve o id (AUTO_INCREMENT) que a base de dados acabou de gerar no último INSERT feito por esta ligação.","manual":"8.2, 12.4"},{"id":"pdo-036","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Os autores existentes têm os ids 1 a 4 e nunca se apagou nenhum. Que valor fica em `$novoId`?","codigo":"$stmt = $pdo->prepare('INSERT INTO autores (nome, nacionalidade) VALUES (?, ?)');\n$stmt->execute(['Fernando Pessoa', 'Portuguesa']);\n$novoId = $pdo->lastInsertId();","linguagem":"php","alternativas":["4","5","1","true"],"correta":1,"explicacao":"O id_autor é AUTO_INCREMENT: o novo autor recebe o número seguinte, 5, e lastInsertId() devolve esse id.","manual":"8.2, 3.5"},{"id":"pdo-037","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Porque é que livro_novo.php chama lastInsertId() logo a seguir ao INSERT?","codigo":"","linguagem":"","alternativas":["Para confirmar que o ISBN não está repetido.","Para saber o id do livro novo e abrir a sua página de detalhe.","Para saber quantos livros tem agora a tabela.","Para guardar o id do livro na sessão do utilizador."],"correta":1,"explicacao":"Depois de gravar, a Biblioteca redireciona para livro_ver.php?id= do livro novo, e esse id só se conhece com lastInsertId().","manual":"12.4"},{"id":"pdo-038","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"O que devolve `$stmt->rowCount()` depois de um DELETE?","codigo":"","linguagem":"","alternativas":["Quantas linhas foram apagadas.","O id da linha que foi apagada.","true ou false, conforme correu.","Quantas linhas ficaram na tabela."],"correta":0,"explicacao":"rowCount() diz quantas linhas o UPDATE ou o DELETE afetou. A Biblioteca usa-o para saber se o livro foi mesmo apagado.","manual":"8.2, 12.6"},{"id":"pdo-039","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Abres o mesmo livro em dois separadores e carregas em Apagar nos dois. Que mensagem aparece no segundo?","codigo":"$stmt = $pdo->prepare('DELETE FROM livros WHERE id_livro = ?');\n$stmt->execute([(int) ($_POST['id_livro'] ?? 0)]);\nif ($stmt->rowCount() === 1) {\n    mensagem('sucesso', 'Livro apagado.');\n} else {\n    mensagem('erro', 'O livro já não existia.');\n}","linguagem":"php","alternativas":["\"Livro apagado.\"","\"O livro já não existia.\"","Um erro SQLSTATE[23000]","Uma página de erro 404"],"correta":1,"explicacao":"No segundo pedido o livro já não existe: o DELETE não apaga nenhuma linha, rowCount() dá 0 e cai no else. Um DELETE que não encontra nada não dá erro.","manual":"12.6"},{"id":"pdo-040","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Não existe nenhum autor com o id 99. Que valor dá rowCount() a seguir a este UPDATE?","codigo":"$stmt = $pdo->prepare('UPDATE autores SET nome = ? WHERE id_autor = ?');\n$stmt->execute(['Ana', 99]);\necho $stmt->rowCount();","linguagem":"php","alternativas":["1","99","0","false"],"correta":2,"explicacao":"O WHERE não encontra nenhuma linha, por isso nada é alterado e rowCount() dá 0. Não há erro: um UPDATE sem linhas afetadas é válido.","manual":"8.2"},{"id":"pdo-041","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"O formulário de apagar foi enviado sem o campo id_livro. O que acontece?","codigo":"$stmt = $pdo->prepare('DELETE FROM livros WHERE id_livro = ?');\n$stmt->execute([(int) ($_POST['id_livro'] ?? 0)]);","linguagem":"php","alternativas":["Apaga todos os livros, porque o id chega vazio ao WHERE.","Dá o erro HY093, porque falta o valor do ?.","Apaga o primeiro livro da tabela.","Procura o livro 0, não apaga nada e rowCount() dá 0."],"correta":3,"explicacao":"O ?? 0 dá 0 quando o campo não vem, e o (int) garante um número. Como nenhum livro tem id 0, o DELETE não apaga nada. O WHERE continua lá, por isso nunca apaga tudo.","manual":"12.6, 7.5"},{"id":"pdo-042","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Qual destes pares \"método → o que devolve\" está correto?","codigo":"","linguagem":"","alternativas":["rowCount() → o id gerado pelo último INSERT","fetch() → todas as linhas da consulta","lastInsertId() → as linhas afetadas pelo UPDATE","fetchColumn() → o valor da primeira coluna"],"correta":3,"explicacao":"fetchColumn() dá o valor da primeira coluna (útil para COUNT). O id do INSERT é com lastInsertId(), as linhas afetadas com rowCount() e todas as linhas com fetchAll().","manual":"8.2"},{"id":"pdo-043","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Este é um excerto do livro_ver.php. O que faz a página quando o fetch() devolve false?","codigo":"$stmt->execute([$id]);\n$livro = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif (!$livro) {\n    http_response_code(404);\n    $titulo = 'Livro não encontrado';\n    require 'includes/cabecalho.php';\n    echo '<h1>Livro não encontrado</h1><p><a href=\"livros.php\">Voltar à lista</a></p>';\n    require 'includes/rodape.php';\n    exit;\n}","linguagem":"php","alternativas":["Redireciona para o login com uma mensagem de erro.","Responde com o código 404 e uma mensagem própria.","Mostra a página de detalhe com os campos vazios.","Lança uma PDOException com o código 23000."],"correta":1,"explicacao":"false quer dizer que não há livro com esse id. O livro_ver.php faz http_response_code(404) e mostra \"Livro não encontrado\", em vez de uma página partida.","manual":"12.3, 1.3"},{"id":"pdo-044","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Alguém abre `livro_ver.php?id=abc`. O que acontece?","codigo":"$id = (int) ($_GET['id'] ?? 0);\n$stmt = $pdo->prepare('SELECT * FROM livros WHERE id_livro = ?');\n$stmt->execute([$id]);\n$livro = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif (!$livro) {\n    http_response_code(404);\n    // ... mostra \"Livro não encontrado\" e sai\n}","linguagem":"php","alternativas":["O SQL procura o texto abc no título e devolve todos os livros.","O id fica 0, o fetch() devolve false e aparece a página 404.","Dá o erro SQLSTATE[42S22] Unknown column 'abc'.","Aparece o primeiro livro da tabela."],"correta":1,"explicacao":"O (int) converte \"abc\" em 0, que não existe. O fetch() dá false e a página responde 404. O valor nunca entra no texto do SQL, por isso não pode alterar a consulta.","manual":"12.3"},{"id":"pdo-045","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"O que significa o erro `SQLSTATE[HY093]: Invalid parameter number`?","codigo":"","linguagem":"","alternativas":["Há um valor repetido num campo UNIQUE.","O número de ? é diferente do número de valores no execute().","Um nome de coluna está mal escrito no SQL.","O id passado no execute() não existe na tabela."],"correta":1,"explicacao":"HY093 aparece quando os ? e os valores do array não batem certo. A solução do manual: contar os dois.","manual":"17.2"},{"id":"pdo-046","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Que erro dá este código?","codigo":"$stmt = $pdo->prepare('INSERT INTO autores (nome, nacionalidade) VALUES (?, ?)');\n$stmt->execute([$nome]);","linguagem":"php","alternativas":["SQLSTATE[23000] ... 1062 Duplicate entry","SQLSTATE[42S22] ... Unknown column","SQLSTATE[HY093]: Invalid parameter number","SQLSTATE[HY000] [1049] Unknown database"],"correta":2,"explicacao":"Há dois ? e só um valor no execute(). Se a nacionalidade é opcional, passa-se $nacionalidade ?: null, mas o número de valores tem de ser sempre igual ao de ?.","manual":"17.2, 8.2"},{"id":"pdo-047","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"O que acontece quando esta edição é gravada?","codigo":"$stmt = $pdo->prepare(\n    'UPDATE livros\n     SET titulo = ?, id_autor = ?, isbn = ?, ano_edicao = ?, sinopse = ?\n     WHERE id_livro = ?'\n);\n$stmt->execute([$titulo, $idAutor, $isbn, $ano, $sinopse]);","linguagem":"php","alternativas":["Altera todos os livros, porque falta o id.","Altera o livro com id 0.","Não faz nada e rowCount() dá 0.","Dá HY093: há seis ? e só cinco valores."],"correta":3,"explicacao":"Faltou o $id no fim do array. O PDO não completa valores em falta nem ignora o WHERE: recusa a consulta com HY093.","manual":"17.2, 12.5"},{"id":"pdo-048","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Qual é a forma segura de pesquisar os livros cujo título contém `$q`?","codigo":"","linguagem":"","alternativas":["prepare('... WHERE titulo LIKE ?') e execute(['%' . $q . '%'])","prepare('... WHERE titulo LIKE %?%') e execute([$q])","prepare(\"... WHERE titulo LIKE '%$q%'\") e execute()","prepare('... WHERE titulo LIKE ?') e execute(['%' + trim($q) + '%'])"],"correta":0,"explicacao":"Os % juntam-se ao valor, com o operador . do PHP, e o SQL fica só com o ?. Pôr $q dentro do SQL abre a porta à injeção; o + não junta textos em PHP.","manual":"8.4, 12.2"},{"id":"pdo-049","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Numa pesquisa com `LIKE ?`, onde se acrescentam os `%`?","codigo":"","linguagem":"","alternativas":["No SQL, à volta do ?: LIKE '%?%'.","No atributo value da caixa de pesquisa.","Em lado nenhum: o LIKE já procura em todo o texto.","Ao valor passado no execute()."],"correta":3,"explicacao":"O manual chama a atenção: os % são acrescentados ao valor, não ao SQL. Sem %, o LIKE só encontra títulos exatamente iguais ao texto.","manual":"12.2"},{"id":"pdo-050","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"A caixa de pesquisa foi enviada vazia. Que livros aparecem?","codigo":"$q = trim($_GET['q'] ?? '');\n$stmt = $pdo->prepare('SELECT titulo FROM livros WHERE titulo LIKE ? ORDER BY titulo');\n$stmt->execute(['%' . $q . '%']);\n$livros = $stmt->fetchAll(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["Nenhum: um texto vazio não encontra nada.","Todos os livros: o valor fica %%.","Só os livros que não têm título.","Dá erro HY093, porque o valor vem vazio."],"correta":1,"explicacao":"Com $q vazio, o valor é %%, que corresponde a qualquer título. Um valor vazio continua a ser um valor, por isso não há HY093.","manual":"12.2"},{"id":"pdo-051","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Em PHP, que operador junta os `%` ao texto pesquisado em `'%' __ $q __ '%'`?","codigo":"","linguagem":"","alternativas":["+","&",",","."],"correta":3,"explicacao":"Em PHP, os textos juntam-se com o ponto: '%' . $q . '%'. O + é a soma de números (e é o que se usa em JavaScript para juntar textos).","manual":"8.4, 12.2"},{"id":"pdo-052","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"O que é a injeção de SQL (SQL injection)?","codigo":"","linguagem":"","alternativas":["Meter JavaScript nos dados, para correr no browser de outros utilizadores.","Um erro do MySQL quando falta uma vírgula no SQL.","Inserir várias linhas de uma vez com um só INSERT.","Meter código SQL nos valores enviados, para alterar a consulta."],"correta":3,"explicacao":"Na injeção de SQL, o valor escrito pelo utilizador passa a fazer parte do código da consulta. Meter JavaScript que corre no browser de outros é XSS, que se evita com htmlspecialchars().","manual":"8.4"},{"id":"pdo-053","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Qual destas instruções é vulnerável a injeção de SQL?","codigo":"","linguagem":"","alternativas":["$pdo->prepare('SELECT * FROM livros WHERE id_livro = ?')","$stmt->execute([$id]), depois de um prepare() com o SQL e um ?","$stmt->fetch(PDO::FETCH_ASSOC) depois do execute()","$pdo->query(\"SELECT * FROM livros WHERE id_livro = $id\")"],"correta":3,"explicacao":"A variável está dentro do texto do SQL, por isso o valor passa a ser código. Com prepare() e ?, o valor vai em separado no execute().","manual":"8.4"},{"id":"pdo-055","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Na tentativa de injeção `' OR 1=1 -- `, o que faz o `--`?","codigo":"","linguagem":"","alternativas":["Fecha o texto que a plica abriu.","Torna a condição sempre verdadeira.","Subtrai 1 ao resultado da consulta.","Transforma o resto do SQL num comentário."],"correta":3,"explicacao":"Cada peça tem um papel: a plica fecha o texto, o OR 1=1 é sempre verdadeiro e o -- faz com que o resto (%') seja ignorado como comentário.","manual":"8.4"},{"id":"pdo-056","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"A pesquisa da Biblioteca usa prepare() com `LIKE ?`. Pesquisas `' OR 1=1 -- `. O que acontece?","codigo":"","linguagem":"","alternativas":["Devolve todos os livros da tabela.","Procura um título com esse texto e não encontra nenhum.","Dá um erro de sintaxe SQL por causa da plica que não fecha.","Apaga a tabela livros."],"correta":1,"explicacao":"Com parâmetros, o texto é tratado só como valor: a base de dados procura um título que contenha esse texto estranho. É o teste 19: não devolve tudo e não dá erro.","manual":"8.4, 16"},{"id":"pdo-057","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Num login vulnerável, que junta o email ao SQL, o que consegue um atacante com `' OR 1=1 -- `?","codigo":"","linguagem":"","alternativas":["Entrar sem saber a password.","Ver as passwords guardadas em texto.","Criar uma conta com um email repetido.","Roubar o cookie de sessão de outros."],"correta":0,"explicacao":"O manual avisa que, numa página de login, o mesmo truque entra sem password. Roubar cookies é o que faz um ataque de XSS.","manual":"8.4"},{"id":"pdo-058","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Segundo a regra do manual, este código está correto? O id já foi convertido com `(int)`.","codigo":"$id = (int) $_GET['id'];\n$stmt = $pdo->query(\"SELECT * FROM livros WHERE id_livro = $id\");","linguagem":"php","alternativas":["Sim: os números podem ir diretamente no SQL.","Sim, porque o query() também protege os valores numéricos.","Não: nenhuma variável entra no texto do SQL, nem os ids.","Não: o (int) tinha de vir depois do query()."],"correta":2,"explicacao":"A regra é simples: nenhuma variável dentro do texto do SQL, nem as que vêm do próprio site, nem os ids, nem os números. Usa-se prepare() com ? e execute([$id]).","manual":"8.4"},{"id":"pdo-059","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Este código usa prepare(). Está protegido contra injeção de SQL?","codigo":"$stmt = $pdo->prepare(\"SELECT * FROM livros WHERE id_autor = $idAutor\");\n$stmt->execute();","linguagem":"php","alternativas":["Sim: usar prepare() basta para estar protegido.","Sim, porque o SQL está entre aspas duplas.","Não: o prepare() não aceita aspas duplas.","Não: o valor devia ir num ? e no execute()."],"correta":3,"explicacao":"O prepare() só protege quando os valores vão em separado, no execute(). Se vires $ dentro das aspas de um prepare() ou de um query(), está mal.","manual":"8.4"},{"id":"pdo-060","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Que tipo de exceção lança o PDO quando uma consulta falha?","codigo":"","linguagem":"","alternativas":["SQLException","PDOException","MySQLError","DatabaseError"],"correta":1,"explicacao":"Com ERRMODE_EXCEPTION, as falhas do PDO lançam uma PDOException, que se apanha com catch (PDOException $e).","manual":"8.5"},{"id":"pdo-061","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Que método da exceção dá o código do erro, como 23000?","codigo":"","linguagem":"","alternativas":["$e->getCode()","$e->getMessage()","$e->getError()","$e->code()"],"correta":0,"explicacao":"getCode() dá o código (23000, por exemplo); getMessage() dá o texto completo do erro.","manual":"8.5"},{"id":"pdo-062","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"O que quer dizer o código 23000 numa PDOException?","codigo":"","linguagem":"","alternativas":["A base de dados indicada no DSN do db.php não existe no MySQL.","O MySQL está desligado no XAMPP Control Panel.","Violação de uma restrição, como um UNIQUE repetido.","O número de ? não bate certo com os valores."],"correta":2,"explicacao":"23000 é a violação de uma restrição de integridade: um valor repetido num campo UNIQUE ou uma chave estrangeira que impede a operação.","manual":"8.5"},{"id":"pdo-063","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Porque é que este catch faz `throw $e;` no else?","codigo":"} catch (PDOException $e) {\n    if ($e->getCode() == 23000) {\n        $erros[] = 'Já existe um livro com esse ISBN.';\n    } else {\n        throw $e;\n    }\n}","linguagem":"php","alternativas":["Para tentar gravar o livro mais uma vez.","Para mostrar a mensagem do ISBN repetido.","Para não esconder outros erros: só o 23000 é o ISBN repetido.","Para redirecionar o utilizador para a lista."],"correta":2,"explicacao":"Só o 23000 corresponde a um caso previsto. Qualquer outro erro (coluna mal escrita, MySQL desligado) é relançado, para não ser disfarçado de \"ISBN repetido\".","manual":"8.5"},{"id":"pdo-064","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Qual é o problema deste catch num INSERT de livros?","codigo":"} catch (PDOException $e) {\n    $erros[] = 'Já existe um livro com esse ISBN.';\n}","linguagem":"php","alternativas":["Falta um exit depois de acrescentar o erro.","Uma PDOException só se pode apanhar dentro de um if com getCode().","Qualquer erro seria mostrado como ISBN repetido.","O $erros[] não funciona dentro de um catch."],"correta":2,"explicacao":"Sem testar getCode() == 23000, um erro de programação ou o MySQL desligado também dariam \"Já existe um livro com esse ISBN.\", e ficavas sem saber o que se passou.","manual":"8.5"},{"id":"pdo-065","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Gravas um livro com um ISBN que já existe. O que vê o utilizador?","codigo":"try {\n    $stmt = $pdo->prepare('INSERT INTO livros (...) VALUES (?, ?, ?, ?, ?)');\n    $stmt->execute([...]);\n    $novoId = $pdo->lastInsertId();\n    mensagem('sucesso', 'Livro criado.');\n    header(\"Location: livro_ver.php?id=$novoId\");\n    exit;\n} catch (PDOException $e) {\n    if ($e->getCode() == 23000) {\n        $erros[] = 'Já existe um livro com esse ISBN.';\n    } else { throw $e; }\n}","linguagem":"php","alternativas":["O formulário outra vez, com o erro e os valores escritos.","A página do livro, com a mensagem \"Livro criado.\"","Uma página de erro do servidor, com o código 500 e a exceção.","A lista de livros, com uma mensagem de erro."],"correta":0,"explicacao":"O execute() lança a exceção antes do mensagem() e do header(), por isso não há redirecionamento. O catch põe o erro em $erros e a página mostra o formulário com os valores.","manual":"8.5, 12.4"},{"id":"pdo-066","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Porque é que o header() e o exit estão dentro do try, logo a seguir ao execute() do INSERT?","codigo":"","linguagem":"","alternativas":["Porque o header() só funciona dentro de um try.","Só se redireciona se o INSERT não lançar exceção.","Para o catch poder apanhar também os erros do header().","Para o exit fechar a ligação à base de dados."],"correta":1,"explicacao":"Se o execute() falhar, a execução salta logo para o catch e as linhas seguintes do try não correm. Assim, só há mensagem de sucesso e redirecionamento quando o livro foi gravado.","manual":"12.4, 8.5"},{"id":"pdo-067","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Se o livro_novo.php não tivesse try/catch e o ISBN fosse repetido, o que acontecia?","codigo":"","linguagem":"","alternativas":["O livro era gravado na mesma, duplicado.","A página parava com o erro da PDOException.","O MySQL substituía o livro que já existia com esse ISBN.","O ISBN era gravado como NULL."],"correta":1,"explicacao":"O UNIQUE impede sempre o duplicado. Sem catch, a exceção não é tratada e aparece a página de erro, em vez de uma mensagem clara (o teste 12 exige que não apareça).","manual":"8.5, 16"},{"id":"pdo-068","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Vê a tabela livros e o autor_apagar.php. Quem garante que um autor com livros não é apagado?","codigo":"-- tabela livros\nCONSTRAINT fk_livros_autores\n    FOREIGN KEY (id_autor) REFERENCES autores (id_autor)\n    ON DELETE RESTRICT\n\n// autor_apagar.php\ntry {\n    $stmt = $pdo->prepare('DELETE FROM autores WHERE id_autor = ?');\n    $stmt->execute([(int) ($_POST['id_autor'] ?? 0)]);\n    mensagem('sucesso', 'Autor apagado.');\n} catch (PDOException $e) {\n    mensagem('erro', 'Não é possível apagar este autor, porque tem livros registados.');\n}","linguagem":"php","alternativas":["Um if no autor_apagar.php que conta antes os livros desse autor.","O JavaScript, com o confirm() antes de apagar.","A base de dados, pelo ON DELETE RESTRICT da chave estrangeira.","O auth.php, que só deixa apagar ao administrador."],"correta":2,"explicacao":"Não é o código que verifica: é a base de dados que recusa o DELETE. O PHP só apanha a exceção e explica o que se passou. A regra vale até no phpMyAdmin.","manual":"13.3, 3.3"},{"id":"pdo-069","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Tentas apagar o José Saramago, que tem livros. O que acontece?","codigo":"try {\n    $stmt = $pdo->prepare('DELETE FROM autores WHERE id_autor = ?');\n    $stmt->execute([(int) ($_POST['id_autor'] ?? 0)]);\n    mensagem('sucesso', 'Autor apagado.');\n} catch (PDOException $e) {\n    mensagem('erro', 'Não é possível apagar este autor, porque tem livros registados.');\n}\nheader('Location: autores.php');\nexit;","linguagem":"php","alternativas":["O autor e os seus livros são apagados.","O DELETE falha e a lista mostra a mensagem de erro.","O autor é apagado e os seus livros ficam com id_autor vazio.","Aparece o erro 1451 numa página de erro."],"correta":1,"explicacao":"O RESTRICT faz o DELETE lançar uma PDOException, por isso o mensagem('sucesso', ...) não chega a correr. O catch guarda a mensagem de erro e a página redireciona para autores.php.","manual":"13.3"},{"id":"pdo-070","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Gravas um segundo livro com o mesmo ISBN e não há try/catch. Que erro técnico aparece?","codigo":"","linguagem":"","alternativas":["SQLSTATE[23000] ... 1451 Cannot delete or update a parent row","SQLSTATE[42S22] ... Unknown column","SQLSTATE[23000] ... 1062 Duplicate entry","SQLSTATE[HY093]: Invalid parameter number"],"correta":2,"explicacao":"Um valor repetido num campo UNIQUE dá 23000 com 1062 Duplicate entry. O 1451 também é 23000, mas é a chave estrangeira a impedir apagar.","manual":"17.2"},{"id":"pdo-071","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Tentas apagar no phpMyAdmin um autor que tem livros. Que erro aparece?","codigo":"DELETE FROM autores WHERE id_autor = 1;","linguagem":"sql","alternativas":["SQLSTATE[23000] ... 1062 Duplicate entry","SQLSTATE[HY000] [1045] Access denied","Nenhum: apaga o autor e os seus livros","SQLSTATE[23000] ... 1451 Cannot delete or update a parent row"],"correta":3,"explicacao":"Com ON DELETE RESTRICT, a base de dados recusa apagar o \"pai\" que ainda tem \"filhos\": é o erro 1451, com o código 23000. Apagar também os livros seria ON DELETE CASCADE.","manual":"17.2, 3.3"},{"id":"pdo-072","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Porque é que validar_livro() confirma na base de dados que o autor escolhido existe?","codigo":"","linguagem":"","alternativas":["Alguém podia alterar o formulário e enviar id_autor=999.","Porque o <select> envia o nome do autor escolhido e não o id.","Para o JOIN da lista não devolver NULL.","Porque o (int) pode trocar o id escolhido."],"correta":0,"explicacao":"O <select> só mostra os autores que existem, mas o pedido pode ser alterado. A validação no servidor confirma o id com SELECT COUNT(*).","manual":"12.4"},{"id":"pdo-073","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"O pedido chega com `id_autor=999`, que não existe. O que acontece?","codigo":"$stmt = $pdo->prepare('SELECT COUNT(*) FROM autores WHERE id_autor = ?');\n$stmt->execute([$livro['id_autor']]);\nif ($stmt->fetchColumn() == 0) {\n    $erros[] = 'Escolhe um autor da lista.';\n}","linguagem":"php","alternativas":["O COUNT dá 0 e é acrescentado o erro do autor.","O fetchColumn() dá false e a validação passa.","O execute() lança uma PDOException com o código 23000.","O livro é gravado com o autor 999."],"correta":0,"explicacao":"O COUNT(*) devolve sempre uma linha: aqui com o valor 0. Como é 0, entra o erro \"Escolhe um autor da lista.\" e o INSERT não é feito.","manual":"12.4"},{"id":"pdo-074","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"O formulário foi alterado e envia `id_autor=abc`. O que acontece?","codigo":"// ler_livro()\n'id_autor' => (int) ($_POST['id_autor'] ?? 0),\n\n// validar_livro()\n$stmt = $pdo->prepare('SELECT COUNT(*) FROM autores WHERE id_autor = ?');\n$stmt->execute([$livro['id_autor']]);\nif ($stmt->fetchColumn() == 0) {\n    $erros[] = 'Escolhe um autor da lista.';\n}","linguagem":"php","alternativas":["O SQL recebe o texto abc e devolve todos os autores da tabela.","Dá SQLSTATE[42S22] Unknown column 'abc'.","O (int) dá 0, que não existe: aparece o erro do autor.","O livro é gravado sem autor."],"correta":2,"explicacao":"O (int) converte o texto em 0. A validação conta os autores com id 0, obtém 0 e acrescenta o erro \"Escolhe um autor da lista.\"","manual":"12.4"},{"id":"pdo-075","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Para que serve o `?: null` nos campos opcionais do INSERT?","codigo":"$livro['isbn'] ?: null,","linguagem":"php","alternativas":["Impedir que o utilizador deixe o campo vazio.","Converter o valor do campo num número inteiro.","Dar um erro de validação sempre que o campo opcional vier vazio.","Gravar NULL em vez de texto vazio quando o campo vem vazio."],"correta":3,"explicacao":"Se o valor estiver vazio, o ?: usa o que está à direita: null. Os campos opcionais vazios ficam NULL na base de dados, não ''.","manual":"12.4"},{"id":"pdo-076","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"O utilizador preencheu só o título, o autor e o ano 1888. Que valores vão para os três últimos `?` (isbn, ano, sinopse)?","codigo":"$stmt->execute([\n    $livro['titulo'],\n    $livro['id_autor'],\n    $livro['isbn'] ?: null,\n    $livro['ano_edicao'] ?: null,\n    $livro['sinopse'] ?: null,\n]);","linguagem":"php","alternativas":["'', '1888', ''","NULL, NULL, NULL","'1888', NULL, NULL","NULL, '1888', NULL"],"correta":3,"explicacao":"O isbn e a sinopse vêm vazios e passam a null; o ano tem valor e fica igual. A ordem é a dos ?: isbn, ano_edicao, sinopse.","manual":"12.4, 8.2"},{"id":"pdo-077","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Ao abrir a aplicação aparece `SQLSTATE[HY000] [2002] ... connection refused`. Qual é a causa provável?","codigo":"","linguagem":"","alternativas":["A password em db.php está errada.","O MySQL está desligado.","A base de dados não foi importada.","Uma coluna tem o nome mal escrito."],"correta":1,"explicacao":"2002 quer dizer que nem foi possível ligar ao servidor: falta carregar em Start no MySQL do XAMPP Control Panel.","manual":"17.2"},{"id":"pdo-078","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"Aparece `SQLSTATE[HY000] [1049] Unknown database 'biblioteca'`. O que deves verificar?","codigo":"","linguagem":"","alternativas":["Se o MySQL está ligado no XAMPP Control Panel (botão Start).","Se o utilizador root tem a password certa.","Se o DSN tem charset=utf8mb4 no fim.","Se a base de dados existe e o $bd do db.php está certo."],"correta":3,"explicacao":"1049 diz que o MySQL está a funcionar mas não tem nenhuma base de dados com esse nome: ou não foi criada, ou o $bd no db.php está mal escrito.","manual":"17.2"},{"id":"pdo-079","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Aparece `SQLSTATE[HY000] [1045] Access denied for user 'root'`. Qual é a causa provável?","codigo":"","linguagem":"","alternativas":["O utilizador ou a password em db.php estão errados.","O utilizador ainda não iniciou sessão na aplicação Biblioteca.","A página não tem o require do auth.php.","O MySQL está desligado no XAMPP."],"correta":0,"explicacao":"1045 é a recusa das credenciais do MySQL. No XAMPP o root não tem password. Não tem nada a ver com o login na aplicação.","manual":"17.2"},{"id":"pdo-080","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"Que erro dá esta consulta?","codigo":"$stmt = $pdo->prepare('SELECT titlo FROM livros WHERE id_livro = ?');\n$stmt->execute([$id]);","linguagem":"php","alternativas":["SQLSTATE[HY093]: Invalid parameter number","SQLSTATE[HY000] [1049] Unknown database 'titlo'","SQLSTATE[42S22] ... Unknown column 'titlo'","Nenhum: o fetch() devolve false"],"correta":2,"explicacao":"A coluna chama-se titulo e está escrita titlo: é o 42S22. Há um ? e um valor, por isso não é HY093. Com ERRMODE_EXCEPTION, o erro aparece, não fica em silêncio.","manual":"17.2"},{"id":"pdo-081","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"A lista mostra \"JosÃ©\" em vez de \"José\". Qual é a causa provável?","codigo":"","linguagem":"","alternativas":["Falta htmlspecialchars() quando se mostra o nome na página da lista.","A coluna nome é VARCHAR em vez de TEXT.","Os dados foram gravados ou lidos com a codificação errada.","O fetch() foi feito sem PDO::FETCH_ASSOC."],"correta":2,"explicacao":"É um problema de codificação. Resolve-se com charset=utf8mb4 no db.php, SET NAMES utf8mb4 no .sql e os ficheiros gravados em UTF-8.","manual":"17.2, 8.1"},{"id":"pdo-082","bloco":"php","tema":"PDO","dificuldade":"media","pergunta":"A mesma página serve para criar e editar um autor. Vendo este excerto do autor_form.php, como sabe a página se faz INSERT ou UPDATE?","codigo":"$id = (int) ($_GET['id'] ?? 0);\n// ...\nif (!$erros) {\n    if ($id > 0) {\n        $stmt = $pdo->prepare('UPDATE autores SET nome = ?, nacionalidade = ? WHERE id_autor = ?');\n        $stmt->execute([$autor['nome'], $autor['nacionalidade'] ?: null, $id]);\n        mensagem('sucesso', 'Autor atualizado.');\n    } else {\n        $stmt = $pdo->prepare('INSERT INTO autores (nome, nacionalidade) VALUES (?, ?)');\n        $stmt->execute([$autor['nome'], $autor['nacionalidade'] ?: null]);\n        mensagem('sucesso', 'Autor criado.');\n    }\n    header('Location: autores.php');\n    exit;\n}","linguagem":"php","alternativas":["Pelo id no endereço: com $id > 0 faz UPDATE, sem id faz INSERT.","Pelo método do pedido: um GET faz o INSERT e um POST faz o UPDATE.","Pelo rowCount() de um SELECT feito antes.","Pelo lastInsertId(): se der 0, faz INSERT."],"correta":0,"explicacao":"Sem ?id= a página cria, com ?id= edita. Os dois casos gravam com POST; o GET só mostra o formulário.","manual":"13.2"},{"id":"pdo-083","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Em livro_editar.php, para que serve este SELECT no pedido GET?","codigo":"$stmt = $pdo->prepare('SELECT * FROM livros WHERE id_livro = ?');\n$stmt->execute([$id]);\n$livro = $stmt->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["Confirmar que o utilizador tem sessão iniciada.","Carregar o livro para preencher o formulário.","Contar quantos livros tem o autor escolhido.","Verificar se o ISBN já existe noutro livro."],"correta":1,"explicacao":"No GET, o formulário de edição é preenchido com os dados que já estão na base de dados. O fetch() devolve a linha do livro, ou false se não existir.","manual":"12.5"},{"id":"pdo-084","bloco":"php","tema":"PDO","dificuldade":"facil","pergunta":"Na página \"A minha conta\", de onde vem o valor do `?` deste SELECT?","codigo":"$stmt = $pdo->prepare('SELECT nome, email FROM utilizadores WHERE id_utilizador = ?');\n$stmt->execute([________]);","linguagem":"php","alternativas":["$_GET['id'], vindo do endereço da página","$_SESSION['id_utilizador'], guardado no login","$_POST['id_utilizador'], de um campo hidden","$pdo->lastInsertId(), do INSERT do registo"],"correta":1,"explicacao":"O id do utilizador com sessão iniciada está na sessão desde o login. Um id vindo do endereço ou do formulário podia ser trocado para ver os dados de outra pessoa.","manual":"15.4"},{"id":"pdo-085","bloco":"php","tema":"PDO","dificuldade":"dificil","pergunta":"O utilizador apagou a nacionalidade do autor 4 e gravou. Que valores vão para os três `?`?","codigo":"$stmt = $pdo->prepare('UPDATE autores SET nome = ?, nacionalidade = ? WHERE id_autor = ?');\n$stmt->execute([$autor['nome'], $autor['nacionalidade'] ?: null, $id]);\n// $autor['nome'] = 'Machado de Assis', $autor['nacionalidade'] = '', $id = 4","linguagem":"php","alternativas":["'Machado de Assis', '', 4","4, 'Machado de Assis', NULL","'Machado de Assis', NULL, 4","'Machado de Assis', NULL, NULL"],"correta":2,"explicacao":"Os valores seguem a ordem dos ?: nome, nacionalidade e o id do WHERE. A nacionalidade vazia passa a NULL por causa do ?: null; o id continua a ser 4.","manual":"13.2, 8.2"},{"id":"amostra-012","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Qual é o problema deste livro_apagar.php?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/auth.php';\n\nif ($_SERVER['REQUEST_METHOD'] !== 'POST') {\n    header('Location: livros.php');\n}\n\n$stmt = $pdo->prepare('DELETE FROM livros WHERE id_livro = ?');\n$stmt->execute([(int) ($_POST['id_livro'] ?? 0)]);","linguagem":"php","alternativas":["Falta o exit depois do header(): num pedido GET, o resto da página continua a ser executado.","O header() tinha de vir depois do DELETE.","O (int) impede que o livro seja apagado.","Para apagar devia usar-se $_GET em vez de $_POST."],"correta":0,"explicacao":"O header() só manda o browser ir para outra página; o PHP continua a correr. O exit logo a seguir é obrigatório, senão o código abaixo (aqui, o DELETE) é executado na mesma.","manual":"7.7, 12.6"},{"id":"prg-001","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"O que faz `header('Location: livros.php');`?","codigo":"","linguagem":"","alternativas":["Inclui o livros.php no fim da página atual.","Escreve na página um link para livros.php.","Mostra o livros.php dentro de um <header>.","Manda o browser pedir a página livros.php."],"correta":3,"explicacao":"O header('Location: ...') responde ao browser com um redirecionamento: é o browser que faz um novo pedido a essa página.","manual":"7.7"},{"id":"prg-002","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Que código de estado HTTP acompanha um `header('Location: ...')`?","codigo":"","linguagem":"","alternativas":["200","302","404","500"],"correta":1,"explicacao":"302 é o redirecionamento: depois de gravar, o servidor manda o browser ir a outra página. 200 é OK, 404 não encontrado e 500 erro no servidor.","manual":"1.3, 7.7"},{"id":"prg-003","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Porque é que o `exit;` a seguir ao header() é obrigatório?","codigo":"","linguagem":"","alternativas":["Sem ele, o browser não chega a seguir o redirecionamento 302.","Fecha a sessão antes de mudar de página.","Sem ele, o PHP continuaria a executar o resto da página.","É ele que envia o código 302 ao browser."],"correta":2,"explicacao":"O header() não para o script: só acrescenta o cabeçalho à resposta. O exit garante que nada do que vem a seguir é executado.","manual":"7.7"},{"id":"prg-004","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Qual é o problema deste auth.php?","codigo":"<?php\nif (!isset($_SESSION['id_utilizador'])) {\n    mensagem('erro', 'Tens de iniciar sessão para ver essa página.');\n    header('Location: login.php');\n}","linguagem":"php","alternativas":["Falta um session_destroy() antes do header().","O header() devia vir depois do HTML da página.","Devia redirecionar com um echo do endereço e não com header().","Sem exit, o resto da página restrita continua a ser executado."],"correta":3,"explicacao":"O header() só pede ao browser para mudar de página. Sem exit, o PHP continua e corre o resto da página restrita (consultas, apagar, etc.) para quem não tem sessão.","manual":"7.7, 11.2"},{"id":"prg-005","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Qual é a forma certa de redirecionar depois de gravar?","codigo":"","linguagem":"","alternativas":["header('lista.php'); exit;","location('lista.php'); exit;","header('Location: lista.php'); exit;","include 'lista.php'; exit;"],"correta":2,"explicacao":"O cabeçalho tem de ser Location: seguido do endereço, e logo a seguir exit. O include não redireciona: junta outro ficheiro à página atual, no mesmo pedido POST.","manual":"7.7, Anexo B"},{"id":"prg-006","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"No separador Rede (F12), o que vês depois de gravar um livro na Biblioteca?","codigo":"","linguagem":"","alternativas":["Um POST com resposta 302, seguido de um GET à página do livro.","Só um POST, com resposta 200 e a página do livro já preenchida.","Um GET com resposta 302, seguido de um POST.","Um POST com resposta 404, seguido de um GET."],"correta":0,"explicacao":"O formulário envia um POST; o servidor grava e responde com 302; o browser faz então um GET a livro_ver.php?id=... É o Post/Redirect/Get.","manual":"1.3, 9.5"},{"id":"prg-007","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"O que causa o aviso \"Cannot modify header information - headers already sent\"?","codigo":"","linguagem":"","alternativas":["O header() foi chamado duas vezes na página.","A página de destino do Location não existe.","Falta o exit a seguir ao header().","Foi enviado HTML, ou um espaço, antes do header()."],"correta":3,"explicacao":"Os cabeçalhos vão antes do conteúdo da resposta. Depois de sair HTML (mesmo um espaço), já não se podem alterar.","manual":"17.1, 7.7"},{"id":"prg-008","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Ao gravar um autor aparece \"headers already sent\". Porquê?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/auth.php';\n$titulo = 'Novo autor';\nrequire 'includes/cabecalho.php';\nif ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    // ... gravar\n    header('Location: autores.php');\n    exit;\n}","linguagem":"php","alternativas":["O cabeçalho já escreveu HTML antes do header().","Falta o require do db.php antes do auth.php.","O exit devia vir antes do header().","O $titulo só pode ser definido depois do bloco do POST."],"correta":0,"explicacao":"O cabecalho.php envia o <!DOCTYPE html> e o resto do topo. O POST tem de ser tratado antes desse require: primeiro processa-se, depois mostra-se.","manual":"7.8, 17.1"},{"id":"prg-009","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Segundo o manual, como se resolve o \"headers already sent\"?","codigo":"","linguagem":"","alternativas":["Processar o formulário antes do require do cabeçalho.","Pôr o header() dentro do ficheiro includes/cabecalho.php.","Trocar o header() por um echo com o endereço.","Chamar o exit antes do require do cabeçalho."],"correta":0,"explicacao":"O tratamento do POST, com o seu header(), tem de acontecer antes de qualquer HTML. O manual indica também tirar o ?> do fim dos ficheiros só de PHP.","manual":"17.1"},{"id":"prg-010","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Porque é que o manual manda tirar o `?>` do fim dos ficheiros que só têm PHP, como o db.php?","codigo":"","linguagem":"","alternativas":["Um espaço depois do ?> seria enviado e impedia o header().","Com o ?> no fim, o PHP deixa de ler os ficheiros incluídos.","Sem o ?>, o ficheiro é lido mais depressa pelo servidor.","O ?> no fim apaga as variáveis definidas no ficheiro."],"correta":0,"explicacao":"Tudo o que está fora de <?php ... ?> é enviado ao browser, mesmo uma linha em branco. Isso basta para dar \"headers already sent\" num redirecionamento seguinte.","manual":"17.1"},{"id":"prg-011","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Em que momento da página tem de ser chamado o header() de um redirecionamento?","codigo":"","linguagem":"","alternativas":["Depois do require do rodapé.","Antes de qualquer HTML ser enviado.","Em qualquer ponto, desde que haja exit.","Logo a seguir à tag <body>."],"correta":1,"explicacao":"O header() tem de acontecer antes de qualquer HTML. Por isso as páginas tratam o POST antes de incluir o cabeçalho.","manual":"7.7"},{"id":"prg-012","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Qual é a ordem do padrão das páginas com formulário?","codigo":"","linguagem":"","alternativas":["inicio → mostrar HTML → auth → tratar o POST → preparar dados","inicio → auth → tratar o POST → preparar dados → mostrar HTML","auth → inicio → preparar dados → mostrar HTML → tratar o POST","inicio → auth → mostrar HTML → tratar o POST → preparar os dados"],"correta":1,"explicacao":"Preparar (sessão e ligação), proteger, tratar o POST (ler, validar, gravar, redirecionar), preparar os dados e só no fim mostrar o HTML.","manual":"7.8"},{"id":"prg-013","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Qual é a regra que resume o padrão das páginas da Biblioteca?","codigo":"","linguagem":"","alternativas":["Primeiro mostra-se, depois processa-se.","Primeiro redireciona-se, depois valida-se.","Primeiro processa-se, depois mostra-se.","Primeiro grava-se, depois valida-se."],"correta":2,"explicacao":"Se a página escrevesse HTML antes de processar o formulário, já não podia redirecionar.","manual":"7.8"},{"id":"prg-014","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"No passo 3 do padrão, o que se faz quando o pedido é POST?","codigo":"","linguagem":"","alternativas":["Mostrar o formulário vazio ao utilizador.","Ler, gravar, mostrar o HTML e redirecionar.","Ler, validar, gravar e redirecionar.","Validar só no browser e reenviar os dados."],"correta":2,"explicacao":"O bloco if ($_SERVER['REQUEST_METHOD'] === 'POST') lê os campos, valida-os no servidor, grava e redireciona. Mostrar o HTML é o último passo, e nunca antes do redirecionamento.","manual":"7.8"},{"id":"prg-015","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Como sabe a página que o pedido é o envio do formulário?","codigo":"","linguagem":"","alternativas":["$_POST['method'] === 'POST'","$_SESSION['metodo'] === 'POST'","$_SERVER['REQUEST_METHOD'] === 'POST'","$_GET['REQUEST_METHOD'] === 'POST'"],"correta":2,"explicacao":"$_SERVER['REQUEST_METHOD'] tem o método do pedido: 'GET' quando se abre a página e 'POST' quando se envia o formulário.","manual":"7.5, 7.8"},{"id":"prg-016","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Porque é que `$autores = lista_autores($pdo);` vem depois do bloco do POST e não antes?","codigo":"","linguagem":"","alternativas":["Porque o prepare() só funciona depois de tratar um POST.","Só serve para mostrar o formulário, e se gravar redireciona.","Porque o bloco do POST apaga as variáveis definidas antes.","Porque é a função lista_autores() que faz o redirecionamento."],"correta":1,"explicacao":"O passo 4 prepara os dados que o HTML vai mostrar. Se o POST correr bem, a página redireciona e sai com exit, por isso não vale a pena carregá-los antes.","manual":"7.8, 12.4"},{"id":"prg-017","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Abres `livro_novo.php` pela primeira vez, com um link. O que acontece?","codigo":"$erros = [];\n$livro = ['titulo' => '', 'id_autor' => 0, 'isbn' => '', 'ano_edicao' => '', 'sinopse' => ''];\n\nif ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    $livro = ler_livro();\n    $erros = validar_livro($pdo, $livro);\n    // ... gravar e redirecionar\n}\n\n$autores = lista_autores($pdo);","linguagem":"php","alternativas":["Grava um livro vazio e redireciona para ele.","Mostra logo os erros de validação dos campos obrigatórios.","Redireciona logo para a lista de livros.","Salta o bloco do POST e mostra o formulário vazio."],"correta":3,"explicacao":"Um link é um pedido GET, por isso o if não entra. Fica o $livro com valores vazios e $erros vazio, e a página mostra o formulário em branco.","manual":"12.4, 7.8"},{"id":"prg-018","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Porque se redireciona depois de um POST bem sucedido?","codigo":"","linguagem":"","alternativas":["Para a página seguinte carregar mais depressa.","Para o F5 não voltar a enviar o formulário.","Para o browser guardar a password escrita.","Para limpar a sessão do utilizador."],"correta":1,"explicacao":"Depois do redirecionamento, o último pedido do browser é um GET. Atualizar a página já não repete o POST.","manual":"9.5, Anexo B"},{"id":"prg-019","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Como se chama o padrão \"gravar com POST, responder com um redirecionamento e mostrar com GET\"?","codigo":"","linguagem":"","alternativas":["Post/Redirect/Get","Get/Post/Redirect","Request/Response","Model-View-Controller"],"correta":0,"explicacao":"É o Post/Redirect/Get: depois de um POST bem sucedido, o servidor não mostra uma página, manda o browser pedir outra.","manual":"9.5"},{"id":"prg-020","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Uma página grava o livro e responde ao POST mostrando logo \"Livro criado.\", sem redirecionar. O utilizador carrega em F5. O que acontece?","codigo":"","linguagem":"","alternativas":["A página volta a mostrar a mesma mensagem, sem gravar nada de novo na base.","O browser faz um GET e mostra a lista de livros.","O browser pede para reenviar e o livro pode ficar gravado duas vezes.","O PHP deteta o pedido repetido e ignora-o."],"correta":2,"explicacao":"Sem redirecionamento, o último pedido foi o POST. O F5 repete-o (com o aviso \"Confirmar reenvio do formulário\") e o INSERT corre outra vez.","manual":"9.5"},{"id":"prg-021","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"O que quer dizer o aviso do browser \"Confirmar reenvio do formulário\"?","codigo":"","linguagem":"","alternativas":["Que o formulário tem erros de validação.","Que atualizar a página vai repetir o último POST.","Que a sessão expirou e é preciso novo login.","Que o servidor respondeu com o código 302."],"correta":1,"explicacao":"Aparece quando a página atual é a resposta a um POST. É exatamente o que o Post/Redirect/Get evita.","manual":"9.5"},{"id":"prg-022","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Com o Post/Redirect/Get, porque é que o F5 depois de gravar já não faz mal?","codigo":"","linguagem":"","alternativas":["O último pedido foi um GET, e repetir um GET não altera dados.","O servidor apaga o $_POST logo depois de gravar.","O exit impede o browser de atualizar a página.","A sessão guarda o formulário e bloqueia-o."],"correta":0,"explicacao":"Depois do 302, o browser pediu a página com GET. Atualizar repete esse GET, que só lê dados.","manual":"9.5, 1.2"},{"id":"prg-023","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Que teste confirma que o Post/Redirect/Get está a funcionar?","codigo":"","linguagem":"","alternativas":["Abrir o detalhe de um id que não existe e ver o código 404.","Enviar o formulário vazio com o JavaScript desligado.","F5 logo depois de criar não cria um segundo registo.","Pesquisar ' OR 1=1 -- e ver que não devolve tudo."],"correta":2,"explicacao":"É o teste 13 do capítulo 16: F5 logo depois de criar não pode criar um segundo registo.","manual":"16, 9.5"},{"id":"prg-024","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Quando a validação no servidor falha, o que faz a página?","codigo":"","linguagem":"","alternativas":["Redireciona para o formulário vazio, com uma mensagem flash.","Mostra o formulário com os erros e os valores escritos.","Redireciona para a lista, com a mensagem de erro.","Mostra uma página de erro com o código 500."],"correta":1,"explicacao":"O redirecionamento é só para o caso de sucesso. Com erros, a página é mostrada logo, com a lista de erros e o que o utilizador já tinha escrito.","manual":"9.5"},{"id":"prg-025","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Este código trata a validação falhada. Qual é o problema?","codigo":"$erros = validar_livro($pdo, $livro);\nif ($erros) {\n    mensagem('erro', 'Corrige os erros.');\n    header('Location: livro_novo.php');\n    exit;\n}","linguagem":"php","alternativas":["Perdem-se os erros detalhados e tudo o que foi escrito.","Falta chamar session_start() antes de usar a função mensagem().","O header() devia apontar para livro_ver.php.","O exit apaga a mensagem antes de ser mostrada."],"correta":0,"explicacao":"O redirecionamento faz um pedido novo: o $erros e o $livro deixam de existir e o formulário volta vazio. Quando a validação falha, não se redireciona.","manual":"9.4, 9.5"},{"id":"prg-026","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Porque é que o título escrito volta a aparecer no formulário quando há um erro de validação?","codigo":"$livro = ler_livro();          // no POST\n...\n<input type=\"text\" id=\"titulo\" name=\"titulo\"\n       value=\"<?= htmlspecialchars($livro['titulo']) ?>\">","linguagem":"php","alternativas":["O browser guarda os valores escritos na sessão do utilizador.","O redirecionamento leva os valores no endereço.","O $livro tem os valores do POST e o formulário mostra-os.","O atributo required repõe os valores sozinho."],"correta":2,"explicacao":"Como não há redirecionamento, a mesma execução que leu o POST mostra o formulário, com o $livro preenchido no value de cada campo.","manual":"12.4, 9.5"},{"id":"prg-027","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Em livro_novo.php, quando é que há redirecionamento?","codigo":"","linguagem":"","alternativas":["Sempre que o pedido é POST.","Quando não há erros e o INSERT corre bem.","Sempre que há erros de validação.","Só quando o pedido é GET."],"correta":1,"explicacao":"O header() está depois da validação e dentro do try, a seguir ao INSERT. Com erros de validação ou ISBN repetido, a página volta a mostrar o formulário.","manual":"12.4, 9.5"},{"id":"prg-028","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Onde é que a função mensagem() guarda o texto a mostrar?","codigo":"function mensagem($tipo, $texto)\n{\n    // ...\n}","linguagem":"php","alternativas":["$_SESSION['msg']","$_POST['msg']","$_GET['msg']","$erros[]"],"correta":0,"explicacao":"mensagem() faz $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto]. Só a sessão sobrevive ao redirecionamento.","manual":"9.1, 9.3"},{"id":"prg-029","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Porque é que a mensagem \"Livro criado.\" tem de passar pela sessão?","codigo":"","linguagem":"","alternativas":["Porque é criada num pedido e mostrada no seguinte.","Porque o $_POST não consegue guardar textos com acentos.","Porque a sessão protege a mensagem contra ataques de XSS.","Porque o cabeçalho não consegue ler variáveis normais."],"correta":0,"explicacao":"O redirecionamento faz o browser pedir outra página: as variáveis do primeiro pedido perdem-se. A sessão leva a mensagem de um pedido para o outro.","manual":"9.3"},{"id":"prg-030","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"O que faz o `unset` neste excerto do cabeçalho?","codigo":"<?php if (isset($_SESSION['msg'])): ?>\n    <div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\">\n        <?= htmlspecialchars($_SESSION['msg']['texto']) ?>\n    </div>\n    <?php unset($_SESSION['msg']); ?>\n<?php endif; ?>","linguagem":"php","alternativas":["Esconde a mensagem com CSS até ser clicada.","Termina a sessão do utilizador.","Apaga todos os dados guardados em $_SESSION.","Apaga a mensagem, para só ser mostrada uma vez."],"correta":3,"explicacao":"Mostra-se uma vez e apaga-se. Só a chave msg é removida: a sessão e o id do utilizador continuam.","manual":"9.2, 9.3"},{"id":"prg-031","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Depois de criar um livro, vês \"Livro criado.\" e carregas em F5. O que aparece?","codigo":"","linguagem":"","alternativas":["A página do livro, com a mensagem outra vez.","O aviso \"Confirmar reenvio do formulário\".","Um segundo livro igual, com a mensagem.","A página do livro, sem a mensagem."],"correta":3,"explicacao":"O F5 repete o GET a livro_ver.php, que só lê. A mensagem já foi mostrada e apagada da sessão, por isso não volta a aparecer.","manual":"9.3, 9.5"},{"id":"prg-032","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Se tirasses o `unset($_SESSION['msg'])` do cabeçalho, o que acontecia?","codigo":"","linguagem":"","alternativas":["A mensagem aparecia em todas as páginas seguintes.","A mensagem nunca chegava a aparecer.","Dava o erro \"headers already sent\".","A mensagem só aparecia depois de carregar em F5 na página."],"correta":0,"explicacao":"A mensagem ficava na sessão e o cabeçalho, que é incluído em todas as páginas, mostrava-a sempre, até ser substituída por outra.","manual":"9.2, 9.3"},{"id":"prg-033","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Que HTML escreve o cabeçalho depois de `mensagem('erro', 'Esse livro não existe.');`?","codigo":"// includes/inicio.php\nfunction mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}\n\n// includes/cabecalho.php\n<?php if (isset($_SESSION['msg'])): ?>\n    <div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\"><?= htmlspecialchars($_SESSION['msg']['texto']) ?></div>\n    <?php unset($_SESSION['msg']); ?>\n<?php endif; ?>","linguagem":"php","alternativas":["<div class=\"msg sucesso\">Esse livro não existe.</div>","<div class=\"msg erro\">Esse livro não existe.</div>","<div id=\"erro\">Esse livro não existe.</div>","<div class=\"msg\">erro: Esse livro não existe.</div>"],"correta":1,"explicacao":"O tipo entra no atributo class, ao lado de msg: class=\"msg erro\". O texto vai dentro da div, escapado com htmlspecialchars().","manual":"9.2, 9.3"},{"id":"prg-034","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Para que serve o tipo ('sucesso' ou 'erro') de uma mensagem?","codigo":"","linguagem":"","alternativas":["Decide se a página redireciona ou não.","Escolhe o código de estado HTTP da resposta.","Indica se a mensagem fica na sessão para sempre.","É usado como classe CSS, que dá a cor verde ou vermelha."],"correta":3,"explicacao":"O cabeçalho escreve class=\"msg sucesso\" ou class=\"msg erro\", e a folha de estilos dá a cor a cada uma.","manual":"9.3"},{"id":"prg-035","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Qual é o problema deste final de autor_form.php?","codigo":"header('Location: autores.php');\nexit;\nmensagem('sucesso', 'Autor criado.');","linguagem":"php","alternativas":["A mensagem nunca é guardada: o exit para o script antes.","Dá \"headers already sent\", porque a mensagem é HTML.","A mensagem aparece duas vezes seguidas na lista de autores.","A mensagem só aparece depois de um F5 na lista."],"correta":0,"explicacao":"Depois do exit não corre mais nada. O mensagem() tem de vir antes do header(), para ficar guardado na sessão antes de o browser mudar de página.","manual":"7.7, 9.3"},{"id":"prg-037","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Como se chama, em inglês, uma mensagem guardada para ser mostrada uma só vez na página seguinte?","codigo":"","linguagem":"","alternativas":["cookie","session cookie","flash message","alert box"],"correta":2,"explicacao":"É a flash message: fica na sessão, é mostrada uma vez pelo cabeçalho e apagada logo a seguir.","manual":"9.3"},{"id":"prg-038","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Porque é que os erros de validação não precisam da sessão, ao contrário das mensagens de sucesso?","codigo":"","linguagem":"","alternativas":["São mostrados pelo JavaScript, no browser, antes de enviar.","Ficam guardados na base de dados.","A página é mostrada logo, sem redirecionamento.","O $_POST guarda-os até ao pedido seguinte."],"correta":2,"explicacao":"Os erros ficam num array $erros e são mostrados na mesma execução, porque quando a validação falha não se redireciona.","manual":"9.4"},{"id":"prg-039","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"Quando é que este bloco mostra a caixa de erros?","codigo":"<?php if (!empty($erros)): ?>\n    <div class=\"msg erro\">\n        Corrige o seguinte:\n        <ul>\n            <?php foreach ($erros as $erro): ?>\n                <li><?= htmlspecialchars($erro) ?></li>\n            <?php endforeach; ?>\n        </ul>\n    </div>\n<?php endif; ?>","linguagem":"php","alternativas":["Sempre que o pedido é POST.","Quando $erros existe, mesmo vazio.","Quando há uma mensagem em $_SESSION['msg'].","Quando $erros tem pelo menos um elemento."],"correta":3,"explicacao":"!empty($erros) só é verdadeiro se o array tiver erros. Num GET, ou num POST válido, o $erros está vazio e a caixa não aparece.","manual":"9.4"},{"id":"prg-040","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"O livro é gravado, mas o browser vai para uma página errada. Porquê?","codigo":"$novoId = $pdo->lastInsertId();\nmensagem('sucesso', 'Livro criado.');\nheader('Location: livro_ver.php?id=$novoId');\nexit;","linguagem":"php","alternativas":["O lastInsertId() só funciona se for chamado depois do header().","Falta converter o $novoId com (int).","O header() não aceita endereços com ?.","Com plicas, o $novoId não é substituído pelo valor."],"correta":3,"explicacao":"Dentro de plicas o PHP não substitui variáveis: o endereço fica literalmente ?id=$novoId. A Biblioteca usa aspas: header(\"Location: livro_ver.php?id=$novoId\").","manual":"12.4, 7.2"},{"id":"prg-041","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"O que faz livro_apagar.php se receber um pedido GET?","codigo":"if ($_SERVER['REQUEST_METHOD'] !== 'POST') {\n    header('Location: livros.php');\n    exit;\n}","linguagem":"php","alternativas":["Apaga o livro indicado no endereço.","Mostra um formulário de confirmação.","Responde com o código 404.","Redireciona para a lista sem apagar nada."],"correta":3,"explicacao":"Um pedido que não seja POST é mandado de volta para a lista. Um link (GET) nunca deve apagar dados.","manual":"12.6"},{"id":"prg-042","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"facil","pergunta":"Porque é que livro_apagar.php só aceita POST?","codigo":"","linguagem":"","alternativas":["Porque um pedido GET não consegue enviar números inteiros no URL.","Um GET não deve alterar dados: um robô podia seguir o link.","Porque o rowCount() só funciona em pedidos POST.","Porque os pedidos GET não passam pelo auth.php."],"correta":1,"explicacao":"Um link pode ser seguido por um robô de pesquisa ou por uma pré-visualização do browser. Por isso apagar é sempre um formulário POST.","manual":"1.2, 12.6"},{"id":"prg-043","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"A Biblioteca tem esta função mensagem() e este bloco no cabeçalho. livro_apagar.php redireciona sempre para livros.php. Como fica o utilizador a saber se o livro foi apagado?","codigo":"// includes/inicio.php\nfunction mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}\n\n// includes/cabecalho.php (logo a seguir ao <main>)\n<?php if (isset($_SESSION['msg'])): ?>\n    <div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\">\n        <?= htmlspecialchars($_SESSION['msg']['texto']) ?>\n    </div>\n    <?php unset($_SESSION['msg']); // mostra-se uma vez e apaga-se ?>\n<?php endif; ?>","linguagem":"php","alternativas":["Pelo código de estado da resposta: 200 se apagou, 404 se não.","Por um alert() que o livro_apagar.php escreve.","Pelo $erros, que vai junto no redirecionamento.","Pela mensagem guardada com mensagem(), mostrada na lista."],"correta":3,"explicacao":"Antes de redirecionar, guarda \"Livro apagado.\" ou \"O livro já não existia.\" na sessão, conforme o rowCount(). O cabeçalho da lista mostra-a.","manual":"12.6, 9.3"},{"id":"prg-044","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"dificil","pergunta":"O formulário de edição tem `action=\"livro_editar.php?id=7\"` e `method=\"post\"`. Como lê a página o id quando grava?","codigo":"","linguagem":"","alternativas":["Em $_GET['id'], porque vai no endereço.","Em $_POST['id'], porque o formulário é POST.","Em $_SESSION['id'], guardado no GET anterior.","Não chega: tinha de ir num campo hidden."],"correta":0,"explicacao":"O que vai no endereço, depois do ?, chega em $_GET, mesmo num pedido POST. Por isso o id_livro do WHERE vem de $_GET['id'].","manual":"12.5"},{"id":"prg-045","bloco":"php","tema":"Redirecionar e PRG","dificuldade":"media","pergunta":"Este é o pedido GET do livro_editar.php. Abres livro_editar.php?id=999 e esse livro não existe. O que acontece?","codigo":"} else {\n    // GET: carregar o livro para preencher o formulário\n    $stmt = $pdo->prepare('SELECT * FROM livros WHERE id_livro = ?');\n    $stmt->execute([$id]);\n    $livro = $stmt->fetch(PDO::FETCH_ASSOC);\n\n    if (!$livro) {\n        mensagem('erro', 'Esse livro não existe.');\n        header('Location: livros.php');\n        exit;\n    }\n}","linguagem":"php","alternativas":["Responde com o código 404 e uma página própria.","Guarda uma mensagem de erro e redireciona para a lista.","Mostra o formulário de edição vazio, para criar um livro novo.","Lança uma PDOException com o código 23000."],"correta":1,"explicacao":"No GET, se o fetch() der false, faz mensagem('erro', 'Esse livro não existe.') e redireciona para livros.php. O 404 é o comportamento da página de detalhe, não da de edição.","manual":"12.5"},{"id":"amostra-013","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"No login, porque não se encontra o utilizador comparando password_hash($password, PASSWORD_DEFAULT) com o hash guardado?","codigo":"","linguagem":"","alternativas":["Porque o password_hash() é demasiado lento para o login.","Porque o hash é reversível e devia ser decifrado primeiro.","Porque falta o htmlspecialchars() na password.","Porque o sal é aleatório: o mesmo texto dá um hash diferente de cada vez."],"correta":3,"explicacao":"Cada password_hash() gera um sal novo, por isso o hash nunca coincide. Procura-se o utilizador pelo email e compara-se com password_verify(), que usa o sal guardado no próprio hash.","manual":"10.1, 10.4"},{"id":"pass-001","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Porque é que a aplicação não guarda a password tal como o utilizador a escreveu?","codigo":"","linguagem":"","alternativas":["Porque a coluna VARCHAR(255) não aceita os caracteres especiais da password.","Porque o MySQL recusa gravar texto vindo de um campo type=\"password\".","Porque a password em claro ocuparia demasiado espaço na tabela.","Se a base de dados fosse roubada, o atacante ficava com todas as passwords."],"correta":3,"explicacao":"Guarda-se só o hash para que um roubo da base de dados não entregue as passwords ao atacante. Não há nenhuma limitação técnica do MySQL que impeça gravar a password.","manual":"10.1"},{"id":"pass-002","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Além da conta na tua aplicação, porque é que uma password roubada em claro é especialmente grave?","codigo":"","linguagem":"","alternativas":["Muitas pessoas usam a mesma password noutros sites, como o email ou o banco.","A password do utilizador dá também acesso direto ao MySQL como root.","O browser do utilizador deixa de conseguir abrir a aplicação.","O atacante passa a poder alterar o código PHP da aplicação no servidor."],"correta":0,"explicacao":"Como a mesma password é muitas vezes reutilizada, quem a rouba numa aplicação pode entrar noutros serviços da mesma pessoa. A password do utilizador não tem nada a ver com as credenciais do db.php.","manual":"10.1"},{"id":"pass-003","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"O que é o hash de uma password?","codigo":"","linguagem":"","alternativas":["Um código aleatório que o servidor envia ao browser num cookie.","Um texto de tamanho fixo, calculado a partir dela, que não se pode reverter.","A password cifrada com uma chave guardada no db.php, que permite recuperá-la depois.","A mesma password escrita noutra codificação, como o base64."],"correta":1,"explicacao":"O hash é o resultado de uma função matemática que transforma a password num texto de tamanho fixo e não é reversível. Não há chave para o \"decifrar\".","manual":"10.1"},{"id":"pass-004","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"No login, como é que o servidor sabe se a password escrita está certa?","codigo":"","linguagem":"","alternativas":["Calcula o hash da password escrita com o sal guardado e compara os dois.","Decifra o hash guardado e compara o resultado com a password escrita.","Procura uma linha em que a coluna password_hash seja igual à password escrita.","Envia o hash guardado ao browser, que o compara com o que foi escrito."],"correta":0,"explicacao":"O hash não se decifra: compara-se. É isso que password_verify() faz, usando o sal que está dentro do hash guardado.","manual":"10.1, 10.4"},{"id":"pass-005","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Um utilizador esqueceu-se da password. A partir do hash guardado na base de dados, o que consegues fazer?","codigo":"","linguagem":"","alternativas":["Recuperá-la com base64_decode().","Recuperá-la a partir dos 22 caracteres do sal.","Nada que a recupere: o hash não é reversível.","Recuperá-la com password_verify()."],"correta":2,"explicacao":"Uma das propriedades essenciais do hash é não ser reversível: a partir dele não há forma de chegar à password. password_verify() só diz se uma password corresponde ao hash.","manual":"10.1"},{"id":"pass-006","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Registas duas contas diferentes, ambas com a password Demo1234. O que acontece aos dois hashes guardados?","codigo":"","linguagem":"","alternativas":["O segundo registo falha, porque a coluna password_hash é UNIQUE.","São diferentes, porque cada um tem o seu sal aleatório.","São iguais, porque a password é a mesma.","São iguais no sal e diferentes no resto do texto."],"correta":1,"explicacao":"password_hash() gera um sal aleatório de cada vez e guarda-o dentro do hash, por isso a mesma password dá hashes diferentes. A coluna password_hash não é UNIQUE: só o email é.","manual":"10.1, 3.5"},{"id":"pass-007","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Num hash bcrypt, o que é o sal?","codigo":"","linguagem":"","alternativas":["Um valor aleatório, guardado dentro do próprio hash.","Uma chave secreta, igual para todos, guardada no config/db.php.","Uma coluna à parte na tabela utilizadores.","O número que define quanto custa calcular o hash."],"correta":0,"explicacao":"O sal é um valor aleatório que entra no cálculo e fica guardado no próprio hash (os 22 caracteres a seguir ao custo). O número que define o esforço é o custo, não o sal.","manual":"10.1"},{"id":"pass-008","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Se o sal é aleatório e muda em cada registo, como é que password_verify() consegue repetir o cálculo no login?","codigo":"","linguagem":"","alternativas":["Lê o sal que está guardado dentro do hash que lhe passas.","Usa um sal fixo, igual para todos os utilizadores.","Não repete o cálculo: decifra o hash e compara.","Vai buscar o sal guardado na sessão do utilizador."],"correta":0,"explicacao":"O sal fica escrito dentro do hash guardado, por isso password_verify() tem tudo o que precisa: calcula o hash da password escrita com esse sal e compara. Nunca há decifração.","manual":"10.1, 10.4"},{"id":"pass-009","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Na coluna password_hash vês um texto que começa por `$2y$12$`. O que indica o `2y`?","codigo":"","linguagem":"","alternativas":["Que o texto está codificado em base64.","Que o algoritmo usado é o bcrypt.","Que o custo do cálculo é 2.","Que a password foi calculada com md5()."],"correta":1,"explicacao":"O $2y$ identifica o bcrypt, o algoritmo usado por password_hash() com PASSWORD_DEFAULT. O custo é o número seguinte (12).","manual":"10.1"},{"id":"pass-010","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Num hash `$2y$12$…`, o que significa o 12?","codigo":"","linguagem":"","alternativas":["O número mínimo de caracteres que a password tem de ter no registo.","O número de caracteres do sal, que vem a seguir.","O número de vezes que o utilizador já iniciou sessão.","O custo: quanto maior, mais lento é calcular e atacar o hash."],"correta":3,"explicacao":"O 12 é o custo do bcrypt: aumenta o tempo de cálculo e, com ele, o tempo de um ataque. O sal são os 22 caracteres seguintes.","manual":"10.1"},{"id":"pass-011","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"Um colega criou a tabela assim e usa password_hash() no registo. Que problema vai ter?","codigo":"CREATE TABLE utilizadores (\n    id_utilizador INT AUTO_INCREMENT PRIMARY KEY,\n    email         VARCHAR(150) NOT NULL UNIQUE,\n    password_hash VARCHAR(20)  NOT NULL\n);","linguagem":"sql","alternativas":["Nenhum, porque password_hash() encurta o hash ao tamanho da coluna.","Só falha para passwords com mais de 20 caracteres.","Nenhum, porque o hash fica sempre com o tamanho da password.","O hash não cabe: tem dezenas de caracteres, mesmo para uma password curta."],"correta":3,"explicacao":"O hash tem tamanho fixo e é longo (o do utilizador de teste tem 60 caracteres), seja qual for a password. Por isso a Biblioteca usa VARCHAR(255).","manual":"10.1, 3.5"},{"id":"pass-012","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Que função PHP confirma, no login, que a password escrita corresponde ao hash guardado?","codigo":"","linguagem":"","alternativas":["password_compare()","password_hash()","password_verify()","password_decode()"],"correta":2,"explicacao":"password_verify() calcula o hash da password escrita com o sal guardado e compara. password_hash() só serve para criar o hash no registo; as outras duas não existem.","manual":"10.4, Anexo B"},{"id":"pass-013","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Porque é que base64_encode() não serve para guardar passwords?","codigo":"","linguagem":"","alternativas":["Porque o resultado tem sempre mais de 255 caracteres e não cabe na coluna.","Porque só funciona com passwords sem acentos.","Não é um hash: é só outra forma de escrever o mesmo texto.","Porque é lento demais para usar em cada login."],"correta":2,"explicacao":"O base64 nem sequer é um hash: qualquer pessoa o converte de volta ao texto original. Para passwords usa-se sempre password_hash().","manual":"10.1"},{"id":"pass-014","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"Este registo grava e o login funciona. Qual é o problema?","codigo":"$hash = md5($password);\n$stmt = $pdo->prepare(\n    'INSERT INTO utilizadores (nome, email, password_hash, consentimento_em)\n     VALUES (?, ?, ?, NOW())'\n);\n$stmt->execute([$nome, $email, $hash]);","linguagem":"php","alternativas":["md5() cifra a password e o login teria de a decifrar.","Nenhum: como md5() calcula um hash, a password está protegida.","O resultado de md5() não cabe numa coluna VARCHAR(255).","md5() é rápido demais e fácil de atacar: devia usar-se password_hash()."],"correta":3,"explicacao":"md5() e sha1() são rápidos demais, o que os torna fáceis de atacar. A consulta preparada está correta; o erro é só a função usada para o hash.","manual":"10.1"},{"id":"pass-015","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Qual destas linhas calcula corretamente o hash da password para guardar?","codigo":"","linguagem":"","alternativas":["$hash = hash_password($password, PASSWORD_DEFAULT);","$hash = password_hash($password, PASSWORD_DEFAULT);","$hash = password_hash(PASSWORD_DEFAULT, $password);","$hash = password_verify($password, PASSWORD_DEFAULT);"],"correta":1,"explicacao":"password_hash() recebe primeiro a password e depois o algoritmo (PASSWORD_DEFAULT). password_verify() serve para comparar no login e hash_password() não existe.","manual":"10.1, Anexo B"},{"id":"pass-016","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"O que acontece quando o utilizador tenta entrar com a password certa?","codigo":"$stmt = $pdo->prepare('SELECT id_utilizador, nome, password_hash FROM utilizadores WHERE email = ?');\n$stmt->execute([$email]);\n$utilizador = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif ($utilizador && password_verify($utilizador['password_hash'], $password)) {\n    // iniciar sessão\n}","linguagem":"php","alternativas":["Entra, porque a ordem dos argumentos de password_verify() não importa.","Entra, mas só se a password tiver pelo menos 8 caracteres.","Dá erro de sintaxe, porque falta um parêntesis no if.","Nunca entra: os argumentos de password_verify() estão trocados."],"correta":3,"explicacao":"A ordem é password_verify($escrita, $hashGuardado). Trocados, a função trata o hash como se fosse a password e o texto escrito como se fosse um hash, e devolve sempre false.","manual":"10.4, Anexo B"},{"id":"pass-017","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"O que devolve password_verify()?","codigo":"","linguagem":"","alternativas":["true ou false.","O hash da password escrita.","O id do utilizador.","A password original."],"correta":0,"explicacao":"password_verify() só responde se a password corresponde ao hash: true ou false. Não devolve a password, porque o hash não é reversível.","manual":"10.4"},{"id":"pass-018","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"Um aluno escreveu assim a verificação do login. O que acontece com a password certa?","codigo":"if ($utilizador &&\n    password_hash($password, PASSWORD_DEFAULT) === $utilizador['password_hash']) {\n    // iniciar sessão\n}","linguagem":"php","alternativas":["A condição é sempre verdadeira, mesmo com a password errada.","Funciona, porque a mesma password dá sempre o mesmo hash.","A condição é sempre falsa, porque o novo hash tem outro sal.","Funciona apenas se trocares o === por ==."],"correta":2,"explicacao":"Cada chamada a password_hash() usa um sal novo, por isso o hash calculado nunca é igual ao guardado. Para comparar usa-se password_verify().","manual":"10.1, 10.4"},{"id":"pass-019","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"Qual é o problema deste login?","codigo":"$stmt = $pdo->prepare(\n    'SELECT id_utilizador, nome FROM utilizadores\n     WHERE email = ? AND password_hash = ?'\n);\n$stmt->execute([$email, $password]);\n$utilizador = $stmt->fetch(PDO::FETCH_ASSOC);","linguagem":"php","alternativas":["Permite injeção de SQL, porque a password vai no execute().","Só funciona se o email for escrito em maiúsculas.","Nenhum: a consulta preparada protege a password.","Compara a password escrita com um hash: nunca encontra o utilizador."],"correta":3,"explicacao":"A coluna guarda o hash, não a password, por isso a condição password_hash = ? nunca é verdadeira. Procura-se só pelo email e compara-se depois com password_verify().","manual":"10.4"},{"id":"pass-020","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"No login.php, por que campo se procura o utilizador na base de dados?","codigo":"","linguagem":"","alternativas":["Pelo nome e pela password, juntos.","Pelo id que vem num campo escondido.","Pelo email; a password confirma-se depois.","Pela password, que é única para cada utilizador."],"correta":2,"explicacao":"Procura-se pelo email, que é UNIQUE, e só depois se confirma a password com password_verify() contra o hash dessa linha.","manual":"10.4"},{"id":"pass-021","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"Porque é que esta condição testa $utilizador antes de chamar password_verify()?","codigo":"$utilizador = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif ($utilizador && password_verify($password, $utilizador['password_hash'])) {","linguagem":"php","alternativas":["Para garantir que o email foi escrito em minúsculas.","Se o email não existir, fetch() devolve false e não há hash.","Para confirmar que o utilizador já tinha sessão iniciada.","Porque password_verify() só funciona dentro de um &&."],"correta":1,"explicacao":"Quando nenhuma linha tem aquele email, fetch() devolve false. O && faz com que password_verify() só seja chamada quando há mesmo um utilizador e um hash para comparar.","manual":"10.4"},{"id":"pass-022","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Porque é que o login mostra \"Email ou password errados.\" tanto para um email que não existe como para uma password errada?","codigo":"","linguagem":"","alternativas":["Porque o servidor não consegue distinguir os dois casos.","Para não revelar a um atacante que emails têm conta.","Porque o RGPD proíbe mostrar o email na página.","Para o utilizador não perceber que se enganou."],"correta":1,"explicacao":"Com mensagens diferentes, um atacante podia descobrir que emails estão registados. O servidor distingue os dois casos, mas escolhe não o dizer.","manual":"10.4, 14.2"},{"id":"pass-023","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"O base_dados.sql cria este utilizador de teste. Tentas entrar como demo@biblioteca.pt com a password demo1234, tudo em minúsculas. O que acontece?","codigo":"-- Utilizador de teste: demo@biblioteca.pt / Demo1234\nINSERT INTO utilizadores (nome, email, password_hash, consentimento_em) VALUES\n    ('Utilizador de teste', 'demo@biblioteca.pt', '$2y$12$wtvyr7Br21NfSwx8lFD1EujFE1Q/5l4NumFPTF4aZ5OVbvUr4/V2m', NOW());","linguagem":"sql","alternativas":["Aparece uma mensagem a dizer que só a password está errada.","Entras, mas sem o teu nome no menu.","Entras, porque password_verify() ignora maiúsculas.","Aparece \"Email ou password errados.\" e ficas no login."],"correta":3,"explicacao":"A password do utilizador de teste é Demo1234. \"demo1234\" é outro texto, por isso password_verify() devolve false e aparece a mensagem única de erro.","manual":"3.5, 10.4"},{"id":"pass-024","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"No base_dados.sql, o utilizador de teste é inserido assim. O que é o valor que começa por $2y$?","codigo":"INSERT INTO utilizadores (nome, email, password_hash, consentimento_em) VALUES\n    ('Utilizador de teste', 'demo@biblioteca.pt',\n     '$2y$12$wtvyr7Br21NfSwx8lFD1EujFE1Q/5l4NumFPTF4aZ5OVbvUr4/V2m', NOW());","linguagem":"sql","alternativas":["A password Demo1234 codificada em base64.","A password Demo1234 cifrada com md5().","O hash da password Demo1234, calculado com password_hash().","O identificador da sessão do utilizador de teste."],"correta":2,"explicacao":"É o hash bcrypt da password Demo1234 ($2y$, custo 12). Como o hash leva o sal dentro, password_verify('Demo1234', …) devolve true no login.","manual":"3.5, 10.1"},{"id":"pass-025","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Para confirmar a medida \"passwords com hash\", abres a tabela utilizadores no phpMyAdmin. O que tens de ver na coluna da password?","codigo":"","linguagem":"","alternativas":["Textos que começam por $2, nunca a password escrita.","As passwords tal como foram escritas, visíveis só ao administrador.","Asteriscos, como no campo type=\"password\".","Um número inteiro diferente para cada utilizador."],"correta":0,"explicacao":"É o teste 5 do capítulo 16: a coluna só pode ter hashes bcrypt ($2…). Se aparecer a password escrita, a medida falhou.","manual":"14, 16"},{"id":"pass-026","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"O formulário de registo já tem required e é validado pelo validacao.js. Porque é que o registo.php volta a validar tudo?","codigo":"","linguagem":"","alternativas":["Porque o required só funciona em formulários com method=\"get\".","A validação no browser pode ser contornada (por exemplo, sem JavaScript).","Para mostrar os erros duas vezes e o utilizador não os ignorar.","Porque o PHP não recebe os campos que o JavaScript já validou antes do envio."],"correta":1,"explicacao":"O browser está nas mãos do utilizador: pode desligar o JavaScript ou enviar o pedido diretamente. Só a validação no servidor é obrigatória e fiável (testes 2 e 4 do capítulo 16).","manual":"10.2, 16"},{"id":"pass-027","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Qual destas passwords é recusada por esta validação do registo?","codigo":"if (strlen($password) < 8) {\n    $erros[] = 'A password tem de ter pelo menos 8 caracteres.';\n}","linguagem":"php","alternativas":["biblioteca","Demo123","Demo1234","12345678"],"correta":1,"explicacao":"A condição junta um erro quando a password tem menos de 8 caracteres. Demo123 tem 7; as outras têm 8 ou mais e passam.","manual":"10.2"},{"id":"pass-028","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Porque é que o registo verifica o consentimento com isset() e não lendo o valor do campo?","codigo":"if (!isset($_POST['consentimento'])) {\n    $erros[] = 'Tens de aceitar a política de privacidade.';\n}","linguagem":"php","alternativas":["O valor de uma caixa de verificação chega sempre vazio.","Porque isset() confirma também que a política foi lida.","Porque o $_POST não guarda os valores das caixas.","Uma caixa de verificação por assinalar não é enviada no pedido."],"correta":3,"explicacao":"Se a caixa não for assinalada, o campo simplesmente não vem no pedido. Por isso basta ver se existe em $_POST.","manual":"10.2, 7.5"},{"id":"pass-029","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"O que faz esta condição do registo.php?","codigo":"if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {\n    $erros[] = 'O email não é válido.';\n}","linguagem":"php","alternativas":["Tira do email os caracteres perigosos antes de gravar.","Junta um erro se o email não tiver um formato válido.","Envia um email de confirmação para o endereço escrito.","Junta um erro se o email já existir na base de dados."],"correta":1,"explicacao":"filter_var() com FILTER_VALIDATE_EMAIL devolve false quando o formato não é de um email, e aí junta-se o erro. A verificação de email repetido é feita depois, com um SELECT.","manual":"10.2"},{"id":"pass-030","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"No registo, o utilizador escreve só espaços no campo do nome. O que acontece?","codigo":"$nome = trim($_POST['nome'] ?? '');\n\nif ($nome === '' || mb_strlen($nome) > 100) {\n    $erros[] = 'O nome é obrigatório e não pode ter mais de 100 caracteres.';\n}","linguagem":"php","alternativas":["Dá erro, porque mb_strlen() não aceita espaços.","É aceite, porque os espaços contam como caracteres.","É recusado: o trim() deixa o texto vazio.","É aceite, mas o nome fica gravado como NULL."],"correta":2,"explicacao":"trim() tira os espaços do início e do fim, por isso o nome fica '' e a primeira parte da condição é verdadeira. A segunda parte rejeita nomes com mais de 100 caracteres.","manual":"10.2"},{"id":"pass-031","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"No registo.php, quando é executado o código dentro deste if?","codigo":"$erros = [];\n// ... validações que podem fazer $erros[] = '...';\n\nif (!$erros) {\n    $hash = password_hash($password, PASSWORD_DEFAULT);\n    // INSERT ...\n}","linguagem":"php","alternativas":["Só quando o array $erros está vazio.","Só quando há pelo menos um erro.","Sempre, porque o array $erros foi criado antes.","Nunca, porque !$erros é sempre falso."],"correta":0,"explicacao":"Um array vazio vale false numa condição, por isso !$erros só é verdadeiro quando não houve nenhum erro de validação. Só aí se calcula o hash e se grava.","manual":"10.2"},{"id":"pass-032","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"A coluna email já é UNIQUE. Porque é que o registo.php ainda faz um SELECT pelo email antes de inserir?","codigo":"","linguagem":"","alternativas":["Para ir buscar o hash da password que já está guardado.","Porque sem o SELECT o INSERT gravava o email duas vezes.","Para mostrar uma mensagem clara em vez de um erro da base de dados.","Porque o UNIQUE só é respeitado se houver um SELECT antes do INSERT."],"correta":2,"explicacao":"A base de dados recusaria o email repetido de qualquer forma, mas com o SELECT o utilizador recebe \"Já existe uma conta com esse email.\" em vez de um erro.","manual":"10.2"},{"id":"pass-033","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"No registo, o que significa a condição do if neste excerto?","codigo":"$stmt = $pdo->prepare('SELECT id_utilizador FROM utilizadores WHERE email = ?');\n$stmt->execute([$email]);\nif ($stmt->fetch()) {\n    $erros[] = 'Já existe uma conta com esse email.';\n}","linguagem":"php","alternativas":["A conta nova acabou de ser criada.","A consulta deu erro e o email não foi lido.","A consulta encontrou uma conta com esse email.","O email escrito tem um formato válido."],"correta":2,"explicacao":"fetch() devolve a linha encontrada ou false se não houver nenhuma. Se devolver uma linha, o email já está registado e junta-se o erro.","manual":"10.2"},{"id":"pass-034","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"Qual é o erro neste registo?","codigo":"$hash = password_hash($password, PASSWORD_DEFAULT);\n$stmt = $pdo->prepare(\n    'INSERT INTO utilizadores (nome, email, password_hash, consentimento_em)\n     VALUES (?, ?, ?, NOW())'\n);\n$stmt->execute([$nome, $email, $password]);","linguagem":"php","alternativas":["Falta htmlspecialchars() no $nome antes de o gravar.","Grava a password em claro: devia passar $hash ao execute().","O número de ? não bate certo com os valores do execute().","Nenhum: o MySQL calcula o hash ao gravar na coluna password_hash."],"correta":1,"explicacao":"O hash é calculado mas nunca usado: vai para a base de dados a variável $password. Os três ? correspondem aos três valores, e o htmlspecialchars() usa-se ao mostrar, não ao gravar.","manual":"10.2"},{"id":"pass-035","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"Para que serve o NOW() neste INSERT do registo?","codigo":"INSERT INTO utilizadores (nome, email, password_hash, consentimento_em)\nVALUES (?, ?, ?, NOW())","linguagem":"sql","alternativas":["Entra no cálculo do sal da password.","Obriga o MySQL a executar o INSERT de imediato, sem esperar pelos outros.","Guarda a data e a hora em que o consentimento foi dado.","Guarda a data em que a password deixa de ser válida."],"correta":2,"explicacao":"NOW() é a data e hora atuais, gravadas em consentimento_em para provar que o utilizador aceitou a política. O sal é gerado por password_hash(), no PHP.","manual":"10.2, 15.2"},{"id":"pass-036","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Este é o fim do registo.php. Depois de um registo bem sucedido, o que acontece?","codigo":"// 3. Guardar: a password nunca é guardada, só o seu hash\nif (!$erros) {\n    $hash = password_hash($password, PASSWORD_DEFAULT);\n    $stmt = $pdo->prepare(\n        'INSERT INTO utilizadores (nome, email, password_hash, consentimento_em)\n         VALUES (?, ?, ?, NOW())'\n    );\n    $stmt->execute([$nome, $email, $hash]);\n\n    mensagem('sucesso', 'Conta criada. Já podes iniciar sessão.');\n    header('Location: login.php');\n    exit;\n}","linguagem":"php","alternativas":["Guarda a mensagem \"Conta criada…\" e redireciona para o login.","Mostra outra vez o formulário, vazio, com a mensagem de sucesso por cima.","Inicia logo a sessão e mostra a lista de livros.","Mostra a password escolhida, para o utilizador a confirmar."],"correta":0,"explicacao":"Grava, chama mensagem('sucesso', 'Conta criada. Já podes iniciar sessão.') e faz header('Location: login.php'); exit;. O registo não inicia sessão: o utilizador entra a seguir, no login.","manual":"10.2"},{"id":"pass-037","bloco":"php","tema":"Passwords","dificuldade":"dificil","pergunta":"Com este login, o que acontece quando alguém escreve um email que existe e a password certa?","codigo":"$stmt = $pdo->prepare('SELECT id_utilizador, nome FROM utilizadores WHERE email = ?');\n$stmt->execute([$email]);\n$utilizador = $stmt->fetch(PDO::FETCH_ASSOC);\n\nif ($utilizador && password_verify($password, $utilizador['password_hash'])) {","linguagem":"php","alternativas":["Não entra: o SELECT não traz a coluna password_hash.","Entra normalmente, porque o email está correto.","Entra, porque password_verify() vai ler o hash à tabela.","Dá erro de SQL, porque falta o * no SELECT."],"correta":0,"explicacao":"O SELECT só pede id_utilizador e nome, por isso $utilizador['password_hash'] não existe (aviso \"Undefined array key\") e password_verify() devolve false.","manual":"10.4, 17.1"},{"id":"pass-038","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"Na página \"A minha conta\", porque é que a password não aparece junto dos outros dados do utilizador?","codigo":"","linguagem":"","alternativas":["Porque não é guardada: só existe o seu hash.","Porque está cifrada e só o administrador a pode ver.","Porque fica guardada na sessão, e não na tabela.","Porque o RGPD proíbe mostrar a password ao próprio."],"correta":0,"explicacao":"A aplicação nunca guarda a password, apenas o hash, que não é reversível. Não há forma de a mostrar, nem ao próprio nem a um administrador.","manual":"15.4, 10.1"},{"id":"pass-039","bloco":"php","tema":"Passwords","dificuldade":"facil","pergunta":"O manual diz que, numa aplicação publicada na internet, faltaria ainda uma proteção para as passwords não viajarem em claro. Qual?","codigo":"","linguagem":"","alternativas":["Codificar a password em base64.","Um campo type=\"password\".","md5() aplicado no JavaScript.","HTTPS."],"correta":3,"explicacao":"Sem HTTPS, a password vai em claro do browser ao servidor. O type=\"password\" só a esconde no ecrã, e md5 ou base64 no browser não resolvem nada.","manual":"14.3"},{"id":"pass-040","bloco":"php","tema":"Passwords","dificuldade":"media","pergunta":"O que faz, de facto, o atributo type=\"password\" no campo do formulário de login?","codigo":"","linguagem":"","alternativas":["Calcula o hash da password antes de a enviar.","Cifra a password durante a viagem até ao servidor.","Impede que a password apareça em $_POST.","Mostra pontos no ecrã em vez do texto escrito."],"correta":3,"explicacao":"O type=\"password\" só esconde o texto no ecrã. A password chega ao servidor em $_POST['password'] tal como foi escrita, e é o PHP que calcula o hash.","manual":"4.2, 10.2"},{"id":"amostra-014","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"No logout.php, porque se volta a chamar session_start() logo depois de session_destroy()?","codigo":"$_SESSION = [];\nsession_destroy();\nsession_start();\nmensagem('sucesso', 'Sessão terminada.');\nheader('Location: index.php');\nexit;","linguagem":"php","alternativas":["Para voltar a iniciar sessão com o mesmo utilizador.","Para abrir uma sessão nova e vazia, só para levar a mensagem à página seguinte.","Porque o session_destroy() só funciona se houver um session_start() depois.","Para gerar um novo id de sessão contra a fixação de sessão."],"correta":1,"explicacao":"A sessão antiga já foi apagada. A nova está vazia e só serve para a função mensagem() guardar \"Sessão terminada.\" até ao index.php. O novo id contra a fixação é o session_regenerate_id(), usado no login.","manual":"10.5"},{"id":"sess-001","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"O que quer dizer que o HTTP \"não tem memória\"?","codigo":"","linguagem":"","alternativas":["O servidor apaga todos os dados da base de dados no fim de cada pedido.","Cada pedido é independente: o servidor não se lembra dos anteriores.","O browser não guarda o histórico das páginas visitadas.","Os valores de $_POST perdem-se se a página tiver dois formulários."],"correta":1,"explicacao":"Cada pedido HTTP chega ao servidor sem ligação ao anterior. É por isso que é preciso uma sessão para saber quem fez login.","manual":"10.3"},{"id":"sess-002","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Fizeste login há dois minutos. No pedido seguinte, como é que o servidor sabe que és tu?","codigo":"","linguagem":"","alternativas":["O servidor reconhece o endereço IP do teu computador.","Cada link da aplicação leva o teu id no endereço (?id=).","O browser volta a enviar o email e a password, em campos escondidos do pedido.","O browser envia o cookie da sessão e o servidor vai buscar os dados dela."],"correta":3,"explicacao":"No login, o servidor cria a sessão e manda ao browser um cookie com o seu identificador. Em cada pedido seguinte o browser devolve esse cookie e o servidor encontra os dados.","manual":"10.3"},{"id":"sess-003","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"O que guarda o cookie PHPSESSID no browser?","codigo":"","linguagem":"","alternativas":["Só o identificador da sessão, um código aleatório e longo.","Uma cópia de todo o conteúdo de $_SESSION.","O id e o nome do utilizador que fez login, em texto simples.","O hash da password do utilizador."],"correta":0,"explicacao":"O browser só guarda o identificador da sessão. Os dados ($_SESSION['id_utilizador'], $_SESSION['nome']) ficam no servidor.","manual":"10.3"},{"id":"sess-004","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Onde ficam guardados os valores de $_SESSION['id_utilizador'] e $_SESSION['nome']?","codigo":"","linguagem":"","alternativas":["No servidor; o browser só tem o identificador.","No cookie do browser, em texto simples.","Numa coluna sessao da tabela utilizadores, atualizada a cada pedido.","No formulário, em campos escondidos."],"correta":0,"explicacao":"Os dados da sessão ficam no servidor, por isso o utilizador não os pode ler nem alterar. O cookie leva apenas o identificador.","manual":"10.3"},{"id":"sess-005","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"O cabeçalho mostra \"Olá, Maria\" em todas as páginas. De onde vem esse nome?","codigo":"","linguagem":"","alternativas":["Do cookie PHPSESSID, que guarda o nome.","De $_SESSION['nome'], guardado no momento do login.","De $_POST['nome'], enviado em cada pedido.","De um SELECT à tabela utilizadores feito no cabeçalho."],"correta":1,"explicacao":"No login guarda-se o nome na sessão e o cabecalho.php escreve-o com htmlspecialchars($_SESSION['nome']). Não é preciso ir à base de dados em cada página.","manual":"10.4, 9.2"},{"id":"sess-006","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Que instrução falta no espaço em branco para esta página poder ler a sessão?","codigo":"<?php\n________;\nrequire __DIR__ . '/../config/db.php';\n\necho 'Olá, ' . $_SESSION['nome'];","linguagem":"php","alternativas":["session_start()","session_create()","session_open()","session_begin()"],"correta":0,"explicacao":"session_start() ativa a sessão. Sem ela, $_SESSION não tem os dados guardados. As outras três funções não existem.","manual":"10.3, Anexo B"},{"id":"sess-007","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Todas as páginas da Biblioteca começam por require 'includes/inicio.php'; (em baixo). Onde é chamado session_start()?","codigo":"<?php\n// Incluído na PRIMEIRA linha de todas as páginas.\nsession_start();\nrequire __DIR__ . '/../config/db.php';\n\n// Guarda uma mensagem para mostrar na página seguinte (depois do redirect)\nfunction mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}","linguagem":"php","alternativas":["Só no login.php, porque é aí que a sessão é criada pela primeira vez.","No inicio.php, incluído na primeira linha de todas as páginas.","Só nas páginas restritas, dentro do auth.php.","No cabecalho.php, a seguir ao <!DOCTYPE html>."],"correta":1,"explicacao":"Todas as páginas começam por require 'includes/inicio.php';, que chama session_start() antes de qualquer HTML. Assim, nenhuma página se esquece da sessão.","manual":"9.1, 10.3"},{"id":"sess-008","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Qual é o problema desta página?","codigo":"<!DOCTYPE html>\n<html lang=\"pt\">\n<body>\n<?php\nsession_start();\nif (isset($_SESSION['id_utilizador'])) {\n    echo 'Bem-vindo!';\n}\n?>","linguagem":"php","alternativas":["Falta chamar session_destroy() antes de session_start().","Nenhum: session_start() pode estar em qualquer ponto.","session_start() tem de ser chamado antes de qualquer HTML.","session_start() só pode ser chamado dentro do <head>, antes do <title>."],"correta":2,"explicacao":"session_start() tem de vir antes de qualquer HTML, porque precisa de enviar o cookie da sessão ao browser. Por isso a Biblioteca o chama na primeira linha, no inicio.php.","manual":"9.1, 17.1"},{"id":"sess-009","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Criaste a página novidades.php e esqueceste-te do require 'includes/inicio.php'. Já tens login feito, mas nessa página o menu mostra \"Entrar\" e \"Criar conta\". Porquê?","codigo":"","linguagem":"","alternativas":["O menu só muda nas páginas que incluem o auth.php.","O login não guardou o nome do utilizador na sessão.","Sem session_start(), $_SESSION não tem os dados da sessão.","O cookie PHPSESSID só é enviado pelo browser para a página login.php."],"correta":2,"explicacao":"É no inicio.php que está o session_start(). Sem ele, isset($_SESSION['id_utilizador']) é falso e o cabeçalho mostra o menu de quem não tem sessão.","manual":"9.1, 9.2, 17.1"},{"id":"sess-010","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Depois do login, és sempre mandado de volta para o login ao abrir livros.php, que verifica isset($_SESSION['id_utilizador']). Porquê?","codigo":"if ($utilizador && password_verify($password, $utilizador['password_hash'])) {\n    session_regenerate_id(true);\n    $_SESSION['id']   = $utilizador['id_utilizador'];\n    $_SESSION['nome'] = $utilizador['nome'];\n    header('Location: livros.php');\n    exit;\n}","linguagem":"php","alternativas":["session_regenerate_id(true) apaga os dados guardados a seguir.","O header() apaga a sessão antes de mudar de página.","O login guarda o id numa chave diferente da que é verificada.","Falta chamar session_start() outra vez antes do header()."],"correta":2,"explicacao":"O login guarda $_SESSION['id'], mas a verificação procura $_SESSION['id_utilizador'], que nunca existe. É uma das causas de \"estou sempre a ser mandado para o login\": o login não guardou os dados certos.","manual":"10.4, 17.1"},{"id":"sess-011","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Este é o login bem sucedido no login.php. O que fica guardado na sessão?","codigo":"// 2. Comparar a password escrita com o hash guardado\nif ($utilizador && password_verify($password, $utilizador['password_hash'])) {\n    session_regenerate_id(true);   // novo id de sessão depois do login\n    $_SESSION['id_utilizador'] = $utilizador['id_utilizador'];\n    $_SESSION['nome']          = $utilizador['nome'];\n\n    mensagem('sucesso', 'Sessão iniciada. Bem-vindo, ' . $utilizador['nome'] . '!');\n    header('Location: livros.php');\n    exit;\n}\n\n// Mensagem igual nos dois casos: não se revela se o email existe\n$erros[] = 'Email ou password errados.';","linguagem":"php","alternativas":["O id e a password escrita.","Toda a linha, incluindo o hash.","O id e o nome do utilizador.","O email e o hash da password."],"correta":2,"explicacao":"Guarda-se $_SESSION['id_utilizador'] (para saber quem é) e $_SESSION['nome'] (para o menu). A password e o hash nunca vão para a sessão.","manual":"10.4"},{"id":"sess-012","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Depois de este código correr num login correto, o que tem de aparecer na página seguinte?","codigo":"$_SESSION['id_utilizador'] = $utilizador['id_utilizador'];\n$_SESSION['nome']          = $utilizador['nome'];\n\nmensagem('sucesso', 'Sessão iniciada. Bem-vindo, ' . $utilizador['nome'] . '!');\nheader('Location: livros.php');\nexit;","linguagem":"php","alternativas":["A página inicial, sem mensagem, até carregares em F5.","A lista de livros, com o nome no menu e uma mensagem de boas-vindas.","O formulário de login, vazio, com uma mensagem de sucesso por cima dos campos.","A lista de livros, com \"Entrar\" e \"Criar conta\" no menu."],"correta":1,"explicacao":"O login guarda o id e o nome na sessão, guarda a mensagem \"Sessão iniciada. Bem-vindo, …!\" e redireciona para livros.php. Como há sessão, o cabeçalho mostra o nome e o menu completo (teste 7).","manual":"10.4, 9.2, 16"},{"id":"sess-013","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Para que serve a primeira linha dentro deste if do login?","codigo":"if ($utilizador && password_verify($password, $utilizador['password_hash'])) {\n    session_regenerate_id(true);\n    $_SESSION['id_utilizador'] = $utilizador['id_utilizador'];\n    $_SESSION['nome']          = $utilizador['nome'];","linguagem":"php","alternativas":["Calcula de novo o hash da password do utilizador.","Prolonga o tempo de vida do cookie de sessão no browser do utilizador.","Gera um novo id_utilizador na tabela utilizadores.","Dá à sessão um identificador novo, contra a fixação de sessão."],"correta":3,"explicacao":"Cria um identificador de sessão novo no momento do login. Assim, um identificador que um atacante tenha conseguido fixar antes do login deixa de servir.","manual":"10.4, 14.2"},{"id":"sess-014","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Neste excerto do login.php, em que momento é chamado session_regenerate_id(true)?","codigo":"// 2. Comparar a password escrita com o hash guardado\nif ($utilizador && password_verify($password, $utilizador['password_hash'])) {\n    session_regenerate_id(true);   // novo id de sessão depois do login\n    $_SESSION['id_utilizador'] = $utilizador['id_utilizador'];\n    $_SESSION['nome']          = $utilizador['nome'];\n\n    mensagem('sucesso', 'Sessão iniciada. Bem-vindo, ' . $utilizador['nome'] . '!');\n    header('Location: livros.php');\n    exit;\n}\n\n// Mensagem igual nos dois casos: não se revela se o email existe\n$erros[] = 'Email ou password errados.';","linguagem":"php","alternativas":["No logout, antes de chamar session_destroy().","No registo, logo a seguir ao INSERT.","No início de cada página, dentro do inicio.php.","Logo depois de confirmar a password, no login."],"correta":3,"explicacao":"É chamado dentro do if do login, quando password_verify() devolve true e antes de guardar os dados na sessão. É aí que o utilizador passa a estar autenticado.","manual":"10.4"},{"id":"sess-015","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"No logout.php, que função falta no espaço em branco para destruir a sessão?","codigo":"$_SESSION = [];\n________;\n\nsession_start();\nmensagem('sucesso', 'Sessão terminada.');","linguagem":"php","alternativas":["session_destroy()","session_terminate()","session_end()","session_close()"],"correta":0,"explicacao":"session_destroy() destrói a sessão. session_terminate(), session_end() e session_close() não existem em PHP.","manual":"10.5, Anexo B"},{"id":"sess-016","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"No logout.php, o que faz a linha `$_SESSION = [];`?","codigo":"","linguagem":"","alternativas":["Apaga todos os dados guardados na sessão.","Cria uma sessão nova com um id diferente.","Apaga o cookie PHPSESSID do browser.","Apaga a conta do utilizador da base de dados."],"correta":0,"explicacao":"Atribuir um array vazio limpa todos os dados da sessão; a seguir, session_destroy() destrói a própria sessão. A conta na base de dados não é tocada.","manual":"10.5"},{"id":"sess-017","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Um colega tirou uma linha ao logout.php e ficou assim. O que acontece?","codigo":"<?php\nrequire 'includes/inicio.php';\n\n$_SESSION = [];\nsession_destroy();\n\nmensagem('sucesso', 'Sessão terminada.');\nheader('Location: index.php');\nexit;","linguagem":"php","alternativas":["A sessão termina, mas a mensagem \"Sessão terminada.\" não aparece.","A sessão não termina, porque falta session_close().","A mensagem passa a aparecer em todas as páginas seguintes.","Dá erro, porque mensagem() não existe depois de session_destroy()."],"correta":0,"explicacao":"Depois de session_destroy() já não há sessão ativa, por isso o que mensagem() escreve em $_SESSION não é guardado. Falta o session_start() que abre uma sessão nova só para levar a mensagem.","manual":"10.5, 9.3"},{"id":"sess-018","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"O logout.php vai destruir a sessão. Porque é que começa, mesmo assim, por require 'includes/inicio.php';?","codigo":"","linguagem":"","alternativas":["Por hábito: no logout.php esta linha não faz nada.","Para abrir a sessão: só se destrói uma sessão que foi iniciada.","Para criar a ligação $pdo e apagar o utilizador da tabela utilizadores.","Porque o inicio.php apaga o cookie do browser."],"correta":1,"explicacao":"session_destroy() e $_SESSION só funcionam depois de session_start(), que está no inicio.php. O logout não mexe na base de dados.","manual":"10.5, 9.1"},{"id":"sess-019","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Fazes logout. Depois carregas no botão Voltar do browser e em F5 na lista de livros. O que tem de acontecer?","codigo":"","linguagem":"","alternativas":["Mostra a lista, guardada no browser.","Mostra a lista até fechares o browser.","Aparece um erro 404.","Pede o login outra vez."],"correta":3,"explicacao":"É o teste 8 do capítulo 16. Ao atualizar, o pedido chega ao servidor sem sessão, por isso a página restrita manda para o login.","manual":"16, 10.5"},{"id":"sess-020","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Um colega escreveu assim o fim do logout.php. O que acontece quando o utilizador carrega em \"Sair\"?","codigo":"$_SESSION = [];\nsession_close();\nsession_start();\nmensagem('sucesso', 'Sessão terminada.');\nheader('Location: index.php');\nexit;","linguagem":"php","alternativas":["Dá um erro fatal, porque session_close() não existe.","Funciona, mas a mensagem não aparece na página inicial.","A sessão fecha, mas o utilizador continua com login.","Funciona: session_close() é o mesmo que session_destroy()."],"correta":0,"explicacao":"session_close() não existe em PHP, por isso a página para com um erro fatal ao chamá-la. A função certa é session_destroy().","manual":"10.5"},{"id":"sess-021","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Porque é que a mensagem \"Livro criado.\" é guardada na sessão e não numa variável normal?","codigo":"mensagem('sucesso', 'Livro criado.');\nheader('Location: livro_ver.php?id=' . $id);\nexit;","linguagem":"php","alternativas":["Porque o header() apaga todas as variáveis criadas antes do redirect.","As variáveis normais não aceitam texto com acentos.","Para que só quem tem sessão iniciada a possa ver.","É criada num pedido e mostrada no seguinte, depois do redirect."],"correta":3,"explicacao":"Depois de gravar, o servidor redireciona e a página seguinte é outro pedido, sem as variáveis do anterior. Só a sessão passa de um pedido para o outro.","manual":"9.3"},{"id":"sess-022","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Um colega apagou a linha do unset() no cabecalho.php. O que acontece depois de criar um livro?","codigo":"<?php if (isset($_SESSION['msg'])): ?>\n    <div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\">\n        <?= htmlspecialchars($_SESSION['msg']['texto']) ?>\n    </div>\n<?php endif; ?>","linguagem":"php","alternativas":["A mensagem nunca chega a aparecer, porque não é apagada da sessão.","A mensagem aparece uma vez e o PHP apaga-a sozinho.","\"Livro criado.\" continua a aparecer nas páginas seguintes.","Dá erro, porque a sessão fica com dados a mais."],"correta":2,"explicacao":"Sem unset($_SESSION['msg']), a mensagem fica na sessão e o cabeçalho mostra-a em todas as páginas até haver outra. O unset() é o que a faz aparecer só uma vez.","manual":"9.2, 9.3"},{"id":"sess-023","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Acabaste de criar um livro e vês \"Livro criado.\". Carregas em F5. O que acontece à mensagem?","codigo":"","linguagem":"","alternativas":["Aparece outra vez, até fazeres logout.","Já não aparece: foi mostrada uma vez e apagada.","Aparece como erro, porque o livro já existe.","Aparece outra vez, porque o F5 repete o último pedido feito."],"correta":1,"explicacao":"A mensagem é mostrada uma vez e apagada da sessão (flash message). Graças ao redirect, o F5 repete só um GET, que não cria nada.","manual":"9.3, 9.5"},{"id":"sess-024","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Porque é que os erros de validação ($erros) não precisam de passar pela sessão?","codigo":"","linguagem":"","alternativas":["Os erros vão no endereço da página seguinte, depois do ?.","Os erros são poucos e não cabem na sessão.","A sessão só pode guardar mensagens de sucesso.","A página é mostrada logo, sem redirecionamento."],"correta":3,"explicacao":"Quando a validação falha não se redireciona: o mesmo pedido mostra o formulário com os erros. A sessão só é precisa quando a mensagem tem de sobreviver a um redirect.","manual":"9.4, 9.3"},{"id":"sess-025","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Depois de chamar mensagem('sucesso', 'Conta criada.'), o que fica em $_SESSION['msg']?","codigo":"function mensagem($tipo, $texto)\n{\n    $_SESSION['msg'] = ['tipo' => $tipo, 'texto' => $texto];\n}","linguagem":"php","alternativas":["'Conta criada.'","'sucesso'","['tipo' => 'sucesso', 'texto' => 'Conta criada.']","Nada: a função só escreve a mensagem na página com echo."],"correta":2,"explicacao":"A função guarda na sessão um array com o tipo e o texto. O cabeçalho usa o tipo como classe CSS e o texto como conteúdo.","manual":"9.1, 9.3"},{"id":"sess-026","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Com que condição é que o cabeçalho decide se mostra \"Sair\" ou \"Entrar\"?","codigo":"","linguagem":"","alternativas":["isset($_SESSION['id_utilizador'])","isset($_COOKIE['nome'])","$_SERVER['REQUEST_METHOD'] === 'POST'","isset($_POST['email'])"],"correta":0,"explicacao":"Se existir $_SESSION['id_utilizador'], há sessão iniciada e o menu mostra Livros, Autores, A minha conta e Sair; senão, mostra Entrar e Criar conta.","manual":"9.2"},{"id":"sess-027","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"O nome que o cabeçalho mostra vem da sessão. Porque é que passa, mesmo assim, por htmlspecialchars()?","codigo":"<span class=\"ola\">Olá, <?= htmlspecialchars($_SESSION['nome']) ?></span>","linguagem":"php","alternativas":["Porque o nome é gravado com acentos estragados.","Porque a sessão guarda o nome cifrado e é preciso decifrá-lo.","Foi escrito pelo utilizador no registo e pode conter HTML.","Para o nome não aparecer no cookie."],"correta":2,"explicacao":"O nome veio do formulário de registo, passou pela base de dados e foi para a sessão: continua a ser texto escrito por um utilizador. Escapá-lo evita que um <script> no nome seja executado.","manual":"9.2, 14.1"},{"id":"sess-028","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Porque é que conta.php apaga a conta com o id da sessão e não com um id enviado pelo formulário?","codigo":"if ($_SERVER['REQUEST_METHOD'] === 'POST') {\n    $stmt = $pdo->prepare('DELETE FROM utilizadores WHERE id_utilizador = ?');\n    $stmt->execute([$_SESSION['id_utilizador']]);","linguagem":"php","alternativas":["Porque os formulários com method=\"post\" não podem enviar ids ao servidor.","Porque o id da sessão é apagado depois do DELETE.","Para o DELETE não precisar de cláusula WHERE.","Um id enviado pelo formulário podia ser trocado para apagar outra conta."],"correta":3,"explicacao":"Tudo o que vem do browser pode ser alterado. O id da sessão está no servidor e é sempre o de quem fez login, por isso cada um só consegue apagar a própria conta.","manual":"15.4, 10.3"},{"id":"sess-029","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Em conta.php, depois do DELETE da própria conta, porque se faz $_SESSION = [] e session_destroy()?","codigo":"$stmt = $pdo->prepare('DELETE FROM utilizadores WHERE id_utilizador = ?');\n$stmt->execute([$_SESSION['id_utilizador']]);\n\n$_SESSION = [];\nsession_destroy();\nsession_start();","linguagem":"php","alternativas":["Para apagar o hash da password, que também estava guardado na sessão.","Para impedir que o browser repita o pedido com F5.","A conta já não existe, por isso a sessão também tem de terminar.","Para o DELETE ser confirmado pela base de dados."],"correta":2,"explicacao":"Sem isto, o utilizador continuava com uma sessão de uma conta que já não existe. Depois abre-se uma sessão nova, só para levar a mensagem de confirmação.","manual":"15.4"},{"id":"sess-030","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Apagas a tua conta em \"A minha conta\" e tentas entrar de novo com o mesmo email e password. O que acontece?","codigo":"","linguagem":"","alternativas":["\"Já existe uma conta com esse email.\"","Entras, porque a sessão antiga ainda guarda o teu id_utilizador.","\"Email ou password errados.\", porque a conta já não existe.","Entras, porque o hash da password ficou guardado."],"correta":2,"explicacao":"É o teste 22: o DELETE apagou a linha, por isso o SELECT do login não encontra o email e aparece a mensagem de erro habitual.","manual":"15.4, 16"},{"id":"sess-031","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Um atacante conseguiu roubar o cookie PHPSESSID de um utilizador com sessão iniciada (por exemplo, com XSS). O que consegue fazer?","codigo":"","linguagem":"","alternativas":["Ler a password da pessoa, que fica guardada dentro do cookie.","Nada, porque o cookie só tem o identificador da sessão.","Alterar diretamente os dados guardados em $_SESSION.","Usar a sessão dessa pessoa, como se tivesse feito login."],"correta":3,"explicacao":"O cookie só tem o identificador, mas é esse identificador que diz ao servidor de quem é a sessão. Quem o envia é tratado como o dono da sessão, sem precisar da password.","manual":"10.3, 14.1"},{"id":"sess-032","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"Em PHP, em que variável estão os dados da sessão do utilizador?","codigo":"","linguagem":"","alternativas":["$_SERVER","$_SESSION","$_POST","$_COOKIE"],"correta":1,"explicacao":"Os dados da sessão leem-se e escrevem-se no array $_SESSION, por exemplo $_SESSION['id_utilizador'], depois de session_start().","manual":"7.5, 10.3"},{"id":"sess-033","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Este é o logout.php. Porque é que volta a chamar session_start() logo depois de session_destroy()?","codigo":"<?php\nrequire 'includes/inicio.php';\n\n// Apaga os dados da sessão e destrói-a\n$_SESSION = [];\nsession_destroy();\n\nsession_start();\nmensagem('sucesso', 'Sessão terminada.');\nheader('Location: index.php');\nexit;","linguagem":"php","alternativas":["Para voltar a abrir a sessão do mesmo utilizador.","Porque o header() só funciona com uma sessão aberta.","Para ter uma sessão nova e vazia onde guardar a mensagem.","Para apagar o cookie da sessão no browser."],"correta":2,"explicacao":"$_SESSION = [] e session_destroy() apagam a sessão do utilizador. Abre-se logo uma sessão nova e vazia só para mensagem() poder guardar \"Sessão terminada.\" e a página inicial a mostrar depois do redirecionamento.","manual":"10.5"},{"id":"sess-034","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Qual é o problema grave deste login?","codigo":"$utilizador = $stmt->fetch(PDO::FETCH_ASSOC);\n$_SESSION['id_utilizador'] = $utilizador['id_utilizador'];\n\nif ($utilizador && password_verify($password, $utilizador['password_hash'])) {\n    header('Location: livros.php');\n    exit;\n}\n$erros[] = 'Email ou password errados.';","linguagem":"php","alternativas":["O header() devia vir antes do password_verify().","Guarda o id na sessão antes de confirmar a password.","Falta guardar também o hash da password na sessão.","A mensagem de erro devia dizer qual dos campos falhou."],"correta":1,"explicacao":"Com a password errada aparece o erro, mas a sessão já ficou com o id: as páginas restritas passam a abrir sem login. Os dados só vão para a sessão dentro do if, depois de password_verify() dar true.","manual":"10.4"},{"id":"sess-035","bloco":"php","tema":"Sessões","dificuldade":"facil","pergunta":"O que é uma sessão, numa aplicação PHP?","codigo":"","linguagem":"","alternativas":["Uma ligação ao MySQL que fica aberta entre os pedidos do utilizador.","O tempo em que o separador do browser está aberto.","Um cookie com o email e a password do utilizador.","Dados guardados no servidor para um utilizador, entre pedidos."],"correta":3,"explicacao":"A sessão guarda no servidor os dados de um utilizador ($_SESSION) e liga-os aos pedidos dele através do identificador do cookie.","manual":"10.3"},{"id":"sess-036","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Um colega trocou, no cabeçalho, o unset($_SESSION['msg']) por $_SESSION = [];. O que acontece quando aparece uma mensagem?","codigo":"","linguagem":"","alternativas":["A mensagem repete-se em todas as páginas seguintes.","A mensagem nunca chega a aparecer.","Fica tudo igual, porque as duas instruções fazem exatamente o mesmo.","A mensagem aparece, mas o utilizador perde o login."],"correta":3,"explicacao":"$_SESSION = [] apaga todos os dados da sessão, incluindo o id_utilizador, e não só a mensagem. unset($_SESSION['msg']) apaga apenas a chave msg.","manual":"9.2, 10.5"},{"id":"sess-037","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Os testes sem sessão fazem-se numa janela anónima do browser. Porque é que aí não tens sessão, mesmo com login feito noutra janela?","codigo":"","linguagem":"","alternativas":["A janela anónima apaga a sessão que estava guardada no servidor.","A janela anónima não envia o teu cookie de sessão.","O PHP não aceita pedidos de janelas anónimas.","A janela anónima desliga o session_start()."],"correta":1,"explicacao":"Sem o cookie com o identificador, o servidor não encontra nenhuma sessão e trata o pedido como de alguém sem login. A sessão da outra janela continua intacta no servidor.","manual":"16, 10.3"},{"id":"sess-038","bloco":"php","tema":"Sessões","dificuldade":"media","pergunta":"Se a tua aplicação tiver administradores, o que acrescentas ao login, segundo o manual?","codigo":"","linguagem":"","alternativas":["Guardar o perfil num cookie criado pela aplicação.","Guardar também o perfil do utilizador na sessão.","Pedir a password de novo em cada página.","Criar uma segunda sessão só para os administradores."],"correta":1,"explicacao":"Acrescenta-se uma coluna perfil à tabela e guarda-se o seu valor na sessão no momento do login. Assim, as páginas de administrador verificam-no no servidor.","manual":"10.5"},{"id":"sess-039","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Porque é que o cabeçalho usa isset($_SESSION['id_utilizador']) em vez de testar só $_SESSION['id_utilizador']?","codigo":"<?php if (isset($_SESSION['id_utilizador'])): ?>\n    <a href=\"logout.php\">Sair</a>\n<?php else: ?>\n    <a href=\"login.php\">Entrar</a>\n<?php endif; ?>","linguagem":"php","alternativas":["Sem sessão a chave não existe, o que dava \"Undefined array key\".","Porque isset() lê o valor do cookie.","Porque isset() converte o id num número inteiro.","Porque isset() também inicia a sessão, se ainda não estiver iniciada."],"correta":0,"explicacao":"Quem não fez login não tem a chave id_utilizador na sessão. isset() responde false sem aviso, enquanto ler a chave diretamente dava o aviso \"Undefined array key\".","manual":"9.2, 17.1"},{"id":"sess-040","bloco":"php","tema":"Sessões","dificuldade":"dificil","pergunta":"Em vez da sessão, um colega guarda o id num cookie criado por ele: setcookie('id_utilizador', 7). Que problema tem?","codigo":"","linguagem":"","alternativas":["O utilizador pode mudar o valor para o id de outra pessoa.","O cookie desaparece no fim de cada pedido HTTP e o id perde-se.","O PHP não consegue ler cookies criados pela aplicação.","Nenhum: um cookie é o mesmo que uma sessão."],"correta":0,"explicacao":"Um cookie está no browser e o utilizador pode alterá-lo. Com a sessão, o cookie leva só o identificador e o id fica no servidor, onde o utilizador não lhe pode mexer.","manual":"10.3"},{"id":"acesso-001","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"Qual destas linhas protege corretamente uma página restrita?","codigo":"","linguagem":"","alternativas":["if (isset($_SESSION['id_utilizador'])) { header('Location: login.php'); exit; }","if (!isset($_SESSION['id_utilizador'])) { echo 'Sem acesso'; }","if (!isset($_COOKIE['id_utilizador'])) { header('Location: login.php'); exit; }","if (!isset($_SESSION['id_utilizador'])) { header('Location: login.php'); exit; }"],"correta":3,"explicacao":"Se não existir id_utilizador na sessão, manda para o login e para a página com exit. Só com echo o resto da página continuava a correr, e o $_COOKIE pode ser alterado pelo próprio utilizador.","manual":"11.2, Anexo B"},{"id":"acesso-002","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"O que faz a linha do meio deste ficheiro includes/auth.php?","codigo":"if (!isset($_SESSION['id_utilizador'])) {\n    mensagem('erro', 'Tens de iniciar sessão para ver essa página.');\n    header('Location: login.php');\n    exit;\n}","linguagem":"php","alternativas":["Mostra a mensagem na página restrita e deixa-a continuar.","Escreve a mensagem no ficheiro de erros do Apache.","Guarda na sessão uma mensagem para a página de login mostrar.","Envia a mensagem por email ao administrador."],"correta":2,"explicacao":"A função mensagem() do inicio.php guarda a mensagem em $_SESSION['msg']. Depois do redirecionamento, o cabeçalho do login mostra-a uma vez e apaga-a.","manual":"11.2, 9.3"},{"id":"acesso-003","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"Para que serve o exit no fim do bloco do auth.php?","codigo":"header('Location: login.php');\nexit;","linguagem":"php","alternativas":["Garante que nada do resto da página é executado.","Termina a sessão do utilizador no servidor.","Envia ao browser o código 404.","Apaga a mensagem guardada na sessão."],"correta":0,"explicacao":"O header() só pede ao browser que vá a outra página; o PHP continuaria a executar o resto. O exit para tudo ali.","manual":"11.2, 7.7"},{"id":"acesso-004","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Alguém sem sessão envia um POST com id_livro=3 diretamente para esta página. O que acontece?","codigo":"<?php\nrequire 'includes/inicio.php';\nif (!isset($_SESSION['id_utilizador'])) {\n    header('Location: login.php');\n}\n$stmt = $pdo->prepare('DELETE FROM livros WHERE id_livro = ?');\n$stmt->execute([(int) ($_POST['id_livro'] ?? 0)]);","linguagem":"php","alternativas":["Vai para o login sem apagar nada, porque o header() termina a página.","O livro 3 é apagado, e só depois o browser vai para o login.","Dá o erro \"headers already sent\" e nada é apagado.","Nada é apagado, porque o pedido não traz o cookie da sessão."],"correta":1,"explicacao":"Falta o exit: o header() não para o PHP, que continua e executa o DELETE. O redirecionamento só acontece quando a resposta chega ao browser.","manual":"11.2, 7.7"},{"id":"acesso-005","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"Numa página restrita, onde se inclui o auth.php?","codigo":"<?php\nrequire 'includes/inicio.php';\n// ← aqui?","linguagem":"php","alternativas":["No fim da página, depois do rodapé.","Logo a seguir ao inicio.php, antes de fazer seja o que for.","Dentro do cabecalho.php, para ficar em todas as páginas.","Antes do inicio.php, para ser a primeira linha."],"correta":1,"explicacao":"O inicio.php abre a sessão e cria a função mensagem(), de que o auth.php precisa; a seguir protege-se a página antes de ler, gravar ou mostrar dados. No cabeçalho, protegeria também o login e o registo.","manual":"11.2, 7.8"},{"id":"acesso-006","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Que problema tem esta ordem no topo de uma página restrita?","codigo":"<?php\nrequire 'includes/auth.php';\nrequire 'includes/inicio.php';","linguagem":"php","alternativas":["Não tem problema: a ordem dos require é indiferente.","O inicio.php apaga a sessão que o auth.php acabou de verificar.","O auth.php corre antes da sessão e da função mensagem().","O auth.php deixa passar quem não tem sessão."],"correta":2,"explicacao":"Sem session_start(), $_SESSION ainda não tem os dados da sessão e a função mensagem() ainda não foi definida, por isso a página dá erro. Primeiro o inicio.php, depois o auth.php.","manual":"11.2, 9.1"},{"id":"acesso-007","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"A livro_apagar.php não mostra HTML: só recebe POST e redireciona. Precisa do auth.php?","codigo":"<?php\nrequire 'includes/inicio.php';\n// ← auth.php?\nif ($_SERVER['REQUEST_METHOD'] !== 'POST') {\n    header('Location: livros.php');\n    exit;\n}","linguagem":"php","alternativas":["Sim: sem ele, qualquer pessoa apagava livros com um pedido direto.","Não: só aceita POST, e os POST vêm sempre dos formulários do próprio site.","Não: o botão Apagar só aparece a quem tem sessão.","Só se a página passar a mostrar HTML ao utilizador."],"correta":0,"explicacao":"O manual avisa que as páginas só de POST também têm de ser protegidas. Um pedido POST pode ser enviado sem passar pelo formulário.","manual":"11.2"},{"id":"acesso-008","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"A livro_editar.php ficou assim, sem o auth.php. O que acontece?","codigo":"<?php\nrequire 'includes/inicio.php';\nrequire 'includes/livro_funcoes.php';\n\n$id = (int) ($_GET['id'] ?? 0);","linguagem":"php","alternativas":["O PHP dá um erro fatal por faltar esse ficheiro.","Só quem tem sessão a consegue abrir, por causa do session_start().","A página manda sempre para o login.","A página fica aberta a quem escrever o endereço."],"correta":3,"explicacao":"Sem o require, não há verificação: a página funciona para toda a gente. O session_start() só abre a sessão, não recusa ninguém.","manual":"11.2"},{"id":"acesso-009","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"Qual destas páginas da Biblioteca NÃO deve incluir o auth.php?","codigo":"","linguagem":"","alternativas":["login.php","livro_apagar.php","conta.php","autores.php"],"correta":0,"explicacao":"O login tem de abrir sem sessão; se tivesse o auth.php, mandava para si próprio sem fim. As páginas dos livros, dos autores e da conta são restritas.","manual":"11, 11.2"},{"id":"acesso-010","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Este código está no cabeçalho de todas as páginas. Protege a página livros.php?","codigo":"<?php if (isset($_SESSION['id_utilizador'])): ?>\n    <a href=\"livros.php\">Livros</a>\n<?php endif; ?>","linguagem":"php","alternativas":["Sim: quem não tem sessão não vê o link e por isso não chega à página.","Não: só esconde o link; protege-a o auth.php na própria página.","Sim, desde que o cabeçalho seja incluído com require.","Não, porque devia usar $_POST em vez de $_SESSION."],"correta":1,"explicacao":"Mudar o menu é conforto, não segurança: quem escrever livros.php no browser chega à página. A proteção tem de estar no topo de cada página restrita.","manual":"11.1, 9.2"},{"id":"acesso-011","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Porque é que o auth.php confia em $_SESSION['id_utilizador'] e não num campo enviado pelo browser?","codigo":"","linguagem":"","alternativas":["Porque o $_SESSION é lido mais depressa do que o $_POST.","Porque os campos do formulário são apagados após o login.","Os dados da sessão ficam no servidor e o utilizador não os altera.","Porque o $_SESSION vai cifrado com a password do próprio utilizador."],"correta":2,"explicacao":"O browser guarda só o identificador da sessão; os dados ficam no servidor. Um campo do formulário, um parâmetro do URL ou um cookie podem ser escritos por quem faz o pedido.","manual":"10.3, 11.2"},{"id":"acesso-012","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"Porque se usa uma janela anónima para testar o controlo de acesso?","codigo":"","linguagem":"","alternativas":["Porque desliga o JavaScript automaticamente.","Porque envia todos os pedidos por POST.","Porque mostra os erros do PHP no ecrã.","Porque nela não tens sessão iniciada."],"correta":3,"explicacao":"A janela anónima (Ctrl + Shift + N) não partilha os cookies da janela normal, por isso não tens sessão: és um visitante qualquer.","manual":"11.3"},{"id":"acesso-013","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"O livros.php começa com require do inicio.php e do auth.php (em baixo). Numa janela anónima, escreves localhost/biblioteca/livros.php. O que acontece?","codigo":"<?php\n// includes/auth.php: incluído no topo de cada página restrita,\n// logo a seguir a inicio.php.\nif (!isset($_SESSION['id_utilizador'])) {\n    mensagem('erro', 'Tens de iniciar sessão para ver essa página.');\n    header('Location: login.php');\n    exit;\n}","linguagem":"php","alternativas":["Ir para o login, com \"Tens de iniciar sessão para ver essa página.\"","Ver a lista sem os botões de criar, editar e apagar.","Aparecer o código 404, porque a página não existe para quem não tem sessão.","Aparecer uma página em branco, sem cabeçalho nem rodapé."],"correta":0,"explicacao":"É o teste 9: sem sessão, cada página restrita redireciona para o login com a mensagem do auth.php. Repete-se para todas, incluindo editar e apagar.","manual":"11.3, 16"},{"id":"acesso-014","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Fazes logout numa página restrita e depois carregas em Voltar e em F5. O que tem de acontecer?","codigo":"","linguagem":"","alternativas":["Mostra a página, porque o browser ainda a tem.","Pede o login outra vez.","Mostra a página, mas sem o nome no menu.","Dá um erro 500, porque a sessão foi destruída."],"correta":1,"explicacao":"Com o F5 o pedido chega ao servidor, que já não encontra a sessão; o auth.php manda para o login. É o teste 8 do capítulo 16.","manual":"16, 11.2"},{"id":"acesso-015","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"A tua aplicação tem um administrador. Como proteges as páginas só de administrador, como sugere o manual?","codigo":"","linguagem":"","alternativas":["Escondendo do menu os links de gestão a quem não é administrador.","Pondo as páginas de gestão numa pasta com um nome difícil de adivinhar pelos utilizadores.","Pedindo de novo a password com JavaScript antes de abrir a página.","Com um segundo controlo, como includes/admin.php, que verifica o perfil na sessão."],"correta":3,"explicacao":"Tal como o auth.php, o admin.php corre no servidor em cada pedido e recusa quem não tem o perfil certo. Esconder links ou \"esconder\" páginas não é controlo de acesso.","manual":"11.3"},{"id":"acesso-016","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"De onde vem o perfil que o includes/admin.php verifica?","codigo":"$_SESSION['id_utilizador'] = $utilizador['id_utilizador'];\n$_SESSION['nome']          = $utilizador['nome'];\n$_SESSION['perfil']        = $utilizador['perfil'];","linguagem":"php","alternativas":["De um campo escondido nos formulários de gestão.","Do endereço da página pedida, num parâmetro como ?perfil=admin.","Da sessão, onde o login o guarda a partir da coluna perfil.","De um cookie criado pelo JavaScript no login."],"correta":2,"explicacao":"O manual sugere acrescentar uma coluna perfil à tabela utilizadores e guardá-la na sessão no login. Um campo escondido, o URL ou um cookie seriam alterados por quem faz o pedido.","manual":"10.5, 11.3"},{"id":"acesso-017","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Um utilizador com sessão, mas sem perfil de administrador, escreve o endereço de uma página de gestão que só tem o auth.php. O que acontece?","codigo":"","linguagem":"","alternativas":["É mandado para o login com a mensagem do auth.php.","Vê a página, mas sem os botões de gestão.","Recebe o código 404 em vez da página.","Abre a página: o auth.php só verifica se há sessão."],"correta":3,"explicacao":"O auth.php só pergunta se existe id_utilizador na sessão. Para exigir o perfil, é preciso o segundo controlo (admin.php) nessas páginas.","manual":"11.2, 11.3"},{"id":"acesso-018","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Uma página só de administrador usa este admin.php. Qual é a ordem certa dos require no topo?","codigo":"if (($_SESSION['perfil'] ?? '') !== 'admin') {\n    mensagem('erro', 'Essa página é só para o administrador.');\n    header('Location: index.php');\n    exit;\n}","linguagem":"php","alternativas":["inicio.php, auth.php, admin.php","auth.php, admin.php, inicio.php","inicio.php, cabecalho.php, admin.php","admin.php, inicio.php, auth.php"],"correta":0,"explicacao":"Primeiro a sessão e a função mensagem() (inicio.php), depois a sessão iniciada (auth.php) e por fim o perfil (admin.php). Com o cabeçalho antes, o header() já não podia redirecionar.","manual":"11.2, 11.3, 7.8"},{"id":"acesso-019","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Porque é que a conta.php apaga a conta com o id da sessão, e não com um id enviado pelo formulário?","codigo":"$stmt = $pdo->prepare('DELETE FROM utilizadores WHERE id_utilizador = ?');\n$stmt->execute([$_SESSION['id_utilizador']]);","linguagem":"php","alternativas":["Porque um formulário não consegue enviar números.","Porque o DELETE só aceita valores vindos da sessão.","Assim, cada utilizador só consegue apagar a própria conta.","Para o id não aparecer no endereço do browser."],"correta":2,"explicacao":"Um id enviado pelo formulário podia ser trocado pelo de outra pessoa. O da sessão foi posto lá pelo servidor no login e o utilizador não o altera.","manual":"15.4, 10.3"},{"id":"acesso-020","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"Quando se usa htmlspecialchars()?","codigo":"","linguagem":"","alternativas":["Ao gravar os dados na base de dados, antes de fazer o INSERT.","Ao mostrar na página dados da base de dados ou do utilizador.","Ao ler os campos do $_POST, logo no início.","Ao preparar a consulta, dentro do prepare()."],"correta":1,"explicacao":"Escapa-se no momento de mostrar, em todos os <?= ?> que escrevem dados. Na base de dados os dados ficam tal como foram escritos.","manual":"14.1, Anexo B"},{"id":"acesso-021","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Um colega grava o título com htmlspecialchars() e, como o resto da Biblioteca, também o mostra com htmlspecialchars(). O título é Ensaio & Prosa. O que aparece no ecrã?","codigo":"$titulo = htmlspecialchars(trim($_POST['titulo'] ?? ''));\n// ... INSERT com $titulo ...\n// na página de detalhe:\n<h1><?= htmlspecialchars($livro['titulo']) ?></h1>","linguagem":"php","alternativas":["Ensaio & Prosa","Ensaio &amp;amp; Prosa","Ensaio Prosa","Ensaio &amp; Prosa"],"correta":3,"explicacao":"Na base de dados fica Ensaio &amp; Prosa; ao mostrar, o & volta a ser escapado e o browser exibe o &amp; como texto. Por isso escapa-se só ao mostrar, nunca ao gravar.","manual":"14.1"},{"id":"acesso-022","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"facil","pergunta":"Que caracteres troca o htmlspecialchars()?","codigo":"","linguagem":"","alternativas":["Os -- e os ;, para evitar a injeção de SQL.","<, >, \" e &, por &lt;, &gt;, &quot; e &amp;.","As letras acentuadas, por códigos como &eacute;.","Os espaços e as mudanças de linha, por &nbsp; e <br>."],"correta":1,"explicacao":"São os caracteres com significado especial em HTML. Trocados pelos seus códigos, o browser mostra-os como texto. As mudanças de linha são o trabalho do nl2br().","manual":"14.1"},{"id":"acesso-023","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Porque é que trocar < por &lt; impede o ataque?","codigo":"","linguagem":"","alternativas":["O browser mostra-o como <, mas não o lê como etiqueta.","O &lt; apaga do texto tudo o que vem a seguir.","O MySQL recusa gravar textos que tenham &lt;.","O browser desliga o JavaScript da página sempre que encontra um &lt;."],"correta":0,"explicacao":"Sem um < verdadeiro não há etiqueta <script>: o texto aparece no ecrã tal e qual e nada é executado.","manual":"14.1"},{"id":"acesso-024","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Um título foi gravado como <script>alert(1)</script> e a página mostra-o com htmlspecialchars(). Que HTML chega ao browser?","codigo":"<h2><?= htmlspecialchars($livro['titulo']) ?></h2>","linguagem":"php","alternativas":["<h2><script>alert(1)</script></h2>","<h2>alert(1)</h2>","<h2>&lt;script&gt;alert(1)&lt;/script&gt;</h2>","<h2>&amp;lt;script&amp;gt;alert(1)&amp;lt;/script&amp;gt;</h2>"],"correta":2,"explicacao":"Os < e > são trocados por &lt; e &gt; uma vez. O browser mostra <script>alert(1)</script> como texto e não abre nenhuma janela: é o resultado do teste 20.","manual":"14.1, 16"},{"id":"acesso-025","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"O título de um livro é O \"Memorial\". O que aparece dentro desta caixa de texto?","codigo":"<?php $titulo = 'O \"Memorial\"'; ?>\n<input type=\"text\" name=\"titulo\" value=\"<?= $titulo ?>\">","linguagem":"php","alternativas":["O \"Memorial\", completo.","Só O , porque a aspa fecha o value.","Nada: o campo fica vazio.","Um erro de PHP por causa das aspas."],"correta":1,"explicacao":"O HTML fica value=\"O \"Memorial\"\" e o browser termina o value na segunda aspa. É por isso que o htmlspecialchars() troca \" por &quot;, e o formulário usa value=\"<?= htmlspecialchars(...) ?>\".","manual":"14.1, 12.4"},{"id":"acesso-026","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Que HTML produz esta linha?","codigo":"<?= htmlspecialchars('Eça de Queirós & Machado de Assis') ?>","linguagem":"php","alternativas":["E&ccedil;a de Queir&oacute;s &amp; Machado de Assis","Eça de Queirós & Machado de Assis","E&ccedil;a de Queir&oacute;s & Machado de Assis","Eça de Queirós &amp; Machado de Assis"],"correta":3,"explicacao":"O htmlspecialchars() só troca <, >, \" e &. As letras acentuadas ficam como estão, porque a página está em UTF-8.","manual":"14.1"},{"id":"acesso-027","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Que valores se podem escrever na página sem htmlspecialchars(), sem risco de XSS?","codigo":"","linguagem":"","alternativas":["Todos os que já foram validados no servidor.","Os que foram gravados com consultas preparadas.","Números (ids e anos) e valores fixos do próprio código.","Os que vêm da sessão, como o nome do utilizador."],"correta":2,"explicacao":"Um id ou um ano não podem conter < nem >, e um valor fixo foi escrito pelo programador. Tudo o resto que veio de um utilizador, mesmo validado ou guardado na sessão, é escapado.","manual":"14.1"},{"id":"acesso-028","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Nesta lista, que linha deixa a página vulnerável a XSS?","codigo":"<?php foreach ($livros as $livro): ?>\n    <h2><?= htmlspecialchars($livro['titulo']) ?></h2>\n    <p><?= $livro['autor'] ?> · <?= $livro['ano_edicao'] ?></p>\n    <a href=\"livro_ver.php?id=<?= $livro['id_livro'] ?>\">Ver</a>\n<?php endforeach; ?>","linguagem":"php","alternativas":["A do nome do autor.","A do título do livro.","A do ano de edição.","A do link com o id."],"correta":0,"explicacao":"O nome do autor é texto escrito por um utilizador e aparece sem escapar. O título já está escapado; o ano e o id são números, que a Biblioteca escreve sem htmlspecialchars().","manual":"14.1, 12.2"},{"id":"acesso-029","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Esta linha do cabeçalho mostra o nome guardado na sessão. Precisa de htmlspecialchars()?","codigo":"<span class=\"ola\">Olá, <?= $_SESSION['nome'] ?></span>","linguagem":"php","alternativas":["Sim: o nome foi escrito pelo utilizador no registo.","Não: os dados da sessão ficam no servidor e ninguém os altera.","Não: o nome só aparece ao próprio utilizador.","Só se o nome tiver letras acentuadas."],"correta":0,"explicacao":"A sessão é segura contra alterações, mas o nome lá guardado veio da base de dados, onde o utilizador o escreveu. Por isso o cabeçalho da Biblioteca usa htmlspecialchars($_SESSION['nome']).","manual":"9.2, 14.1"},{"id":"acesso-030","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"No cabeçalho, o tipo da mensagem é escrito sem htmlspecialchars(). Porque é aceitável?","codigo":"<div class=\"msg <?= $_SESSION['msg']['tipo'] ?>\">\n    <?= htmlspecialchars($_SESSION['msg']['texto']) ?>\n</div>","linguagem":"php","alternativas":["Porque está dentro de um atributo class.","Porque a mensagem é apagada da sessão logo a seguir.","Porque é sempre 'sucesso' ou 'erro', valores fixos do código.","Porque a sessão escapa tudo o que lá se guarda."],"correta":2,"explicacao":"O tipo é escolhido pelo programador nas chamadas a mensagem(). Já o texto pode incluir dados do utilizador (como o nome no \"Bem-vindo\"), por isso é escapado.","manual":"9.2, 14.1"},{"id":"acesso-031","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"A caixa de pesquisa mostra o texto procurado. Porque se usa htmlspecialchars() se $q nem vem da base de dados?","codigo":"<input type=\"search\" name=\"q\"\n       value=\"<?= htmlspecialchars($q) ?>\">","linguagem":"php","alternativas":["Porque o value só aceita texto já escapado.","Porque vem do URL: é texto de quem fez o pedido.","Para impedir a injeção de SQL na pesquisa seguinte.","Não é preciso: só os dados da base de dados se escapam."],"correta":1,"explicacao":"Qualquer texto que veio de fora e é escrito na página tem de ser escapado. Um link com ?q= e umas aspas podia fechar o value e meter HTML na página.","manual":"12.2, 14.1"},{"id":"acesso-032","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Porque é que o cabeçalho escapa o $titulo, se é cada página que o define?","codigo":"<title><?= htmlspecialchars($titulo) ?> · Biblioteca</title>","linguagem":"php","alternativas":["Porque o <title> só aceita texto escapado.","Porque o $titulo é lido de $_GET em todas as páginas.","Porque o cabeçalho é incluído com require.","Porque no detalhe o $titulo é o título do livro."],"correta":3,"explicacao":"Na livro_ver.php faz-se $titulo = $livro['titulo']. Como o mesmo cabeçalho serve todas as páginas, escapa-se sempre.","manual":"9.2, 12.3"},{"id":"acesso-033","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Queres mostrar a sinopse com as mudanças de linha e protegida contra XSS. Qual está certo?","codigo":"","linguagem":"","alternativas":["<?= nl2br(htmlspecialchars($livro['sinopse'])) ?>","<?= htmlspecialchars(nl2br($livro['sinopse'])) ?>","<?= nl2br($livro['sinopse']) ?>","<?= htmlspecialchars($livro['sinopse']) . '<br>' ?>"],"correta":0,"explicacao":"Primeiro escapa-se o texto, depois o nl2br() acrescenta os <br> verdadeiros. Ao contrário, os <br> seriam escapados; só com nl2br(), o texto ficaria por escapar.","manual":"12.3"},{"id":"acesso-034","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"dificil","pergunta":"Uma sinopse tem duas linhas. O que aparece no ecrã com esta linha?","codigo":"<dd><?= htmlspecialchars(nl2br($livro['sinopse'])) ?></dd>","linguagem":"php","alternativas":["As duas linhas separadas, como se pretende.","O texto <br /> escrito entre as duas linhas.","A sinopse inteira a negrito.","Um erro, porque nl2br() devolve um array."],"correta":1,"explicacao":"O nl2br() acrescenta <br />, mas o htmlspecialchars() a seguir troca-o por &lt;br /&gt;, que o browser mostra como texto. A ordem certa é nl2br(htmlspecialchars(...)).","manual":"12.3, 14.1"},{"id":"acesso-035","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Um atacante grava <script>…</script> no nome de um autor. Onde atua a defesa da Biblioteca?","codigo":"","linguagem":"","alternativas":["No INSERT, onde o prepare() remove o script.","No validacao.js, que recusa os sinais < e >.","Na base de dados, que não aceita etiquetas HTML.","Nas páginas que mostram o nome, com htmlspecialchars()."],"correta":3,"explicacao":"O nome é gravado tal como foi escrito; a defesa é escapá-lo sempre que é escrito na página. O prepare() protege o SQL, não o HTML.","manual":"14.1"},{"id":"amostra-015","bloco":"php","tema":"Controlo de acesso e XSS","dificuldade":"media","pergunta":"Alguém gravou um livro com o título <script>alert(1)</script>. O que acontece quando a lista o mostra assim?","codigo":"<h2><?= htmlspecialchars($livro['titulo']) ?></h2>","linguagem":"php","alternativas":["Abre-se uma janela de alerta no browser de quem vê a lista.","A base de dados recusou gravar o título, por isso não aparece.","O título aparece como texto, tal e qual, e nada é executado.","O título aparece vazio, porque o htmlspecialchars() apaga as tags."],"correta":2,"explicacao":"O htmlspecialchars() troca < e > por &lt; e &gt;, que o browser mostra como texto. É a defesa contra o XSS: escapar ao mostrar os dados, não ao gravar.","manual":"14.1"}];
